INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36012, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "歌や音楽で、音が続いている流れのこと。", "primary_collocate": null, "pronunciation": "めろでぃー", "ipa": "meɾodʲiː", "syllable_count": 4, "sentences": [{"text": "この歌のメロディーは、一度聞いたらすぐ覚えられる。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "この歌[うた]のメロディーは、一度[いちど]聞[き]いたらすぐ覚[おぼ]えられる。", "sentence_source": "generated"}, {"text": "彼は歌詞よりもメロディーが好きだと言った。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "彼[かれ]は歌詞[かし]よりもメロディーが好[す]きだと言[い]った。", "sentence_source": "generated"}, {"text": "駅の近くで、なつかしいメロディーが流れていた。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くで、なつかしいメロディーが流[なが]れていた。", "sentence_source": "generated"}, {"text": "母は台所で、やさしいメロディーを口ずさんでいる。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "母[はは]は台所[だいどころ]で、やさしいメロディーを口[くち]ずさんでいる。", "sentence_source": "generated"}, {"text": "歌詞は忘れたが、メロディーだけはまだ覚えている。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "歌詞[かし]は忘[わす]れたが、メロディーだけはまだ覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "子どもが、ピアノでかんたんなメロディーをひいた。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "子[こ]どもが、ピアノでかんたんなメロディーをひいた。", "sentence_source": "generated"}, {"text": "このメロディーを聞くと、小学校の運動会を思い出す。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "このメロディーを聞[き]くと、小学校[しょうがっこう]の運動会[うんどうかい]を思[おも]い出[だ]す。", "sentence_source": "generated"}, {"text": "悲しいメロディーなのに、歌詞は明るくておもしろい。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "悲[かな]しいメロディーなのに、歌詞[かし]は明[あか]るくておもしろい。", "sentence_source": "generated"}, {"text": "姉は夜に思いついたメロディーを、急いで紙に書いた。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "姉[あね]は夜[よる]に思[おも]いついたメロディーを、急[いそ]いで紙[かみ]に書[か]いた。", "sentence_source": "generated"}, {"text": "電話の待ち時間に流れるメロディーが、なぜか頭から離れない。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "電話[でんわ]の待[ま]ち時間[じかん]に流[なが]れるメロディーが、なぜか頭[あたま]から離[はな]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メロディー", "label": "基本形"}], "register": "中立", "sense_fingerprint": "歌や音楽で、音が続いてできる耳に残る流れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36012, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メロディー", "is_correct": true, "explanation": "「聞いたらすぐ覚えられる」に合う、耳に残る音の流れを指す語。"}, {"text": "楽器", "is_correct": false, "explanation": "楽器は演奏する道具で、「一度聞いたら覚えられる」対象にはならない。"}, {"text": "音符", "is_correct": false, "explanation": "音符は楽譜に書く記号で、耳で聞いて覚えるものではない。"}, {"text": "楽譜", "is_correct": false, "explanation": "楽譜は目で読むもので、「一度聞いたら覚えられる」とは合わない。"}], "explanations": {"メロディー": "「聞いたらすぐ覚えられる」に合う、耳に残る音の流れを指す語。", "楽器": "楽器は演奏する道具で、「一度聞いたら覚えられる」対象にはならない。", "音符": "音符は楽譜に書く記号で、耳で聞いて覚えるものではない。", "楽譜": "楽譜は目で読むもので、「一度聞いたら覚えられる」とは合わない。"}, "sentence_index": 0, "correct_answer": "メロディー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このドラムは、メロディーを正確に刻んでいる。", "explanation": "ここは〈リズム〉の意味。刻むのは拍のリズムで、音の流れであるメロディーには使わない。"}, {"text": "この曲は、メロディーの言葉づかいがとても丁寧だ。", "explanation": "ここは〈歌詞〉の意味。言葉づかいは歌詞の話で、メロディーには使わないので合わない。"}, {"text": "このギターは、メロディーの音を三つ同時に重ねて和音を作った。", "explanation": "ここは〈和音〉の意味。三つの音を同時に重ねて作るのは和音で、一本の流れであるメロディーには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36012, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メロディー", "is_correct": true, "explanation": "「聞くと思い出す」に合う、耳に残る音の流れを指す語。"}, {"text": "作曲家", "is_correct": false, "explanation": "作曲家は人で、聞いて運動会を思い出させる対象にはならない。"}, {"text": "休符", "is_correct": false, "explanation": "休符は音を休む記号で、聞いて運動会を思い出すものではない。"}, {"text": "調性", "is_correct": false, "explanation": "調性は曲の調の枠組みで、「聞くと運動会を思い出す」には合わない。"}], "explanations": {"メロディー": "「聞くと思い出す」に合う、耳に残る音の流れを指す語。", "作曲家": "作曲家は人で、聞いて運動会を思い出させる対象にはならない。", "休符": "休符は音を休む記号で、聞いて運動会を思い出すものではない。", "調性": "調性は曲の調の枠組みで、「聞くと運動会を思い出す」には合わない。"}, "sentence_index": 6, "correct_answer": "メロディー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この歌手は、メロディーの声が遠くまでよく通る。", "explanation": "ここは〈声〉の意味。声が通るのは人の声で、メロディーには使わない。"}, {"text": "この曲は、メロディーの歌手が三人で交代する。", "explanation": "ここは〈歌手〉の意味。交代するのは歌う人で、メロディーに歌手はいない。"}, {"text": "指揮者は、メロディーを大きく振って合図を出した。", "explanation": "ここは〈指揮〉の意味。振るのは指揮棒や腕で、メロディーを振るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36012, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はこの歌のメロディーに口ずさみながら帰った。", "corrected_sentence": "彼女はこの歌のメロディーを口ずさみながら帰った。", "error_description": "助詞の誤り。「口ずさむ」は目的語に「を」をとる。「に」にすると不自然なので、正しくは「メロディーを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36012, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車の中で、ずっと同じメロディーが繰り返し聞いている。", "corrected_sentence": "電車の中で、ずっと同じメロディーを繰り返し聞いている。", "error_description": "助詞の誤り。「聞く」は目的語に「を」をとる。「が」だと主語のように読まれて不自然で、正しくは「メロディーを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36013, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「歌う」の対象（目的語）は「を」で示すので、メロディーに続けるのは「を」。"}, {"text": "が", "is_correct": false, "explanation": "「が」を入れると主語が重なり、文の形が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「歌う」の対象を「に」で示す用法はなく、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」では名詞を修飾するだけで、「歌い」に続く文にならない。"}], "correct_answer": "を", "explanations": {"を": "「歌う」の対象（目的語）は「を」で示すので、メロディーに続けるのは「を」。", "が": "「が」を入れると主語が重なり、文の形が崩れる。", "に": "「歌う」の対象を「に」で示す用法はなく、不自然。", "の": "「の」では名詞を修飾するだけで、「歌い」に続く文にならない。"}, "error_tags": {"が": "主語の重複", "に": "方向・相手", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36013, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「書き写す」の対象は「を」で示すので、メロディーに続けるのは「を」。"}, {"text": "が", "is_correct": false, "explanation": "「書き写す」の目的語に「が」は使えず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は書き写す先を示す助詞で、ここでは直前の「メロディー」には続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すので、「メロディーで書き写し」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「書き写す」の対象は「を」で示すので、メロディーに続けるのは「を」。", "が": "「書き写す」の目的語に「が」は使えず、不自然。", "に": "「に」は書き写す先を示す助詞で、ここでは直前の「メロディー」には続かない。", "で": "「で」は手段を示すので、「メロディーで書き写し」は意味が通らない。"}, "error_tags": {"が": "目的語", "に": "位置・相手", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36013, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "楽曲の中で、音の高さや長さが変化しながら続く旋律のこと。", "primary_collocate": null, "pronunciation": "めろでぃー", "ipa": "meɾodʲiː", "syllable_count": 4, "sentences": [{"text": "作曲家は、高い音と低い音を組み合わせて美しいメロディーを作った。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "作曲家[さっきょくか]は、高[たか]い音[おと]と低[ひく]い音[おと]を組[く]み合[あ]わせて美[うつく]しいメロディーを作[つく]った。", "sentence_source": "generated"}, {"text": "ボーカルがメロディーを歌い、ギターが伴奏をひいた。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "ボーカルがメロディーを歌[うた]い、ギターが伴奏[ばんそう]をひいた。", "sentence_source": "generated"}, {"text": "サビのメロディーは、音が少しずつ上がっていく。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "サビのメロディーは、音[おと]が少[すこ]しずつ上[あ]がっていく。", "sentence_source": "generated"}, {"text": "この曲は、リズムは速いが、メロディーはゆったりしている。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "この曲[きょく]は、リズムは速[はや]いが、メロディーはゆったりしている。", "sentence_source": "generated"}, {"text": "バイオリンが主なメロディーを受け持ち、ほかの楽器がそれを支える。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "バイオリンが主[おも]なメロディーを受[う]け持[も]ち、ほかの楽器[がっき]がそれを支[ささ]える。", "sentence_source": "generated"}, {"text": "同じメロディーでも、テンポを変えると雰囲気が大きく変わる。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "同[おな]じメロディーでも、テンポを変[か]えると雰囲気[ふんいき]が大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "作曲を学ぶ学生は、まずメロディーの作り方から練習する。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "作曲[さっきょく]を学[まな]ぶ学生[がくせい]は、まずメロディーの作[つく]り方[かた]から練習[れんしゅう]する。", "sentence_source": "generated"}, {"text": "彼はメロディーを楽譜に書き写し、歌詞をつけた。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "彼[かれ]はメロディーを楽譜[がくふ]に書[か]き写[うつ]し、歌詞[かし]をつけた。", "sentence_source": "generated"}, {"text": "音の長さが違うと、同じ音の並びでも別のメロディーになる。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "音[おと]の長[なが]さが違[ちが]うと、同[おな]じ音[おと]の並[なら]びでも別[べつ]のメロディーになる。", "sentence_source": "generated"}, {"text": "この映画音楽は、短くて覚えやすいメロディーが何度も出てくる。", "target_word": "メロディー", "complexity_tier": "T3", "furigana": "この映画音楽[えいがおんがく]は、短[みじか]くて覚[おぼ]えやすいメロディーが何度[なんど]も出[で]てくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メロディー", "label": "基本形"}], "register": "やや専門的", "sense_fingerprint": "楽曲の中で、音の高さと長さが変わりながら続く旋律の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36013, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メロディー", "is_correct": true, "explanation": "「美しい〜を作った」に入る、曲の旋律を指す語。"}, {"text": "歌手", "is_correct": false, "explanation": "歌手は人で、「作った」の対象にはならない。"}, {"text": "指揮者", "is_correct": false, "explanation": "指揮者は人で、曲を作る対象としては合わない。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子は曲の拍の枠組みで、「美しい拍子を作った」は不自然。"}], "explanations": {"メロディー": "「美しい〜を作った」に入る、曲の旋律を指す語。", "歌手": "歌手は人で、「作った」の対象にはならない。", "指揮者": "指揮者は人で、曲を作る対象としては合わない。", "拍子": "拍子は曲の拍の枠組みで、「美しい拍子を作った」は不自然。"}, "sentence_index": 0, "correct_answer": "メロディー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このドラムは、メロディーを正確に刻んで曲を前へ進めている。", "explanation": "ここは〈リズム〉の意味。刻むのは拍のリズムで、旋律のメロディーを刻むとは言わない。"}, {"text": "この曲は、メロディーの言葉づかいが丁寧で、意味がよく伝わる。", "explanation": "ここは〈歌詞〉の意味。言葉づかいや意味は歌詞の話で、旋律には当てはまらない。"}, {"text": "この曲は、メロディーの和音が三つ重なって、厚く響く。", "explanation": "ここは〈和音〉の意味。複数の音が重なって鳴るのは和音で、音の流れであるメロディーには当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36013, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メロディー", "is_correct": true, "explanation": "「作り方から練習する」の対象として、曲の旋律を指す語。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は弾く行為で、作り方を練習する対象としては不自然。"}, {"text": "休符", "is_correct": false, "explanation": "休符は音を休む記号で、作り方を練習する対象ではない。"}, {"text": "調性", "is_correct": false, "explanation": "調性は曲の調の枠組みで、「作り方から練習する」の対象としては不自然。"}], "explanations": {"メロディー": "「作り方から練習する」の対象として、曲の旋律を指す語。", "演奏": "演奏は弾く行為で、作り方を練習する対象としては不自然。", "休符": "休符は音を休む記号で、作り方を練習する対象ではない。", "調性": "調性は曲の調の枠組みで、「作り方から練習する」の対象としては不自然。"}, "sentence_index": 6, "correct_answer": "メロディー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この合唱団は、メロディーの声が遠くまで通る。", "explanation": "ここは〈声〉の意味。声が通るのは人の声で、旋律には使わない。"}, {"text": "この曲は、メロディーの作詞を担当したことで有名だ。", "explanation": "ここは〈作詞〉の意味。作詞は歌詞を書く仕事で、旋律には当てはまらない。"}, {"text": "この曲は、メロディーの語彙が豊富で、難しい言葉が多い。", "explanation": "ここは〈語彙〉の意味。語彙は言葉の集まりで、音の流れには当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36013, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ギタリストは、このメロディーに何度も弾き直した。", "corrected_sentence": "ギタリストは、このメロディーを何度も弾き直した。", "error_description": "助詞の誤り。「弾き直す」は目的語に「を」をとる。「に」は不自然で、正しくは「このメロディーを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36013, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "番組の最後に、このメロディーを静かに流れた。", "corrected_sentence": "番組の最後に、このメロディーが静かに流れた。", "error_description": "助詞の誤り。「流れる」は自動詞なので主語に「が」をとる。「を」にすると不自然で、正しくは「このメロディーが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36014, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "〈で〉は手段や方法を表す。手で方向を示す文に合う。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は対象や方向を表す。手に方向を示すとすると、手を相手として扱う文になり、手段の意味が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や相手を表す。手と方向を示すという文では手段の関係が表せない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表す。手から方向を示すという文は、手段ではなく出どころを表してしまう。"}], "correct_answer": "で", "explanations": {"で": "〈で〉は手段や方法を表す。手で方向を示す文に合う。", "に": "〈に〉は対象や方向を表す。手に方向を示すとすると、手を相手として扱う文になり、手段の意味が成り立たない。", "と": "〈と〉は並列や相手を表す。手と方向を示すという文では手段の関係が表せない。", "から": "〈から〉は起点を表す。手から方向を示すという文は、手段ではなく出どころを表してしまう。"}, "error_tags": {"に": "対象・方向", "と": "並列・相手", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36014, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は直接の対象を表す。ノートを示すという対象の関係に合う。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を表す。「ノートが示し」になるとノートが動作主になり、文の意味が変わる。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は連体を表す。「ノートの示し」は名詞になり、文の動詞として続かない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較や起点を表す。「ノートより示し」は比較の意味になり、示す対象を表さない。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は直接の対象を表す。ノートを示すという対象の関係に合う。", "が": "〈が〉は主語を表す。「ノートが示し」になるとノートが動作主になり、文の意味が変わる。", "の": "〈の〉は連体を表す。「ノートの示し」は名詞になり、文の動詞として続かない。", "より": "〈より〉は比較や起点を表す。「ノートより示し」は比較の意味になり、示す対象を表さない。"}, "error_tags": {"が": "主語", "の": "連体", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36014, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを他の人に見せたり、知らせたりすること。", "primary_collocate": null, "pronunciation": "しめす", "ipa": "ɕimesɯ", "syllable_count": 3, "sentences": [{"text": "先生は地図を広げて、行き先を指で示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "先生[せんせい]は地図[ちず]を広[ひろ]げて、行[い]き先[さき]を指[ゆび]で示[しめ]した。", "sentence_source": "generated"}, {"text": "受付の人は、入口の方向を手で示してくれた。", "target_word": "示して", "complexity_tier": "T3", "furigana": "受付[うけつけ]の人[ひと]は、入口[いりぐち]の方向[ほうこう]を手[て]で示[しめ]してくれた。", "sentence_source": "generated"}, {"text": "警察官に身分証を示して、建物の中に入った。", "target_word": "示して", "complexity_tier": "T3", "furigana": "警察官[けいさつかん]に身分証[みぶんしょう]を示[しめ]して、建物[たてもの]の中[なか]に入[はい]った。", "sentence_source": "generated"}, {"text": "弟は自分の研究の成果を、みんなに誇らしげに示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "弟[おとうと]は自分[じぶん]の研究[けんきゅう]の成果[せいか]を、みんなに誇[ほこ]らしげに示[しめ]した。", "sentence_source": "generated"}, {"text": "案内係が旗を上げて、集合場所を示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "案内係[あんないがかり]が旗[はた]を上[あ]げて、集合[しゅうごう]場所[ばしょ]を示[しめ]した。", "sentence_source": "generated"}, {"text": "店員は商品の値段を、小さな札で客に示している。", "target_word": "示している", "complexity_tier": "T3", "furigana": "店員[てんいん]は商品[しょうひん]の値段[ねだん]を、小[ちい]さな札[ふだ]で客[きゃく]に示[しめ]している。", "sentence_source": "generated"}, {"text": "彼は切符を駅員に示してから、改札を通った。", "target_word": "示して", "complexity_tier": "T3", "furigana": "彼[かれ]は切符[きっぷ]を駅員[えきいん]に示[しめ]してから、改札[かいさつ]を通[とお]った。", "sentence_source": "generated"}, {"text": "子どもは先生に宿題のノートを示し、ほめてもらった。", "target_word": "示し", "complexity_tier": "T3", "furigana": "子[こ]どもは先生[せんせい]に宿題[しゅくだい]のノートを示[しめ]し、ほめてもらった。", "sentence_source": "generated"}, {"text": "登山者は山の頂上を指して、仲間に目的地を示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]は山[やま]の頂上[ちょうじょう]を指[さ]して、仲間[なかま]に目的地[もくてきち]を示[しめ]した。", "sentence_source": "generated"}, {"text": "道に立つ矢印の看板は、出口の場所を示している。", "target_word": "示している", "complexity_tier": "T3", "furigana": "道[みち]に立[た]つ矢印[やじるし]の看板[かんばん]は、出口[でぐち]の場所[ばしょ]を示[しめ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "示す", "label": "終止形"}, {"form": "示した", "label": "過去形"}, {"form": "示して", "label": "て形"}, {"form": "示さない", "label": "否定形"}, {"form": "示せば", "label": "仮定形"}, {"form": "示される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "物や方向を相手に見せて知らせる（指で示す・提示する）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36014, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "示した", "is_correct": true, "explanation": "過去形で、先生が地図を使って行き先を示した文脈に合う。"}, {"text": "隠した", "is_correct": false, "explanation": "隠すは〈見えないようにする〉の意味。行き先を指で隠す文脈では意味が逆になる。"}, {"text": "洗った", "is_correct": false, "explanation": "洗うは〈汚れを落とす〉の意味。行き先を指で洗うという文は成り立たない。"}, {"text": "壊した", "is_correct": false, "explanation": "壊すは〈形をなくす〉の意味。行き先を指で壊すという文脈に合わない。"}], "explanations": {"示した": "過去形で、先生が地図を使って行き先を示した文脈に合う。", "隠した": "隠すは〈見えないようにする〉の意味。行き先を指で隠す文脈では意味が逆になる。", "洗った": "洗うは〈汚れを落とす〉の意味。行き先を指で洗うという文は成り立たない。", "壊した": "壊すは〈形をなくす〉の意味。行き先を指で壊すという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "示した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い部屋で、彼は暖炉に手を示した。", "explanation": "ここは〈かざす〉の意味。示すは相手に見せて知らせる動作で、手を火に向けて温める意味では使わない。"}, {"text": "落とした財布を、彼は交番の前に示した。", "explanation": "ここは〈届ける〉の意味。示すは物を届ける意味を持たないので、交番に財布を届ける文には合わない。"}, {"text": "寝坊した日、彼は家族の前で大きな声を示した。", "explanation": "ここは〈出す〉の意味。声は示すものではなく出すものなので、〈示す〉は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36014, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "示して", "is_correct": true, "explanation": "て形で、「示してから改札を通った」と文がつながる。駅員に切符を見せる動作に合う。"}, {"text": "着て", "is_correct": false, "explanation": "着るは〈身につける〉の意味。切符を着るという文は成り立たない。"}, {"text": "焼いて", "is_correct": false, "explanation": "焼くは〈熱で加工する〉の意味。切符を駅員に焼くという文脈は不自然で意味が通らない。"}, {"text": "乾かして", "is_correct": false, "explanation": "乾かすは〈水気をなくす〉の意味。切符を駅員に乾かしてから改札を通るという文は成り立たない。"}], "explanations": {"示して": "て形で、「示してから改札を通った」と文がつながる。駅員に切符を見せる動作に合う。", "着て": "着るは〈身につける〉の意味。切符を着るという文は成り立たない。", "焼いて": "焼くは〈熱で加工する〉の意味。切符を駅員に焼くという文脈は不自然で意味が通らない。", "乾かして": "乾かすは〈水気をなくす〉の意味。切符を駅員に乾かしてから改札を通るという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "示して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒さに耐えられず、彼は窓を示した。", "explanation": "ここは〈開ける〉の意味。窓は示すものではなく開けるものなので、〈示す〉は使えない。"}, {"text": "彼は庭の花壇に水を示した。", "explanation": "ここは〈やる〉の意味。花に水をかける動作は示すでは表せないので、この文は誤り。"}, {"text": "財布を探した彼は、ポケットに千円札を示した。", "explanation": "ここは〈しまう〉の意味。札を財布やポケットに収める動作は示すでは言えないので、この文は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36014, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "係員にチケットを示すて、会場へ入った。", "corrected_sentence": "係員にチケットを示して、会場へ入った。", "error_description": "て形の正しい形は〈示して〉。〈示すて〉は動詞の連用形につく〈て〉の形になっていない誤りである。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "示して", "is_correct": true, "explanation": "て形。「示してくれた」で、受付の人が方向を手で知らせたことを表す。"}, {"text": "示せば", "is_correct": false, "explanation": "仮定形。「示せば」は条件を表し、過去の行為を述べる文に合わない。"}, {"text": "示される", "is_correct": false, "explanation": "受身形。方向が知らされる側の表現になり、受付の人が示す主体の文に合わない。"}, {"text": "示さない", "is_correct": false, "explanation": "否定形。示していないことになり、実際に方向を示したという文と矛盾する。"}], "correct_form": "示して", "base_form": "示す", "form_label": "て形", "sentence_index": 1, "explanations": {"示して": "て形。「示してくれた」で、受付の人が方向を手で知らせたことを表す。", "示せば": "仮定形。「示せば」は条件を表し、過去の行為を述べる文に合わない。", "示される": "受身形。方向が知らされる側の表現になり、受付の人が示す主体の文に合わない。", "示さない": "否定形。示していないことになり、実際に方向を示したという文と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36014, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は出口を手で示さてから、外へ出た。", "corrected_sentence": "彼は出口を手で示してから、外へ出た。", "error_description": "て形の正しい形は〈示して〉。〈示さて〉は活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "示し", "is_correct": true, "explanation": "連用形。「示し、ほめてもらった」と後ろに続けて、動作を並べる用法に合う。"}, {"text": "示した", "is_correct": false, "explanation": "過去形。文を言い切る形になり、「ほめてもらった」へ連用形で続ける形としては合わない。"}, {"text": "示そう", "is_correct": false, "explanation": "意志形。自分の意志を表すので、子どもが実際にノートを見せた事実の文に合わない。"}, {"text": "示せ", "is_correct": false, "explanation": "命令形。命令の文になるので、ノートを見せた出来事を述べる文に合わない。"}], "correct_form": "示し", "base_form": "示す", "form_label": "連用形", "sentence_index": 7, "explanations": {"示し": "連用形。「示し、ほめてもらった」と後ろに続けて、動作を並べる用法に合う。", "示した": "過去形。文を言い切る形になり、「ほめてもらった」へ連用形で続ける形としては合わない。", "示そう": "意志形。自分の意志を表すので、子どもが実際にノートを見せた事実の文に合わない。", "示せ": "命令形。命令の文になるので、ノートを見せた出来事を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36015, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "〈で〉は動作の場所を表す。記者会見の場で方針を示したという文に合う。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は連体や所属を表す。「記者会見の示した」は文の述語にならない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を表す。「記者会見が示した」では記者会見が動作主になり、市長が示したという意味が変わる。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や相手を表す。「記者会見と示した」では場所の意味が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "〈で〉は動作の場所を表す。記者会見の場で方針を示したという文に合う。", "の": "〈の〉は連体や所属を表す。「記者会見の示した」は文の述語にならない。", "が": "〈が〉は主語を表す。「記者会見が示した」では記者会見が動作主になり、市長が示したという意味が変わる。", "と": "〈と〉は並列や相手を表す。「記者会見と示した」では場所の意味が成り立たない。"}, "error_tags": {"の": "所属・連体", "が": "主語", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36015, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36015, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある情報や状態を、相手にわかるように見せたり、伝えたりする。", "primary_collocate": null, "pronunciation": "しめす", "ipa": "ɕimesɯ", "syllable_count": 3, "sentences": [{"text": "グラフは、売り上げが年々増えていることを示している。", "target_word": "示している", "complexity_tier": "T3", "furigana": "グラフは、売[う]り上[あ]げが年々[ねんねん]増[ふ]えていることを示[しめ]している。", "sentence_source": "generated"}, {"text": "市長は新しい計画の方針を、記者会見で示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "市長[しちょう]は新[あたら]しい計画[けいかく]の方針[ほうしん]を、記者会見[きしゃかいけん]で示[しめ]した。", "sentence_source": "generated"}, {"text": "先生は答えの出し方を、黒板に例を書いて示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "先生[せんせい]は答[こた]えの出[だ]し方[かた]を、黒板[こくばん]に例[れい]を書[か]いて示[しめ]した。", "sentence_source": "generated"}, {"text": "検査の結果は、体に問題がないことを示している。", "target_word": "示している", "complexity_tier": "T3", "furigana": "検査[けんさ]の結果[けっか]は、体[からだ]に問題[もんだい]がないことを示[しめ]している。", "sentence_source": "generated"}, {"text": "彼は反対の意思を、はっきりと態度で示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "彼[かれ]は反対[はんたい]の意思[いし]を、はっきりと態度[たいど]で示[しめ]した。", "sentence_source": "generated"}, {"text": "地図の記号は、駅や学校の位置を示す。", "target_word": "示す", "complexity_tier": "T3", "furigana": "地図[ちず]の記号[きごう]は、駅[えき]や学校[がっこう]の位置[いち]を示[しめ]す。", "sentence_source": "generated"}, {"text": "会社は来年の目標を、社員に数字で示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は来年[らいねん]の目標[もくひょう]を、社員[しゃいん]に数字[すうじ]で示[しめ]した。", "sentence_source": "generated"}, {"text": "調査は、若い人ほど本を読まなくなったことを示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "調査[ちょうさ]は、若[わか]い人[ひと]ほど本[ほん]を読[よ]まなくなったことを示[しめ]した。", "sentence_source": "generated"}, {"text": "医者は治療の進み方を、図を使って患者に示した。", "target_word": "示した", "complexity_tier": "T3", "furigana": "医者[いしゃ]は治療[ちりょう]の進[すす]み方[かた]を、図[ず]を使[つか]って患者[かんじゃ]に示[しめ]した。", "sentence_source": "generated"}, {"text": "犬はしっぽを振って、うれしい気持ちを示す。", "target_word": "示す", "complexity_tier": "T3", "furigana": "犬[いぬ]はしっぽを振[ふ]って、うれしい気持[きも]ちを示[しめ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "示す", "label": "終止形"}, {"form": "示した", "label": "過去形"}, {"form": "示して", "label": "て形"}, {"form": "示さない", "label": "否定形"}, {"form": "示せば", "label": "仮定形"}, {"form": "示される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "情報・結果・態度・状態を相手に分かる形で表して伝える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36015, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "示している", "is_correct": true, "explanation": "〜ている形で、グラフが増加を表している状態に合う。"}, {"text": "示しない", "is_correct": false, "explanation": "〈示しない〉は動詞の否定形として文を終えられず、「ことを」に続かない。"}, {"text": "示された", "is_correct": false, "explanation": "受身形。「ことが示された」なら自然だが、「ことを」と組み合わさると成立しない。"}, {"text": "示し", "is_correct": false, "explanation": "連用形の語幹で文が終わらず、「ことを示し。」は文として成り立たない。"}], "explanations": {"示している": "〜ている形で、グラフが増加を表している状態に合う。", "示しない": "〈示しない〉は動詞の否定形として文を終えられず、「ことを」に続かない。", "示された": "受身形。「ことが示された」なら自然だが、「ことを」と組み合わさると成立しない。", "示し": "連用形の語幹で文が終わらず、「ことを示し。」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "示している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の日、彼は濡れた服を暖房の前に示した。", "explanation": "ここは〈干す〉の意味。濡れた服を乾かすために掛ける動作は示すでは表せないので、この文は誤り。"}, {"text": "兄は弟に、大きな声を示した。", "explanation": "ここは〈出す〉の意味。声は示すものではなく出すものなので、〈示す〉は使えない。"}, {"text": "彼は風邪を家族に示した。", "explanation": "ここは〈うつす〉の意味。病気を人に移す意味は示すにはなく、〈うつす〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36015, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "示した", "is_correct": true, "explanation": "過去形で、会社が社員に目標を数字で示したという文脈に合う。"}, {"text": "眠った", "is_correct": false, "explanation": "眠るは〈寝る〉の意味。目標を社員に数字で眠らせるという文は成り立たない。"}, {"text": "壊した", "is_correct": false, "explanation": "壊すは〈形をなくす〉の意味。目標を数字で壊すという文脈に合わない。"}, {"text": "洗った", "is_correct": false, "explanation": "洗うは〈汚れを落とす〉の意味。目標を数字で洗うという文は成り立たない。"}], "explanations": {"示した": "過去形で、会社が社員に目標を数字で示したという文脈に合う。", "眠った": "眠るは〈寝る〉の意味。目標を社員に数字で眠らせるという文は成り立たない。", "壊した": "壊すは〈形をなくす〉の意味。目標を数字で壊すという文脈に合わない。", "洗った": "洗うは〈汚れを落とす〉の意味。目標を数字で洗うという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "示した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は重い荷物を、玄関まで示して運んだ。", "explanation": "ここは〈移動させる〉の意味。荷物を場所から別の場所へ移す動作は示すでは表せないので、この文は誤り。"}, {"text": "母は今日買った野菜を、冷蔵庫に示した。", "explanation": "ここは〈しまう〉の意味。野菜を冷蔵庫に収める動作は、示すでは言えない。"}, {"text": "彼女は、友達の誕生日に花束を示した。", "explanation": "ここは〈贈る〉の意味。花束を人に渡す意味は示すにはなく、〈贈る〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36015, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "実験の結果は、この薬が効くことを示すている。", "corrected_sentence": "実験の結果は、この薬が効くことを示している。", "error_description": "〜ている形の正しい形は〈示している〉。〈示すている〉は接続が誤っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "示した", "is_correct": true, "explanation": "過去形。市長が計画の方針を記者会見で示したという過去の出来事に合う。"}, {"text": "示して", "is_correct": false, "explanation": "て形。「示して」だけでは出来事の時制が定まらず、文の終わりとして成り立たない。"}, {"text": "示したら", "is_correct": false, "explanation": "たら形。文を言い切れず、「記者会見で示したら。」は成り立たない。"}, {"text": "示される", "is_correct": false, "explanation": "受身形。方針が示される側になり、市長が示した主体の文と合わない。"}], "correct_form": "示した", "base_form": "示す", "form_label": "過去形", "sentence_index": 1, "explanations": {"示した": "過去形。市長が計画の方針を記者会見で示したという過去の出来事に合う。", "示して": "て形。「示して」だけでは出来事の時制が定まらず、文の終わりとして成り立たない。", "示したら": "たら形。文を言い切れず、「記者会見で示したら。」は成り立たない。", "示される": "受身形。方針が示される側になり、市長が示した主体の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36015, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店長は新しい売り場の計画を、社員にメモで示すた。", "corrected_sentence": "店長は新しい売り場の計画を、社員にメモで示した。", "error_description": "過去形の正しい形は〈示した〉。〈示すた〉は活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "示した", "is_correct": true, "explanation": "過去形。調査が若い人の読書離れを示したという過去の結果を述べる文に合う。"}, {"text": "示さなかった", "is_correct": false, "explanation": "過去の否定形。「ことを示さなかった」は、調査が結果を示したという肯定の事実と意味が反対になる。"}, {"text": "示せば", "is_correct": false, "explanation": "仮定形。条件を表す形で、調査が結果を示したという事実の文に合わない。"}, {"text": "示そう", "is_correct": false, "explanation": "意志形。意志を表す文になり、調査の結果という事実を述べる文と合わない。"}], "correct_form": "示した", "base_form": "示す", "form_label": "過去形", "sentence_index": 7, "explanations": {"示した": "過去形。調査が若い人の読書離れを示したという過去の結果を述べる文に合う。", "示さなかった": "過去の否定形。「ことを示さなかった」は、調査が結果を示したという肯定の事実と意味が反対になる。", "示せば": "仮定形。条件を表す形で、調査が結果を示したという事実の文に合わない。", "示そう": "意志形。意志を表す文になり、調査の結果という事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36016, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『ネウマを見た』と、見る対象の目的語を示すので文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "主格の『が』になるとネウマが見る主体になり、意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着・相手の『に』で、見るという動作の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』で、見るという動作には使えない。"}], "correct_answer": "を", "explanations": {"を": "『ネウマを見た』と、見る対象の目的語を示すので文が成り立つ。", "が": "主格の『が』になるとネウマが見る主体になり、意味が合わない。", "に": "帰着・相手の『に』で、見るという動作の目的語にはならない。", "へ": "方向の『へ』で、見るという動作には使えない。"}, "error_tags": {"が": "主格で、見る主体になる", "に": "帰着・相手の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36016, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示し、『ネウマが歌のメロディーを教えてくれる』で文が成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の『と』で、ネウマが教える主体を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「ネウマを…歌のメロディーを」と目的語が二つ並び、教える文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』で、文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "主語を示し、『ネウマが歌のメロディーを教えてくれる』で文が成り立つ。", "と": "並列・共同の『と』で、ネウマが教える主体を示せない。", "を": "「ネウマを…歌のメロディーを」と目的語が二つ並び、教える文として成り立たない。", "より": "比較の『より』で、文の意味が通らない。"}, "error_tags": {"と": "並列の格", "より": "比較の格", "を": "目的語が二重になる"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36016, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "昔の楽譜に使う、音の高低や動きを表す小さな記号です。", "primary_collocate": null, "pronunciation": "ねうま", "ipa": "neɯma", "syllable_count": 3, "sentences": [{"text": "ネウマは、昔の楽譜に使われた、音の高さを表す小さな記号だ。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "ネウマは、昔[むかし]の楽譜[がくふ]に使[つか]われた、音[おと]の高[たか]さを表[あらわ]す小[ちい]さな記号[きごう]だ。", "sentence_source": "generated"}, {"text": "博物館で、古い楽譜に書かれたネウマを見た。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、古[ふる]い楽譜[がくふ]に書[か]かれたネウマを見[み]た。", "sentence_source": "generated"}, {"text": "初期のネウマは、今の五線譜と違って、音の高さがはっきり決まらない。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "初期[しょき]のネウマは、今[いま]の五線譜[ごせんふ]と違[ちが]って、音[おと]の高[たか]さがはっきり決[き]まらない。", "sentence_source": "generated"}, {"text": "先生は、ネウマの形を見れば、音が上がるか下がるかわかると教えてくれた。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ネウマの形[かたち]を見[み]れば、音[おと]が上[あ]がるか下[さ]がるかわかると教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "この本には、ネウマで書かれた歌がたくさんのっている。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "この本[ほん]には、ネウマで書[か]かれた歌[うた]がたくさんのっている。", "sentence_source": "generated"}, {"text": "ネウマを読むには、昔の楽譜の決まりを勉強する必要がある。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "ネウマを読[よ]むには、昔[むかし]の楽譜[がくふ]の決[き]まりを勉強[べんきょう]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "弟は音楽の授業でネウマを知って、古い楽譜に興味を持った。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "弟[おとうと]は音楽[おんがく]の授業[じゅぎょう]でネウマを知[し]って、古[ふる]い楽譜[がくふ]に興味[きょうみ]を持[も]った。", "sentence_source": "generated"}, {"text": "小さな点や線のネウマが、歌のメロディーを教えてくれる。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "小[ちい]さな点[てん]や線[せん]のネウマが、歌[うた]のメロディーを教[おし]えてくれる。", "sentence_source": "generated"}, {"text": "現代の楽譜と比べると、ネウマは音の長さを細かく示さない。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "現代[げんだい]の楽譜[がくふ]と比[くら]べると、ネウマは音[おと]の長[なが]さを細[こま]かく示[しめ]さない。", "sentence_source": "generated"}, {"text": "昔の修道士は、ネウマを使って歌を紙に残した。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "昔[むかし]の修道士[しゅうどうし]は、ネウマを使[つか]って歌[うた]を紙[かみ]に残[のこ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ネウマ", "label": "基本形"}], "register": "中立（日常的な説明文）", "sense_fingerprint": "昔の楽譜で、音の高さや動きを示すために書かれた小さな記号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36016, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ネウマ", "is_correct": true, "explanation": "昔の楽譜で音の高さを表す記号の名前で、『記号だ』の主語として文が成り立つ。"}, {"text": "合唱", "is_correct": false, "explanation": "合唱は大勢で歌う活動で、記号ではないので『記号だ』の主語に合わない。"}, {"text": "指揮", "is_correct": false, "explanation": "指揮は楽団を導く行為で、音の高さを表す記号ではない。"}, {"text": "音階", "is_correct": false, "explanation": "音階は音の並びのことで、一つの記号を指すものではない。"}], "explanations": {"ネウマ": "昔の楽譜で音の高さを表す記号の名前で、『記号だ』の主語として文が成り立つ。", "合唱": "合唱は大勢で歌う活動で、記号ではないので『記号だ』の主語に合わない。", "指揮": "指揮は楽団を導く行為で、音の高さを表す記号ではない。", "音階": "音階は音の並びのことで、一つの記号を指すものではない。"}, "sentence_index": 0, "correct_answer": "ネウマ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ピアノのネウマを弾いた。", "explanation": "ここは〈鍵盤〉の意味。ネウマは記号で、弾くことはできないので合わない。"}, {"text": "駅まで、ネウマに乗って行った。", "explanation": "ここは〈電車〉の意味。ネウマは楽譜の記号で、乗り物ではないので合わない。"}, {"text": "空腹を満たすために、ネウマを食べた。", "explanation": "ここは〈パン〉の意味。ネウマは記号で、食べ物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36016, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ネウマ", "is_correct": true, "explanation": "音楽の授業で学んだ楽譜の記号で、『知って』の対象として文に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、音楽の授業で知る対象ではない。"}, {"text": "台風", "is_correct": false, "explanation": "天気の現象で、授業で知って楽譜に興味を持つ流れに合わない。"}, {"text": "海苔", "is_correct": false, "explanation": "食品で、楽譜の話題の対象にならない。"}], "explanations": {"ネウマ": "音楽の授業で学んだ楽譜の記号で、『知って』の対象として文に合う。", "冷蔵庫": "家電で、音楽の授業で知る対象ではない。", "台風": "天気の現象で、授業で知って楽譜に興味を持つ流れに合わない。", "海苔": "食品で、楽譜の話題の対象にならない。"}, "sentence_index": 6, "correct_answer": "ネウマ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行のネウマを、アルバムに残した。", "explanation": "ここは〈写真〉の意味。ネウマは楽譜の記号で、アルバムに残すものではない。"}, {"text": "友人にネウマを封筒に入れて、送った。", "explanation": "ここは〈手紙〉の意味。ネウマは記号で、封筒に入れて送るものではない。"}, {"text": "ネウマを広げて、道を確かめた。", "explanation": "ここは〈地図〉の意味。ネウマは楽譜の記号で、道を確かめる道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36016, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父が残した古い写本のネウマが、大学で調べた。", "corrected_sentence": "祖父が残した古い写本のネウマを、大学で調べた。", "error_description": "『調べる』の対象は目的語の『を』で示す。『が』にするとネウマが調べる主語になってしまい文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36016, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い聖歌集のネウマに、音楽学者が一つずつ確かめた。", "corrected_sentence": "古い聖歌集のネウマを、音楽学者が一つずつ確かめた。", "error_description": "『確かめる』の対象は目的語の『を』で示す。『に』にすると文の対象関係が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36017, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "受身文『ネウマが書き込まれている』の主語を示すので、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』では、受身文『書き込まれている』の主語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "帰着の『に』では、受身の主語として文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』で、受身の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "受身文『ネウマが書き込まれている』の主語を示すので、文が成り立つ。", "を": "目的語の『を』では、受身文『書き込まれている』の主語を示せない。", "に": "帰着の『に』では、受身の主語として文が成り立たない。", "へ": "方向の『へ』で、受身の主語にはならない。"}, "error_tags": {"を": "目的語の格で、受身の主語にならない", "に": "帰着の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36017, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『写本のネウマは』で文の話題を示し、『解読が難しい』と続く説明に合う。"}, {"text": "と", "is_correct": false, "explanation": "並列の『と』では、話題を示す形として文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』は「写本のネウマへ」の形で主題を示せず、後続の動詞もないので成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は後続の動詞の目的語になるが、ここには受ける動詞がなく文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "『写本のネウマは』で文の話題を示し、『解読が難しい』と続く説明に合う。", "と": "並列の『と』では、話題を示す形として文が成り立たない。", "へ": "方向の『へ』は「写本のネウマへ」の形で主題を示せず、後続の動詞もないので成り立たない。", "を": "『を』は後続の動詞の目的語になるが、ここには受ける動詞がなく文が成り立たない。"}, "error_tags": {"と": "並列の格", "へ": "方向の格で、主題にならない", "を": "目的語で、受ける動詞がない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36017, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "中世ヨーロッパで使われた音楽の記号で、旋律の高低や動きを示すために用いられた。", "primary_collocate": null, "pronunciation": "ねうま", "ipa": "neɯma", "syllable_count": 3, "sentences": [{"text": "ネウマは、中世ヨーロッパで旋律の高低を示すために用いられた記号である。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "ネウマは、中世[ちゅうせい]ヨーロッパで旋律[せんりつ]の高低[こうてい]を示[しめ]すために用[もち]いられた記号[きごう]である。", "sentence_source": "generated"}, {"text": "グレゴリオ聖歌の写本には、ネウマが丁寧に書き込まれている。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "グレゴリオ聖歌[せいか]の写本[しゃほん]には、ネウマが丁寧[ていねい]に書[か]き込[こ]まれている。", "sentence_source": "generated"}, {"text": "初期のネウマは、音の正確な高さではなく、旋律の動きを示していた。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "初期[しょき]のネウマは、音[おと]の正確[せいかく]な高[たか]さではなく、旋律[せんりつ]の動[うご]きを示[しめ]していた。", "sentence_source": "generated"}, {"text": "中世の修道院では、聖歌を伝えるためにネウマが使われた。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]の修道院[しゅうどういん]では、聖歌[せいか]を伝[つた]えるためにネウマが使[つか]われた。", "sentence_source": "generated"}, {"text": "ネウマの研究によって、中世の聖歌の歌い方が少しずつ明らかになってきた。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "ネウマの研究[けんきゅう]によって、中世[ちゅうせい]の聖歌[せいか]の歌[うた]い方[かた]が少[すこ]しずつ明[あき]らかになってきた。", "sentence_source": "generated"}, {"text": "のちにネウマは線の上に書かれるようになり、音の高さが読み取りやすくなった。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "のちにネウマは線[せん]の上[うえ]に書[か]かれるようになり、音[おと]の高[たか]さが読[よ]み取[と]りやすくなった。", "sentence_source": "generated"}, {"text": "歴史の授業で、ネウマが現代の五線譜の起源の一つだと学んだ。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、ネウマが現代[げんだい]の五線譜[ごせんふ]の起源[きげん]の一[ひと]つだと学[まな]んだ。", "sentence_source": "generated"}, {"text": "写本のネウマは、書き手によって形が異なるため、解読が難しい。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "写本[しゃほん]のネウマは、書[か]き手[て]によって形[かたち]が異[こと]なるため、解読[かいどく]が難[むずか]しい。", "sentence_source": "generated"}, {"text": "ネウマは、声の上がり下がりを目に見える形にした工夫であった。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "ネウマ[ねうま]は、声[こえ]の上[あ]がり下[さ]がりを目[め]に見[み]える形[かたち]にした工夫[くふう]であった。", "sentence_source": "generated"}, {"text": "この展覧会では、ネウマが記された十二世紀の楽譜が公開されている。", "target_word": "ネウマ", "complexity_tier": "T3", "furigana": "この展覧会[てんらんかい]では、ネウマが記[しる]された十二世紀[じゅうにせいき]の楽譜[がくふ]が公開[こうかい]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ネウマ", "label": "基本形"}], "register": "書き言葉（硬い説明文・学術的）", "sense_fingerprint": "中世ヨーロッパの聖歌写本などに見られる、旋律の高低や動きを示す記譜記号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 4 words above tier T3 (max 3): グレゴリオ (Zipf 2.24), 聖歌 (Zipf 2.99), 写本 (Zipf 2.81), 書き込ま (Zipf 3.18)']::text[], '9992a0cb-2327-4aa2-bde0-60df8cd86bf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36017, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ネウマ", "is_correct": true, "explanation": "中世の旋律の高低を示す記号の名前で、『記号である』の主語として文が成り立つ。"}, {"text": "指揮", "is_correct": false, "explanation": "指揮は楽団を導く行為で、旋律を示す記号ではない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の部分で、旋律を示す記号にはならない。"}, {"text": "寺院", "is_correct": false, "explanation": "礼拝のための建物で、記号ではないので文の主語に合わない。"}], "explanations": {"ネウマ": "中世の旋律の高低を示す記号の名前で、『記号である』の主語として文が成り立つ。", "指揮": "指揮は楽団を導く行為で、旋律を示す記号ではない。", "窓": "建物の部分で、旋律を示す記号にはならない。", "寺院": "礼拝のための建物で、記号ではないので文の主語に合わない。"}, "sentence_index": 0, "correct_answer": "ネウマ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教会のネウマが鳴り響いた。", "explanation": "ここは〈鐘〉の意味。ネウマは記号で、鳴り響くことはない。"}, {"text": "ネウマが祈りを捧げた。", "explanation": "ここは〈修道士〉の意味。ネウマは記号で、祈りを捧げる主体にはならない。"}, {"text": "修道院の塔にネウマを掲げた。", "explanation": "ここは〈十字架〉の意味。ネウマは記号で、塔に掲げるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36017, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ネウマ", "is_correct": true, "explanation": "中世の記譜記号の名前で、『現代の五線譜の起源の一つ』と説明する主語として文に合う。"}, {"text": "座布団", "is_correct": false, "explanation": "寝具や座るための物で、五線譜の起源にはならない。"}, {"text": "台風", "is_correct": false, "explanation": "天気の現象で、五線譜の起源とは言えない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、音楽記譜の起源ではない。"}], "explanations": {"ネウマ": "中世の記譜記号の名前で、『現代の五線譜の起源の一つ』と説明する主語として文に合う。", "座布団": "寝具や座るための物で、五線譜の起源にはならない。", "台風": "天気の現象で、五線譜の起源とは言えない。", "冷蔵庫": "家電で、音楽記譜の起源ではない。"}, "sentence_index": 6, "correct_answer": "ネウマ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は、ネウマを使って靴下を編んだ。", "explanation": "ここは〈毛糸〉の意味。ネウマは楽譜の記号で、靴下の材料にはならないので合わない。"}, {"text": "花瓶にネウマを生けた。", "explanation": "ここは〈花〉の意味。ネウマは記号で、生けられるものではないので合わない。"}, {"text": "鍋で、ネウマを煮た。", "explanation": "ここは〈スープ〉の意味。ネウマは記号で、煮ることはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36017, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中世の写本に書かれたネウマが、研究者が読み解いた。", "corrected_sentence": "中世の写本に書かれたネウマを、研究者が読み解いた。", "error_description": "『読み解く』の対象は目的語の『を』で示す。『が』にすると、ネウマが読み解く主語になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36017, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修道院の写本に残るネウマに、研究者が解読した。", "corrected_sentence": "修道院の写本に残るネウマを、研究者が解読した。", "error_description": "『解読する』の対象は目的語の『を』で示す。『に』にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82be0cd8-928c-4b59-993b-289166961950') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36018, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「いたずらが過ぎる」の主語を示す「が」。いたずらが限度を超える、の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「いたずらを過ぎて」は「過ぎる」が通過の意味で目的語を取る形になり、限度超過の意味にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「いたずらと過ぎて」は並列を示すが、主語を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「いたずらへ過ぎて」は方向を示すが、主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「いたずらが過ぎる」の主語を示す「が」。いたずらが限度を超える、の主語になる。", "を": "「いたずらを過ぎて」は「過ぎる」が通過の意味で目的語を取る形になり、限度超過の意味にならず不自然。", "と": "「いたずらと過ぎて」は並列を示すが、主語を示せず不自然。", "へ": "「いたずらへ過ぎて」は方向を示すが、主語の位置には合わない。"}, "error_tags": {"を": "目的語", "と": "共同", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36018, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「自慢が過ぎる」の主語を示す「が」。自慢が限度を超える、の主語になる。"}, {"text": "に", "is_correct": false, "explanation": "「自慢に過ぎる人」は受け手を示すが、「過ぎる」の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「自慢で過ぎる人」は手段を示すが、程度の主語としては成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「自慢より過ぎる人」は比較を示すが、主語を示せず不自然。"}], "correct_answer": "が", "explanations": {"が": "「自慢が過ぎる」の主語を示す「が」。自慢が限度を超える、の主語になる。", "に": "「自慢に過ぎる人」は受け手を示すが、「過ぎる」の主語にはならない。", "で": "「自慢で過ぎる人」は手段を示すが、程度の主語としては成り立たない。", "より": "「自慢より過ぎる人」は比較を示すが、主語を示せず不自然。"}, "error_tags": {"に": "相手", "で": "手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36018, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "程度や量が適切な限度を超えていること。", "primary_collocate": null, "pronunciation": "すぎる", "ipa": "sɯɡiɾɯ", "syllable_count": 3, "sentences": [{"text": "冗談が過ぎると、友達を怒らせてしまうよ。", "target_word": "過ぎると", "complexity_tier": "T3", "furigana": "冗談[じょうだん]が過[す]ぎると、友達[ともだち]を怒[おこ]らせてしまうよ。", "sentence_source": "generated"}, {"text": "いたずらが過ぎて、先生にしかられた。", "target_word": "過ぎて", "complexity_tier": "T3", "furigana": "いたずらが過[す]ぎて、先生[せんせい]にしかられた。", "sentence_source": "generated"}, {"text": "彼は用心が過ぎて、新しい店に入れない。", "target_word": "過ぎて", "complexity_tier": "T3", "furigana": "彼[かれ]は用心[ようじん]が過[す]ぎて、新[あたら]しい店[みせ]に入[はい]れない。", "sentence_source": "generated"}, {"text": "ふざけるのも度が過ぎる。", "target_word": "過ぎる", "complexity_tier": "T3", "furigana": "ふざけるのも度[ど]が過[す]ぎる。", "sentence_source": "generated"}, {"text": "親切も過ぎれば、相手に迷惑になる。", "target_word": "過ぎれば", "complexity_tier": "T3", "furigana": "親切[しんせつ]も過[す]ぎれば、相手[あいて]に迷惑[めいわく]になる。", "sentence_source": "generated"}, {"text": "遊びが過ぎた結果、宿題が終わらなかった。", "target_word": "過ぎた", "complexity_tier": "T3", "furigana": "遊[あそ]びが過[す]ぎた結果[けっか]、宿題[しゅくだい]が終[お]わらなかった。", "sentence_source": "generated"}, {"text": "心配が過ぎるせいで、夜に眠れない。", "target_word": "過ぎる", "complexity_tier": "T3", "furigana": "心配[しんぱい]が過[す]ぎるせいで、夜[よる]に眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "自慢が過ぎる人とは、長く話したくない。", "target_word": "過ぎる", "complexity_tier": "T3", "furigana": "自慢[じまん]が過[す]ぎる人[ひと]とは、長[なが]く話[はな]したくない。", "sentence_source": "generated"}, {"text": "彼女の世話焼きは過ぎていて、周りが疲れてしまう。", "target_word": "過ぎて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の世話焼[せわや]きは過[す]ぎていて、周[まわ]りが疲[つか]れてしまう。", "sentence_source": "generated"}, {"text": "欲張りが過ぎたので、結局なにも手に入らなかった。", "target_word": "過ぎた", "complexity_tier": "T3", "furigana": "欲張[よくば]りが過[す]ぎたので、結局[けっきょく]なにも手[て]に入[はい]らなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過ぎる", "label": "終止形・連体形"}, {"form": "過ぎ", "label": "連用形"}, {"form": "過ぎない", "label": "未然形(否定)"}, {"form": "過ぎた", "label": "過去形"}, {"form": "過ぎて", "label": "て形"}, {"form": "過ぎれば", "label": "仮定形"}, {"form": "過ぎよう", "label": "意志形"}], "register": "neutral (plain form, everyday)", "sense_fingerprint": "程度・量が適切な限度を超えている(〜が過ぎる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 世話焼き (Zipf 2.46)']::text[], 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36018, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過ぎると", "is_correct": true, "explanation": "ここは〈限度を超える〉の意味。冗談が限度を超えると友達を怒らせる、と合う。"}, {"text": "過ごすと", "is_correct": false, "explanation": "過ごすは時間を使う意味。「冗談が過ごすと」は程度の超過を表さず合わない。"}, {"text": "過ごせば", "is_correct": false, "explanation": "過ごせばは時間を使う意味の仮定形。冗談の程度を表せず合わない。"}, {"text": "過ぎよう", "is_correct": false, "explanation": "過ぎようは意志形で、これから程度を超えようとする意味になり、条件として文に合わない。"}], "explanations": {"過ぎると": "ここは〈限度を超える〉の意味。冗談が限度を超えると友達を怒らせる、と合う。", "過ごすと": "過ごすは時間を使う意味。「冗談が過ごすと」は程度の超過を表さず合わない。", "過ごせば": "過ごせばは時間を使う意味の仮定形。冗談の程度を表せず合わない。", "過ぎよう": "過ぎようは意志形で、これから程度を超えようとする意味になり、条件として文に合わない。"}, "sentence_index": 0, "correct_answer": "過ぎると"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもの頃が過ぎて、彼は大人になった。", "explanation": "ここは〈時が経つ〉の意味。限度を超える意味ではないので、教える義項では使えない。"}, {"text": "三日が過ぎた頃、荷物が届いた。", "explanation": "ここは〈時が経つ〉の意味。限度を超える意味ではないので、教える義項では使えない。"}, {"text": "嵐が過ぎるのを待った。", "explanation": "ここは〈通り過ぎる〉の意味。限度を超える意味ではないので、教える義項では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36018, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過ぎる", "is_correct": true, "explanation": "ここは〈限度を超える〉の意味。心配が限度を超えたせいで眠れない、と合う。"}, {"text": "過ごす", "is_correct": false, "explanation": "過ごすは時間を使う意味。「心配が過ごすせいで」では原因として意味が通らない。"}, {"text": "過ごした", "is_correct": false, "explanation": "過ごしたは時間を使った意味の過去形。心配の程度を表せず合わない。"}, {"text": "過ごせる", "is_correct": false, "explanation": "過ごせるは可能の意味。心配が原因として働く文脈に合わない。"}], "explanations": {"過ぎる": "ここは〈限度を超える〉の意味。心配が限度を超えたせいで眠れない、と合う。", "過ごす": "過ごすは時間を使う意味。「心配が過ごすせいで」では原因として意味が通らない。", "過ごした": "過ごしたは時間を使った意味の過去形。心配の程度を表せず合わない。", "過ごせる": "過ごせるは可能の意味。心配が原因として働く文脈に合わない。"}, "sentence_index": 6, "correct_answer": "過ぎる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "梅雨が過ぎて、暑い夏が来た。", "explanation": "ここは〈時が経つ〉の意味。限度を超える意味ではないので、教える義項では使えない。"}, {"text": "嵐が過ぎたので、外に出た。", "explanation": "ここは〈時が経つ〉の意味。限度を超える意味ではないので、教える義項では使えない。"}, {"text": "この道を過ぎると、駅が見える。", "explanation": "ここは〈通り過ぎる〉の意味。場所を通る動きで、限度超過の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36018, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遊びが過ぎったので、宿題が終わらなかった。", "corrected_sentence": "遊びが過ぎたので、宿題が終わらなかった。", "error_description": "「過ぎる」は上一段活用で、過去形は「過ぎた」。「過ぎった」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "過ぎて", "is_correct": true, "explanation": "て形。後ろの「先生にしかられた」へ、原因として続けられる形。"}, {"text": "過ぎる", "is_correct": false, "explanation": "終止形。「、」の後に続くと文の骨組みが崩れ、原因として続かない。"}, {"text": "過ぎよう", "is_correct": false, "explanation": "意志形で、これから程度を超えようとする意味になり、文脈に合わない。"}, {"text": "過ぎない", "is_correct": false, "explanation": "否定形で「限度を超えない」の意味になり、原因として文がつながらない。"}], "correct_form": "過ぎて", "base_form": "過ぎる", "form_label": "て形", "sentence_index": 1, "explanations": {"過ぎて": "て形。後ろの「先生にしかられた」へ、原因として続けられる形。", "過ぎる": "終止形。「、」の後に続くと文の骨組みが崩れ、原因として続かない。", "過ぎよう": "意志形で、これから程度を超えようとする意味になり、文脈に合わない。", "過ぎない": "否定形で「限度を超えない」の意味になり、原因として文がつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36018, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "欲張りに過ぎたので、なにも手に入らなかった。", "corrected_sentence": "欲張りが過ぎたので、なにも手に入らなかった。", "error_description": "「過ぎる」の主語は「が」。「に」では主語を表せず、文の意味も成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "過ぎる", "is_correct": true, "explanation": "終止形・連体形。後ろの「人」を修飾する形で、文に合う。"}, {"text": "過ぎ", "is_correct": false, "explanation": "連用形で、名詞「人」を直接修飾できず文が成り立たない。"}, {"text": "過ぎて", "is_correct": false, "explanation": "て形で、「人とは」へ直接続けられない。"}, {"text": "過ぎよう", "is_correct": false, "explanation": "意志形。「人」を修飾できず、文が成り立たない。"}], "correct_form": "過ぎる", "base_form": "過ぎる", "form_label": "連体形", "sentence_index": 7, "explanations": {"過ぎる": "終止形・連体形。後ろの「人」を修飾する形で、文に合う。", "過ぎ": "連用形で、名詞「人」を直接修飾できず文が成り立たない。", "過ぎて": "て形で、「人とは」へ直接続けられない。", "過ぎよう": "意志形。「人」を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36020, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「音程」と「大きさ」を結び、音程の大きさを表す連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「音程を」は後ろの「大きさ」を直接修飾できず、名詞どうしを結ぶ位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "「大きさに」は相手や方向を表す形になり、「音程に大きさ」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、名詞どうしを結ぶ連体修飾には使えない。"}], "correct_answer": "の", "explanations": {"の": "「音程」と「大きさ」を結び、音程の大きさを表す連体修飾の「の」。", "を": "「音程を」は後ろの「大きさ」を直接修飾できず、名詞どうしを結ぶ位置には入らない。", "に": "「大きさに」は相手や方向を表す形になり、「音程に大きさ」では意味が通らない。", "で": "「で」は場所や手段を表すので、名詞どうしを結ぶ連体修飾には使えない。"}, "error_tags": {"を": "対象", "に": "方向・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36020, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「音程」と「差」を結ぶ連体修飾の「の」で、音程の差を表す。"}, {"text": "へ", "is_correct": false, "explanation": "「音程へ差」は方向を示す形になり、名詞どうしを結べない。"}, {"text": "から", "is_correct": false, "explanation": "「音程から差」は起点を示す形で、名詞を結ぶ連体修飾には使えない。"}, {"text": "より", "is_correct": false, "explanation": "「音程より差」は比較の形になり、ここでは意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「音程」と「差」を結ぶ連体修飾の「の」で、音程の差を表す。", "へ": "「音程へ差」は方向を示す形になり、名詞どうしを結べない。", "から": "「音程から差」は起点を示す形で、名詞を結ぶ連体修飾には使えない。", "より": "「音程より差」は比較の形になり、ここでは意味が通らない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36020, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの音の高さのちがいのこと。", "primary_collocate": null, "pronunciation": "おんてい", "ipa": "onteː", "syllable_count": 4, "sentences": [{"text": "ドとソの音程は、五度だ。", "target_word": "音程", "complexity_tier": "T3", "furigana": "ドとソの音程[おんてい]は、五度[ごど]だ。", "sentence_source": "generated"}, {"text": "半音と全音は、音程の大きさがちがう。", "target_word": "音程", "complexity_tier": "T3", "furigana": "半音[はんおん]と全音[ぜんおん]は、音程[おんてい]の大[おお]きさがちがう。", "sentence_source": "generated"}, {"text": "ピアノの先生に、音程を正しく取る練習を教わった。", "target_word": "音程", "complexity_tier": "T3", "furigana": "ピアノの先生[せんせい]に、音程[おんてい]を正[ただ]しく取[と]る練習[れんしゅう]を教[おそ]わった。", "sentence_source": "generated"}, {"text": "ドとレは音程が近いが、ドとラは遠い。", "target_word": "音程", "complexity_tier": "T3", "furigana": "ドとレは音程[おんてい]が近[ちか]いが、ドとラは遠[とお]い。", "sentence_source": "generated"}, {"text": "音程が広い曲は、小さい子には歌いにくい。", "target_word": "音程", "complexity_tier": "T3", "furigana": "音程[おんてい]が広[ひろ]い曲[きょく]は、小[ちい]さい子[こ]には歌[うた]いにくい。", "sentence_source": "generated"}, {"text": "緊張したせいで、高い音の音程が合わなくなった。", "target_word": "音程", "complexity_tier": "T3", "furigana": "緊張[きんちょう]したせいで、高[たか]い音[おと]の音程[おんてい]が合[あ]わなくなった。", "sentence_source": "generated"}, {"text": "バイオリンは、指の位置で音程が変わる。", "target_word": "音程", "complexity_tier": "T3", "furigana": "バイオリンは、指[ゆび]の位置[いち]で音程[おんてい]が変[か]わる。", "sentence_source": "generated"}, {"text": "耳をきたえると、音程の差が聞き分けられる。", "target_word": "音程", "complexity_tier": "T3", "furigana": "耳[みみ]をきたえると、音程[おんてい]の差[さ]が聞[き]き分[わ]けられる。", "sentence_source": "generated"}, {"text": "二人の声の音程が合って、きれいなハーモニーになった。", "target_word": "音程", "complexity_tier": "T3", "furigana": "二人[ふたり]の声[こえ]の音程[おんてい]が合[あ]って、きれいなハーモニーになった。", "sentence_source": "generated"}, {"text": "彼は声は大きいが、音程が不安定だ。", "target_word": "音程", "complexity_tier": "T3", "furigana": "彼[かれ]は声[こえ]は大[おお]きいが、音程[おんてい]が不安定[ふあんてい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "音程", "label": "基本形"}], "register": "neutral (plain form, music)", "sense_fingerprint": "二つの音の高さの隔たり(音楽用語。歌や演奏の音の高さの正確さにも使う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36020, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表すので、高さの隔たりである「五度」の関係とは結びつかない。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子は音の長さの区切りを表し、音の高さの差は表さないので「ドとソの拍子」は成り立たない。"}, {"text": "音程", "is_correct": true, "explanation": "二つの音の高さの隔たりを表す「音程」で、ドとソの関係を五度と言うのに合う。"}, {"text": "音符", "is_correct": false, "explanation": "音符は音の長さや記号を表すもので、高さの隔たりを表さないので五度とは合わない。"}], "explanations": {"音量": "音量は音の大きさを表すので、高さの隔たりである「五度」の関係とは結びつかない。", "拍子": "拍子は音の長さの区切りを表し、音の高さの差は表さないので「ドとソの拍子」は成り立たない。", "音程": "二つの音の高さの隔たりを表す「音程」で、ドとソの関係を五度と言うのに合う。", "音符": "音符は音の長さや記号を表すもので、高さの隔たりを表さないので五度とは合わない。"}, "sentence_index": 0, "correct_answer": "音程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この楽器は音程がやわらかく、聞いていて落ち着く。", "explanation": "ここは〈音色〉の意味。やわらかいという質感は音色について言い、二つの音の高さの差である音程には合わない。"}, {"text": "来月の音程は、もう決まっている。", "explanation": "ここは〈日程〉の意味。来月の予定は日程と言い、音程は音の高さの隔たりなので予定の意味にはならない。"}, {"text": "ピアノの音程を弱くしたので、家族は眠れた。", "explanation": "ここは〈音量〉の意味。音の大きさを弱くするのは音量で、音程は音の高さの差なので音の大きさには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36020, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弓", "is_correct": false, "explanation": "弓は弦をこするための道具で、指の位置で変わるものではないので文に合わない。"}, {"text": "楽器", "is_correct": false, "explanation": "楽器そのものは指の位置で変わらないので、「指の位置で楽器が変わる」は成り立たない。"}, {"text": "手", "is_correct": false, "explanation": "手は体の部位で、指の位置で変わるという文の主語としては意味が通らない。"}, {"text": "音程", "is_correct": true, "explanation": "指の位置によって音の高さの隔たりが変わるという意味で、「音程が変わる」が自然。"}], "explanations": {"弓": "弓は弦をこするための道具で、指の位置で変わるものではないので文に合わない。", "楽器": "楽器そのものは指の位置で変わらないので、「指の位置で楽器が変わる」は成り立たない。", "手": "手は体の部位で、指の位置で変わるという文の主語としては意味が通らない。", "音程": "指の位置によって音の高さの隔たりが変わるという意味で、「音程が変わる」が自然。"}, "sentence_index": 6, "correct_answer": "音程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この曲は音程の長さがそろっていて、リズムが取りやすい。", "explanation": "ここは〈音符〉の意味。音符には音の長さがあるが、音程は高さの隔たりなので「長さ」とは言えない。"}, {"text": "この旅の音程は三日間だ。", "explanation": "ここは〈行程〉の意味。旅の道のりや日数は行程で表し、音程は音の高さの差なので合わない。"}, {"text": "彼は音程が豊かで、大きな声でよく響く。", "explanation": "ここは〈声量〉の意味。声の量が豊かだと言う語で、音程は音の高さの差なので豊かとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36020, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "歌のテストで、音程に外さずに歌えた。", "corrected_sentence": "歌のテストで、音程を外さずに歌えた。", "error_description": "「外す」は対象を「を」で示すので、「音程に」は誤り。正しくは「音程を外さずに」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36020, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "本番で、音程をずれないように注意した。", "corrected_sentence": "本番で、音程がずれないように注意した。", "error_description": "「ずれる」は主語に「が」を取るので、「音程を」は誤り。正しくは「音程がずれないように」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36021, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「広い」の主語を示す「が」で、広いのは音程なので「音程が広い」となる。"}, {"text": "を", "is_correct": false, "explanation": "「広い」は形容詞なので、対象を示す「を」は取れず「音程を広い」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「音程に広い」は方向を示す形になり、広さの主語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「音程から広い」は起点を示す形で、主語を表せないので文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「広い」の主語を示す「が」で、広いのは音程なので「音程が広い」となる。", "を": "「広い」は形容詞なので、対象を示す「を」は取れず「音程を広い」は成り立たない。", "に": "「音程に広い」は方向を示す形になり、広さの主語を示せない。", "から": "「音程から広い」は起点を示す形で、主語を表せないので文が成り立たない。"}, "error_tags": {"を": "対象", "に": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
