INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36021, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音楽で、二つの音の高さの隔たり。", "primary_collocate": null, "pronunciation": "おんてい", "ipa": "oɴteː", "syllable_count": 4, "sentences": [{"text": "ドとソの音程は完全五度にあたる。", "target_word": "音程", "complexity_tier": "T3", "furigana": "ドとソの音程[おんてい]は完全[かんぜん]五度[ごど]にあたる。", "sentence_source": "generated"}, {"text": "二つの音の音程が広いと、歌うのが難しくなる。", "target_word": "音程", "complexity_tier": "T3", "furigana": "二[ふた]つの音[おと]の音程[おんてい]が広[ひろ]いと、歌[うた]うのが難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "ピアノでは、隣り合う鍵盤の音程は半音だ。", "target_word": "音程", "complexity_tier": "T3", "furigana": "ピアノでは、隣[とな]り合[あ]う鍵盤[けんばん]の音程[おんてい]は半音[はんおん]だ。", "sentence_source": "generated"}, {"text": "先生は楽譜を見ながら、二つの音の音程を説明した。", "target_word": "音程", "complexity_tier": "T3", "furigana": "先生[せんせい]は楽譜[がくふ]を見[み]ながら、二[ふた]つの音[おと]の音程[おんてい]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この曲は音程の跳躍が大きいので、初心者には難しい。", "target_word": "音程", "complexity_tier": "T3", "furigana": "この曲[きょく]は音程[おんてい]の跳躍[ちょうやく]が大[おお]きいので、初心者[しょしんしゃ]には難[むずか]しい。", "sentence_source": "generated"}, {"text": "ドからミまでの音程は長三度と呼ばれる。", "target_word": "音程", "complexity_tier": "T3", "furigana": "ドからミまでの音程[おんてい]は長三度[ちょうさんど]と呼[よ]ばれる。", "sentence_source": "generated"}, {"text": "音程が狭いので、二つの音はほとんど同じに聞こえる。", "target_word": "音程", "complexity_tier": "T3", "furigana": "音程[おんてい]が狭[せま]いので、二[ふた]つの音[おと]はほとんど同[おな]じに聞[き]こえる。", "sentence_source": "generated"}, {"text": "耳をきたえると、音程を聞き分けられるようになる。", "target_word": "音程", "complexity_tier": "T3", "furigana": "耳[みみ]をきたえると、音程[おんてい]を聞[き]き分[わ]けられるようになる。", "sentence_source": "generated"}, {"text": "和音は、いくつかの音程が重なってできている。", "target_word": "音程", "complexity_tier": "T3", "furigana": "和音[わおん]は、いくつかの音程[おんてい]が重[かさ]なってできている。", "sentence_source": "generated"}, {"text": "試験では、二つの音を聞いて音程を答える問題が出た。", "target_word": "音程", "complexity_tier": "T3", "furigana": "試験[しけん]では、二[ふた]つの音[おと]を聞[き]いて音程[おんてい]を答[こた]える問題[もんだい]が出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "音程", "label": "基本形"}], "register": "中立", "sense_fingerprint": "音楽用語。二つの音の高さの隔たり(度数で表す)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36021, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表すので、完全五度という高さの隔たりとは合わない。"}, {"text": "音程", "is_correct": true, "explanation": "二つの音の高さの隔たりを表す音程で、ドとソの関係を完全五度と言うのに合う。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子は音の長さの区切りで、音の高さの隔たりを表さないので文が成り立たない。"}, {"text": "音符", "is_correct": false, "explanation": "音符は音の長さや記号を表し、音の高さの隔たりとして完全五度と結びつかない。"}], "explanations": {"音量": "音量は音の大きさを表すので、完全五度という高さの隔たりとは合わない。", "音程": "二つの音の高さの隔たりを表す音程で、ドとソの関係を完全五度と言うのに合う。", "拍子": "拍子は音の長さの区切りで、音の高さの隔たりを表さないので文が成り立たない。", "音符": "音符は音の長さや記号を表し、音の高さの隔たりとして完全五度と結びつかない。"}, "sentence_index": 0, "correct_answer": "音程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は楽譜を見ながら、二つの音の音程の柔らかさを説明した。", "explanation": "ここは〈音色〉の意味。柔らかさは音の質を言う語で、高さの隔たりである音程には合わない。"}, {"text": "先生は楽譜を見ながら、来月の音程を説明した。", "explanation": "ここは〈日程〉の意味。来月の予定は日程と言い、音程は音の高さの隔たりなので予定には使えない。"}, {"text": "先生はマイクの音程を確かめてから、話し始めた。", "explanation": "ここは〈音量〉の意味。マイクの音の大きさを確かめる場面で、音程は音の高さの差なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36021, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音色", "is_correct": false, "explanation": "音色は音の質の違いで、音が狭いという高さの隔たりの話には合わない。"}, {"text": "残響", "is_correct": false, "explanation": "残響は音が残って響く現象で、音の高さの隔たりとは関係がないので文に合わない。"}, {"text": "音程", "is_correct": true, "explanation": "二つの音の高さの隔たりを表す音程で、狭いという評価がつくのはこの意味のとき。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽全体を指す語で、「音楽が狭い」は成り立たず、二つの音の隔たりを表せない。"}], "explanations": {"音色": "音色は音の質の違いで、音が狭いという高さの隔たりの話には合わない。", "残響": "残響は音が残って響く現象で、音の高さの隔たりとは関係がないので文に合わない。", "音程": "二つの音の高さの隔たりを表す音程で、狭いという評価がつくのはこの意味のとき。", "音楽": "音楽全体を指す語で、「音楽が狭い」は成り立たず、二つの音の隔たりを表せない。"}, "sentence_index": 6, "correct_answer": "音程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験では、二つの音を聞いて音程の長さを答える問題が出た。", "explanation": "ここは〈音符〉の意味。音符には音の長さがあるが、音程は高さの隔たりなので「長さ」は言えない。"}, {"text": "試験では、この旅の音程を答える問題が出た。", "explanation": "ここは〈行程〉の意味。旅の道のりや日程は行程と言い、音程は音の高さの差なので合わない。"}, {"text": "彼女は音程が豊かで、遠くまで通る声だ。", "explanation": "ここは〈声量〉の意味。声の量が豊かだと言う語で、音程は音の高さの差なので豊かとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36021, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試験で、二つの音程に差を答えた。", "corrected_sentence": "試験で、二つの音程の差を答えた。", "error_description": "「音程の差」と名詞をつなぐ「の」が正しく、「音程に差」は誤り。「の」を「に」に置き換えた形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36021, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "緊張して、音程を外れてしまった。", "corrected_sentence": "緊張して、音程が外れてしまった。", "error_description": "「外れる」は自動詞で主語に「が」を取るので、「音程を」は誤り。正しくは「音程が外れてしまった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36022, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「危機感の欠如」で、〈の〉が危機感と欠如を名詞同士でつなぐ。ここが正しい形。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は動作の目的語を示す。ここは名詞同士をつなぐ場面なので、〈を〉では文の形が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や相手を示す。「危機感と欠如」と並べると、欠如が危機感の内容だという関係を表せない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段・原因を示す。「危機感で欠如」では名詞句として成り立たず、欠如の内容を表せない。"}], "correct_answer": "の", "explanations": {"の": "「危機感の欠如」で、〈の〉が危機感と欠如を名詞同士でつなぐ。ここが正しい形。", "を": "〈を〉は動作の目的語を示す。ここは名詞同士をつなぐ場面なので、〈を〉では文の形が崩れる。", "と": "〈と〉は並列や相手を示す。「危機感と欠如」と並べると、欠如が危機感の内容だという関係を表せない。", "で": "〈で〉は手段・原因を示す。「危機感で欠如」では名詞句として成り立たず、欠如の内容を表せない。"}, "error_tags": {"を": "目的語", "と": "並列", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36022, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「責任感の欠如」で、〈の〉が責任感を欠如の内容として名詞につなぐ。ここが正しい形。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示す。〈欠如する〉は目的語を取らないので、「責任感を欠如した行動」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。「責任感へ欠如」では方向の意味になり、欠如の内容を表せない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較や起点を示す。「責任感より欠如」では比較の意味になり、この名詞修飾の形に合わない。"}], "correct_answer": "の", "explanations": {"の": "「責任感の欠如」で、〈の〉が責任感を欠如の内容として名詞につなぐ。ここが正しい形。", "を": "〈を〉は目的語を示す。〈欠如する〉は目的語を取らないので、「責任感を欠如した行動」は成り立たない。", "へ": "〈へ〉は方向を示す。「責任感へ欠如」では方向の意味になり、欠如の内容を表せない。", "より": "〈より〉は比較や起点を示す。「責任感より欠如」では比較の意味になり、この名詞修飾の形に合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36022, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが足りなくて、ないこと。", "primary_collocate": null, "pronunciation": "けつじょ", "ipa": "ketsɯʑo", "syllable_count": 3, "sentences": [{"text": "彼の失敗の原因は、準備の欠如だった。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "彼[かれ]の失敗[しっぱい]の原因[げんいん]は、準備[じゅんび]の欠如[けつじょ]だった。", "sentence_source": "generated"}, {"text": "危機感の欠如が、事故につながった。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "危機感[ききかん]の欠如[けつじょ]が、事故[じこ]につながった。", "sentence_source": "generated"}, {"text": "この町には、子どもが遊べる場所の欠如が問題になっている。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "この町[まち]には、子[こ]どもが遊[あそ]べる場所[ばしょ]の欠如[けつじょ]が問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "協調性の欠如を、上司に指摘された。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "協調性[きょうちょうせい]の欠如[けつじょ]を、上司[じょうし]に指摘[してき]された。", "sentence_source": "generated"}, {"text": "やる気の欠如が、成績にも表れている。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "やる気[き]の欠如[けつじょ]が、成績[せいせき]にも表[あらわ]れている。", "sentence_source": "generated"}, {"text": "彼女は経験の欠如を、努力で補おうとした。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は経験[けいけん]の欠如[けつじょ]を、努力[どりょく]で補[おぎな]おうとした。", "sentence_source": "generated"}, {"text": "計画に具体性の欠如があるため、許可が下りなかった。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "計画[けいかく]に具体性[ぐたいせい]の欠如[けつじょ]があるため、許可[きょか]が下[お]りなかった。", "sentence_source": "generated"}, {"text": "責任感の欠如した行動は、周りの人を困らせる。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "責任感[せきにんかん]の欠如[けつじょ]した行動[こうどう]は、周[まわ]りの人[ひと]を困[こま]らせる。", "sentence_source": "generated"}, {"text": "常識の欠如を疑われるような発言だった。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "常識[じょうしき]の欠如[けつじょ]を疑[うたが]われるような発言[はつげん]だった。", "sentence_source": "generated"}, {"text": "問題は能力の欠如ではなく、自信の欠如にある。", "target_word": "欠如", "complexity_tier": "T3", "furigana": "問題[もんだい]は能力[のうりょく]の欠如[けつじょ]ではなく、自信[じしん]の欠如[けつじょ]にある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "欠如", "label": "基本形"}, {"form": "欠如する", "label": "サ変動詞"}, {"form": "欠如した", "label": "過去形"}], "register": "書き言葉（普通体）", "sense_fingerprint": "気持ち・能力・性質など、あるべきものが足りないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36022, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欠如", "is_correct": true, "explanation": "「準備の欠如」で、準備が足りなかったことを表す。原因の説明として自然。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は〈響きが残ること〉の意味。準備の余韻では原因の説明にならない。"}, {"text": "誇り", "is_correct": false, "explanation": "誇りは〈自分を高く思うこと〉の意味。準備の誇りという表現は失敗の原因として通らない。"}, {"text": "衝動", "is_correct": false, "explanation": "衝動は〈急に動かされる気持ち〉の意味。準備の衝動では原因の説明にならない。"}], "explanations": {"欠如": "「準備の欠如」で、準備が足りなかったことを表す。原因の説明として自然。", "余韻": "余韻は〈響きが残ること〉の意味。準備の余韻では原因の説明にならない。", "誇り": "誇りは〈自分を高く思うこと〉の意味。準備の誇りという表現は失敗の原因として通らない。", "衝動": "衝動は〈急に動かされる気持ち〉の意味。準備の衝動では原因の説明にならない。"}, "sentence_index": 0, "correct_answer": "欠如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この車は、ブレーキを踏むたびに欠如するので、危険だ。", "explanation": "ここは〈故障する〉の意味。ブレーキが壊れて効かなくなる動作は欠如とは言わないので、この文は誤り。"}, {"text": "彼は知識の欠如が豊富だ。", "explanation": "ここは〈豊かさ〉の意味。欠如は足りないことなので、知識が豊かだという内容と正反対になり、同じ文で組み合わせると矛盾する。"}, {"text": "彼は授業の欠如が多く、単位を落とした。", "explanation": "ここは〈欠席〉の意味。授業に出ないことは欠席と言い、欠如とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36022, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欠如", "is_correct": true, "explanation": "「具体性の欠如」で、具体性が足りないことを表す。許可が下りなかった理由として自然。"}, {"text": "偏見", "is_correct": false, "explanation": "偏見は〈かたよった見方〉の意味。具体性の偏見では理由の説明にならない。"}, {"text": "熱意", "is_correct": false, "explanation": "熱意は〈強い気持ち〉の意味。具体性の熱意があるという文では許可が下りない理由にならない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は〈うるさい音〉の意味。具体性の騒音という表現は成り立たない。"}], "explanations": {"欠如": "「具体性の欠如」で、具体性が足りないことを表す。許可が下りなかった理由として自然。", "偏見": "偏見は〈かたよった見方〉の意味。具体性の偏見では理由の説明にならない。", "熱意": "熱意は〈強い気持ち〉の意味。具体性の熱意があるという文では許可が下りない理由にならない。", "騒音": "騒音は〈うるさい音〉の意味。具体性の騒音という表現は成り立たない。"}, "sentence_index": 6, "correct_answer": "欠如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、客の数が欠如しているのでいつも混んでいる。", "explanation": "ここは〈豊富〉の意味。欠如は足りないことで、客が多くて混む文とは意味が逆になり矛盾する。"}, {"text": "選手は試合で欠如したプレーを見せた。", "explanation": "ここは〈精彩〉の意味。活躍が生き生きしないことは〈精彩を欠く〉と言い、欠如とは言わない。"}, {"text": "先生は生徒の長所の欠如を褒めた。", "explanation": "ここは〈欠点〉の意味。欠点、つまり足りない点を褒めるのは筋が通らないので、欠如は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36022, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "予算の欠如を、計画が中止になった。", "corrected_sentence": "予算の欠如で、計画が中止になった。", "error_description": "原因を表すには〈で〉を使う。〈欠如を〉の〈を〉は目的語用で、原因の文には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36022, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は情報を欠如したまま、判断を下した。", "corrected_sentence": "彼は情報が欠如したまま、判断を下した。", "error_description": "〈欠如する〉は主語が欠けている側になるので、〈情報が〉と〈が〉を使う。〈情報を〉の〈を〉は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36024, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「中世のヨーロッパ」と名詞を結ぶ連体修飾。ここでは正しい。"}, {"text": "が", "is_correct": false, "explanation": "「中世がヨーロッパで描かれた」では主語にならず、描かれた場所が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「中世をヨーロッパで描かれた」は目的語の「を」と受身の「描かれた」が結びつかず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「中世へヨーロッパで描かれた」は方向になり、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「中世のヨーロッパ」と名詞を結ぶ連体修飾。ここでは正しい。", "が": "「中世がヨーロッパで描かれた」では主語にならず、描かれた場所が成り立たない。", "を": "「中世をヨーロッパで描かれた」は目的語の「を」と受身の「描かれた」が結びつかず、文が成り立たない。", "へ": "「中世へヨーロッパで描かれた」は方向になり、意味が通らない。"}, "error_tags": {"が": "主格", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36024, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「中世から続くお寺」と起点を表す。ここでは正しい。"}, {"text": "で", "is_correct": false, "explanation": "「中世で続く」は手段や場所の意味になり、起点を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「中世と続く」は並列になり、続き始める時点を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「中世を続く」は目的語になり、続くものとして成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「中世から続くお寺」と起点を表す。ここでは正しい。", "で": "「中世で続く」は手段や場所の意味になり、起点を示せない。", "と": "「中世と続く」は並列になり、続き始める時点を示せない。", "を": "「中世を続く」は目的語になり、続くものとして成り立たない。"}, "error_tags": {"で": "手段", "と": "並列", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36024, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今から何百年も前の、日本やヨーロッパの昔の時代のことです。", "primary_collocate": null, "pronunciation": "ちゅうせい", "ipa": "t͡ɕɯːseː", "syllable_count": 4, "sentences": [{"text": "中世の人々は、今とはちがう暮らしをしていた。", "target_word": "中世", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]の人々[ひとびと]は、今[いま]とはちがう暮[く]らしをしていた。", "sentence_source": "generated"}, {"text": "この絵は、中世のヨーロッパで描かれたものです。", "target_word": "中世", "complexity_tier": "T3", "furigana": "この絵[え]は、中世[ちゅうせい]のヨーロッパで描[えが]かれたものです。", "sentence_source": "generated"}, {"text": "中世の城は、敵を防ぐために高い壁で囲まれていた。", "target_word": "中世", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]の城[しろ]は、敵[てき]を防[ふせ]ぐために高[たか]い壁[かべ]で囲[かこ]まれていた。", "sentence_source": "generated"}, {"text": "兄は中世の歴史が好きで、よく本を読んでいる。", "target_word": "中世", "complexity_tier": "T3", "furigana": "兄[あに]は中世[ちゅうせい]の歴史[れきし]が好[す]きで、よく本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "日本の中世には、武士が大きな力を持つようになった。", "target_word": "中世", "complexity_tier": "T3", "furigana": "日本[にほん]の中世[ちゅうせい]には、武士[ぶし]が大[おお]きな力[ちから]を持[も]つようになった。", "sentence_source": "generated"}, {"text": "中世の町を再現した映画を見て、当時の服に興味を持った。", "target_word": "中世", "complexity_tier": "T4", "furigana": "中世[ちゅうせい]の町[まち]を再現[さいげん]した映画[えいが]を見[み]て、当時[とうじ]の服[ふく]に興味[きょうみ]を持[も]った。", "sentence_source": "generated"}, {"text": "中世の騎士の話は、物語や映画によく出てくる。", "target_word": "中世", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]の騎士[きし]の話[はなし]は、物語[ものがたり]や映画[えいが]によく出[で]てくる。", "sentence_source": "generated"}, {"text": "京都には、中世から続くお寺がたくさんある。", "target_word": "中世", "complexity_tier": "T3", "furigana": "京都[きょうと]には、中世[ちゅうせい]から続[つづ]くお寺[てら]がたくさんある。", "sentence_source": "generated"}, {"text": "中世には車も電車もなかったので、人々は歩いて旅をした。", "target_word": "中世", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]には車[くるま]も電車[でんしゃ]もなかったので、人々[ひとびと]は歩[ある]いて旅[たび]をした。", "sentence_source": "generated"}, {"text": "先生は、中世の服や食べ物について、写真を見せながら説明した。", "target_word": "中世", "complexity_tier": "T4", "furigana": "先生[せんせい]は、中世[ちゅうせい]の服[ふく]や食[た]べ物[もの]について、写真[しゃしん]を見[み]せながら説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中世", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何百年も前の、日本やヨーロッパの昔の時代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36024, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中世", "is_correct": true, "explanation": "何百年も前の時代の人々を指すので、「中世の人々」が正しい。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は時代ではないので、「鉄の人々」は意味が通らない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は時代ではないので、「砂糖の人々」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は時代ではないので、「天気の人々」は意味が通らない。"}], "explanations": {"中世": "何百年も前の時代の人々を指すので、「中世の人々」が正しい。", "鉄": "鉄は時代ではないので、「鉄の人々」は意味が通らない。", "砂糖": "砂糖は時代ではないので、「砂糖の人々」は意味が通らない。", "天気": "天気は時代ではないので、「天気の人々」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "中世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先週の中世に、友だちと映画を見に行った。", "explanation": "ここは〈最近の時期〉の意味。中世は何百年も前の時代なので、近い時期を指す言い方には合わない。"}, {"text": "この店のケーキは、中世がとても安い。", "explanation": "ここは〈値段〉の意味。中世は価格ではないので、「安い」の主語にはならない。"}, {"text": "おじいさんは中世を三つ買って、家族に配った。", "explanation": "ここは〈品物〉の意味。中世は物ではないので、「三つ」と数えて買う対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36024, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中世", "is_correct": true, "explanation": "何百年も前の時代の騎士の話なので、「中世の騎士」が正しい。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは時代ではないので、「夕焼けの騎士」は意味が通らない。"}, {"text": "紅茶", "is_correct": false, "explanation": "紅茶は時代ではないので、「紅茶の騎士」は意味が通らない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は時代ではないので、「電話の騎士」は意味が通らない。"}], "explanations": {"中世": "何百年も前の時代の騎士の話なので、「中世の騎士」が正しい。", "夕焼け": "夕焼けは時代ではないので、「夕焼けの騎士」は意味が通らない。", "紅茶": "紅茶は時代ではないので、「紅茶の騎士」は意味が通らない。", "電話": "電話は時代ではないので、「電話の騎士」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "中世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹は中世と手をつないで、学校へ行った。", "explanation": "ここは〈人〉の意味。中世は人ではないので、一緒に歩く相手にはならない。"}, {"text": "机の上に中世を置いて、宿題を始めた。", "explanation": "ここは〈物〉の意味。中世は置ける物ではないので、机の上に置く対象にはならない。"}, {"text": "中世がいい天気なので、散歩に出かけた。", "explanation": "ここは〈天候〉の意味。中世は天候を表さないので、「いい天気」の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36024, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中世を城は、石で作られていた。", "corrected_sentence": "中世の城は、石で作られていた。", "error_description": "「中世の城」は連体修飾なので「の」が正しい。「中世を」にすると目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36024, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "中世を車がなかった。", "corrected_sentence": "中世は車がなかった。", "error_description": "「中世は」の「は」が主題を示す。「中世を」にすると目的語になり、「なかった」の文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36025, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「日本の中世は、…をいいます」と主題を示し、定義文として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「日本の中世を、…をいいます」では「を」が二つ重なり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「中世で」は場所や手段になり、定義文の主題にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「中世へ」は方向を表すので、定義文の主題にはならない。"}], "correct_answer": "は", "explanations": {"は": "「日本の中世は、…をいいます」と主題を示し、定義文として正しい。", "を": "「日本の中世を、…をいいます」では「を」が二つ重なり、文が成り立たない。", "で": "「中世で」は場所や手段になり、定義文の主題にはならない。", "へ": "「中世へ」は方向を表すので、定義文の主題にはならない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36025, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「中世の日本」と名詞を結ぶ連体修飾。ここでは正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「中世へ日本では」は方向を表す「へ」になり、時期を述べる文脈に合わない。"}, {"text": "を", "is_correct": false, "explanation": "「中世を日本では」は目的語になり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「中世と日本では」は並列になり、時代を示す意味が変わる。"}], "correct_answer": "の", "explanations": {"の": "「中世の日本」と名詞を結ぶ連体修飾。ここでは正しい。", "へ": "「中世へ日本では」は方向を表す「へ」になり、時期を述べる文脈に合わない。", "を": "「中世を日本では」は目的語になり、文が成り立たない。", "と": "「中世と日本では」は並列になり、時代を示す意味が変わる。"}, "error_tags": {"へ": "方向", "を": "目的語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36025, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "西洋史や日本史で、古代と近世の間の時代を指します。日本では鎌倉時代から安土桃山時代ごろ、西洋では5世紀から15世紀ごろの時代です。", "primary_collocate": null, "pronunciation": "ちゅうせい", "ipa": "t͡ɕɯːseː", "syllable_count": 4, "sentences": [{"text": "中世ヨーロッパで発展したゴシック様式の大聖堂は、その圧倒的な高さと美しさで人々を魅了しました。", "target_word": "中世", "complexity_tier": "T4", "furigana": "中世[ちゅうせい]ヨーロッパで発展[はってん]したゴシック様式[ようしき]の大聖堂[だいせいどう]は、その圧倒的[あっとうてき]な高[たか]さと美[うつく]しさで人々[ひとびと]を魅了[みりょう]しました。", "sentence_source": "mined"}, {"text": "日本の中世は、鎌倉時代から安土桃山時代ごろまでをいいます。", "target_word": "中世", "complexity_tier": "T4", "furigana": "日本[にほん]の中世[ちゅうせい]は、鎌倉時代[かまくらじだい]から安土桃山時代[あづちももやまじだい]ごろまでをいいます。", "sentence_source": "generated"}, {"text": "中世のヨーロッパでは、教会が人々の生活に大きな力を持っていた。", "target_word": "中世", "complexity_tier": "T4", "furigana": "中世[ちゅうせい]のヨーロッパでは、教会[きょうかい]が人々[ひとびと]の生活[せいかつ]に大[おお]きな力[ちから]を持[も]っていた。", "sentence_source": "generated"}, {"text": "中世の武士は、主君のために戦うことを大切にした。", "target_word": "中世", "complexity_tier": "T4", "furigana": "中世[ちゅうせい]の武士[ぶし]は、主君[しゅくん]のために戦[たたか]うことを大切[たいせつ]にした。", "sentence_source": "generated"}, {"text": "この城は中世に建てられたため、石の壁がとても厚い。", "target_word": "中世", "complexity_tier": "T3", "furigana": "この城[しろ]は中世[ちゅうせい]に建[た]てられたため、石[いし]の壁[かべ]がとても厚[あつ]い。", "sentence_source": "generated"}, {"text": "中世の修道院では、僧たちが本を手で写していた。", "target_word": "中世", "complexity_tier": "T4", "furigana": "中世[ちゅうせい]の修道院[しゅうどういん]では、僧[そう]たちが本[ほん]を手[て]で写[うつ]していた。", "sentence_source": "generated"}, {"text": "歴史の授業で、古代から中世への変化を学んだ。", "target_word": "中世", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、古代[こだい]から中世[ちゅうせい]への変化[へんか]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "中世の日本では、お寺が学問の中心になることも多かった。", "target_word": "中世", "complexity_tier": "T4", "furigana": "中世[ちゅうせい]の日本[にほん]では、お寺[てら]が学問[がくもん]の中心[ちゅうしん]になることも多[おお]かった。", "sentence_source": "generated"}, {"text": "町の博物館には、中世の刀やよろいが展示されている。", "target_word": "中世", "complexity_tier": "T3", "furigana": "町[まち]の博物館[はくぶつかん]には、中世[ちゅうせい]の刀[かたな]やよろいが展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "中世の騎士は、重いよろいを着て馬に乗り、戦場へ向かった。", "target_word": "中世", "complexity_tier": "T4", "furigana": "中世[ちゅうせい]の騎士[きし]は、重[おも]いよろいを着[き]て馬[うま]に乗[の]り、戦場[せんじょう]へ向[む]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中世", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "歴史の時代区分で、古代と近世の間にあたる時代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36025, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中世", "is_correct": true, "explanation": "ゴシック様式は中世ヨーロッパを代表する様式なので、「中世」が正しい。"}, {"text": "雨", "is_correct": false, "explanation": "雨は時代を示せないので、ヨーロッパで発展した様式を修飾できない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は時代を示せないので、ヨーロッパで発展した様式を修飾できない。"}, {"text": "音", "is_correct": false, "explanation": "音は時代を示せないので、ヨーロッパで発展した様式を修飾できない。"}], "explanations": {"中世": "ゴシック様式は中世ヨーロッパを代表する様式なので、「中世」が正しい。", "雨": "雨は時代を示せないので、ヨーロッパで発展した様式を修飾できない。", "夢": "夢は時代を示せないので、ヨーロッパで発展した様式を修飾できない。", "音": "音は時代を示せないので、ヨーロッパで発展した様式を修飾できない。"}, "sentence_index": 0, "correct_answer": "中世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中世の三時間で、レポートを書き終えた。", "explanation": "ここは〈時間の長さ〉の意味。中世は数時間を測る長さの単位ではないので、「三時間」と組み合わせて時間の量を表すことはできない。"}, {"text": "彼は中世の性格で、いつも明るい。", "explanation": "ここは〈中世的だ〉の意味。「中世」は時代名で、性格を表す語にはならない。「中世的」と言えば形容語として使える。"}, {"text": "今年の中世は、雨が多い。", "explanation": "ここは〈現在の時期〉の意味。中世は過去の時代なので、今の年や季節を指す言い方にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36025, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中世", "is_correct": true, "explanation": "古代から次の時代へ移る変化として、「中世への変化」が正しい。"}, {"text": "波", "is_correct": false, "explanation": "波は時代の変化を表さないので、「古代から波への変化」は意味が通らない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は時代の区分ではないので、「古代から雷への変化」は意味が通らない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は時代の区分ではないので、「古代から霧への変化」は意味が通らない。"}], "explanations": {"中世": "古代から次の時代へ移る変化として、「中世への変化」が正しい。", "波": "波は時代の変化を表さないので、「古代から波への変化」は意味が通らない。", "雷": "雷は時代の区分ではないので、「古代から雷への変化」は意味が通らない。", "霧": "霧は時代の区分ではないので、「古代から霧への変化」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "中世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中世が犬の散歩に行った。", "explanation": "ここは〈人〉の意味。中世は人ではないので、散歩に行く主語にはならない。"}, {"text": "店の前で、中世を開けてから入った。", "explanation": "ここは〈戸・扉〉の意味。中世は戸のように開けるものではないので、「開ける」の対象にはならない。"}, {"text": "この中世はとても美味しい。", "explanation": "ここは〈食べ物〉の意味。中世は食べ物ではないので、「美味しい」の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36025, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中世を建てられた寺は、今も残っている。", "corrected_sentence": "中世に建てられた寺は、今も残っている。", "error_description": "「建てられた」は受身で、時期の「中世」には「を」が付かない。時期は「に」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36025, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "中世を戦が多かった。", "corrected_sentence": "中世は戦が多かった。", "error_description": "「中世は」の「は」が主題を示す。「中世を」にすると目的語になり、「多かった」の主語として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36026, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を表す『に』。『平安時代後期に建てられた』で自然に通る。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』。建てられるのは寺で、時代は『に』で示す。『後期を』は不自然。"}, {"text": "が", "is_correct": false, "explanation": "『平安時代後期が建てられた』では時代が主語になり、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』。時点には使わないので、ここでは不自然。"}], "correct_answer": "に", "explanations": {"に": "時点を表す『に』。『平安時代後期に建てられた』で自然に通る。", "を": "目的語の『を』。建てられるのは寺で、時代は『に』で示す。『後期を』は不自然。", "が": "『平安時代後期が建てられた』では時代が主語になり、意味が通らない。", "へ": "方向を示す『へ』。時点には使わないので、ここでは不自然。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前期", "is_correct": true, "explanation": "時代や期間の前半を指し、後期と対になる語。"}, {"text": "中期", "is_correct": false, "explanation": "真ん中の時期を指す語。後期の反対語ではない。"}, {"text": "末期", "is_correct": false, "explanation": "終わりの時期を指す語で、後期に近い意味。反対語ではない。"}, {"text": "初頭", "is_correct": false, "explanation": "始まりの部分を指す語。後期の反対語とは言えない。"}], "correct_answer": "前期", "explanations": {"前期": "時代や期間の前半を指し、後期と対になる語。", "中期": "真ん中の時期を指す語。後期の反対語ではない。", "末期": "終わりの時期を指す語で、後期に近い意味。反対語ではない。", "初頭": "始まりの部分を指す語。後期の反対語とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36026, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す『は』。『室町時代の後期は戦いが多く』と文が続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』。時代は目的語になりにくく、『後期を戦いが多く』は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』。時代へ向かうとは言えず、『後期へ戦いが多く』は不自然。"}, {"text": "ので", "is_correct": false, "explanation": "理由の『ので』は名詞に直接つかず、『後期ので』は誤り。"}], "correct_answer": "は", "explanations": {"は": "主題を示す『は』。『室町時代の後期は戦いが多く』と文が続く。", "を": "目的語の『を』。時代は目的語になりにくく、『後期を戦いが多く』は不自然。", "へ": "方向の『へ』。時代へ向かうとは言えず、『後期へ戦いが多く』は不自然。", "ので": "理由の『ので』は名詞に直接つかず、『後期ので』は誤り。"}, "error_tags": {"を": "目的語", "へ": "方向", "ので": "接続"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前期", "is_correct": true, "explanation": "時代や期間の前半を指し、後期と対になる語。"}, {"text": "中盤", "is_correct": false, "explanation": "途中の部分を指す語。後期の反対語ではない。"}, {"text": "終盤", "is_correct": false, "explanation": "終わりに近い部分を指す語で、後期に近い意味。反対語ではない。"}, {"text": "初回", "is_correct": false, "explanation": "最初の回を指す語。期間の前半を表す語ではない。"}], "correct_answer": "前期", "explanations": {"前期": "時代や期間の前半を指し、後期と対になる語。", "中盤": "途中の部分を指す語。後期の反対語ではない。", "終盤": "終わりに近い部分を指す語で、後期に近い意味。反対語ではない。", "初回": "最初の回を指す語。期間の前半を表す語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36026, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あとの方の時間や時代のこと。", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "江戸時代の後期には、各地で学問が盛んになりました。", "target_word": "後期", "complexity_tier": "T3", "furigana": "江戸時代[えどじだい]の後期[こうき]には、各地[かくち]で学問[がくもん]が盛[さか]んになりました。", "sentence_source": "generated"}, {"text": "この寺は平安時代後期に建てられたと言われています。", "target_word": "後期", "complexity_tier": "T3", "furigana": "この寺[てら]は平安時代[へいあんじだい]後期[こうき]に建[た]てられたと言[い]われています。", "sentence_source": "generated"}, {"text": "祖父は昭和の後期に生まれました。", "target_word": "後期", "complexity_tier": "T2", "furigana": "祖父[そふ]は昭和[しょうわ]の後期[こうき]に生[う]まれました。", "sentence_source": "generated"}, {"text": "後期の作品は、初期のものより色が暗くなっている。", "target_word": "後期", "complexity_tier": "T3", "furigana": "後期[こうき]の作品[さくひん]は、初期[しょき]のものより色[いろ]が暗[くら]くなっている。", "sentence_source": "generated"}, {"text": "十九世紀後期、鉄道が急速に広がった。", "target_word": "後期", "complexity_tier": "T3", "furigana": "十九世紀[じゅうきゅうせいき]後期[こうき]、鉄道[てつどう]が急速[きゅうそく]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "その画家の後期の絵には、静かな海がよく描かれている。", "target_word": "後期", "complexity_tier": "T4", "furigana": "その画家[がか]の後期[こうき]の絵[え]には、静[しず]かな海[うみ]がよく描[えが]かれている。", "sentence_source": "generated"}, {"text": "古墳時代後期になると、小さな墓が増えた。", "target_word": "後期", "complexity_tier": "T3", "furigana": "古墳時代[こふんじだい]後期[こうき]になると、小[ちい]さな墓[はか]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "室町時代の後期は戦いが多く、人々の生活は苦しかった。", "target_word": "後期", "complexity_tier": "T4", "furigana": "室町時代[むろまちじだい]の後期[こうき]は戦[たたか]いが多[おお]く、人々[ひとびと]の生活[せいかつ]は苦[くる]しかった。", "sentence_source": "generated"}, {"text": "博物館で、縄文時代後期の土器を見た。", "target_word": "後期", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、縄文時代[じょうもんじだい]後期[こうき]の土器[どき]を見[み]た。", "sentence_source": "generated"}, {"text": "彼の後期の考え方は、若いころと大きく違う。", "target_word": "後期", "complexity_tier": "T3", "furigana": "彼[かれ]の後期[こうき]の考[かんが]え方[かた]は、若[わか]いころと大[おお]きく違[ちが]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "後期", "label": "基本形"}, {"form": "後期の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "時代や歴史の区切りのうち、あとの方の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36026, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "後期", "is_correct": true, "explanation": "時代の後半を指す語。江戸時代の後半を表し、ここに入る。"}, {"text": "学期", "is_correct": false, "explanation": "学校の期間の区切り。時代の話には合わない。"}, {"text": "授業", "is_correct": false, "explanation": "学校で行う指導のこと。『江戸時代の授業』は時代を表さない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。『江戸時代の天気』は時代を表さず、文が成り立たない。"}], "explanations": {"後期": "時代の後半を指す語。江戸時代の後半を表し、ここに入る。", "学期": "学校の期間の区切り。時代の話には合わない。", "授業": "学校で行う指導のこと。『江戸時代の授業』は時代を表さない。", "天気": "空模様のこと。『江戸時代の天気』は時代を表さず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "後期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は三十分後期に始まった。", "explanation": "〈後期〉は時代や期間の後半を指す語。『三十分後』のように時点からの経過には〈後〉を使う。"}, {"text": "箱の後期に、古い手紙が入っていた。", "explanation": "〈後期〉は時間や時代の後半を指す語。箱の奥や裏側の場所は〈奥〉を使う。"}, {"text": "犬の後期を撫でた。", "explanation": "〈後期〉は時間や時代の後半を指す語。犬の尾は〈尻尾〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36026, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "後期", "is_correct": true, "explanation": "時代の後半を指す語。古墳時代の後半を表し、ここに入る。"}, {"text": "夏休み", "is_correct": false, "explanation": "学校の長い休み。『古墳時代夏休みになると』は時代を表さない。"}, {"text": "給料", "is_correct": false, "explanation": "働いて得る金銭のこと。時代の区切りとして合わない。"}, {"text": "試合", "is_correct": false, "explanation": "競技の対戦。時代を表す語として合わない。"}], "explanations": {"後期": "時代の後半を指す語。古墳時代の後半を表し、ここに入る。", "夏休み": "学校の長い休み。『古墳時代夏休みになると』は時代を表さない。", "給料": "働いて得る金銭のこと。時代の区切りとして合わない。", "試合": "競技の対戦。時代を表す語として合わない。"}, "sentence_index": 6, "correct_answer": "後期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車の後期の席に、荷物を置いた。", "explanation": "〈後期〉は時間の後半を指す語。座席の前後を言うには〈後ろ〉を使う。"}, {"text": "名簿の後期に、先生の名前が書いてあった。", "explanation": "〈後期〉は長い期間の後半を指す。名簿の一番下の部分は〈末尾〉と言う。"}, {"text": "この小説は前編と後期に分かれている。", "explanation": "〈後期〉は時代や学期などの期間の区切り。物語の前後の区切りは〈後編〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36026, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は昭和の後期を大阪で生まれました。", "corrected_sentence": "母は昭和の後期に大阪で生まれました。", "error_description": "『生まれる』は出生の時点を『に』で示す。『後期を』は誤りで、正しくは『後期に』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36026, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明治時代後期な画家が多く活動した。", "corrected_sentence": "明治時代後期の画家が多く活動した。", "error_description": "『後期』を名詞として修飾するには『の』を使う。『後期な』は誤りで、正しくは『後期の』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36027, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞を修飾する『の』。『後期の授業』で正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』。『後期を授業は』では文の構造が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』。『後期への授業』では意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』。『後期が授業は』では主語が二つになり、不自然。"}], "correct_answer": "の", "explanations": {"の": "名詞を修飾する『の』。『後期の授業』で正しい。", "を": "目的語の『を』。『後期を授業は』では文の構造が崩れる。", "へ": "方向の『へ』。『後期への授業』では意味が通らない。", "が": "主語の『が』。『後期が授業は』では主語が二つになり、不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主語"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前期", "is_correct": true, "explanation": "学期を前後に分けたときの前の部分。後期と対になる語。"}, {"text": "中間", "is_correct": false, "explanation": "真ん中を指す語。後期の反対語ではない。"}, {"text": "初歩", "is_correct": false, "explanation": "基礎の段階を指す語。前期とは別の意味で、反対語ではない。"}, {"text": "始業", "is_correct": false, "explanation": "仕事や授業の始まりを指す語。反対語ではない。"}], "correct_answer": "前期", "explanations": {"前期": "学期を前後に分けたときの前の部分。後期と対になる語。", "中間": "真ん中を指す語。後期の反対語ではない。", "初歩": "基礎の段階を指す語。前期とは別の意味で、反対語ではない。", "始業": "仕事や授業の始まりを指す語。反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36027, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞を修飾する『の』。『後期の授業料』で正しい。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』。『後期より授業料は』では比べる対象がなく不自然。"}, {"text": "ほど", "is_correct": false, "explanation": "程度の『ほど』。『後期ほど授業料は』では程度を比べる文脈がなく不自然。"}, {"text": "ばかり", "is_correct": false, "explanation": "限定の『ばかり』。『後期ばかり授業料は』では限定する対象が合わず不自然。"}], "correct_answer": "の", "explanations": {"の": "名詞を修飾する『の』。『後期の授業料』で正しい。", "より": "比較の『より』。『後期より授業料は』では比べる対象がなく不自然。", "ほど": "程度の『ほど』。『後期ほど授業料は』では程度を比べる文脈がなく不自然。", "ばかり": "限定の『ばかり』。『後期ばかり授業料は』では限定する対象が合わず不自然。"}, "error_tags": {"より": "比較", "ほど": "程度", "ばかり": "限定"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前期", "is_correct": true, "explanation": "学期を前後に分けたときの前の部分。後期と対になる語。"}, {"text": "中旬", "is_correct": false, "explanation": "一か月を三つに分けた真ん中の時期。後期の反対語ではない。"}, {"text": "上旬", "is_correct": false, "explanation": "一か月を三つに分けた最初の時期。後期の反対語ではない。"}, {"text": "初旬", "is_correct": false, "explanation": "月のはじめの時期を指す語。後期の反対語ではない。"}], "correct_answer": "前期", "explanations": {"前期": "学期を前後に分けたときの前の部分。後期と対になる語。", "中旬": "一か月を三つに分けた真ん中の時期。後期の反対語ではない。", "上旬": "一か月を三つに分けた最初の時期。後期の反対語ではない。", "初旬": "月のはじめの時期を指す語。後期の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36027, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある期間の中で、終わりに近い部分。", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "前期は基礎を学び、後期は実際に作品を作ります。", "target_word": "後期", "complexity_tier": "T3", "furigana": "前期[ぜんき]は基礎[きそ]を学[まな]び、後期[こうき]は実際[じっさい]に作品[さくひん]を作[つく]ります。", "sentence_source": "generated"}, {"text": "後期の授業は十月から始まります。", "target_word": "後期", "complexity_tier": "T2", "furigana": "後期[こうき]の授業[じゅぎょう]は十月[じゅうがつ]から始[はじ]まります。", "sentence_source": "generated"}, {"text": "大学の後期試験は二月にあります。", "target_word": "後期", "complexity_tier": "T3", "furigana": "大学[だいがく]の後期[こうき]試験[しけん]は二月[にがつ]にあります。", "sentence_source": "generated"}, {"text": "今年度の後期は、新しい先生が担当します。", "target_word": "後期", "complexity_tier": "T3", "furigana": "今年度[こんねんど]の後期[こうき]は、新[あたら]しい先生[せんせい]が担当[たんとう]します。", "sentence_source": "generated"}, {"text": "後期の申し込みは九月までなので、急いでください。", "target_word": "後期", "complexity_tier": "T3", "furigana": "後期[こうき]の申[もう]し込[こ]みは九月[くがつ]までなので、急[いそ]いでください。", "sentence_source": "generated"}, {"text": "工事は後期に入ってから、少しずつ進み始めた。", "target_word": "後期", "complexity_tier": "T4", "furigana": "工事[こうじ]は後期[こうき]に入[はい]ってから、少[すこ]しずつ進[すす]み始[はじ]めた。", "sentence_source": "generated"}, {"text": "前期は忙しかったが、後期はゆっくり勉強できそうだ。", "target_word": "後期", "complexity_tier": "T3", "furigana": "前期[ぜんき]は忙[いそが]しかったが、後期[こうき]はゆっくり勉強[べんきょう]できそうだ。", "sentence_source": "generated"}, {"text": "後期の授業料は、九月に払うことになっている。", "target_word": "後期", "complexity_tier": "T3", "furigana": "後期[こうき]の授業料[じゅぎょうりょう]は、九月[くがつ]に払[はら]うことになっている。", "sentence_source": "generated"}, {"text": "このリーグは後期になると、強いチームが勝ち始める。", "target_word": "後期", "complexity_tier": "T4", "furigana": "このリーグは後期[こうき]になると、強[つよ]いチームが勝[か]ち始[はじ]める。", "sentence_source": "generated"}, {"text": "妹は後期から、新しいクラスに移る予定です。", "target_word": "後期", "complexity_tier": "T3", "furigana": "妹[いもうと]は後期[こうき]から、新[あたら]しいクラスに移[うつ]る予定[よてい]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "後期", "label": "基本形"}, {"form": "後期の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "学期や年度などの期間を前後に分けたときの終わりに近い部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36027, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "後期", "is_correct": true, "explanation": "学期などの後半を指す語。前期と対になり、ここに入る。"}, {"text": "教室", "is_correct": false, "explanation": "授業を行う場所。作品を作る主体にはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教材の本。『実際に作品を作ります』の主語にはならない。"}, {"text": "出席簿", "is_correct": false, "explanation": "出席を記録する帳簿。作品を作る文には合わない。"}], "explanations": {"後期": "学期などの後半を指す語。前期と対になり、ここに入る。", "教室": "授業を行う場所。作品を作る主体にはならない。", "教科書": "教材の本。『実際に作品を作ります』の主語にはならない。", "出席簿": "出席を記録する帳簿。作品を作る文には合わない。"}, "sentence_index": 0, "correct_answer": "後期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "薬は食事後期に飲んでください。", "explanation": "〈後期〉は学期などの期間の後半を指す。食後の時点は〈食後〉を使う。"}, {"text": "ろうそくの後期を飾った。", "explanation": "〈後期〉は期間の後半を指す語。ろうそくの部分は〈本体〉と言う。"}, {"text": "ドアの後期を閉めてください。", "explanation": "〈後期〉は時間の後半を指す語。戸を閉める対象は〈扉〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36027, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "後期", "is_correct": true, "explanation": "学期の後の部分を指す語。『前期は忙しかったが』と対になり、ここに入る。"}, {"text": "給食", "is_correct": false, "explanation": "学校で出る食事。勉強の様子を表す文と結びつかない。"}, {"text": "制服", "is_correct": false, "explanation": "学校で着る服。勉強のしやすさの主語にはならない。"}, {"text": "掲示板", "is_correct": false, "explanation": "情報を貼る板。勉強の様子を表さず、不自然。"}], "explanations": {"後期": "学期の後の部分を指す語。『前期は忙しかったが』と対になり、ここに入る。", "給食": "学校で出る食事。勉強の様子を表す文と結びつかない。", "制服": "学校で着る服。勉強のしやすさの主語にはならない。", "掲示板": "情報を貼る板。勉強の様子を表さず、不自然。"}, "sentence_index": 6, "correct_answer": "後期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "少し後期に行きます。", "explanation": "〈後期〉は期間の後半を指す語。『少しあとで』という時間には〈後で〉を使う。"}, {"text": "車を後期に動かしてください。", "explanation": "〈後期〉は期間の後半を指す語。車を後ろへ動かすことは〈後退〉と言う。"}, {"text": "ケーキの後期を残した。", "explanation": "〈後期〉は期間の後半を指す語。ケーキの残り部分は〈残り〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36027, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は三年生の後期を留学する予定です。", "corrected_sentence": "私は三年生の後期に留学する予定です。", "error_description": "『留学する』は時点を『に』で示す。『後期を』は誤りで、正しくは『後期に』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36027, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "後期が成績表は、三月に届く。", "corrected_sentence": "後期の成績表は、三月に届く。", "error_description": "『後期』を名詞として修飾するには『の』を使う。『後期が』は誤りで、正しくは『後期の』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36029, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「相対で」は比べる相手との関係によって決まるという手段・根拠を示し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「相対を決まる」は文法的に成り立たず、「決まる」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「相対へ決まる」は方向を示す形になり、文意に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「相対の決まる」は後ろに名詞が続かず、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「相対で」は比べる相手との関係によって決まるという手段・根拠を示し、文に合う。", "を": "「相対を決まる」は文法的に成り立たず、「決まる」は目的語を取らないので合わない。", "へ": "「相対へ決まる」は方向を示す形になり、文意に合わない。", "の": "「相対の決まる」は後ろに名詞が続かず、文が成り立たない。"}, "error_tags": {"を": "object marker", "へ": "direction", "の": "genitive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "絶対", "is_correct": true, "explanation": "対義語。比べる相手に左右されず成り立つという意味で、相対の反対にあたる。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然は予測できない出来事を指し、比べる相手による関係を表す相対の対義語にはならない。"}, {"text": "平均", "is_correct": false, "explanation": "平均は全体をならした値を指し、相対と対になる関係にはならない。"}, {"text": "固有", "is_correct": false, "explanation": "固有は、そのものだけに備わる性質を指し、相対の対義語とは言えない。"}], "correct_answer": "絶対", "explanations": {"絶対": "対義語。比べる相手に左右されず成り立つという意味で、相対の反対にあたる。", "偶然": "偶然は予測できない出来事を指し、比べる相手による関係を表す相対の対義語にはならない。", "平均": "平均は全体をならした値を指し、相対と対になる関係にはならない。", "固有": "固有は、そのものだけに備わる性質を指し、相対の対義語とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36029, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「相対で」は比べる相手との関係によって決まるという手段・根拠を示し、文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「相対へ決まる」は方向を示す形になり、相対の関係が決まるという文意に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「相対の決まる」は名詞を修飾する形になり、後に続く名詞がないので文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「相対より決まる」は比較を表す形になり、比べる相手による関係で決まるという意味にならない。"}], "correct_answer": "で", "explanations": {"で": "「相対で」は比べる相手との関係によって決まるという手段・根拠を示し、文に合う。", "へ": "「相対へ決まる」は方向を示す形になり、相対の関係が決まるという文意に合わない。", "の": "「相対の決まる」は名詞を修飾する形になり、後に続く名詞がないので文が成り立たない。", "より": "「相対より決まる」は比較を表す形になり、比べる相手による関係で決まるという意味にならない。"}, "error_tags": {"へ": "direction", "の": "genitive", "より": "comparison"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "絶対", "is_correct": true, "explanation": "対義語。比べる相手に左右されず成り立つという意味で、相対の反対にあたる。"}, {"text": "普遍", "is_correct": false, "explanation": "普遍はどこでも通じることを指し、比べる相手による関係を表す相対の対義語にはならない。"}, {"text": "中立", "is_correct": false, "explanation": "中立は立場に偏らないことを指し、相対と対になる関係にはならない。"}, {"text": "永遠", "is_correct": false, "explanation": "永遠は時間が終わらないことを指し、比べる相手による関係を表す相対の対義語とは言えない。"}], "correct_answer": "絶対", "explanations": {"絶対": "対義語。比べる相手に左右されず成り立つという意味で、相対の反対にあたる。", "普遍": "普遍はどこでも通じることを指し、比べる相手による関係を表す相対の対義語にはならない。", "中立": "中立は立場に偏らないことを指し、相対と対になる関係にはならない。", "永遠": "永遠は時間が終わらないことを指し、比べる相手による関係を表す相対の対義語とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36029, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものの間に、一方が変われば他方も変わるような関係があること。また、その関係。", "primary_collocate": null, "pronunciation": "そうたい", "ipa": "soːtai", "syllable_count": 4, "sentences": [{"text": "景気の良し悪しは、他の時期との相対で判断するものだ。", "target_word": "相対", "complexity_tier": "T3", "furigana": "景気(けいき)の良(よ)し悪(あ)しは、他(ほか)の時期(じき)との相対(そうたい)で判断(はんだん)するものだ。", "sentence_source": "generated"}, {"text": "美しさは絶対ではなく、見る人や周りとの相対で決まる。", "target_word": "相対", "complexity_tier": "T4", "furigana": "美(うつく)しさは絶対(ぜったい)ではなく、見(み)る人(ひと)や周(まわ)りとの相対(そうたい)で決(き)まる。", "sentence_source": "generated"}, {"text": "物の価値は相対であり、比べる相手が変われば高くも低くもなる。", "target_word": "相対", "complexity_tier": "T4", "furigana": "物(もの)の価値(かち)は相対(そうたい)であり、比(くら)べる相手(あいて)が変(か)われば高(たか)くも低(ひく)くもなる。", "sentence_source": "generated"}, {"text": "新幹線と比べれば自転車は遅いが、速さは相対で、比べる物が変われば答えも変わる。", "target_word": "相対", "complexity_tier": "T4", "furigana": "新幹線(しんかんせん)と比(くら)べれば自転車(じてんしゃ)は遅(おそ)いが、速(はや)さは相対(そうたい)で、比(くら)べる物(もの)が変(か)われば答(こた)えも変(か)わる。", "sentence_source": "generated"}, {"text": "大きいか小さいかは相対だから、比べる物がなければ決められない。", "target_word": "相対", "complexity_tier": "T3", "furigana": "大(おお)きいか小(ちい)さいかは相対(そうたい)だから、比(くら)べる物(もの)がなければ決(き)められない。", "sentence_source": "generated"}, {"text": "善と悪は相対の関係にあり、立場が変われば見え方も変わる。", "target_word": "相対", "complexity_tier": "T4", "furigana": "善(ぜん)と悪(あく)は相対(そうたい)の関係(かんけい)にあり、立場(たちば)が変(か)われば見(み)え方(かた)も変(か)わる。", "sentence_source": "generated"}, {"text": "彼の成績は高くないが、クラス全体との相対で見れば上位にいる。", "target_word": "相対", "complexity_tier": "T4", "furigana": "彼(かれ)の成績(せいせき)は高(たか)くないが、クラス全体(ぜんたい)との相対(そうたい)で見(み)れば上位(じょうい)にいる。", "sentence_source": "generated"}, {"text": "円が安いか高いかは、他の国のお金との相対で決まる。", "target_word": "相対", "complexity_tier": "T4", "furigana": "円(えん)が安(やす)いか高(たか)いかは、他(ほか)の国(くに)のお金(かね)との相対(そうたい)で決(き)まる。", "sentence_source": "generated"}, {"text": "同じ二十度でも、暑さの感じ方は直前の気温との相対で決まる。", "target_word": "相対", "complexity_tier": "T3", "furigana": "同(おな)じ二十度(にじゅうど)でも、暑(あつ)さの感(かん)じ方(かた)は直前(ちょくぜん)の気温(きおん)との相対(そうたい)で決(き)まる。", "sentence_source": "generated"}, {"text": "「正しさ」は絶対ではなく、時代との相対で変わるものだと彼は考えている。", "target_word": "相対", "complexity_tier": "T5", "furigana": "「正(ただ)しさ」は絶対(ぜったい)ではなく、時代(じだい)との相対(そうたい)で変(か)わるものだと彼(かれ)は考(かんが)えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "相対的", "label": "形容動詞的な派生形"}, {"form": "相対化", "label": "名詞派生形"}, {"form": "相対する", "label": "サ変動詞"}], "register": "formal", "sense_fingerprint": "比べる相手しだいで意味や価値が変わる関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36029, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相対", "is_correct": true, "explanation": "「との相対で判断する」は比べる相手との関係で判断するという意味で、文の流れに合う。"}, {"text": "偶然", "is_correct": false, "explanation": "「との偶然で判断する」は比べる関係を表せず、文の流れに合わない。"}, {"text": "独立", "is_correct": false, "explanation": "「との独立で判断する」は関係を断つ意味になり、比べる文脈と合わない。"}, {"text": "自由", "is_correct": false, "explanation": "「との自由で判断する」は比べ方として成り立たず、文意が通らない。"}], "explanations": {"相対": "「との相対で判断する」は比べる相手との関係で判断するという意味で、文の流れに合う。", "偶然": "「との偶然で判断する」は比べる関係を表せず、文の流れに合わない。", "独立": "「との独立で判断する」は関係を断つ意味になり、比べる文脈と合わない。", "自由": "「との自由で判断する」は比べ方として成り立たず、文意が通らない。"}, "sentence_index": 0, "correct_answer": "相対"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "どこで測っても変わらない、相対の長さだ。", "explanation": "ここは〈絶対〉の意味。相対は比べる相手によって変わることなので、どこで測っても変わらないという文に合わない。"}, {"text": "身長と体重には強い相対がある。", "explanation": "ここは〈相関〉の意味。二つの量が連動する関係を指す語で、相対は比べる相手によって値が変わるという意味なので合わない。"}, {"text": "二人の関係は相対の信頼で成り立っている。", "explanation": "ここは〈相互〉の意味。お互いに信頼し合うことは相互と言い、相対は比べ合わせて変わる関係を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36029, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相対", "is_correct": true, "explanation": "「との相対で見れば」はクラス全体と比べた関係で見るという意味になり、上位という評価に合う。"}, {"text": "感情", "is_correct": false, "explanation": "「との感情で見れば」は比べる関係を表せず、文意が通らない。"}, {"text": "単独", "is_correct": false, "explanation": "「との単独で見れば」は比べる関係として成り立たず、文意が通らない。"}, {"text": "極端", "is_correct": false, "explanation": "「との極端で見れば」は比べ方を表す形として不自然で、上位という評価と結びつかない。"}], "explanations": {"相対": "「との相対で見れば」はクラス全体と比べた関係で見るという意味になり、上位という評価に合う。", "感情": "「との感情で見れば」は比べる関係を表せず、文意が通らない。", "単独": "「との単独で見れば」は比べる関係として成り立たず、文意が通らない。", "極端": "「との極端で見れば」は比べ方を表す形として不自然で、上位という評価と結びつかない。"}, "sentence_index": 6, "correct_answer": "相対"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この二つの三角形は相対だ。", "explanation": "ここは〈相似〉の意味。形が同じ比率で似ていることを指す語で、相対は比べる相手によって変わるという意味なので合わない。"}, {"text": "今日のドルの相対が午後から下がった。", "explanation": "ここは〈相場〉の意味。市場で決まる値段の動きを指し、相対は比べる相手しだいで変わる関係を指すので合わない。"}, {"text": "収入に相対の生活を送っている。", "explanation": "ここは〈相応〉の意味。ふさわしく釣り合うことを指すので、比べる相手しだいで変わる関係を表す相対とは意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36029, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その店の評判は、近所の店との相対を決まる。", "corrected_sentence": "その店の評判は、近所の店との相対で決まる。", "error_description": "「相対で決まる」の「で」は比べる関係を手段・根拠として示す。「を」を使うと、目的語を取らない「決まる」と合わず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36029, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その基準は、周りとの相対に判断される。", "corrected_sentence": "その基準は、周りとの相対で判断される。", "error_description": "「判断される」は手段・根拠を表す「で」を取る。「に」にすると不自然な誤りになる。正しくは「相対で判断される」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
