INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36030, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "音の高さ。低い音と高い音のちがい。", "primary_collocate": null, "pronunciation": "おんこう", "ipa": "oŋkoː", "syllable_count": 4, "sentences": [{"text": "この楽器は、弦を締めると音高が上がります。", "target_word": "音高", "complexity_tier": "T3", "furigana": "この楽器[がっき]は、弦[げん]を締[し]めると音高[おんこう]が上[あ]がります。", "sentence_source": "generated"}, {"text": "笛の長さを変えると、音高も変わる。", "target_word": "音高", "complexity_tier": "T3", "furigana": "笛[ふえ]の長[なが]さを変[か]えると、音高[おんこう]も変[か]わる。", "sentence_source": "generated"}, {"text": "二つの音高がちがうので、すぐに聞き分けられた。", "target_word": "音高", "complexity_tier": "T3", "furigana": "二[ふた]つの音高[おんこう]がちがうので、すぐに聞[き]き分[わ]けられた。", "sentence_source": "generated"}, {"text": "音高が低いほど、太い音に聞こえる。", "target_word": "音高", "complexity_tier": "T3", "furigana": "音高[おんこう]が低[ひく]いほど、太[ふと]い音[おと]に聞[き]こえる。", "sentence_source": "generated"}, {"text": "声の音高は、のどの使い方で変わります。", "target_word": "音高", "complexity_tier": "T3", "furigana": "声[こえ]の音高[おんこう]は、のどの使[つか]い方[かた]で変[か]わります。", "sentence_source": "generated"}, {"text": "先生はピアノで音高を確かめてから歌い始めた。", "target_word": "音高", "complexity_tier": "T4", "furigana": "先生[せんせい]はピアノで音高[おんこう]を確[たし]かめてから歌[うた]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "赤ちゃんは、母親の声の音高に反応する。", "target_word": "音高", "complexity_tier": "T4", "furigana": "赤[あか]ちゃんは、母親[ははおや]の声[こえ]の音高[おんこう]に反応[はんのう]する。", "sentence_source": "generated"}, {"text": "救急車が近づくと、音高が高く聞こえる。", "target_word": "音高", "complexity_tier": "T4", "furigana": "救急車[きゅうきゅうしゃ]が近[ちか]づくと、音高[おんこう]が高[たか]く聞[き]こえる。", "sentence_source": "generated"}, {"text": "弦が短いと音高が高くなる。", "target_word": "音高", "complexity_tier": "T3", "furigana": "弦[げん]が短[みじか]いと音高[おんこう]が高[たか]くなる。", "sentence_source": "generated"}, {"text": "音高をそろえないと、合唱はきれいに聞こえない。", "target_word": "音高", "complexity_tier": "T3", "furigana": "音高[おんこう]をそろえないと、合唱[がっしょう]はきれいに聞[き]こえない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "音高", "label": "基本形"}, {"form": "音高が", "label": "主語形"}], "register": "中立", "sense_fingerprint": "音そのものの高い低いという性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36030, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音高", "is_correct": true, "explanation": "音の高さを表す語。『弦を締めると音高が上がる』で正しい。"}, {"text": "音色", "is_correct": false, "explanation": "音の質を表す語。高さが上がるとは言えない。"}, {"text": "手触り", "is_correct": false, "explanation": "触った感じを表す語。音には使えない。"}, {"text": "字幕", "is_correct": false, "explanation": "映像に出る文字。弦の文脈に合わず、上がるとも言えない。"}], "explanations": {"音高": "音の高さを表す語。『弦を締めると音高が上がる』で正しい。", "音色": "音の質を表す語。高さが上がるとは言えない。", "手触り": "触った感じを表す語。音には使えない。", "字幕": "映像に出る文字。弦の文脈に合わず、上がるとも言えない。"}, "sentence_index": 0, "correct_answer": "音高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このドラムは音高が大きいほど、遠くまで届く。", "explanation": "〈音高〉は音の高低を表す。音の大きさは〈音量〉を使う。"}, {"text": "このピアノは、音高の蓋が重くて開けにくい。", "explanation": "〈音高〉は音の高低を表す語。ふたの重さの話には合わない。"}, {"text": "教会の音高が長く続く。", "explanation": "〈音高〉は音の高低を表す。音が残る長さは〈響き〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36030, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音高", "is_correct": true, "explanation": "音の高さを表す語。『母親の声の音高に反応する』で自然に通る。"}, {"text": "味", "is_correct": false, "explanation": "味覚の感じ。声の高さへの反応を表す文には合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "においのこと。声には使わず、不自然。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度。声に反応する対象としては合わない。"}], "explanations": {"音高": "音の高さを表す語。『母親の声の音高に反応する』で自然に通る。", "味": "味覚の感じ。声の高さへの反応を表す文には合わない。", "匂い": "においのこと。声には使わず、不自然。", "体温": "体の温度。声に反応する対象としては合わない。"}, "sentence_index": 6, "correct_answer": "音高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この塔は音高が三十メートルある。", "explanation": "〈音高〉は音の高低を表す。建物の高さは〈高さ〉を使う。"}, {"text": "彼の音高は背の高さと同じくらいだ。", "explanation": "〈音高〉は音の高低を表す語。背の高さは〈身長〉と言う。"}, {"text": "この絵は、音高が暗くて重い感じがする。", "explanation": "〈音高〉は音の高さを表す。絵の色の濃さや調子は〈色調〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36030, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "太い弦は、ふつう音高を低い。", "corrected_sentence": "太い弦は、ふつう音高が低い。", "error_description": "『音高が低い』は主語を『が』で示す。『音高を低い』は誤りで、正しくは『音高が低い』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36030, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弦をゆるめると音高を下がる。", "corrected_sentence": "弦をゆるめると音高が下がる。", "error_description": "『下がる』は主語『音高』を『が』で示す。『音高を下がる』は誤りで、正しくは『音高が下がる』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36031, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞を修飾する『の』。『音高の差』で正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』。『音高が差を』では文の構造が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』。『音高へ差を』は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』。『音高を差を』と目的語が二つ並び、不自然。"}], "correct_answer": "の", "explanations": {"の": "名詞を修飾する『の』。『音高の差』で正しい。", "が": "主語の『が』。『音高が差を』では文の構造が崩れる。", "へ": "方向の『へ』。『音高へ差を』は意味が通らない。", "を": "目的語の『を』。『音高を差を』と目的語が二つ並び、不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36031, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の『を』。『音高を正しく聞き取る』で正しい。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』。比べる相手がなく、『音高より正しく』は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』。『音高へ正しく聞き取る』は不自然。"}, {"text": "の", "is_correct": false, "explanation": "修飾の『の』。『音高の正しく』は副詞句に続かず、不自然。"}], "correct_answer": "を", "explanations": {"を": "目的語の『を』。『音高を正しく聞き取る』で正しい。", "より": "比較の『より』。比べる相手がなく、『音高より正しく』は意味が通らない。", "へ": "方向の『へ』。『音高へ正しく聞き取る』は不自然。", "の": "修飾の『の』。『音高の正しく』は副詞句に続かず、不自然。"}, "error_tags": {"より": "比較", "へ": "方向", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36031, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音の高低。音楽で使われる、音の相対的な高さや低さを表す概念。", "primary_collocate": null, "pronunciation": "おんこう", "ipa": "oŋkoː", "syllable_count": 4, "sentences": [{"text": "楽譜は、音高と長さを記号で表したものだ。", "target_word": "音高", "complexity_tier": "T3", "furigana": "楽譜[がくふ]は、音高[おんこう]と長[なが]さを記号[きごう]で表[あらわ]したものだ。", "sentence_source": "generated"}, {"text": "音楽では、二つの音高の差を音程という。", "target_word": "音高", "complexity_tier": "T4", "furigana": "音楽[おんがく]では、二[ふた]つの音高[おんこう]の差[さ]を音程[おんてい]という。", "sentence_source": "generated"}, {"text": "絶対音感のある人は、音高をすぐに言い当てる。", "target_word": "音高", "complexity_tier": "T4", "furigana": "絶対音感[ぜったいおんかん]のある人[ひと]は、音高[おんこう]をすぐに言[い]い当[あ]てる。", "sentence_source": "generated"}, {"text": "この曲は、音高の変化が少なくて歌いやすい。", "target_word": "音高", "complexity_tier": "T3", "furigana": "この曲[きょく]は、音高[おんこう]の変化[へんか]が少[すく]なくて歌[うた]いやすい。", "sentence_source": "generated"}, {"text": "作曲では、音高とリズムの組み合わせを考える。", "target_word": "音高", "complexity_tier": "T4", "furigana": "作曲[さっきょく]では、音高[おんこう]とリズムの組[く]み合[あ]わせを考[かんが]える。", "sentence_source": "generated"}, {"text": "授業で、ドとレの音高の関係を学んだ。", "target_word": "音高", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、ドとレの音高[おんこう]の関係[かんけい]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "メロディーは音高が上下して作られる。", "target_word": "音高", "complexity_tier": "T3", "furigana": "メロディーは音高[おんこう]が上下[じょうげ]して作[つく]られる。", "sentence_source": "generated"}, {"text": "彼は音高を正しく聞き取る練習を続けている。", "target_word": "音高", "complexity_tier": "T4", "furigana": "彼[かれ]は音高[おんこう]を正[ただ]しく聞[き]き取[と]る練習[れんしゅう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "音高の並び方が変わると、曲の印象も変わる。", "target_word": "音高", "complexity_tier": "T4", "furigana": "音高[おんこう]の並[なら]び方[かた]が変[か]わると、曲[きょく]の印象[いんしょう]も変[か]わる。", "sentence_source": "generated"}, {"text": "楽器ごとに、出せる音高の範囲がちがう。", "target_word": "音高", "complexity_tier": "T4", "furigana": "楽器[がっき]ごとに、出[だ]せる音高[おんこう]の範囲[はんい]がちがう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "音高", "label": "基本形"}, {"form": "音高の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "音楽理論で旋律や音階を成り立たせる、音の相対的な高さの概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: 言い当てる (Zipf 2.22)','sentence 7 above tier T1: contains vocabulary far above tier T1: 聞き取る (Zipf 2.46)','sentence 8 above tier T1: contains vocabulary far above tier T1: 並び方 (Zipf 2.04)']::text[], '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36031, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音高", "is_correct": true, "explanation": "音楽で音の高さを表す語。楽譜に記す要素として正しい。"}, {"text": "演奏者", "is_correct": false, "explanation": "演奏する人。記号で表す対象ではない。"}, {"text": "指揮者", "is_correct": false, "explanation": "楽団を導く人。記号で表す対象ではない。"}, {"text": "拍手", "is_correct": false, "explanation": "手でたたく動作。楽譜に記す要素ではない。"}], "explanations": {"音高": "音楽で音の高さを表す語。楽譜に記す要素として正しい。", "演奏者": "演奏する人。記号で表す対象ではない。", "指揮者": "楽団を導く人。記号で表す対象ではない。", "拍手": "手でたたく動作。楽譜に記す要素ではない。"}, "sentence_index": 0, "correct_answer": "音高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この曲は、音高が広くて歌いにくい。", "explanation": "〈音高〉は一つの音の高さを指す。音の幅の広さは〈音域〉を使う。"}, {"text": "この曲は、音高が大きくてホールに響く。", "explanation": "〈音高〉は音の高低を指す。音の大きさは〈音量〉を使う。"}, {"text": "この曲は、音高の豊かさが魅力だ。", "explanation": "〈音高〉は高低を指す。音の質の豊かさは〈音色〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36031, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音高", "is_correct": true, "explanation": "旋律を作る要素の音の高さ。『メロディーは音高が上下して』で自然に通る。"}, {"text": "体重", "is_correct": false, "explanation": "人の重さ。旋律には関係しない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数。旋律には関係しない。"}, {"text": "住所", "is_correct": false, "explanation": "住んでいる場所。旋律には関係しない。"}], "explanations": {"音高": "旋律を作る要素の音の高さ。『メロディーは音高が上下して』で自然に通る。", "体重": "人の重さ。旋律には関係しない。", "年齢": "人の年数。旋律には関係しない。", "住所": "住んでいる場所。旋律には関係しない。"}, "sentence_index": 6, "correct_answer": "音高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この音は音高が三拍ある。", "explanation": "〈音高〉は音の高低を指す。拍の長さは〈長さ〉を使う。"}, {"text": "この曲は音高が速く、踊りやすい。", "explanation": "〈音高〉は高低を指す。曲の速さは〈テンポ〉を使う。"}, {"text": "この曲は音高が四分の四拍子だ。", "explanation": "〈音高〉は音の高低を指す。拍の組み方は〈拍子〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36031, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドレミは、音高を低い順に並んでいる。", "corrected_sentence": "ドレミは、音高の低い順に並んでいる。", "error_description": "『音高の低い順』は『の』で修飾する。『音高を低い』は誤りで、正しくは『音高の低い』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36031, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "音階は、音高を叩いて作る。", "corrected_sentence": "音階は、音高を並べて作る。", "error_description": "音階は音高を順に並べて作るので、『叩いて』は誤り。正しくは『並べて』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36032, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「障害がある」の対象を示す「に」。「視覚に障害がある」と成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「視覚を障害があっても」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「視覚で障害」では意味がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「視覚へ障害」は不自然で、障害の対象を表せない。"}], "correct_answer": "に", "explanations": {"に": "「障害がある」の対象を示す「に」。「視覚に障害がある」と成り立つ。", "を": "「を」は目的語を示す。「視覚を障害があっても」では文が成り立たない。", "で": "「で」は手段や場所を示す。「視覚で障害」では意味がつながらない。", "へ": "「へ」は方向を示す。「視覚へ障害」は不自然で、障害の対象を表せない。"}, "error_tags": {"を": "object", "で": "means", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
