INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36032, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目で見てわかること。", "primary_collocate": null, "pronunciation": "しかく", "ipa": "ɕikaku", "syllable_count": 3, "sentences": [{"text": "視覚は、人が外の世界を知る大切な感覚です。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "視覚[しかく]は、人[ひと]が外[そと]の世界[せかい]を知[し]る大切[たいせつ]な感覚[かんかく]です。", "sentence_source": "generated"}, {"text": "視覚に障害があっても、音や手ざわりで多くを感じ取れる。", "target_word": "視覚", "complexity_tier": "T4", "furigana": "視覚[しかく]に障害[しょうがい]があっても、音[おと]や手[て]ざわりで多[おお]くを感[かん]じ取[と]れる。", "sentence_source": "generated"}, {"text": "暗い部屋では、視覚だけに頼ることができない。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "暗[くら]い部屋[へや]では、視覚[しかく]だけに頼[たよ]ることができない。", "sentence_source": "generated"}, {"text": "事故のあと、彼は視覚を失った。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、彼[かれ]は視覚[しかく]を失[うしな]った。", "sentence_source": "generated"}, {"text": "犬は嗅覚が強いが、視覚は人間ほど色を見分けられない。", "target_word": "視覚", "complexity_tier": "T4", "furigana": "犬[いぬ]は嗅覚[きゅうかく]が強[つよ]いが、視覚[しかく]は人間[にんげん]ほど色[いろ]を見分[みわ]けられない。", "sentence_source": "generated"}, {"text": "視覚と聴覚の両方を使うと、内容が覚えやすい。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "視覚[しかく]と聴覚[ちょうかく]の両方[りょうほう]を使[つか]うと、内容[ないよう]が覚[おぼ]えやすい。", "sentence_source": "generated"}, {"text": "図やグラフは、視覚に訴えて情報を伝える。", "target_word": "視覚", "complexity_tier": "T4", "furigana": "図[ず]やグラフは、視覚[しかく]に訴[うった]えて情報[じょうほう]を伝[つた]える。", "sentence_source": "generated"}, {"text": "疲れると、視覚がぼやけて文字が読みにくくなる。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "疲[つか]れると、視覚[しかく]がぼやけて文字[もじ]が読[よ]みにくくなる。", "sentence_source": "generated"}, {"text": "目を閉じると、視覚以外の感覚が強くなる。", "target_word": "視覚", "complexity_tier": "T3", "furigana": "目[め]を閉[と]じると、視覚[しかく]以外[いがい]の感覚[かんかく]が強[つよ]くなる。", "sentence_source": "generated"}, {"text": "視覚で確かめた情報は、人にとって信じやすい。", "target_word": "視覚", "complexity_tier": "T4", "furigana": "視覚[しかく]で確[たし]かめた情報[じょうほう]は、人[ひと]にとって信[しん]じやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "視覚", "label": "基本形"}, {"form": "視覚を", "label": "目的語形"}], "register": "中立", "sense_fingerprint": "目で見て物の形や色を感じ取る感覚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 手ざわり (Zipf 1.62)']::text[], '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36032, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "視覚", "is_correct": true, "explanation": "主語の位置に入り、「人が外の世界を知る大切な感覚」と文意が通る。目で見てわかる働きを指す語で、ここでは正解。"}, {"text": "会議", "is_correct": false, "explanation": "「会議は大切な感覚です」は成り立たない。会議は感覚ではないので合わない。"}, {"text": "家計", "is_correct": false, "explanation": "「家計は大切な感覚です」は意味が通らない。家計は感覚を表さないので合わない。"}, {"text": "保険", "is_correct": false, "explanation": "「保険は大切な感覚です」は意味が通らない。保険は感覚ではないので合わない。"}], "explanations": {"視覚": "主語の位置に入り、「人が外の世界を知る大切な感覚」と文意が通る。目で見てわかる働きを指す語で、ここでは正解。", "会議": "「会議は大切な感覚です」は成り立たない。会議は感覚ではないので合わない。", "家計": "「家計は大切な感覚です」は意味が通らない。家計は感覚を表さないので合わない。", "保険": "「保険は大切な感覚です」は意味が通らない。保険は感覚ではないので合わない。"}, "sentence_index": 0, "correct_answer": "視覚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作者の視覚から物語を読むと、新しい発見がある。", "explanation": "ここは〈視点〉の意味。視覚は目の働きそのものを指し、物の見方や立場の意味では使わないので合わない。"}, {"text": "彼は視覚をそらして、黙って窓の外を見た。", "explanation": "ここは〈視線〉の意味。「視線をそらす」とは言うが、「視覚をそらす」とは言わないので合わない。"}, {"text": "彼は耳を傾ける代わりに、視覚を傾けて先生の話を聞いた。", "explanation": "ここは〈注意〉の意味。「注意を傾ける」は注意して聞くことだが、視覚は目の働きそのものなので傾けられず、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36032, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "視覚", "is_correct": true, "explanation": "「訴える」の対象になる感覚で、「視覚に訴えて情報を伝える」と文意が通る。正解。"}, {"text": "現金", "is_correct": false, "explanation": "「現金に訴える」は成り立たず、文脈にも合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気に訴える」は不自然で、図やグラフの話とつながらない。"}, {"text": "時計", "is_correct": false, "explanation": "「時計に訴えて情報を伝える」は意味が通らないので合わない。"}], "explanations": {"視覚": "「訴える」の対象になる感覚で、「視覚に訴えて情報を伝える」と文意が通る。正解。", "現金": "「現金に訴える」は成り立たず、文脈にも合わない。", "天気": "「天気に訴える」は不自然で、図やグラフの話とつながらない。", "時計": "「時計に訴えて情報を伝える」は意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "視覚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は温かい視覚で子どもを見守った。", "explanation": "ここは〈眼差し〉の意味。温かい眼差しは気持ちのこもった見方だが、視覚は目の働きそのものなので合わない。"}, {"text": "赤い屋根を視覚にしておくと、駅の出口で迷わない。", "explanation": "ここは〈目印〉の意味。「目印にする」とは言うが、「視覚にする」とは言わないので合わない。"}, {"text": "この温度計は、部屋の視覚を測る。", "explanation": "ここは〈室温〉の意味。温度計で測るのは温度で、感覚の視覚は測れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36032, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の夜は、視覚を頼って運転するのが難しい。", "corrected_sentence": "雨の夜は、視覚に頼って運転するのが難しい。", "error_description": "「頼る」は助詞「に」を取る。「を」は誤りで、正しくは「視覚に頼る」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36032, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "視覚が高いので、遠くの看板がよく見える。", "corrected_sentence": "視覚が鋭いので、遠くの看板がよく見える。", "error_description": "感覚の働きの良さは「鋭い」で表す。「高い」は視力の数値などに使うので、ここは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36034, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「図書館の貸し出しシステム」を主題として示し、「簡単です」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「とても簡単です」という形容詞文では目的語が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すが、「システムに、とても簡単です」は文として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すが、ここでは「システムと、とても簡単です」と文が続かない。"}], "correct_answer": "は", "explanations": {"は": "「図書館の貸し出しシステム」を主題として示し、「簡単です」と続く。", "を": "「を」は目的語を示すが、「とても簡単です」という形容詞文では目的語が成り立たない。", "に": "「に」は方向や相手を示すが、「システムに、とても簡単です」は文として不自然。", "と": "「と」は並列を示すが、ここでは「システムと、とても簡単です」と文が続かない。"}, "error_tags": {"を": "object", "に": "dative", "と": "comitative"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36034, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「システム」が「動く」の主語であることを示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は動きの向かう先を示すが、「システムへ、きちんと動く」は文として成り立たず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「システムから、きちんと動く」は主語関係を表せず文に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐので、「システムの、きちんと動く」は動詞の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「システム」が「動く」の主語であることを示す。", "へ": "「へ」は動きの向かう先を示すが、「システムへ、きちんと動く」は文として成り立たず不自然。", "から": "「から」は起点を示すが、「システムから、きちんと動く」は主語関係を表せず文に合わない。", "の": "「の」は名詞どうしをつなぐので、「システムの、きちんと動く」は動詞の主語を示せない。"}, "error_tags": {"へ": "direction", "から": "source", "の": "genitive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36034, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものがきちんと動くためのしくみ", "primary_collocate": null, "pronunciation": "しすてむ", "ipa": "ɕisɯtemɯ", "syllable_count": 4, "sentences": [{"text": "駅の新しいシステムで、切符がなくても電車に乗れます。", "target_word": "システム", "complexity_tier": "T3", "furigana": "駅[えき]の新[あたら]しいシステムで、切符[きっぷ]がなくても電車[でんしゃ]に乗[の]れます。", "sentence_source": "generated"}, {"text": "図書館の貸し出しシステムは、とても簡単です。", "target_word": "システム", "complexity_tier": "T3", "furigana": "図書館[としょかん]の貸[か]し出[だ]しシステムは、とても簡単[かんたん]です。", "sentence_source": "generated"}, {"text": "システムが止まったので、銀行の機械が使えません。", "target_word": "システム", "complexity_tier": "T3", "furigana": "システムが止[と]まったので、銀行[ぎんこう]の機械[きかい]が使[つか]えません。", "sentence_source": "generated"}, {"text": "会社は古いシステムを新しいものにかえました。", "target_word": "システム", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は古[ふる]いシステムを新[あたら]しいものにかえました。", "sentence_source": "generated"}, {"text": "この学校には、生徒が自由に本を借りられるシステムがあります。", "target_word": "システム", "complexity_tier": "T3", "furigana": "この学校[がっこう]には、生徒[せいと]が自由[じゆう]に本[ほん]を借[か]りられるシステムがあります。", "sentence_source": "generated"}, {"text": "雨の水を集めて使うシステムを、家に取り付けました。", "target_word": "システム", "complexity_tier": "T3", "furigana": "雨[あめ]の水[みず]を集[あつ]めて使[つか]うシステムを、家[いえ]に取[と]り付[つ]けました。", "sentence_source": "generated"}, {"text": "システムのエラーで、予約が消えてしまいました。", "target_word": "システム", "complexity_tier": "T3", "furigana": "システムのエラーで、予約[よやく]が消[き]えてしまいました。", "sentence_source": "generated"}, {"text": "工場のシステムがきちんと動くように、毎日点検します。", "target_word": "システム", "complexity_tier": "T3", "furigana": "工場[こうじょう]のシステムがきちんと動[うご]くように、毎日[まいにち]点検[てんけん]します。", "sentence_source": "generated"}, {"text": "買い物のポイントのシステムは、少しわかりにくいです。", "target_word": "システム", "complexity_tier": "T3", "furigana": "買[か]い物[もの]のポイントのシステムは、少[すこ]しわかりにくいです。", "sentence_source": "generated"}, {"text": "新しいシステムに慣れるまで、時間がかかります。", "target_word": "システム", "complexity_tier": "T3", "furigana": "新[あたら]しいシステムに慣[な]れるまで、時間[じかん]がかかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "システム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "いくつかの部分がまとまって、きちんと動くようにできた仕組み・体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36034, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "システム", "is_correct": true, "explanation": "「新しいシステムで、切符がなくても乗れる」は、仕組み・体系という意味で自然に成り立つ。"}, {"text": "ペンキ", "is_correct": false, "explanation": "ペンキは塗料で、切符なしで電車に乗れる仕組みとは結びつかない。"}, {"text": "教科書", "is_correct": false, "explanation": "「新しい教科書で乗れる」は意味が通らない。教科書は学習用の本で、乗車の仕組みを表さない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "ハンカチは持ち物で、「新しいハンカチで電車に乗れる」は文として成り立たない。"}], "explanations": {"システム": "「新しいシステムで、切符がなくても乗れる」は、仕組み・体系という意味で自然に成り立つ。", "ペンキ": "ペンキは塗料で、切符なしで電車に乗れる仕組みとは結びつかない。", "教科書": "「新しい教科書で乗れる」は意味が通らない。教科書は学習用の本で、乗車の仕組みを表さない。", "ハンカチ": "ハンカチは持ち物で、「新しいハンカチで電車に乗れる」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "システム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このカフェは落ち着いたシステムで、勉強がはかどる。", "explanation": "ここは〈雰囲気〉の意味。システムは仕組みを指すので、場の落ち着いた空気を表す言い方にはならない。"}, {"text": "役所でシステムを済ませて、そのまま帰った。", "explanation": "ここは〈手続き〉の意味。システムは仕組みを指すので、役所で行う決まった手続きは表せず、「済ませる」の目的語にはならない。"}, {"text": "この部屋のシステムは、ほのかに甘い香りがする。", "explanation": "ここは〈におい〉の意味。システムは仕組みを指すので、部屋に漂う香りは表せず、「甘い香りがする」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36034, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "システム", "is_correct": true, "explanation": "「システムのエラー」は、仕組みとしての装置や体系の不具合を表し、予約が消えた状況に合う。"}, {"text": "カーテン", "is_correct": false, "explanation": "「カーテンのエラー」は意味をなさない。カーテンはエラーを起こす仕組みではない。"}, {"text": "ランチ", "is_correct": false, "explanation": "「ランチのエラー」は不自然で、予約が消えた原因として成り立たない。"}, {"text": "ハンガー", "is_correct": false, "explanation": "ハンガーは衣類を掛ける道具で、予約システムの不具合の説明にはならない。"}], "explanations": {"システム": "「システムのエラー」は、仕組みとしての装置や体系の不具合を表し、予約が消えた状況に合う。", "カーテン": "「カーテンのエラー」は意味をなさない。カーテンはエラーを起こす仕組みではない。", "ランチ": "「ランチのエラー」は不自然で、予約が消えた原因として成り立たない。", "ハンガー": "ハンガーは衣類を掛ける道具で、予約システムの不具合の説明にはならない。"}, "sentence_index": 6, "correct_answer": "システム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はシステムが派手で、すぐ目立つ。", "explanation": "ここは〈外見〉の意味。システムは仕組みを指すので、人の見た目の派手さには使わない。"}, {"text": "この旅行のシステムは、温泉に入ることだ。", "explanation": "ここは〈目的〉の意味。システムは方法や仕組みを指し、目指すことを表さないので合わない。"}, {"text": "今日はシステムがよくて、散歩に出かけた。", "explanation": "ここは〈気分〉の意味。システムは機械的な仕組みで、そのときの心の状態は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36034, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市役所は新しいシステムに、住民票を発行しています。", "corrected_sentence": "市役所は新しいシステムで、住民票を発行しています。", "error_description": "「システムで（〜を使って）」と手段を表す「で」が正しい。「に」になっているのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36034, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場のシステムを止まったので、生産が遅れました。", "corrected_sentence": "工場のシステムが止まったので、生産が遅れました。", "error_description": "自動詞「止まる」の主語には「が」を使う。「を」を付けたのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
