INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36036, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「確立が急がれている」と主語を示す「が」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「急がれる」は受身なので「確立を急がれる」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示す。「確立に急がれる」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「確立で急がれる」は不自然で文意に合わない。"}], "correct_answer": "が", "explanations": {"が": "「確立が急がれている」と主語を示す「が」。正解。", "を": "「を」は目的語を示す。「急がれる」は受身なので「確立を急がれる」は不自然。", "に": "「に」は方向や相手を示す。「確立に急がれる」は成り立たない。", "で": "「で」は手段や場所を示す。「確立で急がれる」は不自然で文意に合わない。"}, "error_tags": {"を": "object", "に": "direction", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36036, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かがしっかりと決まって、変わらなくなること。", "primary_collocate": null, "pronunciation": "かくりつ", "ipa": "kakuɾitsɯ", "syllable_count": 4, "sentences": [{"text": "この会社は、独自の技術を確立した。", "target_word": "確立", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、独自[どくじ]の技術[ぎじゅつ]を確立[かくりつ]した。", "sentence_source": "generated"}, {"text": "長い議論の末、新しいルールが確立された。", "target_word": "確立", "complexity_tier": "T3", "furigana": "長[なが]い議論[ぎろん]の末[すえ]、新[あたら]しいルールが確立[かくりつ]された。", "sentence_source": "generated"}, {"text": "研究者たちは、治療の方法を確立するために実験を重ねた。", "target_word": "確立", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]たちは、治療[ちりょう]の方法[ほうほう]を確立[かくりつ]するために実験[じっけん]を重[かさ]ねた。", "sentence_source": "generated"}, {"text": "生活のリズムを確立すると、毎日が楽になる。", "target_word": "確立", "complexity_tier": "T3", "furigana": "生活[せいかつ]のリズムを確立[かくりつ]すると、毎日[まいにち]が楽[らく]になる。", "sentence_source": "generated"}, {"text": "彼は若くして、画家としての地位を確立した。", "target_word": "確立", "complexity_tier": "T3", "furigana": "彼[かれ]は若[わか]くして、画家[がか]としての地位[ちい]を確立[かくりつ]した。", "sentence_source": "generated"}, {"text": "国の信頼を確立するには、時間がかかる。", "target_word": "確立", "complexity_tier": "T4", "furigana": "国[くに]の信頼[しんらい]を確立[かくりつ]するには、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "基本の型が確立していないうちは、自由に変えない方がいい。", "target_word": "確立", "complexity_tier": "T4", "furigana": "基本[きほん]の型[かた]が確立[かくりつ]していないうちは、自由[じゆう]に変[か]えない方[ほう]がいい。", "sentence_source": "generated"}, {"text": "安全な制度の確立が急がれている。", "target_word": "確立", "complexity_tier": "T4", "furigana": "安全[あんぜん]な制度[せいど]の確立[かくりつ]が急[いそ]がれている。", "sentence_source": "generated"}, {"text": "彼女は自分のスタイルを確立し、多くのファンを得た。", "target_word": "確立", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]のスタイルを確立[かくりつ]し、多[おお]くのファンを得[え]た。", "sentence_source": "generated"}, {"text": "方法が確立してから、作業の失敗がなくなった。", "target_word": "確立", "complexity_tier": "T3", "furigana": "方法[ほうほう]が確立[かくりつ]してから、作業[さぎょう]の失敗[しっぱい]がなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "確立", "label": "基本形"}, {"form": "確立する", "label": "辞書形"}, {"form": "確立した", "label": "過去形"}, {"form": "確立される", "label": "受身形"}, {"form": "確立して", "label": "て形"}], "register": "やや硬い", "sense_fingerprint": "制度・方法・地位などが固まって、安定して動かなくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36036, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "確立", "is_correct": true, "explanation": "「技術を〜する」と結び、技術を固めて安定させる意味になる。正解。"}, {"text": "散歩", "is_correct": false, "explanation": "「技術を散歩する」は成り立たず、文の意味が通らない。"}, {"text": "渋滞", "is_correct": false, "explanation": "「技術を渋滞する」は不自然で、文脈にも合わない。"}, {"text": "謝罪", "is_correct": false, "explanation": "「技術を謝罪する」は成り立たないので合わない。"}], "explanations": {"確立": "「技術を〜する」と結び、技術を固めて安定させる意味になる。正解。", "散歩": "「技術を散歩する」は成り立たず、文の意味が通らない。", "渋滞": "「技術を渋滞する」は不自然で、文脈にも合わない。", "謝罪": "「技術を謝罪する」は成り立たないので合わない。"}, "sentence_index": 0, "correct_answer": "確立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は雨が降る確立が高い。", "explanation": "ここは〈確率〉の意味。「確率が高い」は可能性を表すが、確立は制度や方法が固まる意味なので合わない。"}, {"text": "新しい橋が確立された。", "explanation": "ここは〈建設〉の意味。橋は建設するもので、固まって安定することを表す確立は合わない。"}, {"text": "この町に新しい会社を確立した。", "explanation": "ここは〈設立〉の意味。会社は設立するもので、制度や方法が固まる意味の確立は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36036, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "確立", "is_correct": true, "explanation": "「〜していないうちは」と続き、型が固まっていない状態を表す。正解。"}, {"text": "停電", "is_correct": false, "explanation": "「型が停電していない」は意味が通らない。"}, {"text": "微笑", "is_correct": false, "explanation": "「型が微笑していない」は成り立たないので合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "「型が解雇していない」は不自然で、文脈に合わない。"}], "explanations": {"確立": "「〜していないうちは」と続き、型が固まっていない状態を表す。正解。", "停電": "「型が停電していない」は意味が通らない。", "微笑": "「型が微笑していない」は成り立たないので合わない。", "解雇": "「型が解雇していない」は不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "確立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、その道で事故が確立した。", "explanation": "ここは〈発生〉の意味。事故は起こるもので、制度や方法が固まる意味の確立は合わない。"}, {"text": "来年の入社が確立した。", "explanation": "ここは〈確定〉の意味。入社などの予定が決まる場合は確定を使い、確立は合わない。"}, {"text": "新しいビルが確立した。", "explanation": "ここは〈完成〉の意味。建物は完成するもので、確立とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36036, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "安全な制度の確立を向けて、会議が開かれた。", "corrected_sentence": "安全な制度の確立に向けて、会議が開かれた。", "error_description": "「確立に向けて」と結ぶ。「確立を向けて」は誤りで、助詞は「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36036, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい手順の確立に急ぐ必要がある。", "corrected_sentence": "新しい手順の確立を急ぐ必要がある。", "error_description": "「急ぐ」は目的語に「を」を取る。「に」は誤りで、正しくは「確立を急ぐ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
