INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36038, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「私の横にぴったりついて」と位置を示す「に」。正解。"}, {"text": "の", "is_correct": false, "explanation": "「横の」は名詞に続く形で、「私の横の、ぴったりついて歩いた」は文が切れて不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「横より」では歩く位置の意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「私の横から」では、そばにぴったりつく動きと合わない。"}], "correct_answer": "に", "explanations": {"に": "「私の横にぴったりついて」と位置を示す「に」。正解。", "の": "「横の」は名詞に続く形で、「私の横の、ぴったりついて歩いた」は文が切れて不自然。", "より": "「より」は比較を示す。「横より」では歩く位置の意味にならない。", "から": "「から」は起点を示す。「私の横から」では、そばにぴったりつく動きと合わない。"}, "error_tags": {"の": "possessive", "より": "comparison", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36038, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物や人のすぐそば、かたわらにあること。", "primary_collocate": null, "pronunciation": "よこ", "ipa": "joko", "syllable_count": 2, "sentences": [{"text": "駅の横に小さな花屋があります。", "target_word": "横", "complexity_tier": "T3", "furigana": "駅[えき]の横[よこ]に小[ちい]さな花屋[はなや]があります。", "sentence_source": "generated"}, {"text": "母の横で、妹が絵本を読んでいます。", "target_word": "横", "complexity_tier": "T3", "furigana": "母[はは]の横[よこ]で、妹[いもうと]が絵本[えほん]を読[よ]んでいます。", "sentence_source": "generated"}, {"text": "道の横を、きれいな川が流れています。", "target_word": "横", "complexity_tier": "T3", "furigana": "道[みち]の横[よこ]を、きれいな川[かわ]が流[なが]れています。", "sentence_source": "generated"}, {"text": "疲れたので、ソファの横に荷物を置いて座った。", "target_word": "横", "complexity_tier": "T3", "furigana": "疲[つか]れたので、ソファの横[よこ]に荷物[にもつ]を置[お]いて座[すわ]った。", "sentence_source": "generated"}, {"text": "バスの横に立っていた男の人が、急に歩き出した。", "target_word": "横", "complexity_tier": "T3", "furigana": "バスの横[よこ]に立[た]っていた男[おとこ]の人[ひと]が、急[きゅう]に歩[ある]き出[だ]した。", "sentence_source": "generated"}, {"text": "ベッドの横に、小さな机を置きました。", "target_word": "横", "complexity_tier": "T3", "furigana": "ベッドの横[よこ]に、小[ちい]さな机[つくえ]を置[お]きました。", "sentence_source": "generated"}, {"text": "彼の横に座ると、いつも安心します。", "target_word": "横", "complexity_tier": "T3", "furigana": "彼[かれ]の横[よこ]に座[すわ]ると、いつも安心[あんしん]します。", "sentence_source": "generated"}, {"text": "犬は私の横にぴったりついて歩いた。", "target_word": "横", "complexity_tier": "T3", "furigana": "犬[いぬ]は私[わたし]の横[よこ]にぴったりついて歩[ある]いた。", "sentence_source": "generated"}, {"text": "郵便局は銀行の横にあるので、すぐ分かります。", "target_word": "横", "complexity_tier": "T3", "furigana": "郵便局[ゆうびんきょく]は銀行[ぎんこう]の横[よこ]にあるので、すぐ分[わ]かります。", "sentence_source": "generated"}, {"text": "先生の横に立つと、緊張して声が出なかった。", "target_word": "横", "complexity_tier": "T3", "furigana": "先生[せんせい]の横[よこ]に立[た]つと、緊張[きんちょう]して声[こえ]が出[で]なかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "横", "label": "基本形"}, {"form": "横に", "label": "に格"}, {"form": "横の", "label": "連体形"}], "register": "中立（日常語）", "sense_fingerprint": "物や人のすぐそば、かたわらの位置を表す「横」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36038, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "横", "is_correct": true, "explanation": "「駅の横に」で、駅のすぐそばに花屋がある位置を表す。正解。"}, {"text": "切符", "is_correct": false, "explanation": "「駅の切符に小さな花屋があります」は意味が通らない。"}, {"text": "運賃", "is_correct": false, "explanation": "「駅の運賃に花屋がある」は成り立たず、位置を表さない。"}, {"text": "時給", "is_correct": false, "explanation": "「駅の時給に花屋がある」は意味が通らないので合わない。"}], "explanations": {"横": "「駅の横に」で、駅のすぐそばに花屋がある位置を表す。正解。", "切符": "「駅の切符に小さな花屋があります」は意味が通らない。", "運賃": "「駅の運賃に花屋がある」は成り立たず、位置を表さない。", "時給": "「駅の時給に花屋がある」は意味が通らないので合わない。"}, "sentence_index": 0, "correct_answer": "横"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "横の下がかゆくて、ずっと掻いていた。", "explanation": "ここは〈脇〉の意味。体の脇の下は「脇の下」と言い、「横の下」とは言わないので合わない。"}, {"text": "彼は横の下の力持ちとして、会を支えてきた。", "explanation": "ここは〈縁〉の意味。「縁の下の力持ち」は目立たず支える人を表す慣用句で、「横の下の力持ち」とは言わないので合わない。"}, {"text": "役人に横の下を渡すなど、許されない。", "explanation": "ここは〈袖〉の意味。「袖の下を渡す」は賄賂を渡すことを表す慣用句で、「横の下を渡す」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36038, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "横", "is_correct": true, "explanation": "「彼の横に座る」で、彼のすぐそばに座ることを表す。正解。"}, {"text": "夢", "is_correct": false, "explanation": "「彼の夢に座る」は成り立たず、文脈にも合わない。"}, {"text": "悲しみ", "is_correct": false, "explanation": "「彼の悲しみに座る」は意味が通らないので合わない。"}, {"text": "名刺", "is_correct": false, "explanation": "「彼の名刺に座ると」は不自然で、位置を表さない。"}], "explanations": {"横": "「彼の横に座る」で、彼のすぐそばに座ることを表す。正解。", "夢": "「彼の夢に座る」は成り立たず、文脈にも合わない。", "悲しみ": "「彼の悲しみに座る」は意味が通らないので合わない。", "名刺": "「彼の名刺に座ると」は不自然で、位置を表さない。"}, "sentence_index": 6, "correct_answer": "横"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この柱は横に高くて、天井まで届く。", "explanation": "高さは縦で表すので、「横に高い」とは言えず、水平方向の横とは合わないので誤り。"}, {"text": "彼女は横に高い声で歌った。", "explanation": "ここは〈音程〉の意味。声の高さは「声が高い」で表し、「横に高い声」とは言わないので合わない。"}, {"text": "このビルは横に深い。", "explanation": "ここは〈奥行き〉の意味。奥行きは「奥」や「深い」で表し、「横に深い」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36038, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベッドの横を、本棚を置きます。", "corrected_sentence": "ベッドの横に、本棚を置きます。", "error_description": "「置く」の場所は助詞「に」で示す。「横を」は目的語の位置に来るので誤りで、正しくは「横に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
