INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36039, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "縦に対して、左右に広がる水平の方向。", "primary_collocate": null, "pronunciation": "よこ", "ipa": "joko", "syllable_count": 2, "sentences": [{"text": "画面を横にすると、動画が大きく見えます。", "target_word": "横", "complexity_tier": "T3", "furigana": "画面[がめん]を横[よこ]にすると、動画[どうが]が大[おお]きく見[み]えます。", "sentence_source": "generated"}, {"text": "横の線を一本引いて、表を作ります。", "target_word": "横", "complexity_tier": "T3", "furigana": "横[よこ]の線[せん]を一本[いっぽん]引[ひ]いて、表[ひょう]を作[つく]ります。", "sentence_source": "generated"}, {"text": "この箱は縦より横のほうが長い。", "target_word": "横", "complexity_tier": "T3", "furigana": "この箱[はこ]は縦[たて]より横[よこ]のほうが長[なが]い。", "sentence_source": "generated"}, {"text": "首を横に振って、いやだと伝えた。", "target_word": "横", "complexity_tier": "T3", "furigana": "首[くび]を横[よこ]に振[ふ]って、いやだと伝[つた]えた。", "sentence_source": "generated"}, {"text": "横の列に、生徒が十人ずつ並んでいます。", "target_word": "横", "complexity_tier": "T3", "furigana": "横[よこ]の列[れつ]に、生徒[せいと]が十人[じゅうにん]ずつ並[なら]んでいます。", "sentence_source": "generated"}, {"text": "横に広い部屋なので、大きいテーブルが置けます。", "target_word": "横", "complexity_tier": "T3", "furigana": "横[よこ]に広[ひろ]い部屋[へや]なので、大[おお]きいテーブルが置[お]けます。", "sentence_source": "generated"}, {"text": "ノートを横にして、地図を書きました。", "target_word": "横", "complexity_tier": "T3", "furigana": "ノートを横[よこ]にして、地図[ちず]を書[か]きました。", "sentence_source": "generated"}, {"text": "横の長さを測ってから、カーテンを買います。", "target_word": "横", "complexity_tier": "T3", "furigana": "横[よこ]の長[なが]さを測[はか]ってから、カーテンを買[か]います。", "sentence_source": "generated"}, {"text": "この写真は横に長いので、壁の端から端まで飾れます。", "target_word": "横", "complexity_tier": "T3", "furigana": "この写真[しゃしん]は横[よこ]に長[なが]いので、壁[かべ]の端[はし]から端[はし]まで飾[かざ]れます。", "sentence_source": "generated"}, {"text": "文字を横に並べると、読みやすくなります。", "target_word": "横", "complexity_tier": "T3", "furigana": "文字[もじ]を横[よこ]に並[なら]べると、読[よ]みやすくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "横", "label": "基本形"}, {"form": "横に", "label": "に格"}, {"form": "横の", "label": "連体形"}], "register": "中立（日常語）", "sense_fingerprint": "縦に対する、左右に広がる水平の方向としての「横」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36039, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "横", "is_correct": true, "explanation": "「横にすると」で、画面を水平の向きにする意味になる。正解。"}, {"text": "音楽", "is_correct": false, "explanation": "「画面を音楽にすると」は成り立たず、意味が通らない。"}, {"text": "満足", "is_correct": false, "explanation": "「画面を満足にすると」は不自然で、文脈に合わない。"}, {"text": "雑談", "is_correct": false, "explanation": "「画面を雑談にすると」は意味が通らないので合わない。"}], "explanations": {"横": "「横にすると」で、画面を水平の向きにする意味になる。正解。", "音楽": "「画面を音楽にすると」は成り立たず、意味が通らない。", "満足": "「画面を満足にすると」は不自然で、文脈に合わない。", "雑談": "「画面を雑談にすると」は意味が通らないので合わない。"}, "sentence_index": 0, "correct_answer": "横"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ろうそくを横に立てて、火をともした。", "explanation": "縦方向に立てるものに「横」を使っており、水平方向の意味と合わず誤り。"}, {"text": "この棚は横が高くて、天井まで届く。", "explanation": "高さは縦で表すので、「横が高い」とは言えず、水平方向の意味と合わず誤り。"}, {"text": "ビルが横にそびえ立っている。", "explanation": "そびえ立つのは上へ伸びる動きで、水平方向の横とは合わず誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36039, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "横", "is_correct": true, "explanation": "「ノートを横にして」で、ノートを水平の向きにする意味になる。正解。"}, {"text": "夢", "is_correct": false, "explanation": "「ノートを夢にして」は成り立たず、意味が通らない。"}, {"text": "悲しみ", "is_correct": false, "explanation": "「ノートを悲しみにして」は意味が通らないので合わない。"}, {"text": "名刺", "is_correct": false, "explanation": "「ノートを名刺にして」は不自然で、文脈に合わない。"}], "explanations": {"横": "「ノートを横にして」で、ノートを水平の向きにする意味になる。正解。", "夢": "「ノートを夢にして」は成り立たず、意味が通らない。", "悲しみ": "「ノートを悲しみにして」は意味が通らないので合わない。", "名刺": "「ノートを名刺にして」は不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "横"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は横にまっすぐ立ち上がった。", "explanation": "「立ち上がる」は上へ起きる動きで、水平方向の横とは合わないので誤り。"}, {"text": "煙が横に高く上っていく。", "explanation": "上へ高く昇る動きは縦方向なので、水平方向の横とは合わず誤り。"}, {"text": "この箱は横が深くて、荷物がたくさん入る。", "explanation": "ここは〈奥行き〉の意味。奥行きは前後の深さを指し、「横が深い」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36039, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ノートを横を置くと、表が書きやすい。", "corrected_sentence": "ノートを横に置くと、表が書きやすい。", "error_description": "「置く」は場所を助詞「に」で示す。「を」は誤りで、正しくは「横に置く」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36039, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "横を幅を測ってから、棚を買います。", "corrected_sentence": "横の幅を測ってから、棚を買います。", "error_description": "「横の幅」と名詞を修飾する「の」が正しい。「横を」は目的語の位置ではなく、「を」が二つ重なるのは誤りで、「横の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36040, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「縦のほう」の「の」で、縦が「ほう」を修飾し、縦向きの側を表す。"}, {"text": "が", "is_correct": false, "explanation": "「縦がほうが長い」は文として成り立たず、「縦の」の連体修飾になる「の」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動詞の目的語を示すが、ここには動詞がなく「縦をほう」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「縦でほう」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「縦のほう」の「の」で、縦が「ほう」を修飾し、縦向きの側を表す。", "が": "「縦がほうが長い」は文として成り立たず、「縦の」の連体修飾になる「の」が必要。", "を": "「を」は動詞の目的語を示すが、ここには動詞がなく「縦をほう」は不自然。", "で": "「で」は場所や手段を示すが、「縦でほう」は意味が通らない。"}, "error_tags": {"が": "主格", "を": "対格", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36040, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「縦に並ぶ」の「に」で、並ぶ様子や向きを表す副詞的な用法。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すが、「縦から並ぶ」は並び方の様子として不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、「縦より並ぶ」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すが、「縦と並ぶ」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。「縦に並ぶ」の「に」で、並ぶ様子や向きを表す副詞的な用法。", "から": "「から」は起点を表すが、「縦から並ぶ」は並び方の様子として不自然。", "より": "「より」は比較を表すため、「縦より並ぶ」は文が成り立たない。", "と": "「と」は並列や相手を表すが、「縦と並ぶ」は意味が通らない。"}, "error_tags": {"から": "起点", "より": "比較", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36040, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "縦は、上から下への方向です。", "primary_collocate": null, "pronunciation": "たて", "ipa": "tate", "syllable_count": 2, "sentences": [{"text": "紙に縦の線を引いて、二つに分けました。", "target_word": "縦", "complexity_tier": "T3", "furigana": "紙[かみ]に縦[たて]の線[せん]を引[ひ]いて、二[ふた]つに分[わ]けました。", "sentence_source": "generated"}, {"text": "この本は横より縦のほうが長いです。", "target_word": "縦", "complexity_tier": "T3", "furigana": "この本[ほん]は横[よこ]より縦[たて]のほうが長[なが]いです。", "sentence_source": "generated"}, {"text": "縦に長いビルが、駅の前に建っています。", "target_word": "縦", "complexity_tier": "T3", "furigana": "縦[たて]に長[なが]いビルが、駅[えき]の前[まえ]に建[た]っています。", "sentence_source": "generated"}, {"text": "名前は縦に書いてください。", "target_word": "縦", "complexity_tier": "T3", "furigana": "名前[なまえ]は縦[たて]に書[か]いてください。", "sentence_source": "generated"}, {"text": "縦の列の一番上に、私の名前があります。", "target_word": "縦", "complexity_tier": "T3", "furigana": "縦[たて]の列[れつ]の一番[いちばん]上[うえ]に、私[わたし]の名前[なまえ]があります。", "sentence_source": "generated"}, {"text": "旗を縦にして、壁にかけました。", "target_word": "縦", "complexity_tier": "T3", "furigana": "旗[はた]を縦[たて]にして、壁[かべ]にかけました。", "sentence_source": "generated"}, {"text": "縦に切ると、ケーキは同じ大きさになります。", "target_word": "縦", "complexity_tier": "T3", "furigana": "縦[たて]に切[き]ると、ケーキは同[おな]じ大[おお]きさになります。", "sentence_source": "generated"}, {"text": "この看板は文字が縦に並んでいて、読みにくい。", "target_word": "縦", "complexity_tier": "T3", "furigana": "この看板[かんばん]は文字[もじ]が縦[たて]に並[なら]んでいて、読[よ]みにくい。", "sentence_source": "generated"}, {"text": "エレベーターは建物の中を縦に動きます。", "target_word": "縦", "complexity_tier": "T3", "furigana": "エレベーターは建物[たてもの]の中[なか]を縦[たて]に動[うご]きます。", "sentence_source": "generated"}, {"text": "写真を縦に撮ると、高い木が全部入ります。", "target_word": "縦", "complexity_tier": "T3", "furigana": "写真[しゃしん]を縦[たて]に撮[と]ると、高[たか]い木[き]が全部[ぜんぶ]入[はい]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "縦", "label": "基本形"}, {"form": "縦に", "label": "に格"}, {"form": "縦の", "label": "連体形"}], "register": "中立（日常語）", "sense_fingerprint": "横に対する、上から下へ向かう方向としての「縦」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36040, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "縦", "is_correct": true, "explanation": "正解。「紙に縦の線を引く」は上から下へ向けて線を引く意味で自然に通る。"}, {"text": "音", "is_correct": false, "explanation": "「紙に音の線を引く」は意味をなさず、線の向きを示す語が入らない。"}, {"text": "声", "is_correct": false, "explanation": "「声の線」は線を引く対象として成り立たず、空所には向きを表す語が必要。"}, {"text": "匂い", "is_correct": false, "explanation": "「匂いの線」は線の描き方を表せず、紙に線を引く文脈に合わない。"}], "explanations": {"縦": "正解。「紙に縦の線を引く」は上から下へ向けて線を引く意味で自然に通る。", "音": "「紙に音の線を引く」は意味をなさず、線の向きを示す語が入らない。", "声": "「声の線」は線を引く対象として成り立たず、空所には向きを表す語が必要。", "匂い": "「匂いの線」は線の描き方を表せず、紙に線を引く文脈に合わない。"}, "sentence_index": 0, "correct_answer": "縦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この棚は縦が重くて、動かせない。", "explanation": "ここは〈重さ〉の意味。重さは「重い」で表すもので、「縦」は方向を表すので重さの説明には使えない。"}, {"text": "天井の縦を測ってから、カーテンを買いに行った。", "explanation": "ここは〈高さ〉の意味。天井の高さを測るなら「高さ」を使う。「縦」は上下の方向を指すので、数値の高さとしては合わない。"}, {"text": "この棒は縦が太い。", "explanation": "ここは〈太さ〉の意味。太さは「太い」で表すもので、「縦」は方向を表すため太さの説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36040, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "縦", "is_correct": true, "explanation": "正解。「縦に切る」は上から下へ切る方向を表し、ケーキを切る文脈で自然。"}, {"text": "光", "is_correct": false, "explanation": "「光に切る」は意味をなさず、切り方の向きを示す語が入らない。"}, {"text": "色", "is_correct": false, "explanation": "「色に切る」は切る方法を表せず、ケーキを切る文脈に合わない。"}, {"text": "熱", "is_correct": false, "explanation": "「熱に切る」は不自然で、切り方や向きを示す語として成り立たない。"}], "explanations": {"縦": "正解。「縦に切る」は上から下へ切る方向を表し、ケーキを切る文脈で自然。", "光": "「光に切る」は意味をなさず、切り方の向きを示す語が入らない。", "色": "「色に切る」は切る方法を表せず、ケーキを切る文脈に合わない。", "熱": "「熱に切る」は不自然で、切り方や向きを示す語として成り立たない。"}, "sentence_index": 6, "correct_answer": "縦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "東京から大阪までの縦は五百キロだ。", "explanation": "ここは〈距離〉の意味。二地点の隔たりは「距離」で表す。「縦」は上下の向きを指すので、距離の意味では使えない。"}, {"text": "この部屋は縦が暖かい。", "explanation": "ここは〈温かさ〉の意味。部屋の暖かさは「暖かい」で表すもので、「縦」は上下の方向を指すので温度の説明には使えない。"}, {"text": "彼の縦はとても優しい。", "explanation": "ここは〈性格〉の意味。人の優しさは「優しい」で表すもので、「縦」は方向を表すので性格の説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36040, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "縦を線に沿って紙を折ってください。", "corrected_sentence": "縦の線に沿って紙を折ってください。", "error_description": "誤りは「縦を」の「を」。「縦の線」は「の」で線を修飾する形が正しく、「縦を線」は文法的に成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36040, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙を縦が二つ折りにして、角をそろえてください。", "corrected_sentence": "紙を縦に二つ折りにして、角をそろえてください。", "error_description": "誤りは「縦が」の「が」。「縦に二つ折り」の「に」が正しく、「縦が」は縦を主語にしてしまい、折る向きを表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36041, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「縦の模様」の「の」で、縦が「模様」を修飾する連体修飾の用法。"}, {"text": "が", "is_correct": false, "explanation": "「縦が模様のシャツ」は縦を主語にする形で、模様を修飾できず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動詞の目的語を示すが、ここには動詞がなく「縦を模様」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「縦で模様」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「縦の模様」の「の」で、縦が「模様」を修飾する連体修飾の用法。", "が": "「縦が模様のシャツ」は縦を主語にする形で、模様を修飾できず不自然。", "を": "「を」は動詞の目的語を示すが、ここには動詞がなく「縦を模様」は成り立たない。", "で": "「で」は手段や場所を示すが、「縦で模様」は意味が通らない。"}, "error_tags": {"が": "主格", "を": "対格", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36041, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「縦に折る」の「に」で、折る向きや様子を表す副詞的な用法。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すが、「縦と折る」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動先を示すが、「縦へ折る」は折る様子を表す形として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「縦から折る」は折り方の説明として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「縦に折る」の「に」で、折る向きや様子を表す副詞的な用法。", "と": "「と」は並列や相手を表すが、「縦と折る」は意味が通らない。", "へ": "「へ」は移動先を示すが、「縦へ折る」は折る様子を表す形として不自然。", "から": "「から」は起点を示すが、「縦から折る」は折り方の説明として成り立たない。"}, "error_tags": {"と": "並列・相手", "へ": "移動先", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36041, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "上下の方向。垂直。", "primary_collocate": null, "pronunciation": "たて", "ipa": "tate", "syllable_count": 2, "sentences": [{"text": "木の棒を縦に立てて、まっすぐか確かめた。", "target_word": "縦", "complexity_tier": "T3", "furigana": "木[き]の棒[ぼう]を縦[たて]に立[た]てて、まっすぐか確[たし]かめた。", "sentence_source": "generated"}, {"text": "縦の模様のシャツは、背が高く見えます。", "target_word": "縦", "complexity_tier": "T3", "furigana": "縦[たて]の模様[もよう]のシャツは、背[せ]が高[たか]く見[み]えます。", "sentence_source": "generated"}, {"text": "画面を縦にすると、長い文章が読みやすいです。", "target_word": "縦", "complexity_tier": "T3", "furigana": "画面[がめん]を縦[たて]にすると、長[なが]い文章[ぶんしょう]が読[よ]みやすいです。", "sentence_source": "generated"}, {"text": "縦に穴を掘ったので、深い井戸になった。", "target_word": "縦", "complexity_tier": "T3", "furigana": "縦[たて]に穴[あな]を掘[ほ]ったので、深[ふか]い井戸[いど]になった。", "sentence_source": "generated"}, {"text": "箱を縦に置いたら、棚に入らなかった。", "target_word": "縦", "complexity_tier": "T3", "furigana": "箱[はこ]を縦[たて]に置[お]いたら、棚[たな]に入[はい]らなかった。", "sentence_source": "generated"}, {"text": "縦の線と横の線が交わるところに印をつけた。", "target_word": "縦", "complexity_tier": "T3", "furigana": "縦[たて]の線[せん]と横[よこ]の線[せん]が交[まじ]わるところに印[しるし]をつけた。", "sentence_source": "generated"}, {"text": "ポスターは縦に貼ると、天井まで届いてしまう。", "target_word": "縦", "complexity_tier": "T3", "furigana": "ポスターは縦[たて]に貼[は]ると、天井[てんじょう]まで届[とど]いてしまう。", "sentence_source": "generated"}, {"text": "用紙を縦に二回折ってから、開いてください。", "target_word": "縦", "complexity_tier": "T3", "furigana": "用紙[ようし]を縦[たて]に二回[にかい]折[お]ってから、開[ひら]いてください。", "sentence_source": "generated"}, {"text": "彼は紙を縦に二つ折りにして、私に渡した。", "target_word": "縦", "complexity_tier": "T3", "furigana": "彼[かれ]は紙[かみ]を縦[たて]に二[に]つ折[お]りにして、私[わたし]に渡[わた]した。", "sentence_source": "generated"}, {"text": "縦の長さは二メートルで、横は一メートルです。", "target_word": "縦", "complexity_tier": "T3", "furigana": "縦[たて]の長[なが]さは二[に]メートルで、横[よこ]は一[いち]メートルです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "縦", "label": "基本形"}, {"form": "縦に", "label": "に格"}, {"form": "縦の", "label": "連体形"}], "register": "中立（日常語）", "sense_fingerprint": "地面に対してまっすぐ上下に立つ、垂直の向きとしての「縦」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36041, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "縦", "is_correct": true, "explanation": "正解。「木の棒を縦に立てる」は地面に対して上下に立てる意味で自然。"}, {"text": "音", "is_correct": false, "explanation": "「木の棒を音に立てる」は意味をなさず、立てる向きを示す語が入らない。"}, {"text": "声", "is_correct": false, "explanation": "「声に立てる」は立て方を表せず、棒を立てる文脈に合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "「匂いに立てる」は不自然で、棒の立て方を示す語として成り立たない。"}], "explanations": {"縦": "正解。「木の棒を縦に立てる」は地面に対して上下に立てる意味で自然。", "音": "「木の棒を音に立てる」は意味をなさず、立てる向きを示す語が入らない。", "声": "「声に立てる」は立て方を表せず、棒を立てる文脈に合わない。", "匂い": "「匂いに立てる」は不自然で、棒の立て方を示す語として成り立たない。"}, "sentence_index": 0, "correct_answer": "縦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この引き出しは縦が冷たい。", "explanation": "ここは〈温度〉の意味。冷たさは「冷たい」で表すもので、「縦」は方向を表すので温度の説明には使えない。"}, {"text": "このスープは縦が甘い。", "explanation": "ここは〈味〉の意味。味の甘さは「甘い」で表すもので、「縦」は上下の方向を指すので味の説明には使えない。"}, {"text": "この板は縦が三度ある。", "explanation": "ここは〈傾き〉の意味。斜めの度合いを角度で表すのは「傾き」で、「縦」は向きそのものを指すので角度の数値には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36041, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "縦", "is_correct": true, "explanation": "正解。「ポスターは縦に貼る」は上下に向けて貼る意味で、天井に届く文脈に合う。"}, {"text": "光", "is_correct": false, "explanation": "「ポスターは光に貼る」は意味をなさず、貼る向きを示す語が入らない。"}, {"text": "色", "is_correct": false, "explanation": "「色に貼る」は貼り方を表せず、ポスターを貼る文脈に合わない。"}, {"text": "熱", "is_correct": false, "explanation": "「熱に貼る」は不自然で、貼る向きを示す語として成り立たない。"}], "explanations": {"縦": "正解。「ポスターは縦に貼る」は上下に向けて貼る意味で、天井に届く文脈に合う。", "光": "「ポスターは光に貼る」は意味をなさず、貼る向きを示す語が入らない。", "色": "「色に貼る」は貼り方を表せず、ポスターを貼る文脈に合わない。", "熱": "「熱に貼る」は不自然で、貼る向きを示す語として成り立たない。"}, "sentence_index": 6, "correct_answer": "縦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は縦が十キロある。", "explanation": "ここは〈重さ〉の意味。重さは「重さ」で表すもので、「縦」は上下の方向を指すので重さの説明には使えない。"}, {"text": "この花は縦の香りが強い。", "explanation": "ここは〈香り〉の意味。香りの強さは「香り」で表すもので、「縦」は上下の方向を指すので香りの説明には使えない。"}, {"text": "この布は縦が濃い。", "explanation": "ここは〈色の濃さ〉の意味。色の濃さは「濃い」で表す語で、「縦」は向きを表すので色の説明には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36041, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱は縦へ置くと、棚に入りにくい。", "corrected_sentence": "箱は縦に置くと、棚に入りにくい。", "error_description": "誤りは「縦へ」の「へ」。「縦に置く」の「に」が状態・様態を表す正しい形で、「へ」は移動先を示すため「置く」の様子を表せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36041, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用紙を縦が一度折ってから、開いてください。", "corrected_sentence": "用紙を縦に一度折ってから、開いてください。", "error_description": "誤りは「縦が」の「が」。「縦に折る」の「に」が正しく、「縦が」は縦を主語にしてしまい、折る方法を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
