INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36042, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「和音を変える」の「を」で、変える対象を表す目的語の用法。"}, {"text": "が", "is_correct": false, "explanation": "「和音が変えると」は和音を主語にする形で、変える動作の対象にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「和音と変える」は並列や相手の意味になり、変える対象を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「和音の変えると」は連体修飾になり、動詞の目的語にならないため文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「和音を変える」の「を」で、変える対象を表す目的語の用法。", "が": "「和音が変えると」は和音を主語にする形で、変える動作の対象にならず不自然。", "と": "「和音と変える」は並列や相手の意味になり、変える対象を表せない。", "の": "「和音の変えると」は連体修飾になり、動詞の目的語にならないため文が成り立たない。"}, "error_tags": {"が": "主格", "と": "並列・相手", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36042, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "二つ以上の音を、同時に鳴らしたときの、音の重なり方のことです。", "primary_collocate": null, "pronunciation": "わおん", "ipa": "waoɴ", "syllable_count": 3, "sentences": [{"text": "ピアノで三つの音を同時に弾くと、和音になる。", "target_word": "和音", "complexity_tier": "T3", "furigana": "ピアノで三[みっ]つの音[おと]を同時[どうじ]に弾[ひ]くと、和音[わおん]になる。", "sentence_source": "generated"}, {"text": "ギターの和音は、指の形を覚えるまで難しいです。", "target_word": "和音", "complexity_tier": "T3", "furigana": "ギターの和音[わおん]は、指[ゆび]の形[かたち]を覚[おぼ]えるまで難[むずか]しいです。", "sentence_source": "generated"}, {"text": "この曲は、最後の和音がとても美しい。", "target_word": "和音", "complexity_tier": "T3", "furigana": "この曲[きょく]は、最後[さいご]の和音[わおん]がとても美[うつく]しい。", "sentence_source": "generated"}, {"text": "合唱で声が合うと、きれいな和音が響きます。", "target_word": "和音", "complexity_tier": "T3", "furigana": "合唱[がっしょう]で声[こえ]が合[あ]うと、きれいな和音[わおん]が響[ひび]きます。", "sentence_source": "generated"}, {"text": "先生は和音の聞き取りを、毎週練習させます。", "target_word": "和音", "complexity_tier": "T3", "furigana": "先生[せんせい]は和音[わおん]の聞[き]き取[と]りを、毎週[まいしゅう]練習[れんしゅう]させます。", "sentence_source": "generated"}, {"text": "楽譜の上に、和音の名前が書いてあります。", "target_word": "和音", "complexity_tier": "T3", "furigana": "楽譜[がくふ]の上[うえ]に、和音[わおん]の名前[なまえ]が書[か]いてあります。", "sentence_source": "generated"}, {"text": "彼女は歌いながら、ギターで和音を弾いた。", "target_word": "和音", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は歌[うた]いながら、ギターで和音[わおん]を弾[ひ]いた。", "sentence_source": "generated"}, {"text": "和音を変えると、曲の雰囲気が明るくなる。", "target_word": "和音", "complexity_tier": "T3", "furigana": "和音[わおん]を変[か]えると、曲[きょく]の雰囲気[ふんいき]が明[あか]るくなる。", "sentence_source": "generated"}, {"text": "一つの音だけでなく、和音で伴奏すると豊かに聞こえる。", "target_word": "和音", "complexity_tier": "T3", "furigana": "一[ひと]つの音[おと]だけでなく、和音[わおん]で伴奏[ばんそう]すると豊[ゆた]かに聞[き]こえる。", "sentence_source": "generated"}, {"text": "子どもたちは、ピアノの和音を聞いて拍手した。", "target_word": "和音", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、ピアノの和音[わおん]を聞[き]いて拍手[はくしゅ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "和音", "label": "基本形"}, {"form": "和音を", "label": "を格"}, {"form": "和音の", "label": "連体修飾"}], "register": "中立（音楽用語）", "sense_fingerprint": "複数の音を同時に鳴らしたときの重なりとしての「和音」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36042, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和音", "is_correct": true, "explanation": "正解。「三つの音を同時に弾くと和音になる」は、同時に鳴る音の重なりを表し自然。"}, {"text": "拍手", "is_correct": false, "explanation": "「拍手になる」は、音を弾いた結果として成り立たない。"}, {"text": "鍵盤", "is_correct": false, "explanation": "「鍵盤になる」は楽器の部品を指すため、弾いた結果の音の重なりを表せない。"}, {"text": "楽譜", "is_correct": false, "explanation": "「楽譜になる」は、音を弾いた結果として成り立たない。"}], "explanations": {"和音": "正解。「三つの音を同時に弾くと和音になる」は、同時に鳴る音の重なりを表し自然。", "拍手": "「拍手になる」は、音を弾いた結果として成り立たない。", "鍵盤": "「鍵盤になる」は楽器の部品を指すため、弾いた結果の音の重なりを表せない。", "楽譜": "「楽譜になる」は、音を弾いた結果として成り立たない。"}, "sentence_index": 0, "correct_answer": "和音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この歌は和音の届く範囲が広く、高音まで出せる。", "explanation": "和音は同時に鳴る音の重なりで、声や楽器の届く範囲（音域）の意味はない。この文は誤り。"}, {"text": "ピアノで一つの音だけを鳴らして、それを和音と呼んだ。", "explanation": "和音は複数の音が同時に鳴ることで、一つの音だけを和音と呼ぶのは誤り。"}, {"text": "この曲は和音の一つ一つに歌詞が付いていて、聞き取りやすい。", "explanation": "和音は音の重なりを指すので、歌詞の付く対象ではない。この文は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36042, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和音", "is_correct": true, "explanation": "正解。「ギターで和音を弾く」は、ギターで音を重ねて鳴らす意味で自然。"}, {"text": "歌", "is_correct": false, "explanation": "「ギターで歌を弾く」は不自然で、弾く対象として成り立たない。"}, {"text": "休符", "is_correct": false, "explanation": "「休符を弾く」は、音を出さない記号を弾くことになり意味が通らない。"}, {"text": "拍", "is_correct": false, "explanation": "「拍を弾く」は、拍を弾くという動作として成り立たない。"}], "explanations": {"和音": "正解。「ギターで和音を弾く」は、ギターで音を重ねて鳴らす意味で自然。", "歌": "「ギターで歌を弾く」は不自然で、弾く対象として成り立たない。", "休符": "「休符を弾く」は、音を出さない記号を弾くことになり意味が通らない。", "拍": "「拍を弾く」は、拍を弾くという動作として成り立たない。"}, "sentence_index": 6, "correct_answer": "和音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドレミファソラシドは和音だ。", "explanation": "ドレミファソラシドは順に並ぶ音の列（音階）で、同時に鳴る和音とは別の概念。この文は誤り。"}, {"text": "この歌は和音を口ずさむと、一本の流れになって心地よい。", "explanation": "口ずさむのは旋律で、和音は同時に鳴る音の重なりなので、この文は誤り。"}, {"text": "二つの音の間の隔たりは和音と言う。", "explanation": "二音の隔たりは音程で、和音は音の重なりを指すので、この文は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36042, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同時に鳴る音が増えると、和音に響きが豊かになる。", "corrected_sentence": "同時に鳴る音が増えると、和音の響きが豊かになる。", "error_description": "誤りは「和音に」の「に」。「和音の響き」の「の」が正しく、「に」は相手や場所を表すため、響きを修飾できず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36042, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "和音が一つ変えると、曲の印象がずいぶん変わる。", "corrected_sentence": "和音を一つ変えると、曲の印象がずいぶん変わる。", "error_description": "誤りは「和音が」の「が」。「和音を変える」の「を」が正しく、「が」を置くと和音が変えるという主語と動詞の関係が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36043, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36043, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「和音の響き」の「の」で、和音が「響き」を修飾する連体修飾の用法。"}, {"text": "へ", "is_correct": false, "explanation": "「和音へ響きが変わる」は移動先を表す形で、和音の響きを修飾できず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動詞の目的語を示すが、「和音を響きが変わる」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「和音より響き」は比較を表すため、和音の響きを示す文としては合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「和音の響き」の「の」で、和音が「響き」を修飾する連体修飾の用法。", "へ": "「和音へ響きが変わる」は移動先を表す形で、和音の響きを修飾できず不自然。", "を": "「を」は動詞の目的語を示すが、「和音を響きが変わる」は文が成り立たない。", "より": "「和音より響き」は比較を表すため、和音の響きを示す文としては合わない。"}, "error_tags": {"へ": "移動先", "を": "対格", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36043, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "複数の異なる高さの音が同時に鳴ることで生じる、音の組み合わせ。", "primary_collocate": null, "pronunciation": "わおん", "ipa": "waoɴ", "syllable_count": 3, "sentences": [{"text": "ドとミとソを一緒に鳴らすと、明るい和音ができる。", "target_word": "和音", "complexity_tier": "T3", "furigana": "ドとミとソを一緒[いっしょ]に鳴[な]らすと、明[あか]るい和音[わおん]ができる。", "sentence_source": "generated"}, {"text": "高さの違う音が重なって、深みのある和音が生まれた。", "target_word": "和音", "complexity_tier": "T3", "furigana": "高[たか]さの違[ちが]う音[おと]が重[かさ]なって、深[ふか]みのある和音[わおん]が生[う]まれた。", "sentence_source": "generated"}, {"text": "オルガンの和音が、教会の中にゆっくり広がった。", "target_word": "和音", "complexity_tier": "T3", "furigana": "オルガンの和音[わおん]が、教会[きょうかい]の中[なか]にゆっくり広[ひろ]がった。", "sentence_source": "generated"}, {"text": "この和音は少しにごっていて、落ち着かない響きだ。", "target_word": "和音", "complexity_tier": "T3", "furigana": "この和音[わおん]は少[すこ]しにごっていて、落[お]ち着[つ]かない響[ひび]きだ。", "sentence_source": "generated"}, {"text": "作曲家は、悲しい場面で暗い和音を選んだ。", "target_word": "和音", "complexity_tier": "T3", "furigana": "作曲家[さっきょくか]は、悲[かな]しい場面[ばめん]で暗[くら]い和音[わおん]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "弦楽器の和音が、静かな夜の場面を支えている。", "target_word": "和音", "complexity_tier": "T3", "furigana": "弦楽器[げんがっき]の和音[わおん]が、静[しず]かな夜[よる]の場面[ばめん]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "音楽の授業で、いくつかの和音を聞き比べた。", "target_word": "和音", "complexity_tier": "T3", "furigana": "音楽[おんがく]の授業[じゅぎょう]で、いくつかの和音[わおん]を聞[き]き比[くら]べた。", "sentence_source": "generated"}, {"text": "一つずつ音を足すと、和音の響きが変わります。", "target_word": "和音", "complexity_tier": "T3", "furigana": "一[ひと]つずつ音[おと]を足[た]すと、和音[わおん]の響[ひび]きが変[か]わります。", "sentence_source": "generated"}, {"text": "和音がずれていたので、調律師に直してもらった。", "target_word": "和音", "complexity_tier": "T3", "furigana": "和音[わおん]がずれていたので、調律師[ちょうりつし]に直[なお]してもらった。", "sentence_source": "generated"}, {"text": "ピアノの左手で和音を押さえ、右手で旋律を弾く。", "target_word": "和音", "complexity_tier": "T3", "furigana": "ピアノの左手[ひだりて]で和音[わおん]を押[お]さえ、右手[みぎて]で旋律[せんりつ]を弾[ひ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "和音", "label": "基本形"}, {"form": "和音を", "label": "を格"}, {"form": "和音が", "label": "が格"}], "register": "中立（音楽用語）", "sense_fingerprint": "高さの違う音の組み合わせが生む響きとしての「和音」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d9b6b-d415-4353-9c27-fa5481251037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36043, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和音", "is_correct": true, "explanation": "正解。「ドとミとソを一緒に鳴らすと、明るい和音ができる」は、同時に鳴る音の組み合わせとして自然。"}, {"text": "拍手", "is_correct": false, "explanation": "「明るい拍手ができる」は意味をなさず、音の組み合わせを表せない。"}, {"text": "休符", "is_correct": false, "explanation": "「明るい休符ができる」は、音を出さない記号に明るさを当てはめることになり不自然。"}, {"text": "楽譜", "is_correct": false, "explanation": "「明るい楽譜ができる」は、音を鳴らした結果として成り立たない。"}], "explanations": {"和音": "正解。「ドとミとソを一緒に鳴らすと、明るい和音ができる」は、同時に鳴る音の組み合わせとして自然。", "拍手": "「明るい拍手ができる」は意味をなさず、音の組み合わせを表せない。", "休符": "「明るい休符ができる」は、音を出さない記号に明るさを当てはめることになり不自然。", "楽譜": "「明るい楽譜ができる」は、音を鳴らした結果として成り立たない。"}, "sentence_index": 0, "correct_answer": "和音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドからソまでの隔たりは、和音と呼ばれる。", "explanation": "ここは「音程」が表す〈二音の間の隔たり〉の意味。音の重なりを指す和音とは別の概念なので、この文脈では使えない。"}, {"text": "この弦楽器は和音の範囲が広く、低音から高音まで出せる。", "explanation": "ここは〈音域〉の意味。出せる音の範囲は「音域」で表す。和音は同時に鳴る音の組み合わせを指すので、範囲の説明には使えない。"}, {"text": "ドレミの並びは和音と呼ぶ。", "explanation": "ここは「音階」が表す〈順に並ぶ音の列〉の意味。同時に鳴る音の重なりを指す和音とは別の概念なので、この文脈では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36043, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和音", "is_correct": true, "explanation": "正解。「いくつかの和音を聞き比べた」は、複数の音の重なりを比べる意味で自然。"}, {"text": "鍵盤", "is_correct": false, "explanation": "「鍵盤を聞き比べた」は、聞き比べる対象として成り立たない。"}, {"text": "汗", "is_correct": false, "explanation": "「汗を聞き比べた」は聞いて比べる対象として成り立たず、音の重なりも表せない。"}, {"text": "指揮", "is_correct": false, "explanation": "「指揮を聞き比べた」は、聞いて比べる対象として意味が通らない。"}], "explanations": {"和音": "正解。「いくつかの和音を聞き比べた」は、複数の音の重なりを比べる意味で自然。", "鍵盤": "「鍵盤を聞き比べた」は、聞き比べる対象として成り立たない。", "汗": "「汗を聞き比べた」は聞いて比べる対象として成り立たず、音の重なりも表せない。", "指揮": "「指揮を聞き比べた」は、聞いて比べる対象として意味が通らない。"}, "sentence_index": 6, "correct_answer": "和音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この曲は、一つの和音に一行ずつ歌詞が付いている。", "explanation": "ここは〈歌詞〉の意味。言葉は「歌詞」で表すもので、和音は音の組み合わせを指すので、歌詞が付く対象としては合わない。"}, {"text": "一本の流れになった音の並びは和音だ。", "explanation": "ここは〈旋律〉（メロディー）の意味。一本の流れとして聞こえる音の並びは「旋律」で、同時に鳴る音の重なりを指す和音とは別の概念。"}, {"text": "一つだけ鳴る音は和音と呼ぶ。", "explanation": "ここは「単音」が表す〈一つの音〉の意味。和音は複数の音が同時に鳴ることなので、一つだけの音には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36043, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高さの違う音を重ねると、和音を生まれる。", "corrected_sentence": "高さの違う音を重ねると、和音が生まれる。", "error_description": "誤りは「和音を」の「を」。「生まれる」は自動詞なので、主語を示す「が」が正しく、「を」は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36043, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "音を一つ増やすごとに、和音に響きは少しずつ変わる。", "corrected_sentence": "音を一つ増やすごとに、和音の響きは少しずつ変わる。", "error_description": "誤りは「和音に」の「に」。「和音の響き」の「の」が正しく、「に」は相手や場所を表すため、響きを修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d805857-d9a0-45c7-9b75-40d8a1409c4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36050, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「多声で歌う」は歌い方・手段を表す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「多声に歌う」とは言わない。歌い方を示す位置に「に」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、歌い方の説明には合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「多声から歌う」は歌い方として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「多声で歌う」は歌い方・手段を表す。正解。", "に": "「多声に歌う」とは言わない。歌い方を示す位置に「に」は合わない。", "へ": "方向を示す助詞で、歌い方の説明には合わない。", "から": "起点を示すため、「多声から歌う」は歌い方として成り立たない。"}, "error_tags": {"に": "帰着・対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36050, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「多声で歌えるようになった」は手段・方法を表す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「多声を歌える」は多声を目的語とする形になり、歌い方を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「多声と歌える」は共に歌う相手を示す形になり、この文では不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すため、「多声より歌える」では文が通らない。"}], "correct_answer": "で", "explanations": {"で": "「多声で歌えるようになった」は手段・方法を表す。正解。", "を": "「多声を歌える」は多声を目的語とする形になり、歌い方を表せない。", "と": "「多声と歌える」は共に歌う相手を示す形になり、この文では不自然。", "より": "比較を示すため、「多声より歌える」では文が通らない。"}, "error_tags": {"を": "目的語", "と": "共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36050, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "いくつかの声が一緒に歌うこと。", "primary_collocate": null, "pronunciation": "たせい", "ipa": "taseː", "syllable_count": 3, "sentences": [{"text": "合唱団は多声で歌い、会場に豊かな響きが広がった。", "target_word": "多声", "complexity_tier": "T3", "furigana": "合唱団[がっしょうだん]は多声[たせい]で歌[うた]い、会場[かいじょう]に豊[ゆた]かな響[ひび]きが広[ひろ]がった。", "sentence_source": "generated"}, {"text": "一人で歌うより、多声で歌うほうが音に厚みが出る。", "target_word": "多声", "complexity_tier": "T3", "furigana": "一人[ひとり]で歌[うた]うより、多声[たせい]で歌[うた]うほうが音[おと]に厚[あつ]みが出[で]る。", "sentence_source": "generated"}, {"text": "子どもたちは先生の指揮に合わせて、多声で歌い始めた。", "target_word": "多声", "complexity_tier": "T3", "furigana": "子[こ]どもたちは先生[せんせい]の指揮[しき]に合[あ]わせて、多声[たせい]で歌[うた]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "この曲は多声で歌うと、ひとりで歌う時とは違う美しさがある。", "target_word": "多声", "complexity_tier": "T3", "furigana": "この曲[きょく]は多声[たせい]で歌[うた]うと、ひとりで歌[うた]う時[とき]とは違[ちが]う美[うつく]しさがある。", "sentence_source": "generated"}, {"text": "教会では、みんなが多声で讃美歌を歌っていた。", "target_word": "多声", "complexity_tier": "T3", "furigana": "教会[きょうかい]では、みんなが多声[たせい]で讃美歌[さんびか]を歌[うた]っていた。", "sentence_source": "generated"}, {"text": "多声で歌うには、ほかの人の声をよく聞くことが大切だ。", "target_word": "多声", "complexity_tier": "T3", "furigana": "多声[たせい]で歌[うた]うには、ほかの人[ひと]の声[こえ]をよく聞[き]くことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "前半は一人で歌い、後半は多声で歌って盛り上がった。", "target_word": "多声", "complexity_tier": "T3", "furigana": "前半[ぜんはん]は一人[ひとり]で歌[うた]い、後半[こうはん]は多声[たせい]で歌[うた]って盛[も]り上[あ]がった。", "sentence_source": "generated"}, {"text": "練習の結果、三人の声がそろい、多声で歌えるようになった。", "target_word": "多声", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の結果[けっか]、三人[さんにん]の声[こえ]がそろい、多声[たせい]で歌[うた]えるようになった。", "sentence_source": "generated"}, {"text": "多声で歌うと、声が重なるので、一人の歌より迫力がある。", "target_word": "多声", "complexity_tier": "T3", "furigana": "多声[たせい]で歌[うた]うと、声[こえ]が重[かさ]なるので、一人[ひとり]の歌[うた]より迫力[はくりょく]がある。", "sentence_source": "generated"}, {"text": "友だちと多声で歌ったので、思い出に残る発表会になった。", "target_word": "多声", "complexity_tier": "T3", "furigana": "友[とも]だちと多声[たせい]で歌[うた]ったので、思[おも]い出[で]に残[のこ]る発表会[はっぴょうかい]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多声", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "複数の人の声が重なって一緒に歌うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36050, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多声", "is_correct": true, "explanation": "〈多声で歌う〉は複数の声が重なって歌うことを表し、合唱の歌い方として文が成り立つ。正解。"}, {"text": "音程", "is_correct": false, "explanation": "音程は音の高さの間隔のこと。「音程で歌い」では歌い方の説明にならず、文が成り立たない。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子は拍の数え方の単位。「拍子で歌い」では歌い方として意味が通らない。"}, {"text": "音階", "is_correct": false, "explanation": "音階は音の高さを順に並べたもの。「音階で歌い」は歌い方として成り立たない。"}], "explanations": {"多声": "〈多声で歌う〉は複数の声が重なって歌うことを表し、合唱の歌い方として文が成り立つ。正解。", "音程": "音程は音の高さの間隔のこと。「音程で歌い」では歌い方の説明にならず、文が成り立たない。", "拍子": "拍子は拍の数え方の単位。「拍子で歌い」では歌い方として意味が通らない。", "音階": "音階は音の高さを順に並べたもの。「音階で歌い」は歌い方として成り立たない。"}, "sentence_index": 0, "correct_answer": "多声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その歌手は多声で一曲歌い、会場を感動させた。", "explanation": "多声は複数の声が一緒に歌うことなので、一人の歌手が歌う場面には合わない。"}, {"text": "夕焼けを見ながら、多声で静かに話した。", "explanation": "多声は一緒に歌うことを表すので、話す場面には合わない。"}, {"text": "この曲は多声で歌うが、全員が順番に一人ずつ歌うので、声は同時に重ならない。", "explanation": "声が順番に歌うので、声が一緒に歌うという多声の意味に反する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36050, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多声", "is_correct": true, "explanation": "前半の一人で歌う場面と対比して、後半は複数の声で歌ったことを表す。正解。"}, {"text": "休符", "is_correct": false, "explanation": "休符は音を休む記号。「休符で歌って」は歌い方として成り立たない。"}, {"text": "調性", "is_correct": false, "explanation": "調性は曲の調の性格を指す。「調性で歌って」では歌い方を表せない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は音が消えたあとの響き。「余韻で歌って」は歌い方の説明にならない。"}], "explanations": {"多声": "前半の一人で歌う場面と対比して、後半は複数の声で歌ったことを表す。正解。", "休符": "休符は音を休む記号。「休符で歌って」は歌い方として成り立たない。", "調性": "調性は曲の調の性格を指す。「調性で歌って」では歌い方を表せない。", "余韻": "余韻は音が消えたあとの響き。「余韻で歌って」は歌い方の説明にならない。"}, "sentence_index": 6, "correct_answer": "多声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仲間を集めて、新しく多声を結成した。", "explanation": "多声は一緒に歌うことを表すので、団体を結成する文では使えない。"}, {"text": "彼女の多声は透き通っていて、聞く人を魅了した。", "explanation": "多声は複数の声が一緒に歌うことで、一人の声の質を表す言葉ではないので、この文は成り立たない。"}, {"text": "彼女は会議で多声でよく話し、ほかの人の発言を遮ってばかりいた。", "explanation": "多声は一緒に歌うことを表すので、話す量の多さを表す使い方はできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36050, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは多声が歌い、教室が明るくなった。", "corrected_sentence": "子どもたちは多声で歌い、教室が明るくなった。", "error_description": "助詞の誤り。手段を表す「多声で」が正しく、「多声が」では多声が主語になり、歌うという動作と結びつかず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36050, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会場の人たちは多声を歌い、拍手が鳴りやまなかった。", "corrected_sentence": "会場の人たちは多声で歌い、拍手が鳴りやまなかった。", "error_description": "助詞の誤り。歌う手段は「多声で」で示す。「多声を」では多声が歌う対象のように扱われ、不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36051, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「多声では」は話題を示す形で、続く説明の前提を提示する。正解。"}, {"text": "が", "is_correct": false, "explanation": "「多声がは」の形は成り立たず、主題の「は」とは続けられない。"}, {"text": "の", "is_correct": false, "explanation": "「多声の、」は修飾の形で、文頭の話題として続かない。"}, {"text": "を", "is_correct": false, "explanation": "「多声を、」は目的語扱いになり、説明の主題として文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「多声では」は話題を示す形で、続く説明の前提を提示する。正解。", "が": "「多声がは」の形は成り立たず、主題の「は」とは続けられない。", "の": "「多声の、」は修飾の形で、文頭の話題として続かない。", "を": "「多声を、」は目的語扱いになり、説明の主題として文が成り立たない。"}, "error_tags": {"が": "主格（は と並ばない）", "の": "連体修飾", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36051, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「多声を研究している」は研究対象を示す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「〜に研究している」とは言わない。研究の対象は「を」で示す。"}, {"text": "と", "is_correct": false, "explanation": "「と研究する」は共同で取り組む相手を示す形で、対象の多声には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、研究の対象を示す位置には使えない。"}], "correct_answer": "を", "explanations": {"を": "「多声を研究している」は研究対象を示す。正解。", "に": "「〜に研究している」とは言わない。研究の対象は「を」で示す。", "と": "「と研究する」は共同で取り組む相手を示す形で、対象の多声には合わない。", "へ": "方向を示す「へ」は、研究の対象を示す位置には使えない。"}, "error_tags": {"に": "位置・相手", "と": "共同", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36051, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の声部から構成される音楽のこと。特に、それぞれの声部が独立した旋律を持つ形式。", "primary_collocate": null, "pronunciation": "たせい", "ipa": "taseː", "syllable_count": 3, "sentences": [{"text": "バッハのフーガは、典型的な多声の作品として知られている。", "target_word": "多声", "complexity_tier": "T3", "furigana": "バッハのフーガは、典型的[てんけいてき]な多声[たせい]の作品[さくひん]として知[し]られている。", "sentence_source": "generated"}, {"text": "多声では、それぞれの声部が独立した旋律を歌う。", "target_word": "多声", "complexity_tier": "T3", "furigana": "多声[たせい]では、それぞれの声部[せいぶ]が独立[どくりつ]した旋律[せんりつ]を歌[うた]う。", "sentence_source": "generated"}, {"text": "中世の教会で、単旋律から多声へと音楽が発展した。", "target_word": "多声", "complexity_tier": "T3", "furigana": "中世[ちゅうせい]の教会[きょうかい]で、単旋律[たんせんりつ]から多声[たせい]へと音楽[おんがく]が発展[はってん]した。", "sentence_source": "generated"}, {"text": "この曲は多声なので、一つの旋律だけを追うと全体がわからない。", "target_word": "多声", "complexity_tier": "T3", "furigana": "この曲[きょく]は多声[たせい]なので、一[ひと]つの旋律[せんりつ]だけを追[お]うと全体[ぜんたい]がわからない。", "sentence_source": "generated"}, {"text": "授業で、多声の楽譜を見ながら各声部の動きを確認した。", "target_word": "多声", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、多声[たせい]の楽譜[がくふ]を見[み]ながら各声部[かくせいぶ]の動[うご]きを確認[かくにん]した。", "sentence_source": "generated"}, {"text": "多声の曲を演奏するときは、すべての声部の入りをそろえる必要がある。", "target_word": "多声", "complexity_tier": "T3", "furigana": "多声[たせい]の曲[きょく]を演奏[えんそう]するときは、すべての声部[せいぶ]の入[はい]りをそろえる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "和音中心の伴奏つきの曲とは違い、多声は旋律どうしが絡み合う。", "target_word": "多声", "complexity_tier": "T3", "furigana": "和音中心[わおんちゅうしん]の伴奏[ばんそう]つきの曲[きょく]とは違[ちが]い、多声[たせい]は旋律[せんりつ]どうしが絡[から]み合[あ]う。", "sentence_source": "generated"}, {"text": "彼女は大学で、ルネサンス期の多声を研究している。", "target_word": "多声", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大学[だいがく]で、ルネサンス期[き]の多声[たせい]を研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "多声の書き方を学ぶために、対位法の本を読んだ。", "target_word": "多声", "complexity_tier": "T3", "furigana": "多声[たせい]の書[か]き方[かた]を学[まな]ぶために、対位法[たいいほう]の本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "旋律が一つだけの曲に比べ、多声の曲は構造が複雑だ。", "target_word": "多声", "complexity_tier": "T3", "furigana": "旋律[せんりつ]が一[ひと]つだけの曲[きょく]に比[くら]べ、多声[たせい]の曲[きょく]は構造[こうぞう]が複雑[ふくざつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多声", "label": "基本形"}], "register": "formal", "sense_fingerprint": "それぞれ独立した旋律を持つ複数の声部からなる音楽の形式（ポリフォニー）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: 4 words above tier T2 (max 3): 和音 (Zipf 3.04), 伴奏 (Zipf 3.36), 旋律 (Zipf 3.29), 絡み合う (Zipf 2.69)','sentence 8 above tier T2: contains vocabulary far above tier T2: 対位法 (Zipf 1.86)']::text[], 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36051, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多声", "is_correct": true, "explanation": "多声の作品は複数の声部が独立した旋律を持つ音楽を指す。フーガが典型例として挙がるので正解。"}, {"text": "音程", "is_correct": false, "explanation": "音程は音の高さの間隔のこと。「典型的な音程の作品」では作品の種類を表せない。"}, {"text": "拍子", "is_correct": false, "explanation": "拍子はリズムの単位で、作品の種類を表す語として成り立たない。"}, {"text": "休符", "is_correct": false, "explanation": "休符は音のない休止の記号で、作品の種類を指す語にはならない。"}], "explanations": {"多声": "多声の作品は複数の声部が独立した旋律を持つ音楽を指す。フーガが典型例として挙がるので正解。", "音程": "音程は音の高さの間隔のこと。「典型的な音程の作品」では作品の種類を表せない。", "拍子": "拍子はリズムの単位で、作品の種類を表す語として成り立たない。", "休符": "休符は音のない休止の記号で、作品の種類を指す語にはならない。"}, "sentence_index": 0, "correct_answer": "多声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この讃美歌は多声で、全員が同じ旋律を一斉に歌う作りになっている。", "explanation": "声部がそれぞれ独立した旋律を持つ多声の定義に反するので、全員が同じ旋律を歌う作りは多声とは言えない。"}, {"text": "この曲は多声で書かれているが、各声部の旋律がすべて同じ動きで、独立した旋律は一つもない。", "explanation": "各声部が独立した旋律を持つという多声の定義に反するので、この文は成り立たない。"}, {"text": "この曲は多声だが、ピアノの伴奏の上に旋律が一本のるだけで、声部はない。", "explanation": "声部が一つしかなく旋律も一本だけなので、複数の声部が独立した旋律を持つ多声の定義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36051, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多声", "is_correct": true, "explanation": "多声は声部どうしが独立した旋律で絡み合う音楽を指す。主語に入れると文意が通る。正解。"}, {"text": "残響", "is_correct": false, "explanation": "残響は音が残って響くこと。主語にすると旋律どうしが絡み合う説明にならない。"}, {"text": "調性", "is_correct": false, "explanation": "調性は曲の調の性格を指す。旋律が絡み合うという主語にはならない。"}, {"text": "旋法", "is_correct": false, "explanation": "旋法は音の並べ方の型を指す。旋律どうしが絡み合うという主語としては成り立たない。"}], "explanations": {"多声": "多声は声部どうしが独立した旋律で絡み合う音楽を指す。主語に入れると文意が通る。正解。", "残響": "残響は音が残って響くこと。主語にすると旋律どうしが絡み合う説明にならない。", "調性": "調性は曲の調の性格を指す。旋律が絡み合うという主語にはならない。", "旋法": "旋法は音の並べ方の型を指す。旋律どうしが絡み合うという主語としては成り立たない。"}, "sentence_index": 6, "correct_answer": "多声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地元の大学生たちが多声を結成し、毎年秋に定期演奏会を開いている。", "explanation": "多声は音楽の形式を指す言葉なので、団体を結成する文には使えない。"}, {"text": "この曲は多声が一つしかなく、旋律が絡み合う場面はほとんどない。", "explanation": "多声は声部が複数ある形式を指すので、声部が一つしかない文とは合わない。"}, {"text": "この曲は多声で書かれているが、旋律は一本だけで単純な構造をしている。", "explanation": "旋律が一本だけで単純な構造は、複数の声部が独立して動く多声と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36051, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この合唱団は多声を作品を練習している。", "corrected_sentence": "この合唱団は多声の作品を練習している。", "error_description": "助詞の誤り。「多声の作品」と修飾の「の」が必要。「多声を」では多声が目的語になり、作品を修飾しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36051, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は大学で多声を楽譜を読み、各声部の動きを追った。", "corrected_sentence": "彼は大学で多声の楽譜を読み、各声部の動きを追った。", "error_description": "助詞の誤り。「多声の楽譜」と修飾の「の」が必要。「多声を」では多声が読む対象のように扱われ、楽譜を修飾しなくなる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36054, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "曖昧", "is_correct": true, "explanation": "「はっきりしない」ことを表し、明確の対義語。"}, {"text": "正確", "is_correct": false, "explanation": "間違いがないことを表し、対義語ではない。"}, {"text": "確実", "is_correct": false, "explanation": "間違いなく確かなことを表し、対義語ではない。"}, {"text": "単純", "is_correct": false, "explanation": "込み入っていないことを表し、対義語ではない。"}], "correct_answer": "曖昧", "explanations": {"曖昧": "「はっきりしない」ことを表し、明確の対義語。", "正確": "間違いがないことを表し、対義語ではない。", "確実": "間違いなく確かなことを表し、対義語ではない。", "単純": "込み入っていないことを表し、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36054, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "曖昧", "is_correct": true, "explanation": "「はっきりしない」ことを表し、明確の対義語。"}, {"text": "重厚", "is_correct": false, "explanation": "重々しく落ち着いたさまで、明確の対義語ではない。"}, {"text": "和やか", "is_correct": false, "explanation": "穏やかで和らいださまで、対義語ではない。"}, {"text": "豪快", "is_correct": false, "explanation": "勢いがよく大きいさまで、対義語ではない。"}], "correct_answer": "曖昧", "explanations": {"曖昧": "「はっきりしない」ことを表し、明確の対義語。", "重厚": "重々しく落ち着いたさまで、明確の対義語ではない。", "和やか": "穏やかで和らいださまで、対義語ではない。", "豪快": "勢いがよく大きいさまで、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36054, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "はっきりしていること。まちがいがないこと。", "primary_collocate": null, "pronunciation": "めいかく", "ipa": "meːkakɯ", "syllable_count": 4, "sentences": [{"text": "先生は、宿題の出し方を明確に説明した。", "target_word": "明確", "complexity_tier": "T3", "furigana": "先生[せんせい]は、宿題[しゅくだい]の出[だ]し方[かた]を明確[めいかく]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この地図には、駅の場所が明確に書かれている。", "target_word": "明確", "complexity_tier": "T3", "furigana": "この地図[ちず]には、駅[えき]の場所[ばしょ]が明確[めいかく]に書[か]かれている。", "sentence_source": "generated"}, {"text": "彼の答えは明確で、まちがいがなかった。", "target_word": "明確", "complexity_tier": "T3", "furigana": "彼[かれ]の答[こた]えは明確[めいかく]で、まちがいがなかった。", "sentence_source": "generated"}, {"text": "事故の原因はまだ明確ではない。", "target_word": "明確", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]はまだ明確[めいかく]ではない。", "sentence_source": "generated"}, {"text": "約束の日時を明確にしておけば、あとで困らない。", "target_word": "明確", "complexity_tier": "T3", "furigana": "約束[やくそく]の日時[にちじ]を明確[めいかく]にしておけば、あとで困[こま]らない。", "sentence_source": "generated"}, {"text": "明確な証拠があるので、彼の話は信じられる。", "target_word": "明確", "complexity_tier": "T3", "furigana": "明確[めいかく]な証拠[しょうこ]があるので、彼[かれ]の話[はなし]は信[しん]じられる。", "sentence_source": "generated"}, {"text": "規則が明確だから、誰でも迷わずに行動できる。", "target_word": "明確", "complexity_tier": "T3", "furigana": "規則[きそく]が明確[めいかく]だから、誰[だれ]でも迷[まよ]わずに行動[こうどう]できる。", "sentence_source": "generated"}, {"text": "この数字を見れば、勝ったのは赤チームだと明確にわかる。", "target_word": "明確", "complexity_tier": "T3", "furigana": "この数字[すうじ]を見[み]れば、勝[か]ったのは赤[あか]チームだと明確[めいかく]にわかる。", "sentence_source": "generated"}, {"text": "電話では、住所を明確に伝えてください。", "target_word": "明確", "complexity_tier": "T3", "furigana": "電話[でんわ]では、住所[じゅうしょ]を明確[めいかく]に伝[つた]えてください。", "sentence_source": "generated"}, {"text": "契約書には、支払いの期限が明確に決まっている。", "target_word": "明確", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]には、支払[しはら]いの期限[きげん]が明確[めいかく]に決[き]まっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "明確だ", "label": "plain"}, {"form": "明確な", "label": "attributive"}, {"form": "明確に", "label": "adverbial"}, {"form": "明確で", "label": "te-form"}], "register": "neutral", "sense_fingerprint": "明確: はっきりしていて間違いがない（確かさ・正確さ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36054, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明確に", "is_correct": true, "explanation": "「あいまいな」ではなく、説明の仕方がはっきりしていることを表し、文に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "ぐっすりは深く眠るさまで、説明の仕方には合わない。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "ぴかぴかは光って輝くさまで、説明の仕方には合わない。"}, {"text": "ふかふか", "is_correct": false, "explanation": "ふかふかは柔らかくふくらんださまで、説明の仕方には合わない。"}], "explanations": {"明確に": "「あいまいな」ではなく、説明の仕方がはっきりしていることを表し、文に合う。", "ぐっすり": "ぐっすりは深く眠るさまで、説明の仕方には合わない。", "ぴかぴか": "ぴかぴかは光って輝くさまで、説明の仕方には合わない。", "ふかふか": "ふかふかは柔らかくふくらんださまで、説明の仕方には合わない。"}, "sentence_index": 0, "correct_answer": "明確に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの先生は明確な性格で、いつも冗談を言って生徒を笑わせる。", "explanation": "ここは〈明朗〉の意味。性格の明るさには明朗を使い、明確は「はっきりしている」ことなので合わない。"}, {"text": "この部屋は明確で、窓から光が入る。", "explanation": "ここは〈明るい〉の意味。部屋の明るさには明るいを使い、明確は合わない。"}, {"text": "次の電車は明確に来るので、待っていればいい。", "explanation": "ここは〈確実〉の意味。起こることの確かさには確実を使い、明確は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36054, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明確", "is_correct": true, "explanation": "規則がはっきりしていると迷わず行動できる、という因果に合う。"}, {"text": "複雑", "is_correct": false, "explanation": "複雑だと迷いやすくなり、「迷わずに行動できる」と逆になる。"}, {"text": "膨大", "is_correct": false, "explanation": "量の多さを表し、迷わず行動できる理由にならない。"}, {"text": "多彩", "is_correct": false, "explanation": "種類の多さを表し、規則の分かりやすさとは関係がない。"}], "explanations": {"明確": "規則がはっきりしていると迷わず行動できる、という因果に合う。", "複雑": "複雑だと迷いやすくなり、「迷わずに行動できる」と逆になる。", "膨大": "量の多さを表し、迷わず行動できる理由にならない。", "多彩": "種類の多さを表し、規則の分かりやすさとは関係がない。"}, "sentence_index": 6, "correct_answer": "明確"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は明確な人で、うそをつかない。", "explanation": "ここは〈正直〉の意味。人柄の誠実さには正直を使い、明確は「はっきりしている」ことなので合わない。"}, {"text": "この店は品数が明確で、客が多い。", "explanation": "ここは〈豊富〉の意味。品数の多さには豊富を使い、明確は合わない。"}, {"text": "この機械は明確に作られていて、ずれがほとんどない。", "explanation": "ここは〈精密〉の意味。機械の細かな作りには精密を使い、明確は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36054, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明確の意見を持つことは大切だ。", "corrected_sentence": "明確な意見を持つことは大切だ。", "error_description": "「明確」は形状詞なので、名詞を修飾するときは「な」を使う。「の」は誤りで、正しくは「明確な意見」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "明確に", "is_correct": true, "explanation": "副詞形で、後ろの「わかりやすく書かれている」を修飾する。"}, {"text": "明確だ", "is_correct": false, "explanation": "文を終える形で、「書かれている」を修飾する位置に入れない。"}, {"text": "明確な", "is_correct": false, "explanation": "名詞を修飾する形で、「書かれている」には続かない。"}, {"text": "明確で", "is_correct": false, "explanation": "て形で、「〜で、」と続けて文をつなぐ形なので、ここでは文法的に合わない。"}], "correct_form": "明確に", "base_form": "明確だ", "form_label": "副詞形", "sentence_index": 1, "explanations": {"明確に": "副詞形で、後ろの「わかりやすく書かれている」を修飾する。", "明確だ": "文を終える形で、「書かれている」を修飾する位置に入れない。", "明確な": "名詞を修飾する形で、「書かれている」には続かない。", "明確で": "て形で、「〜で、」と続けて文をつなぐ形なので、ここでは文法的に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36054, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は、支払いの期限を明確して、契約書に書いた。", "corrected_sentence": "会社は、支払いの期限を明確にして、契約書に書いた。", "error_description": "「明確にする」の形で、副詞形の「に」が必要。「明確して」は誤りで、正しくは「明確にして」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "明確に", "is_correct": true, "explanation": "副詞形で、「わかる」を修飾する。"}, {"text": "明確だった", "is_correct": false, "explanation": "過去の断定の形で、「わかる」を修飾できない。"}, {"text": "明確でない", "is_correct": false, "explanation": "否定の述語形で、「わかる」を修飾する位置に入らない。"}, {"text": "明確だろう", "is_correct": false, "explanation": "推量の述語形で、「わかる」を修飾できない。"}], "correct_form": "明確に", "base_form": "明確だ", "form_label": "副詞形", "sentence_index": 7, "explanations": {"明確に": "副詞形で、「わかる」を修飾する。", "明確だった": "過去の断定の形で、「わかる」を修飾できない。", "明確でない": "否定の述語形で、「わかる」を修飾する位置に入らない。", "明確だろう": "推量の述語形で、「わかる」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36055, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "曖昧", "is_correct": true, "explanation": "「はっきりしない」ことを表し、明確の対義語。"}, {"text": "鮮明", "is_correct": false, "explanation": "はっきりして鮮やかなさまで、対義語ではない。"}, {"text": "歴然", "is_correct": false, "explanation": "明らかで疑いのないさまで、対義語ではない。"}, {"text": "単純", "is_correct": false, "explanation": "込み入っていないさまで、対義語ではない。"}], "correct_answer": "曖昧", "explanations": {"曖昧": "「はっきりしない」ことを表し、明確の対義語。", "鮮明": "はっきりして鮮やかなさまで、対義語ではない。", "歴然": "明らかで疑いのないさまで、対義語ではない。", "単純": "込み入っていないさまで、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
