INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36055, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "あいまいさがなく、はっきりとしているさま。", "primary_collocate": null, "pronunciation": "めいかく", "ipa": "meːkakɯ", "syllable_count": 4, "sentences": [{"text": "あいまいな返事はやめて、明確に答えてほしい。", "target_word": "明確", "complexity_tier": "T3", "furigana": "あいまいな返事[へんじ]はやめて、明確[めいかく]に答[こた]えてほしい。", "sentence_source": "generated"}, {"text": "彼女は明確な根拠を示して、自分の意見を述べた。", "target_word": "明確", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は明確[めいかく]な根拠[こんきょ]を示[しめ]して、自分[じぶん]の意見[いけん]を述[の]べた。", "sentence_source": "generated"}, {"text": "目標が明確だと、毎日の勉強に迷いがなくなる。", "target_word": "明確", "complexity_tier": "T3", "furigana": "目標[もくひょう]が明確[めいかく]だと、毎日[まいにち]の勉強[べんきょう]に迷[まよ]いがなくなる。", "sentence_source": "generated"}, {"text": "二つの案の違いは明確で、選ぶのは簡単だった。", "target_word": "明確", "complexity_tier": "T3", "furigana": "二[ふた]つの案[あん]の違[ちが]いは明確[めいかく]で、選[えら]ぶのは簡単[かんたん]だった。", "sentence_source": "generated"}, {"text": "境界線が明確ではないので、隣の家ともめている。", "target_word": "明確", "complexity_tier": "T3", "furigana": "境界線[きょうかいせん]が明確[めいかく]ではないので、隣[となり]の家[いえ]ともめている。", "sentence_source": "generated"}, {"text": "上司は明確な指示を出さず、みんなが困った。", "target_word": "明確", "complexity_tier": "T3", "furigana": "上司[じょうし]は明確[めいかく]な指示[しじ]を出[だ]さず、みんなが困[こま]った。", "sentence_source": "generated"}, {"text": "彼はやめたいという気持ちを明確に示した。", "target_word": "明確", "complexity_tier": "T3", "furigana": "彼[かれ]はやめたいという気持[きも]ちを明確[めいかく]に示[しめ]した。", "sentence_source": "generated"}, {"text": "説明が明確なので、初めての人でも理解できる。", "target_word": "明確", "complexity_tier": "T3", "furigana": "説明[せつめい]が明確[めいかく]なので、初[はじ]めての人[ひと]でも理解[りかい]できる。", "sentence_source": "generated"}, {"text": "反対か賛成か、立場を明確にしてください。", "target_word": "明確", "complexity_tier": "T3", "furigana": "反対[はんたい]か賛成[さんせい]か、立場[たちば]を明確[めいかく]にしてください。", "sentence_source": "generated"}, {"text": "明確な理由がないまま、会議は中止になった。", "target_word": "明確", "complexity_tier": "T3", "furigana": "明確[めいかく]な理由[りゆう]がないまま、会議[かいぎ]は中止[ちゅうし]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "明確だ", "label": "plain"}, {"form": "明確な", "label": "attributive"}, {"form": "明確に", "label": "adverbial"}, {"form": "明確で", "label": "te-form"}], "register": "neutral", "sense_fingerprint": "明確: あいまいさがなくはっきりしている（意見・目標・違いなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36055, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明確に", "is_correct": true, "explanation": "あいまいな返事をやめる、という文脈で、はっきり答える意味に合う。"}, {"text": "軽やかに", "is_correct": false, "explanation": "軽快なさまを表し、答え方のはっきりさを表さない。"}, {"text": "愉快に", "is_correct": false, "explanation": "楽しく面白いさまで、答え方の求めに合わない。"}, {"text": "無造作に", "is_correct": false, "explanation": "気にせず雑に扱うさまで、あいまいさをなくす文脈と逆になる。"}], "explanations": {"明確に": "あいまいな返事をやめる、という文脈で、はっきり答える意味に合う。", "軽やかに": "軽快なさまを表し、答え方のはっきりさを表さない。", "愉快に": "楽しく面白いさまで、答え方の求めに合わない。", "無造作に": "気にせず雑に扱うさまで、あいまいさをなくす文脈と逆になる。"}, "sentence_index": 0, "correct_answer": "明確に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜景の光が明確で、とてもきれいだった。", "explanation": "ここは〈鮮明〉の意味。色や光の鮮やかさには鮮明を使い、明確は合わない。"}, {"text": "明日は雨が明確に降るので、傘を持って行こう。", "explanation": "ここは〈確実〉の意味。起こることの確かさには確実を使い、明確は合わない。"}, {"text": "このねこの毛並みは明確で、とても柔らかい。", "explanation": "ここは〈艶やか〉の意味。毛並みのつやには艶やかを使い、明確は合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36055, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明確に", "is_correct": true, "explanation": "気持ちを示す様子をはっきり表し、文に合う。"}, {"text": "陽気に", "is_correct": false, "explanation": "明るく快活なさまで、気持ちの示し方を表さない。"}, {"text": "盛大に", "is_correct": false, "explanation": "大規模で華やかなさまで、やめたい気持ちを示す文には合わない。"}, {"text": "身軽に", "is_correct": false, "explanation": "身軽なさまで、気持ちを示す文には合わない。"}], "explanations": {"明確に": "気持ちを示す様子をはっきり表し、文に合う。", "陽気に": "明るく快活なさまで、気持ちの示し方を表さない。", "盛大に": "大規模で華やかなさまで、やめたい気持ちを示す文には合わない。", "身軽に": "身軽なさまで、気持ちを示す文には合わない。"}, "sentence_index": 6, "correct_answer": "明確に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の笑顔は明確で、見る人を安心させる。", "explanation": "ここは〈柔和〉の意味。穏やかな表情には柔和を使い、明確は「はっきりしている」ことなので合わない。"}, {"text": "彼女は経験が明確で、どんな問題にも対応できる。", "explanation": "ここは〈豊富〉の意味。量の多さには豊富を使い、明確は合わない。"}, {"text": "彼は仕事に明確に取り組み、毎日遅くまで残る。", "explanation": "ここは〈熱心〉の意味。仕事への打ち込みには熱心を使い、明確は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36055, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明確の理由を説明しないと、誰も納得しない。", "corrected_sentence": "明確な理由を説明しないと、誰も納得しない。", "error_description": "「明確」は形状詞なので、名詞を修飾するときは「な」を使う。「の」は誤りで、正しくは「明確な理由」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "明確な", "is_correct": true, "explanation": "名詞「根拠」を修飾する連体形で、文の内容に合う。"}, {"text": "明確だ", "is_correct": false, "explanation": "文を終える形で、「根拠」を修飾できない。"}, {"text": "明確だろう", "is_correct": false, "explanation": "推量の形で、名詞「根拠」を修飾できない。"}, {"text": "明確なら", "is_correct": false, "explanation": "仮定の形で、名詞「根拠」を直接修飾できない。"}], "correct_form": "明確な", "base_form": "明確だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"明確な": "名詞「根拠」を修飾する連体形で、文の内容に合う。", "明確だ": "文を終える形で、「根拠」を修飾できない。", "明確だろう": "推量の形で、名詞「根拠」を修飾できない。", "明確なら": "仮定の形で、名詞「根拠」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36055, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "目標が明確に、毎日の勉強に迷いがなくなる。", "corrected_sentence": "目標が明確で、毎日の勉強に迷いがなくなる。", "error_description": "述語として「明確で、〜」と続けるときは「で」を使う。「明確に」は述語にならないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "明確な", "is_correct": true, "explanation": "「明確なので」の形で、理由を表す文に続く。"}, {"text": "明確に", "is_correct": false, "explanation": "副詞形で、「説明が」の述語にも「なので」の前にも立てない。"}, {"text": "明確で", "is_correct": false, "explanation": "て形で、「なので」の前に続けられない。"}, {"text": "明確だろう", "is_correct": false, "explanation": "推量の形で、理由を示す文に合わない。"}], "correct_form": "明確な", "base_form": "明確だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"明確な": "「明確なので」の形で、理由を表す文に続く。", "明確に": "副詞形で、「説明が」の述語にも「なので」の前にも立てない。", "明確で": "て形で、「なので」の前に続けられない。", "明確だろう": "推量の形で、理由を示す文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36056, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「定量のえさ」の「の」。「定量」が後ろの「えさ」を修飾する働きをする。"}, {"text": "を", "is_correct": false, "explanation": "「定量を」は目的語を示すが、直後に「えさを」が続くので目的語が重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「定量へえさ」と続けても意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「定量からえさ」では意味が通らず不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「定量のえさ」の「の」。「定量」が後ろの「えさ」を修飾する働きをする。", "を": "「定量を」は目的語を示すが、直後に「えさを」が続くので目的語が重なり、文が成り立たない。", "へ": "「へ」は方向を示す。「定量へえさ」と続けても意味が通らない。", "から": "「から」は起点を示す。「定量からえさ」では意味が通らず不自然になる。"}, "error_tags": {"を": "object", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
