INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36056, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "決まった量のこと。", "primary_collocate": null, "pronunciation": "ていりょう", "ipa": "teːɾjoː", "syllable_count": 2, "sentences": [{"text": "この薬は定量を守って飲む必要がある。", "target_word": "定量", "complexity_tier": "T3", "furigana": "この薬[くすり]は定量[ていりょう]を守[まも]って飲[の]む必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "毎日、定量のえさを犬にあげている。", "target_word": "定量", "complexity_tier": "T3", "furigana": "毎日[まいにち]、定量[ていりょう]のえさを犬[いぬ]にあげている。", "sentence_source": "generated"}, {"text": "機械には定量の水を入れて使う。", "target_word": "定量", "complexity_tier": "T3", "furigana": "機械[きかい]には定量[ていりょう]の水[みず]を入[い]れて使[つか]う。", "sentence_source": "generated"}, {"text": "定量より多く入れると、味が濃くなりすぎる。", "target_word": "定量", "complexity_tier": "T3", "furigana": "定量[ていりょう]より多[おお]く入[い]れると、味[あじ]が濃[こ]くなりすぎる。", "sentence_source": "generated"}, {"text": "この工場は毎月、定量の部品を作る契約になっている。", "target_word": "定量", "complexity_tier": "T3", "furigana": "この工場[こうじょう]は毎月[まいつき]、定量[ていりょう]の部品[ぶひん]を作[つく]る契約[けいやく]になっている。", "sentence_source": "generated"}, {"text": "米は定量を袋に分けて売られている。", "target_word": "定量", "complexity_tier": "T3", "furigana": "米[こめ]は定量[ていりょう]を袋[ふくろ]に分[わ]けて売[う]られている。", "sentence_source": "generated"}, {"text": "実験では、定量の砂糖を水にとかした。", "target_word": "定量", "complexity_tier": "T3", "furigana": "実験[じっけん]では、定量[ていりょう]の砂糖[さとう]を水[みず]にとかした。", "sentence_source": "generated"}, {"text": "定量以上の肥料をやると、草が枯れてしまう。", "target_word": "定量", "complexity_tier": "T3", "furigana": "定量[ていりょう]以上[いじょう]の肥料[ひりょう]をやると、草[くさ]が枯[か]れてしまう。", "sentence_source": "generated"}, {"text": "店では、客に定量の水を出すことになっている。", "target_word": "定量", "complexity_tier": "T3", "furigana": "店[みせ]では、客[きゃく]に定量[ていりょう]の水[みず]を出[だ]すことになっている。", "sentence_source": "generated"}, {"text": "毎日定量の食事をとると、体重が安定する。", "target_word": "定量", "complexity_tier": "T3", "furigana": "毎日[まいにち]定量[ていりょう]の食事[しょくじ]をとると、体重[たいじゅう]が安定[あんてい]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "定量", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "前もって決められている一定の量（薬・えさ・水など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36056, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定量", "is_correct": true, "explanation": "「決まった量を守って飲む」の意味で、薬の分量を表す「定量」が入る。"}, {"text": "距離", "is_correct": false, "explanation": "薬の飲み方として「距離を守って飲む」では意味が通らず、文が成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "「色を守って」は不自然で、薬を飲む文脈に合わない。"}, {"text": "形", "is_correct": false, "explanation": "「形を守って飲む」とは言わず、文が成り立たない。"}], "explanations": {"定量": "「決まった量を守って飲む」の意味で、薬の分量を表す「定量」が入る。", "距離": "薬の飲み方として「距離を守って飲む」では意味が通らず、文が成り立たない。", "色": "「色を守って」は不自然で、薬を飲む文脈に合わない。", "形": "「形を守って飲む」とは言わず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "定量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会議室は、定量の人数を超えて入れない。", "explanation": "ここは「定員」（人数の上限）の意味。「定量」は決まった量のことで、人の人数には使わない。"}, {"text": "その日の気分で定量を決めて、料理の味を整える。", "explanation": "ここは「適量」（ちょうどよい量）の意味。「定量」は前もって決められた量のことで、その場の気分で決める意味では使わない。"}, {"text": "このバスは定量に発車するので、遅れる心配がない。", "explanation": "ここは「定時」（決まった時刻）の意味。「定量」は量のことなので、発車の時刻には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36056, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定量", "is_correct": true, "explanation": "「定量の砂糖」で、決まった分量の砂糖を表す。実験で量を決めて使う文脈に合う。"}, {"text": "検査", "is_correct": false, "explanation": "「検査の砂糖」では意味が通らず、実験の文脈に合わない。"}, {"text": "登校", "is_correct": false, "explanation": "「登校の砂糖」は成り立たず、文に入らない。"}, {"text": "通院", "is_correct": false, "explanation": "「通院の砂糖」は意味をなさず、文の中で砂糖を修飾できない。"}], "explanations": {"定量": "「定量の砂糖」で、決まった分量の砂糖を表す。実験で量を決めて使う文脈に合う。", "検査": "「検査の砂糖」では意味が通らず、実験の文脈に合わない。", "登校": "「登校の砂糖」は成り立たず、文に入らない。", "通院": "「通院の砂糖」は意味をなさず、文の中で砂糖を修飾できない。"}, "sentence_index": 6, "correct_answer": "定量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会社は、定量の健康診断を毎年受けている。", "explanation": "ここは「定期」（決まった間隔で行うこと）の意味。「定量」は量のことで、健康診断の周期には使わない。"}, {"text": "会社の定量を守って、休暇を取る。", "explanation": "ここは「規定」（決まりごと）の意味。「定量」は量を指すので、社内の決まりの内容には使えない。"}, {"text": "この席は定量の席で、誰も座れない。", "explanation": "ここは「固定」（動かないように決まっていること）の意味。「定量」は量のことなので、席が動かないという意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36056, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場では、定量に守って原料を混ぜる。", "corrected_sentence": "工場では、定量を守って原料を混ぜる。", "error_description": "「守る」の目的語は「を」で示す。「定量に」は誤りで、正しくは「定量を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36056, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校の実験では、定量が食塩を水に溶かす。", "corrected_sentence": "学校の実験では、定量の食塩を水に溶かす。", "error_description": "「定量」は量を表すので、主語にして「溶かす」と続けると不自然。正しくは「定量の食塩」と、「の」で食塩を修飾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36057, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「定量を決めておいた」の「を」。「決める」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「定量が決めておいた」では定量が主語になり、誰が決めたのか文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「定量へ決めておいた」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「定量から決めておいた」では不自然で、目的語の働きもしない。"}], "correct_answer": "を", "explanations": {"を": "「定量を決めておいた」の「を」。「決める」の目的語を示す。", "が": "「定量が決めておいた」では定量が主語になり、誰が決めたのか文が成り立たない。", "へ": "「へ」は方向を示す。「定量へ決めておいた」では意味が通らない。", "から": "「から」は起点を示す。「定量から決めておいた」では不自然で、目的語の働きもしない。"}, "error_tags": {"が": "subject", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36057, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「定量を計って」の「を」。「計る」の目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「定量と計って」は並列や相手の意味になり、「計る」の対象が立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「定量より計って」は比較の意味となり、文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する助詞。「定量の計って」では動詞に対象が結びつかず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「定量を計って」の「を」。「計る」の目的語を示す。", "と": "「定量と計って」は並列や相手の意味になり、「計る」の対象が立たない。", "より": "「より」は比較を示す。「定量より計って」は比較の意味となり、文の意味が通らない。", "の": "「の」は名詞を修飾する助詞。「定量の計って」では動詞に対象が結びつかず、文が成り立たない。"}, "error_tags": {"と": "comitative", "より": "comparison", "の": "modifier"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36057, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数量や程度が決まっていること。また、その数量。", "primary_collocate": null, "pronunciation": "ていりょう", "ipa": "teːɾjoː", "syllable_count": 2, "sentences": [{"text": "工場は定量を決めて、毎日同じ数の製品を作る。", "target_word": "定量", "complexity_tier": "T3", "furigana": "工場[こうじょう]は定量[ていりょう]を決[き]めて、毎日[まいにち]同[おな]じ数[かず]の製品[せいひん]を作[つく]る。", "sentence_source": "generated"}, {"text": "先生は、宿題の定量を前もって決めておいた。", "target_word": "定量", "complexity_tier": "T3", "furigana": "先生[せんせい]は、宿題[しゅくだい]の定量[ていりょう]を前[まえ]もって決[き]めておいた。", "sentence_source": "generated"}, {"text": "薬の定量は、年れいによって決められている。", "target_word": "定量", "complexity_tier": "T3", "furigana": "薬[くすり]の定量[ていりょう]は、年[ねん]れいによって決[き]められている。", "sentence_source": "generated"}, {"text": "この機械は、定量に達すると自動で止まる。", "target_word": "定量", "complexity_tier": "T3", "furigana": "この機械[きかい]は、定量[ていりょう]に達[たっ]すると自動[じどう]で止[と]まる。", "sentence_source": "generated"}, {"text": "定量が決まっているので、追加はできない。", "target_word": "定量", "complexity_tier": "T3", "furigana": "定量[ていりょう]が決[き]まっているので、追加[ついか]はできない。", "sentence_source": "generated"}, {"text": "一日の定量を超えて食べると、体に悪い。", "target_word": "定量", "complexity_tier": "T3", "furigana": "一日[いちにち]の定量[ていりょう]を超[こ]えて食[た]べると、体[からだ]に悪[わる]い。", "sentence_source": "generated"}, {"text": "毎月の使用量が定量を超えたら、料金が上がる。", "target_word": "定量", "complexity_tier": "T3", "furigana": "毎月[まいつき]の使用量[しようりょう]が定量[ていりょう]を超[こ]えたら、料金[りょうきん]が上[あ]がる。", "sentence_source": "generated"}, {"text": "農家は、畑ごとに定量を計って肥料をまく。", "target_word": "定量", "complexity_tier": "T3", "furigana": "農家[のうか]は、畑[はたけ]ごとに定量[ていりょう]を計[はか]って肥料[ひりょう]をまく。", "sentence_source": "generated"}, {"text": "定量に足りないときは、追加で注文する決まりだ。", "target_word": "定量", "complexity_tier": "T3", "furigana": "定量[ていりょう]に足[た]りないときは、追加[ついか]で注文[ちゅうもん]する決[き]まりだ。", "sentence_source": "generated"}, {"text": "検査では、定量をはかる前に容器を洗う。", "target_word": "定量", "complexity_tier": "T3", "furigana": "検査[けんさ]では、定量[ていりょう]をはかる前[まえ]に容器[ようき]を洗[あら]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "定量", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "数量や程度があらかじめ決まっていること、またその決められた数量・基準", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36057, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定量", "is_correct": true, "explanation": "「定量を決めて」で、あらかじめ決めた数量を表す。製品の数を一定にする文脈に合う。"}, {"text": "雨", "is_correct": false, "explanation": "「雨を決めて」とは言わず、工場の生産の文脈に合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気を決めて」は成り立たず、文の意味が通らない。"}, {"text": "湿気", "is_correct": false, "explanation": "「湿気を決めて」は不自然で、製品の数量を決める文に合わない。"}], "explanations": {"定量": "「定量を決めて」で、あらかじめ決めた数量を表す。製品の数を一定にする文脈に合う。", "雨": "「雨を決めて」とは言わず、工場の生産の文脈に合わない。", "眠気": "「眠気を決めて」は成り立たず、文の意味が通らない。", "湿気": "「湿気を決めて」は不自然で、製品の数量を決める文に合わない。"}, "sentence_index": 0, "correct_answer": "定量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車は定量どおりに駅へ着いた。", "explanation": "ここは「定刻」（決められた時刻）の意味。「定量」は数量が決まっていることなので、時刻には使えない。"}, {"text": "彼らは定量の打ち合わせを、月末に開いている。", "explanation": "ここは「定例」（決まって繰り返し行うこと）の意味。「定量」は数量が決まっていることで、会の繰り返しには使わない。"}, {"text": "毎週、定量に店を閉める。", "explanation": "ここは「定休」（決まって休むこと）の意味。「定量」は量のことで、店を休む日には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36057, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定量", "is_correct": true, "explanation": "「定量を超える」で、決められた量を上回る意味になり、使用量の文に合う。"}, {"text": "色", "is_correct": false, "explanation": "「色を超える」は成り立たず、使用量の文に合わない。"}, {"text": "形", "is_correct": false, "explanation": "「形を超える」は意味が通らず、料金の文脈にも合わない。"}, {"text": "寝室", "is_correct": false, "explanation": "「寝室を超える」は成り立たず、文の意味が通らない。"}], "explanations": {"定量": "「定量を超える」で、決められた量を上回る意味になり、使用量の文に合う。", "色": "「色を超える」は成り立たず、使用量の文に合わない。", "形": "「形を超える」は意味が通らず、料金の文脈にも合わない。", "寝室": "「寝室を超える」は成り立たず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "定量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全国の気温の定量をとると、差がわかりやすい。", "explanation": "ここは「平均」（合計を個数で割った値）の意味。「定量」は決まった量のことで、平均を取る対象の語ではない。"}, {"text": "この店では、定量の商品が一番売れている。", "explanation": "ここは「定番」（いつも決まって置かれていること）の意味。「定量」は数量が決まっていることで、商品の種類には使わない。"}, {"text": "この書類は定量の書式で、記入欄が決まっている。", "explanation": "ここは「定型」（決まった形式）の意味。「定量」は数量が決まっていることで、書式の形式には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36057, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "材料は定量が計ってから混ぜる。", "corrected_sentence": "材料は定量を計ってから混ぜる。", "error_description": "「計る」の目的語は「を」で示す。「定量が」と主語にすると、材料を計る文として成り立たない。正しくは「定量を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36057, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "容器に定量が入れてから、ふたを閉める。", "corrected_sentence": "容器に定量を入れてから、ふたを閉める。", "error_description": "「定量」が主語になっている。「入れる」の動作主は人なので、定量は目的語として「を」で示す。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36058, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「リズムに合わせる」の「に」で、合わせる相手を示すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「リズムが合わせて」は主語になり、合わせる対象を示せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「リズムへ合わせて」は方向の意味になり、合わせる対象とは合わないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「リズムから合わせて」は起点を示し、合わせる対象とは合わないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「リズムに合わせる」の「に」で、合わせる相手を示すので正しい。", "が": "「リズムが合わせて」は主語になり、合わせる対象を示せないので合わない。", "へ": "「リズムへ合わせて」は方向の意味になり、合わせる対象とは合わないので合わない。", "から": "「リズムから合わせて」は起点を示し、合わせる対象とは合わないので合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
