INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36058, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音楽の中で、音のながれの速さや、くり返すパターンのことです。", "primary_collocate": null, "pronunciation": "りずむ", "ipa": "ɾizɯmɯ", "syllable_count": 3, "sentences": [{"text": "この曲はリズムがゆっくりで、歌いやすいです。", "target_word": "リズム", "complexity_tier": "T2", "furigana": "この曲[きょく]はリズムがゆっくりで、歌[うた]いやすいです。", "sentence_source": "generated"}, {"text": "太鼓のリズムに合わせて、子どもたちが手をたたいた。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "太鼓[たいこ]のリズムに合[あ]わせて、子[こ]どもたちが手[て]をたたいた。", "sentence_source": "generated"}, {"text": "音楽の授業で、リズムの速さを変えて歌ってみた。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "音楽[おんがく]の授業[じゅぎょう]で、リズムの速[はや]さを変[か]えて歌[うた]ってみた。", "sentence_source": "generated"}, {"text": "ラジオから流れてきた曲のリズムが楽しくて、思わず踊りだした。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "ラジオから流[なが]れてきた曲[きょく]のリズムが楽[たの]しくて、思[おも]わず踊[おど]りだした。", "sentence_source": "generated"}, {"text": "先生は、同じリズムを何度もくり返して練習させた。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "先生[せんせい]は、同[おな]じリズムを何度[なんど]もくり返[かえ]して練習[れんしゅう]させた。", "sentence_source": "generated"}, {"text": "リズムが速い曲は、運動するときによく聞く。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "リズムが速[はや]い曲[きょく]は、運動[うんどう]するときによく聞[き]く。", "sentence_source": "generated"}, {"text": "私はリズムをとるのが苦手で、タンバリンをうまく鳴らせない。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "私[わたし]はリズムをとるのが苦手[にがて]で、タンバリンをうまく鳴[な]らせない。", "sentence_source": "generated"}, {"text": "兄はドラムを習っていて、複雑なリズムもすぐ覚える。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "兄[あに]はドラムを習[なら]っていて、複雑[ふくざつ]なリズムもすぐ覚[おぼ]える。", "sentence_source": "generated"}, {"text": "この歌はサビでリズムが変わるので、聞いていておもしろい。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "この歌[うた]はサビでリズムが変[か]わるので、聞[き]いていておもしろい。", "sentence_source": "generated"}, {"text": "運動会の音楽は、軽いリズムでみんなを元気にしてくれる。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の音楽[おんがく]は、軽[かる]いリズムでみんなを元気[げんき]にしてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リズム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "音楽の中の、音の流れの速さとくり返しのパターン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36058, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リズム", "is_correct": true, "explanation": "音の流れの速さを表す語で、「この曲はリズムがゆっくり」の空所に入る。"}, {"text": "音程", "is_correct": false, "explanation": "音の高さの関係を指す語で、「音程がゆっくり」は速さの説明にならないので合わない。"}, {"text": "音色", "is_correct": false, "explanation": "音の質を指す語で、速さを説明する文脈には合わないので合わない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌う言葉を指す語で、この曲の速さを説明できないので合わない。"}], "explanations": {"リズム": "音の流れの速さを表す語で、「この曲はリズムがゆっくり」の空所に入る。", "音程": "音の高さの関係を指す語で、「音程がゆっくり」は速さの説明にならないので合わない。", "音色": "音の質を指す語で、速さを説明する文脈には合わないので合わない。", "歌詞": "歌う言葉を指す語で、この曲の速さを説明できないので合わない。"}, "sentence_index": 0, "correct_answer": "リズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この曲はリズムが高くて、女性の声でも歌いにくい。", "explanation": "ここは〈音程〉の意味。リズムは音の流れの速さや繰り返しを指し、音の高さには使わないので合わない。"}, {"text": "この部屋はリズムを明るくして、落ち着いた雰囲気にした。", "explanation": "ここは〈照明〉の意味。リズムは音の流れのことで、部屋の明るさを変える対象にはならないので合わない。"}, {"text": "このテノールはリズムが広くて、低い音から高い音まで歌いこなせる。", "explanation": "ここは〈音域〉の意味。リズムには音の範囲の広さという意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36058, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リズム", "is_correct": true, "explanation": "「リズムをとる」は、音に合わせて拍を取ることを表し、この空所に入る。"}, {"text": "響き", "is_correct": false, "explanation": "音の余韻を指す語で、「響きをとる」とは言わないので合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを指す語で、「音量をとる」は意味が通らないので合わない。"}, {"text": "強弱", "is_correct": false, "explanation": "音の強さの変化を指す語で、「強弱をとる」は自然な表現ではないので合わない。"}], "explanations": {"リズム": "「リズムをとる」は、音に合わせて拍を取ることを表し、この空所に入る。", "響き": "音の余韻を指す語で、「響きをとる」とは言わないので合わない。", "音量": "音の大きさを指す語で、「音量をとる」は意味が通らないので合わない。", "強弱": "音の強さの変化を指す語で、「強弱をとる」は自然な表現ではないので合わない。"}, "sentence_index": 6, "correct_answer": "リズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この紅茶はリズムが強く、一口飲むと口いっぱいに広がる。", "explanation": "ここは〈香り〉の意味。リズムは音の流れのことで、紅茶の香りには使わないので合わない。"}, {"text": "このパンはリズムがもちもちしていて、かむほどに味が出る。", "explanation": "ここは〈歯ごたえ〉の意味。リズムは音の流れのことで、パンの歯ごたえを表す語ではないので合わない。"}, {"text": "この絵はリズムが鮮やかで、遠くからでも目を引く。", "explanation": "ここは〈色〉の意味。リズムは音の流れのことで、絵の鮮やかさには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36058, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は手拍子でリズムにとりながら、子どもたちと歌った。", "corrected_sentence": "彼女は手拍子でリズムをとりながら、子どもたちと歌った。", "error_description": "正しくは「リズムをとる」。「とる」は対象を「〜を」で取るので、「リズムに」は誤り（格助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36058, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生はリズムを変えずて、ゆっくり歌うように注意した。", "corrected_sentence": "先生はリズムを変えずに、ゆっくり歌うように注意した。", "error_description": "正しくは「変えずに」。「〜ずに」で後ろに続けるので、「変えずて」は誤り（接続形の誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36059, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36059, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「曲のリズムを覚える」と、覚える対象を示す格助詞で正しい。"}, {"text": "が", "is_correct": false, "explanation": "「リズムが覚える」は主語になり、覚える対象を示せないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「リズムに覚える」は対象の格が合わず、不自然なので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「リズムと覚える」は並列や相手の意味になり、覚える対象とは合わない。"}], "correct_answer": "を", "explanations": {"を": "「曲のリズムを覚える」と、覚える対象を示す格助詞で正しい。", "が": "「リズムが覚える」は主語になり、覚える対象を示せないので合わない。", "に": "「リズムに覚える」は対象の格が合わず、不自然なので合わない。", "と": "「リズムと覚える」は並列や相手の意味になり、覚える対象とは合わない。"}, "error_tags": {"が": "主語", "に": "相手・方向", "と": "相手・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36059, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音楽において、音の長さや強さが規則的にくり返されるパターンや、その流れの感じ。", "primary_collocate": null, "pronunciation": "りずむ", "ipa": "ɾizɯmɯ", "syllable_count": 3, "sentences": [{"text": "ドラム奏者は、一定のリズムをきちんと刻んでいる。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "ドラム奏者[そうしゃ]は、一定[いってい]のリズムをきちんと刻[きざ]んでいる。", "sentence_source": "generated"}, {"text": "このドラムのリズムは速くて、聞いていると自然に体が動く。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "このドラムのリズムは速[はや]くて、聞[き]いていると自然[しぜん]に体[からだ]が動[うご]く。", "sentence_source": "generated"}, {"text": "先生はピアノの生徒に、リズムを正確に保つように注意した。", "target_word": "リズム", "complexity_tier": "T4", "furigana": "先生[せんせい]はピアノの生徒[せいと]に、リズムを正確[せいかく]に保[たも]つように注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "ワルツは三拍子のリズムが特徴で、ゆったりとした流れがある。", "target_word": "リズム", "complexity_tier": "T4", "furigana": "ワルツは三拍子[さんびょうし]のリズムが特徴[とくちょう]で、ゆったりとした流[なが]れがある。", "sentence_source": "generated"}, {"text": "手拍子でリズムをとりながら、みんなで歌を練習した。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "手拍子[てびょうし]でリズムをとりながら、みんなで歌[うた]を練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "その曲は途中でリズムが変わり、急に明るい雰囲気になる。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "その曲[きょく]は途中[とちゅう]でリズムが変[か]わり、急[きゅう]に明[あか]るい雰囲気[ふんいき]になる。", "sentence_source": "generated"}, {"text": "彼のギターは、メロディーよりもリズムの刻み方が印象的だ。", "target_word": "リズム", "complexity_tier": "T4", "furigana": "彼[かれ]のギターは、メロディーよりもリズムの刻[きざ]み方[かた]が印象的[いんしょうてき]だ。", "sentence_source": "generated"}, {"text": "ダンスの練習では、まず曲のリズムを覚えることから始める。", "target_word": "リズム", "complexity_tier": "T3", "furigana": "ダンスの練習[れんしゅう]では、まず曲[きょく]のリズムを覚[おぼ]えることから始[はじ]める。", "sentence_source": "generated"}, {"text": "リズムが合わないと、合唱は一つの音楽として聞こえない。", "target_word": "リズム", "complexity_tier": "T4", "furigana": "リズムが合[あ]わないと、合唱[がっしょう]は一[ひと]つの音楽[おんがく]として聞[き]こえない。", "sentence_source": "generated"}, {"text": "打楽器だけの演奏でも、リズムの強弱で曲の盛り上がりを表現できる。", "target_word": "リズム", "complexity_tier": "T4", "furigana": "打楽器[だがっき]だけの演奏[えんそう]でも、リズムの強弱[きょうじゃく]で曲[きょく]の盛[も]り上[あ]がりを表現[ひょうげん]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リズム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "音楽で、音の長さや強さが規則的にくり返されるパターンとその流れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36059, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リズム", "is_correct": true, "explanation": "音の繰り返しのパターンを「刻む」対象として、この空所に入る。"}, {"text": "音程", "is_correct": false, "explanation": "音の高さの間隔を指す語で、「音程をきちんと刻む」とは言わないので合わない。"}, {"text": "音色", "is_correct": false, "explanation": "音の質を指す語で、「音色を刻む」は成り立たないので合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを指す語で、「音量を刻む」は不自然なので合わない。"}], "explanations": {"リズム": "音の繰り返しのパターンを「刻む」対象として、この空所に入る。", "音程": "音の高さの間隔を指す語で、「音程をきちんと刻む」とは言わないので合わない。", "音色": "音の質を指す語で、「音色を刻む」は成り立たないので合わない。", "音量": "音の大きさを指す語で、「音量を刻む」は不自然なので合わない。"}, "sentence_index": 0, "correct_answer": "リズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この歌手はリズムが高すぎて、サビで声が裏返ってしまった。", "explanation": "ここは〈音程〉の意味。リズムは音の長さや強さの繰り返しを指し、音の高さには使わないので合わない。"}, {"text": "テレビのリズムを下げたら、隣の部屋の人が静かになった。", "explanation": "ここは〈音量〉の意味。リズムは音の流れのパターンを指すので、音の大きさを下げる対象にはならないので合わない。"}, {"text": "この歌手はリズムが広くて、低い音から高い音まで歌いこなせる。", "explanation": "ここは〈音域〉の意味。リズムには音の範囲の広さという意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36059, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リズム", "is_correct": true, "explanation": "音の繰り返しのパターンを「刻み方」として表す語で、この空所に入る。"}, {"text": "音階", "is_correct": false, "explanation": "音の高さを順に並べた列を指す語で、「音階の刻み方」とは言わないので合わない。"}, {"text": "音域", "is_correct": false, "explanation": "声や楽器が出せる音の高低の範囲を指す語で、「音域の刻み方」は成り立たないので合わない。"}, {"text": "ハーモニー", "is_correct": false, "explanation": "複数の音を重ねた響きを指す語で、「ハーモニーの刻み方」とは言わないので合わない。"}], "explanations": {"リズム": "音の繰り返しのパターンを「刻み方」として表す語で、この空所に入る。", "音階": "音の高さを順に並べた列を指す語で、「音階の刻み方」とは言わないので合わない。", "音域": "声や楽器が出せる音の高低の範囲を指す語で、「音域の刻み方」は成り立たないので合わない。", "ハーモニー": "複数の音を重ねた響きを指す語で、「ハーモニーの刻み方」とは言わないので合わない。"}, "sentence_index": 6, "correct_answer": "リズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この曲はリズムの言葉遣いが繊細で、聞くたびに新しい発見がある。", "explanation": "ここは〈歌詞〉の意味。言葉遣いは歌詞の領域で、リズムは音の繰り返しのパターンなので合わない。"}, {"text": "この絵はリズムの色が鮮やかで、遠くからでも目を引く。", "explanation": "ここは〈配色〉の意味。リズムは音の流れのことで、絵の配色の鮮やかさには使わないので合わない。"}, {"text": "このお茶はリズムが強く、一口飲むと口いっぱいに広がる。", "explanation": "ここは〈香り〉の意味。リズムは音の流れのことで、お茶の香りには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
