INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36061, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある方法や考え方を、正式に使うこと。", "primary_collocate": null, "pronunciation": "さいよう", "ipa": "saijoː", "syllable_count": 4, "sentences": [{"text": "あえて色数を抑えたプリント技法を採用したのは、褪せた記憶のニュアンスを表現するためです。", "target_word": "採用", "complexity_tier": "T6", "furigana": "あえて色数[いろすう]を抑[おさ]えたプリント技法[ぎほう]を採用[さいよう]したのは、褪[あ]せた記憶[きおく]のニュアンスを表現[ひょうげん]するためです。", "sentence_source": "mined"}, {"text": "新しい方法を採用しました。", "target_word": "採用", "complexity_tier": "T2", "furigana": "新[あたら]しい方法[ほうほう]を採用[さいよう]しました。", "sentence_source": "generated"}, {"text": "会議で、その案が採用された。", "target_word": "採用", "complexity_tier": "T4", "furigana": "会議[かいぎ]で、その案[あん]が採用[さいよう]された。", "sentence_source": "generated"}, {"text": "この学校は、新しい教科書を採用している。", "target_word": "採用", "complexity_tier": "T3", "furigana": "この学校[がっこう]は、新[あたら]しい教科書[きょうかしょ]を採用[さいよう]している。", "sentence_source": "generated"}, {"text": "採用の理由を教えてください。", "target_word": "採用", "complexity_tier": "T2", "furigana": "採用[さいよう]の理由[りゆう]を教[おし]えてください。", "sentence_source": "generated"}, {"text": "市は、環境にやさしい方式の採用を決めた。", "target_word": "採用", "complexity_tier": "T3", "furigana": "市[し]は、環境[かんきょう]にやさしい方式[ほうしき]の採用[さいよう]を決[き]めた。", "sentence_source": "generated"}, {"text": "彼の意見は、すぐには採用されなかった。", "target_word": "採用", "complexity_tier": "T4", "furigana": "彼[かれ]の意見[いけん]は、すぐには採用[さいよう]されなかった。", "sentence_source": "generated"}, {"text": "ほかの会社も同じ技術を採用すれば、値段が下がる。", "target_word": "採用", "complexity_tier": "T4", "furigana": "ほかの会社[かいしゃ]も同[おな]じ技術[ぎじゅつ]を採用[さいよう]すれば、値段[ねだん]が下[さ]がる。", "sentence_source": "generated"}, {"text": "私たちはチームの提案の採用に賛成した。", "target_word": "採用", "complexity_tier": "T3", "furigana": "私[わたし]たちはチームの提案[ていあん]の採用[さいよう]に賛成[さんせい]した。", "sentence_source": "generated"}, {"text": "採用された案には、いくつかの利点がある。", "target_word": "採用", "complexity_tier": "T4", "furigana": "採用[さいよう]された案[あん]には、いくつかの利点[りてん]がある。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 案や方法を正式に取り入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 褪せ (Zipf 2.21)']::text[], '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36061, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "採用", "is_correct": true, "explanation": "聞いた音「さいよう」と同じで、正解。"}, {"text": "最強", "is_correct": false, "explanation": "「さいきょう」で、3拍目の「よ」が「きょ」に変わっている。"}, {"text": "採光", "is_correct": false, "explanation": "「さいこう」で、3拍目の「よ」が「こ」に変わっている。"}, {"text": "西洋", "is_correct": false, "explanation": "「せいよう」で、1拍目の「さ」が「せ」に変わっている。"}, {"text": "最良", "is_correct": false, "explanation": "「さいりょう」で、3拍目の「よ」が「りょ」に変わっている。"}], "explanations": {"採用": "聞いた音「さいよう」と同じで、正解。", "最強": "「さいきょう」で、3拍目の「よ」が「きょ」に変わっている。", "採光": "「さいこう」で、3拍目の「よ」が「こ」に変わっている。", "西洋": "「せいよう」で、1拍目の「さ」が「せ」に変わっている。", "最良": "「さいりょう」で、3拍目の「よ」が「りょ」に変わっている。"}, "sentence_index": null, "correct_answer": "採用"}, "level_3": {"options": [{"text": "採用", "is_correct": true, "explanation": "「技法を採用した」で、方法を正式に取り入れる意味に合う。"}, {"text": "禁止", "is_correct": false, "explanation": "形は合うが意味が合わない。技法を禁止することと、表現のための選択は結びつかない。"}, {"text": "削除", "is_correct": false, "explanation": "形は合うが意味が合わない。技法を削除することは、表現するためという理由に合わない。"}, {"text": "批判", "is_correct": false, "explanation": "形は合うが意味が合わない。技法を批判することは、表現するためという理由に合わない。"}], "explanations": {"採用": "「技法を採用した」で、方法を正式に取り入れる意味に合う。", "禁止": "形は合うが意味が合わない。技法を禁止することと、表現のための選択は結びつかない。", "削除": "形は合うが意味が合わない。技法を削除することは、表現するためという理由に合わない。", "批判": "形は合うが意味が合わない。技法を批判することは、表現するためという理由に合わない。"}, "sentence_index": 0, "correct_answer": "採用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨がやんだので、傘を採用して家を出た。", "explanation": "「採用」は方法や案を正式に取り入れることで、傘を手に持って使う意味には使えない。"}, {"text": "公園で、きれいな石を採用して持ち帰った。", "explanation": "「採用」に物を拾う意味はなく、「拾う」と混同した誤用になっている。"}, {"text": "先生は、テストを採用して、点数を書いた。", "explanation": "「採用」は採点の意味では使わず、「採点」と混同した誤用になっている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36061, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "採用", "is_correct": true, "explanation": "聞いた音「さいよう」と同じで、正解。"}, {"text": "太陽", "is_correct": false, "explanation": "「たいよう」で、1拍目の「さ」が「た」に変わっている。"}, {"text": "内容", "is_correct": false, "explanation": "「ないよう」で、1拍目の「さ」が「な」に変わっている。"}, {"text": "最高", "is_correct": false, "explanation": "「さいこう」で、3拍目の「よ」が「こ」に変わっている。"}, {"text": "最上", "is_correct": false, "explanation": "「さいじょう」で、3拍目の「よ」が「じょ」に変わっている。"}], "explanations": {"採用": "聞いた音「さいよう」と同じで、正解。", "太陽": "「たいよう」で、1拍目の「さ」が「た」に変わっている。", "内容": "「ないよう」で、1拍目の「さ」が「な」に変わっている。", "最高": "「さいこう」で、3拍目の「よ」が「こ」に変わっている。", "最上": "「さいじょう」で、3拍目の「よ」が「じょ」に変わっている。"}, "sentence_index": null, "correct_answer": "採用"}, "level_3": {"options": [{"text": "採用", "is_correct": true, "explanation": "「採用されなかった」で、意見が取り入れられなかったという意味に合う。"}, {"text": "修理", "is_correct": false, "explanation": "形は合うが意味が合わない。意見は修理するものではない。"}, {"text": "販売", "is_correct": false, "explanation": "形は合うが意味が合わない。意見は販売するものではない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが意味が合わない。意見は運転するものではない。"}], "explanations": {"採用": "「採用されなかった」で、意見が取り入れられなかったという意味に合う。", "修理": "形は合うが意味が合わない。意見は修理するものではない。", "販売": "形は合うが意味が合わない。意見は販売するものではない。", "運転": "形は合うが意味が合わない。意見は運転するものではない。"}, "sentence_index": 6, "correct_answer": "採用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お客さんが来るので、部屋をきれいに採用した。", "explanation": "「採用」に掃除をする意味はなく、「掃除」の意味で使った誤用。"}, {"text": "山で、めずらしい花を採用して写真に撮った。", "explanation": "「採用」に植物を取る意味はなく、「採取」と混同した誤用。"}, {"text": "その映画は、とても採用でした。", "explanation": "「採用」は方法などを取り入れる動作で、映画の様子を表す言い方には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36061, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は、新しいシステムが採用しました。", "corrected_sentence": "この会社は、新しいシステムを採用しました。", "error_description": "「採用する」の対象を表す助詞は「が」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36061, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その計画が、委員会で採用しました。", "corrected_sentence": "その計画が、委員会で採用されました。", "error_description": "計画が主語なので、「採用しました」ではなく受け身の「採用されました」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36063, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「移行を意味する」で、移行が「意味する」の対象になる。"}, {"text": "へ", "is_correct": false, "explanation": "「移行へ意味する」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「移行と意味する」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「移行に意味する」は「意味する」の対象を示せず、文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「移行を意味する」で、移行が「意味する」の対象になる。", "へ": "「移行へ意味する」は文法的に成り立たない。", "と": "「移行と意味する」は文法的に成り立たない。", "に": "「移行に意味する」は「意味する」の対象を示せず、文として成り立たない。"}, "error_tags": {"へ": "direction", "と": "quotation", "に": "target"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36063, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「移行が完了する」で、移行が「完了する」の主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "「移行へ完了すれば」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「移行と完了すれば」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「移行の完了すれば」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「移行が完了する」で、移行が「完了する」の主語になる。", "へ": "「移行へ完了すれば」は文法的に成り立たない。", "と": "「移行と完了すれば」は文法的に成り立たない。", "の": "「移行の完了すれば」は文として成り立たない。"}, "error_tags": {"へ": "direction", "と": "quotation", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36063, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある状態や制度から別のものに変わること。移り変わること。", "primary_collocate": null, "pronunciation": "いこう", "ipa": "ikoː", "syllable_count": 3, "sentences": [{"text": "これは事業の終了ではなく、資本の循環と新たな創造への移行を意味する重要なプロセスだ。", "target_word": "移行", "complexity_tier": "T6", "furigana": "これは事業(じぎょう)の終了(しゅうりょう)ではなく、資本(しほん)の循環(じゅんかん)と新(あら)たな創造(そうぞう)への移行(いこう)を意味(いみ)する重要(じゅうよう)なプロセスだ。", "sentence_source": "mined"}, {"text": "新制度に移行する。", "target_word": "移行", "complexity_tier": "T1", "furigana": "新制度(しんせいど)に移行(いこう)する。", "sentence_source": "generated"}, {"text": "移行は終わった。", "target_word": "移行", "complexity_tier": "T1", "furigana": "移行(いこう)は終(お)わった。", "sentence_source": "generated"}, {"text": "来月、新制度に移行します。", "target_word": "移行", "complexity_tier": "T2", "furigana": "来月(らいげつ)、新制度(しんせいど)に移行(いこう)します。", "sentence_source": "generated"}, {"text": "移行の準備をします。", "target_word": "移行", "complexity_tier": "T2", "furigana": "移行(いこう)の準備(じゅんび)をします。", "sentence_source": "generated"}, {"text": "旧システムから移行して、楽になった。", "target_word": "移行", "complexity_tier": "T3", "furigana": "旧(きゅう)システムから移行(いこう)して、楽(らく)になった。", "sentence_source": "generated"}, {"text": "紙から電子への移行を、少しずつ進めている。", "target_word": "移行", "complexity_tier": "T3", "furigana": "紙(かみ)から電子(でんし)への移行(いこう)を、少(すこ)しずつ進(すす)めている。", "sentence_source": "generated"}, {"text": "移行が完了すれば、古い方法は使われなくなる。", "target_word": "移行", "complexity_tier": "T4", "furigana": "移行(いこう)が完了(かんりょう)すれば、古(ふる)い方法(ほうほう)は使(つか)われなくなる。", "sentence_source": "generated"}, {"text": "市は新しい制度への移行を来年にすると決めた。", "target_word": "移行", "complexity_tier": "T4", "furigana": "市(し)は新(あたら)しい制度(せいど)への移行(いこう)を来年(らいねん)にすると決(き)めた。", "sentence_source": "generated"}, {"text": "企業は変化に対応するため、クラウドへの移行を急がなければならない。", "target_word": "移行", "complexity_tier": "T5", "furigana": "企業(きぎょう)は変化(へんか)に対応(たいおう)するため、クラウドへの移行(いこう)を急(いそ)がなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移行する", "label": "活用"}, {"form": "移行した", "label": "活用"}, {"form": "移行期", "label": "派生"}, {"form": "移行措置", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ある状態から別のものへ変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36063, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "移行", "is_correct": true, "explanation": "見出し語「いこう」そのもの。"}, {"text": "移動", "is_correct": false, "explanation": "「いどう」で、真ん中の音がこ→どに変わる。"}, {"text": "違法", "is_correct": false, "explanation": "「いほう」で、真ん中の音がこ→ほに変わる。"}, {"text": "位相", "is_correct": false, "explanation": "「いそう」で、真ん中の音がこ→そに変わる。"}, {"text": "慰労", "is_correct": false, "explanation": "「いろう」で、真ん中の音がこ→ろに変わる。"}], "explanations": {"移行": "見出し語「いこう」そのもの。", "移動": "「いどう」で、真ん中の音がこ→どに変わる。", "違法": "「いほう」で、真ん中の音がこ→ほに変わる。", "位相": "「いそう」で、真ん中の音がこ→そに変わる。", "慰労": "「いろう」で、真ん中の音がこ→ろに変わる。"}, "sentence_index": null, "correct_answer": "移行"}, "level_3": {"options": [{"text": "移行", "is_correct": true, "explanation": "「創造への移行を意味する」で状態の変化を表し、意味が通る。"}, {"text": "修理", "is_correct": false, "explanation": "形は合うが意味が合わない。「創造への修理」とは言わない。"}, {"text": "欠席", "is_correct": false, "explanation": "形は合うが意味が合わない。「創造への欠席」は意味をなさない。"}, {"text": "到着", "is_correct": false, "explanation": "形は合うが意味が合わない。「創造への到着」は事業の話に合わない。"}], "explanations": {"移行": "「創造への移行を意味する」で状態の変化を表し、意味が通る。", "修理": "形は合うが意味が合わない。「創造への修理」とは言わない。", "欠席": "形は合うが意味が合わない。「創造への欠席」は意味をなさない。", "到着": "形は合うが意味が合わない。「創造への到着」は事業の話に合わない。"}, "sentence_index": 0, "correct_answer": "移行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、移行を食べてから出かけます。", "explanation": "移行は変化を表す名詞で、食べ物ではないので「食べる」と合わない。"}, {"text": "今日の移行は雨で、傘が必要です。", "explanation": "移行は天気を表す語ではないので、雨の意味では使えない。"}, {"text": "友達に移行を贈ったら、とても喜んでくれた。", "explanation": "移行は変化を表す語で、贈り物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36063, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "移行", "is_correct": true, "explanation": "見出し語「いこう」そのもの。"}, {"text": "異国", "is_correct": false, "explanation": "「いこく」で、最後の音がう→くに変わる。"}, {"text": "遺骨", "is_correct": false, "explanation": "「いこつ」で、最後の音がう→つに変わる。"}, {"text": "遺恨", "is_correct": false, "explanation": "「いこん」で、最後の音がう→んに変わる。"}, {"text": "お香", "is_correct": false, "explanation": "「おこう」で、最初の音がい→おに変わる。"}], "explanations": {"移行": "見出し語「いこう」そのもの。", "異国": "「いこく」で、最後の音がう→くに変わる。", "遺骨": "「いこつ」で、最後の音がう→つに変わる。", "遺恨": "「いこん」で、最後の音がう→んに変わる。", "お香": "「おこう」で、最初の音がい→おに変わる。"}, "sentence_index": null, "correct_answer": "移行"}, "level_3": {"options": [{"text": "移行", "is_correct": true, "explanation": "「紙から電子への移行」で変化を表し、意味が通る。"}, {"text": "返品", "is_correct": false, "explanation": "形は合うが意味が合わない。「電子への返品」は意味をなさない。"}, {"text": "見学", "is_correct": false, "explanation": "形は合うが意味が合わない。「電子への見学」は意味をなさない。"}, {"text": "遅刻", "is_correct": false, "explanation": "形は合うが意味が合わない。「電子への遅刻」は意味をなさない。"}], "explanations": {"移行": "「紙から電子への移行」で変化を表し、意味が通る。", "返品": "形は合うが意味が合わない。「電子への返品」は意味をなさない。", "見学": "形は合うが意味が合わない。「電子への見学」は意味をなさない。", "遅刻": "形は合うが意味が合わない。「電子への遅刻」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "移行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "企業は移行を着て、会議に出席した。", "explanation": "移行は変化を表す名詞で、服ではないので「着る」と合わない。"}, {"text": "この移行は重さが五キロもあり、持ち上げられない。", "explanation": "移行は物ではなく、重さを持たない。"}, {"text": "子どもは公園で移行を投げて遊んでいる。", "explanation": "移行は変化を表す語で、投げる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36063, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい制度への移行が燃えた。", "corrected_sentence": "新しい制度への移行が終わった。", "error_description": "「移行」は燃えない。「終わる」などの動詞が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36063, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "データの移行が青い。", "corrected_sentence": "データの移行が完了した。", "error_description": "「移行」の状態を色の形容詞「青い」で表すのは誤り。「完了する」などが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36073, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36073, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「単位」は「使われる」（受け身）の主語なので「が」。「単位がよく使われる」となる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「使われる」は受け身で目的語を取らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「単位のよく使われる」と続けると、名詞の後に動詞が続かず文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「単位へ使われる」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「単位」は「使われる」（受け身）の主語なので「が」。「単位がよく使われる」となる。", "を": "「を」は目的語を示すが、「使われる」は受け身で目的語を取らないので合わない。", "の": "「単位のよく使われる」と続けると、名詞の後に動詞が続かず文として成り立たない。", "へ": "「へ」は方向を表すので、「単位へ使われる」は意味が通らない。"}, "error_tags": {"の": "名詞修飾（文が成立しない）", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36073, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の大きさや量を測る基準となる、一定の大きさや量。また、その区切り。", "primary_collocate": null, "pronunciation": "たんい", "ipa": "taɴi", "syllable_count": 3, "sentences": [{"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "単位", "complexity_tier": "T5", "furigana": "水温(すいおん)と室温(しつおん)をミリ単位(たんい)で制御(せいぎょ)し、小麦粉(こむぎこ)と水(みず)のみを混(ま)ぜ合(あ)わせる行為(こうい)は、単(たん)なる調理(ちょうり)の域(いき)を超(こ)え、微生物(びせいぶつ)の生態系(せいたいけい)を育(はぐく)む科学的(かがくてき)な実験(じっけん)とも呼応(こおう)する。", "sentence_source": "mined"}, {"text": "長さの単位はメートルで、重さの単位はキログラムです。", "target_word": "単位", "complexity_tier": "T3", "furigana": "長(なが)さの単位(たんい)はメートルで、重(おも)さの単位(たんい)はキログラムです。", "sentence_source": "generated"}, {"text": "料理の材料は、グラムという単位ではかります。", "target_word": "単位", "complexity_tier": "T3", "furigana": "料理(りょうり)の材料(ざいりょう)は、グラムという単位(たんい)ではかります。", "sentence_source": "generated"}, {"text": "外国の単位は日本とちがうので、買い物のときに困りました。", "target_word": "単位", "complexity_tier": "T3", "furigana": "外国(がいこく)の単位(たんい)は日本(にほん)とちがうので、買(か)い物(もの)のときに困(こま)りました。", "sentence_source": "generated"}, {"text": "時間の単位には、秒、分、時間などがあります。", "target_word": "単位", "complexity_tier": "T3", "furigana": "時間(じかん)の単位(たんい)には、秒(びょう)、分(ふん)、時間(じかん)などがあります。", "sentence_source": "generated"}, {"text": "数字だけで単位を書き忘れると、答えが間違いになります。", "target_word": "単位", "complexity_tier": "T3", "furigana": "数字(すうじ)だけで単位(たんい)を書(か)き忘(わす)れると、答(こた)えが間違(まちが)いになります。", "sentence_source": "generated"}, {"text": "一週間を単位として、売り上げをまとめます。", "target_word": "単位", "complexity_tier": "T3", "furigana": "一週間(いっしゅうかん)を単位(たんい)として、売(う)り上(あ)げをまとめます。", "sentence_source": "generated"}, {"text": "アメリカでは、マイルやガロンなど日本で使わない単位がよく使われる。", "target_word": "単位", "complexity_tier": "T3", "furigana": "アメリカでは、マイルやガロンなど日本(にほん)で使(つか)わない単位(たんい)がよく使(つか)われる。", "sentence_source": "generated"}, {"text": "温度の単位を摂氏から華氏に変えると、数字が大きくなる。", "target_word": "単位", "complexity_tier": "T3", "furigana": "温度(おんど)の単位(たんい)を摂氏(せっし)から華氏(かし)に変(か)えると、数字(すうじ)が大(おお)きくなる。", "sentence_source": "generated"}, {"text": "地図の距離は、キロメートルという単位で表されている。", "target_word": "単位", "complexity_tier": "T3", "furigana": "地図(ちず)の距離(きょり)は、キロメートルという単位(たんい)で表(あらわ)されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "単位", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "長さ・重さ・時間などを測る基準の量、またはものごとの区切り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 7 words above tier T2 (max 3): 水温 (Zipf 3.22), 室温 (Zipf 3.3), 小麦粉 (Zipf 3.59), 混ぜ合わ (Zipf 2.89), 微生物 (Zipf 3.52), 育む (Zipf 3.02)']::text[], 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36073, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "単語", "is_correct": false, "explanation": "「ミリ単語」は組み合わない。ミリは量の大きさを表す語なので、単語を制御する対象にはできない。"}, {"text": "単位", "is_correct": true, "explanation": "「ミリ単位で制御し」は、ミリという大きさの基準で制御するという意味になり、文脈に合う。"}, {"text": "手順", "is_correct": false, "explanation": "「ミリ手順」は意味が通らない。ミリは量の大きさに付く語で、手順の数え方には使わない。"}, {"text": "記号", "is_correct": false, "explanation": "「ミリ記号」は組み合わない。記号は符号のことで、ミリという大きさで制御する対象ではない。"}], "explanations": {"単語": "「ミリ単語」は組み合わない。ミリは量の大きさを表す語なので、単語を制御する対象にはできない。", "単位": "「ミリ単位で制御し」は、ミリという大きさの基準で制御するという意味になり、文脈に合う。", "手順": "「ミリ手順」は意味が通らない。ミリは量の大きさに付く語で、手順の数え方には使わない。", "記号": "「ミリ記号」は組み合わない。記号は符号のことで、ミリという大きさで制御する対象ではない。"}, "sentence_index": 0, "correct_answer": "単位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は大学の単位を落として、留年が決まった。", "explanation": "ここは〈履修の認定〉の意味。大学の授業で得る単位は学業の認定で、大きさや量を測る基準ではない。"}, {"text": "彼は部隊の単位を率いて、前線へ向かった。", "explanation": "ここは〈部隊〉の意味。軍の編成の集まりを指す語で、測る基準の意味ではない。"}, {"text": "この野菜は一袋の単位が安いので、まとめ買いする。", "explanation": "ここは〈単価〉の意味。一袋あたりの値段を指す単価と混同しやすいが、単位は測る基準で値段には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36073, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "季節", "is_correct": false, "explanation": "「一週間を季節として」は、一週間を季節と見なす意味になり、売り上げをまとめる区切りにならない。"}, {"text": "単位", "is_correct": true, "explanation": "「一週間を単位として」は、一週間を区切りの基準にするという意味で、売り上げをまとめる文脈に合う。"}, {"text": "原因", "is_correct": false, "explanation": "「原因として」は理由を表す語で、まとめる基準にはならない。文の流れに合わない。"}, {"text": "文章", "is_correct": false, "explanation": "「文章として」は一週間を文章と見なすことになり、売り上げを区切る基準として不自然。"}], "explanations": {"季節": "「一週間を季節として」は、一週間を季節と見なす意味になり、売り上げをまとめる区切りにならない。", "単位": "「一週間を単位として」は、一週間を区切りの基準にするという意味で、売り上げをまとめる文脈に合う。", "原因": "「原因として」は理由を表す語で、まとめる基準にはならない。文の流れに合わない。", "文章": "「文章として」は一週間を文章と見なすことになり、売り上げを区切る基準として不自然。"}, "sentence_index": 6, "correct_answer": "単位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国は生活の単位が高く、物価も安定している。", "explanation": "ここは〈水準〉の意味。生活の高さには水準を使う。単位は数量を測る基準を指すので合わない。"}, {"text": "電車は通勤の単位として便利だ。", "explanation": "ここは〈手段〉の意味。通勤のための方法を指すので、単位では意味が合わない。"}, {"text": "彼は単位の割には若く見える。", "explanation": "ここは〈年齢〉の意味。「年齢の割には」という形で使うので、単位は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36073, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長さを測るときの単位を、メートルです。", "corrected_sentence": "長さを測るときの単位は、メートルです。", "error_description": "「を」が誤り。「単位」は説明の主題なので「は」が正しい（単位は〜です）。目的語の「を」では文がつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36073, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "気温は、摂氏という単位の表すことが多い。", "corrected_sentence": "気温は、摂氏という単位で表すことが多い。", "error_description": "「の」が誤り。手段を表す「で」を使い「単位で表す」とする。「の」では「表す」が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
