INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36077, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "他に何もなく、ただそれだけであることを表す。限定の意を表す副詞。", "primary_collocate": null, "pronunciation": "たんに", "ipa": "tanni", "syllable_count": 3, "sentences": [{"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "単に", "complexity_tier": "T6", "furigana": "このはんばいかつどうは、たんにおかねをかせぐためだけでなく、じぶんでけいかくをたててじっこうするというきちょうなけいけんをつむことがもくてきだった。", "sentence_source": "mined"}, {"text": "単に時間がなかったのです。", "target_word": "単に", "complexity_tier": "T2", "furigana": "たんにじかんがなかったのです。", "sentence_source": "generated"}, {"text": "それは単に天気の問題だ。", "target_word": "単に", "complexity_tier": "T3", "furigana": "それはたんにてんきのもんだいだ。", "sentence_source": "generated"}, {"text": "単に好きだから、毎日歌っている。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たんにすきだから、まいにちうたっている。", "sentence_source": "generated"}, {"text": "彼は単に冗談を言っただけだった。", "target_word": "単に", "complexity_tier": "T3", "furigana": "かれはたんにじょうだんをいっただけだった。", "sentence_source": "generated"}, {"text": "単に安いだけでなく、品質もいい。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たんにやすいだけでなく、ひんしつもいい。", "sentence_source": "generated"}, {"text": "私は単に事実を伝えたかった。", "target_word": "単に", "complexity_tier": "T3", "furigana": "わたしはたんにじじつをつたえたかった。", "sentence_source": "generated"}, {"text": "単に見ているだけなら、お金はかからない。", "target_word": "単に", "complexity_tier": "T4", "furigana": "たんにみているだけなら、おかねはかからない。", "sentence_source": "generated"}, {"text": "単に道に迷って、遅れたのです。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たんにみちにまよって、おくれたのです。", "sentence_source": "generated"}, {"text": "君の言葉は単に慰めにすぎなかった。", "target_word": "単に", "complexity_tier": "T4", "furigana": "きみのことばはたんになぐさめにすぎなかった。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | それだけで他にないことを表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36077, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "単に", "is_correct": true, "explanation": "見出し語「たんに」そのもの。"}, {"text": "箪笥", "is_correct": false, "explanation": "「たんす」は最後の「に」が「す」になる一拍違いの別語。"}, {"text": "短歌", "is_correct": false, "explanation": "「たんか」は最後の「に」が「か」になる一拍違いの別語。"}, {"text": "単位", "is_correct": false, "explanation": "「たんい」は最後の「に」が「い」になる一拍違いの別語。"}], "explanations": {"単に": "見出し語「たんに」そのもの。", "箪笥": "「たんす」は最後の「に」が「す」になる一拍違いの別語。", "短歌": "「たんか」は最後の「に」が「か」になる一拍違いの別語。", "単位": "「たんい」は最後の「に」が「い」になる一拍違いの別語。"}, "sentence_index": null, "correct_answer": "単に"}, "level_3": {"options": [{"text": "単に", "is_correct": true, "explanation": "「だけでなく」と呼応して、それだけではないことを示す。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "形は合うが、ゆっくり稼ぐだけでなくという意味が合わない。"}, {"text": "すっかり", "is_correct": false, "explanation": "形は合うが、「だけでなく」と呼応せず意味が合わない。"}, {"text": "はっきり", "is_correct": false, "explanation": "形は合うが、はっきり稼ぐという意味が合わない。"}], "explanations": {"単に": "「だけでなく」と呼応して、それだけではないことを示す。", "ゆっくり": "形は合うが、ゆっくり稼ぐだけでなくという意味が合わない。", "すっかり": "形は合うが、「だけでなく」と呼応せず意味が合わない。", "はっきり": "形は合うが、はっきり稼ぐという意味が合わない。"}, "sentence_index": 0, "correct_answer": "単に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は単に作れるので、初心者にもいい。", "explanation": "「単に」は「ただそれだけ」の意味で、「簡単に」の意味では使えない。"}, {"text": "私は単に二回、京都へ行った。", "explanation": "「単に」は回数を表さず、「二回」の意味では使えない。"}, {"text": "それは単にのミスだった。", "explanation": "「単に」は副詞なので「の」を付けて名詞を修飾できない。名詞の前では「単なる」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36077, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "単に", "is_correct": true, "explanation": "見出し語「たんに」そのもの。"}, {"text": "短気", "is_correct": false, "explanation": "「たんき」は最後の「に」が「き」になる一拍違いの別語。"}, {"text": "単語", "is_correct": false, "explanation": "「たんご」は最後の「に」が「ご」になる一拍違いの別語。"}, {"text": "たんと", "is_correct": false, "explanation": "「たんと」は最後の「に」が「と」になる一拍違いの別語。"}], "explanations": {"単に": "見出し語「たんに」そのもの。", "短気": "「たんき」は最後の「に」が「き」になる一拍違いの別語。", "単語": "「たんご」は最後の「に」が「ご」になる一拍違いの別語。", "たんと": "「たんと」は最後の「に」が「と」になる一拍違いの別語。"}, "sentence_index": null, "correct_answer": "単に"}, "level_3": {"options": [{"text": "単に", "is_correct": true, "explanation": "ほかの意図がなく事実を伝えたかっただけ、という意味に合う。"}, {"text": "だんだん", "is_correct": false, "explanation": "形は合うが、だんだん事実を伝えたかったという意味が合わない。"}, {"text": "さっぱり", "is_correct": false, "explanation": "形は合うが、さっぱり事実を伝えたかったという意味が合わない。"}, {"text": "すっかり", "is_correct": false, "explanation": "形は合うが、すっかり事実を伝えたかったという意味が合わない。"}], "explanations": {"単に": "ほかの意図がなく事実を伝えたかっただけ、という意味に合う。", "だんだん": "形は合うが、だんだん事実を伝えたかったという意味が合わない。", "さっぱり": "形は合うが、さっぱり事実を伝えたかったという意味が合わない。", "すっかり": "形は合うが、すっかり事実を伝えたかったという意味が合わない。"}, "sentence_index": 6, "correct_answer": "単に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このパズルは単に解けたので、すぐ終わった。", "explanation": "「単に」は「ただそれだけ」の意味で、「簡単に」の意味では使えない。"}, {"text": "彼の話は単にの冗談だった。", "explanation": "「単に」は副詞なので「の」を付けて名詞を修飾できない。名詞の前では「単なる」を使う。"}, {"text": "単に起きたら、もう昼だった。", "explanation": "「単に」は「突然」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36077, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は単に寒くて、驚いた。", "corrected_sentence": "昨日は本当に寒くて、驚いた。", "error_description": "「単に」は「ただそれだけ」の意味で、程度を強める「とても」の意味では使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36077, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このかばんは単に持てるほど軽い。", "corrected_sentence": "このかばんは簡単に持てるほど軽い。", "error_description": "「単に」は「ただそれだけ」という限定の意味で、「簡単に（たやすく）」の意味では使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
