INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36078, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "もう一度同じことをすること。", "primary_collocate": null, "pronunciation": "さいげん", "ipa": "saiɡeɴ", "syllable_count": 4, "sentences": [{"text": "同じ実験をやり直して、結果を再現することができた。", "target_word": "再現", "complexity_tier": "T3", "furigana": "同[おな]じ実験[じっけん]をやり直[なお]して、結果[けっか]を再現[さいげん]することができた。", "sentence_source": "generated"}, {"text": "エラーが再現しないので、原因がなかなか分からない。", "target_word": "再現", "complexity_tier": "T3", "furigana": "エラーが再現[さいげん]しないので、原因[げんいん]がなかなか分[わ]からない。", "sentence_source": "generated"}, {"text": "不具合を再現できれば、直し方もすぐ分かる。", "target_word": "再現", "complexity_tier": "T3", "furigana": "不具合[ふぐあい]を再現[さいげん]できれば、直[なお]し方[かた]もすぐ分[わ]かる。", "sentence_source": "generated"}, {"text": "昨日と同じ条件で再現してみたが、今日は何も起きなかった。", "target_word": "再現", "complexity_tier": "T3", "furigana": "昨日[きのう]と同[おな]じ条件[じょうけん]で再現[さいげん]してみたが、今日[きょう]は何[なに]も起[お]きなかった。", "sentence_source": "generated"}, {"text": "他の研究者が結果を再現できなかったため、論文は疑われた。", "target_word": "再現", "complexity_tier": "T3", "furigana": "他[ほか]の研究者[けんきゅうしゃ]が結果[けっか]を再現[さいげん]できなかったため、論文[ろんぶん]は疑[うたが]われた。", "sentence_source": "generated"}, {"text": "手順どおりにやれば、誰でも同じ結果を再現できる。", "target_word": "再現", "complexity_tier": "T3", "furigana": "手順[てじゅん]どおりにやれば、誰[だれ]でも同[おな]じ結果[けっか]を再現[さいげん]できる。", "sentence_source": "generated"}, {"text": "再現に失敗したので、やり方を最初から確認した。", "target_word": "再現", "complexity_tier": "T3", "furigana": "再現[さいげん]に失敗[しっぱい]したので、やり方[かた]を最初[さいしょ]から確認[かくにん]した。", "sentence_source": "generated"}, {"text": "同じ条件で再現するため、温度を細かく記録した。", "target_word": "再現", "complexity_tier": "T3", "furigana": "同[おな]じ条件[じょうけん]で再現[さいげん]するため、温度[おんど]を細[こま]かく記録[きろく]した。", "sentence_source": "generated"}, {"text": "このバグは特定の操作でだけ再現するので、調べにくい。", "target_word": "再現", "complexity_tier": "T3", "furigana": "このバグは特定[とくてい]の操作[そうさ]でだけ再現[さいげん]するので、調[しら]べにくい。", "sentence_source": "generated"}, {"text": "二度目の再現でも同じ数値が出たので、方法は信頼できる。", "target_word": "再現", "complexity_tier": "T3", "furigana": "二度目[にどめ]の再現[さいげん]でも同[おな]じ数値[すうち]が出[で]たので、方法[ほうほう]は信頼[しんらい]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "再現する", "label": "終止形"}, {"form": "再現した", "label": "過去形"}, {"form": "再現できる", "label": "可能形"}, {"form": "再現しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "実験・不具合・結果などを同じ条件でもう一度起こすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36078, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再現", "is_correct": true, "explanation": "同じ実験を繰り返して結果をもう一度起こすことを表す。「結果を再現することができた」で正解。"}, {"text": "撹拌", "is_correct": false, "explanation": "撹拌は液体などをかき混ぜること。結果を対象にすると意味が通らない。"}, {"text": "希釈", "is_correct": false, "explanation": "希釈は液を薄めること。結果を薄めるという文脈にはならない。"}, {"text": "遠心分離", "is_correct": false, "explanation": "遠心分離は遠心力で成分を分ける操作。結果を対象にする文には合わない。"}], "explanations": {"再現": "同じ実験を繰り返して結果をもう一度起こすことを表す。「結果を再現することができた」で正解。", "撹拌": "撹拌は液体などをかき混ぜること。結果を対象にすると意味が通らない。", "希釈": "希釈は液を薄めること。結果を薄めるという文脈にはならない。", "遠心分離": "遠心分離は遠心力で成分を分ける操作。結果を対象にする文には合わない。"}, "sentence_index": 0, "correct_answer": "再現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年の大会で負けた選手が、今年また再現して優勝した。", "explanation": "「再現」は人が勝ったり立ち直ったりする意味では使えず、同じ条件で出来事を起こす意味とは合わないので、この文は成り立たない。"}, {"text": "昨日の映像を再現して、もう一度見直した。", "explanation": "「再現」は録画や録音を流し直すことではなく、同じ条件で出来事を起こすことを表すので、この文には合わない。"}, {"text": "数年ぶりに友人と再現して、昔の話に花が咲いた。", "explanation": "「再現」は人に会うことを表さず、同じ条件で出来事を起こすことを表すので、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36078, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再現", "is_correct": true, "explanation": "実験の結果を同じ条件で起こすことを表す。「再現に失敗した」で正解。"}, {"text": "浮力", "is_correct": false, "explanation": "浮力は液体中で物体を押し上げる力。「浮力に失敗」では文が成り立たない。"}, {"text": "彩度", "is_correct": false, "explanation": "彩度は色の鮮やかさを表す語。「彩度に失敗」は意味が通らない。"}, {"text": "比重", "is_correct": false, "explanation": "比重は物質の重さの比を表す語。「比重に失敗」は意味が通らない。"}], "explanations": {"再現": "実験の結果を同じ条件で起こすことを表す。「再現に失敗した」で正解。", "浮力": "浮力は液体中で物体を押し上げる力。「浮力に失敗」では文が成り立たない。", "彩度": "彩度は色の鮮やかさを表す語。「彩度に失敗」は意味が通らない。", "比重": "比重は物質の重さの比を表す語。「比重に失敗」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "再現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その選手は怪我から再現して、試合に復帰した。", "explanation": "「再現」は立ち直って復帰する意味では使えず、同じ条件で出来事を起こすことを表すので、この文は成り立たない。"}, {"text": "地震で壊れた橋が再現して、来年の秋に車が通れるようになった。", "explanation": "「再現」は物が元に戻る意味では使えず、壊れたものを建て直す場合は「再建」と言うので、この文は成り立たない。"}, {"text": "今年も台風が再現して、川があふれた。", "explanation": "天候や災害が戻ってくることは「再現」では表せず、同じ条件で出来事を起こす意味とは合わないので、この文は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36078, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "実験の再現に確かめるため、同じ手順を繰り返した。", "corrected_sentence": "実験の再現を確かめるため、同じ手順を繰り返した。", "error_description": "助詞の誤り。「再現を確かめる」と目的語の「を」が必要。「再現に」では確かめる対象として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36078, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前回の結果を再現に、新しい装置を使った。", "corrected_sentence": "前回の結果を再現するため、新しい装置を使った。", "error_description": "文法の誤り。目的を表す「再現するため」を、「再現に」と名詞に続けた形にしている。「再現するため」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
