INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36079, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "過去に行われたことや表現を、もう一度作り出すこと。", "primary_collocate": null, "pronunciation": "さいげん", "ipa": "saiɡeɴ", "syllable_count": 4, "sentences": [{"text": "この映画では、百年前の街並みが細かく再現されている。", "target_word": "再現", "complexity_tier": "T3", "furigana": "この映画[えいが]では、百年前[ひゃくねんまえ]の街並[まちな]みが細[こま]かく再現[さいげん]されている。", "sentence_source": "generated"}, {"text": "警察は事件当時の状況を再現して、犯人の動きを調べた。", "target_word": "再現", "complexity_tier": "T3", "furigana": "警察[けいさつ]は事件当時[じけんとうじ]の状況[じょうきょう]を再現[さいげん]して、犯人[はんにん]の動[うご]きを調[しら]べた。", "sentence_source": "generated"}, {"text": "祖母の味を再現したくて、何度もレシピを試した。", "target_word": "再現", "complexity_tier": "T3", "furigana": "祖母[そぼ]の味[あじ]を再現[さいげん]したくて、何度[なんど]もレシピを試[ため]した。", "sentence_source": "generated"}, {"text": "博物館には、縄文時代の家を再現した模型がある。", "target_word": "再現", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]には、縄文時代[じょうもんじだい]の家[いえ]を再現[さいげん]した模型[もけい]がある。", "sentence_source": "generated"}, {"text": "彼女は昔の有名な歌手の声を見事に再現して、客を驚かせた。", "target_word": "再現", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は昔[むかし]の有名[ゆうめい]な歌手[かしゅ]の声[こえ]を見事[みごと]に再現[さいげん]して、客[きゃく]を驚[おどろ]かせた。", "sentence_source": "generated"}, {"text": "当時の衣装を再現するため、職人が古い布を探した。", "target_word": "再現", "complexity_tier": "T3", "furigana": "当時[とうじ]の衣装[いしょう]を再現[さいげん]するため、職人[しょくにん]が古[ふる]い布[ぬの]を探[さが]した。", "sentence_source": "generated"}, {"text": "役者は、実際にあった事件の場面を舞台で再現した。", "target_word": "再現", "complexity_tier": "T3", "furigana": "役者[やくしゃ]は、実際[じっさい]にあった事件[じけん]の場面[ばめん]を舞台[ぶたい]で再現[さいげん]した。", "sentence_source": "generated"}, {"text": "昔の遊びを再現するイベントで、子どもたちはこま回しを楽しんだ。", "target_word": "再現", "complexity_tier": "T3", "furigana": "昔[むかし]の遊[あそ]びを再現[さいげん]するイベントで、子[こ]どもたちはこま回[まわ]しを楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "このゲームでは、戦国時代の合戦が再現できて驚いた。", "target_word": "再現", "complexity_tier": "T3", "furigana": "このゲームでは、戦国時代[せんごくじだい]の合戦[かっせん]が再現[さいげん]できて驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "古い写真をもとに、焼失した門が忠実に再現された。", "target_word": "再現", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]をもとに、焼失[しょうしつ]した門[もん]が忠実[ちゅうじつ]に再現[さいげん]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "再現する", "label": "終止形"}, {"form": "再現した", "label": "過去形"}, {"form": "再現された", "label": "受身過去形"}, {"form": "再現できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "過去の出来事・味・風景・表現などをもう一度作って見せること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9027cc5-bdea-4db0-bd09-cd5da5c5ff46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36079, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再現", "is_correct": true, "explanation": "過去の街並みを作り直して見せることを表す。映画で細かく作られている文脈に合う正解。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は設置物を取り除くこと。街並みを取り除く意味になり、映画の文脈と合わない。"}, {"text": "禁止", "is_correct": false, "explanation": "禁止は行為をやめさせること。街並みが細かく禁止されるという文は成り立たない。"}, {"text": "割愛", "is_correct": false, "explanation": "割愛は省くこと。街並みを細かく省くという説明にはならず、映画の文脈に合わない。"}], "explanations": {"再現": "過去の街並みを作り直して見せることを表す。映画で細かく作られている文脈に合う正解。", "撤去": "撤去は設置物を取り除くこと。街並みを取り除く意味になり、映画の文脈と合わない。", "禁止": "禁止は行為をやめさせること。街並みが細かく禁止されるという文は成り立たない。", "割愛": "割愛は省くこと。街並みを細かく省くという説明にはならず、映画の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "再現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その本を再現して、もう一度読み返した。", "explanation": "ここは〈再読〉の意味。本を読み返すことは再読で、過去の場面を作り直す36079の再現とは合わない。"}, {"text": "離れていた昔の恋人を再現して、来年には式を挙げる予定だ。", "explanation": "ここは〈復縁〉の意味。別れた相手とまた付き合うことは復縁で、過去のことを作り出す再現とは合わない。"}, {"text": "地震で止まった電車を再現して、夕方から運転を始めた。", "explanation": "ここは〈復旧〉の意味。止まった交通を元に戻すことは復旧で、再現は過去の姿を作り出すことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36079, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再現", "is_correct": true, "explanation": "事件の場面を舞台でもう一度作って見せることを表す。舞台の文脈に合う正解。"}, {"text": "衝突", "is_correct": false, "explanation": "衝突はぶつかること。場面を舞台でぶつけるという文脈にはならない。"}, {"text": "変換", "is_correct": false, "explanation": "変換は形式を変えること。場面を舞台で変換するという意味にならない。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分を取り除くこと。場面を乾燥させるという文は成り立たない。"}], "explanations": {"再現": "事件の場面を舞台でもう一度作って見せることを表す。舞台の文脈に合う正解。", "衝突": "衝突はぶつかること。場面を舞台でぶつけるという文脈にはならない。", "変換": "変換は形式を変えること。場面を舞台で変換するという意味にならない。", "乾燥": "乾燥は水分を取り除くこと。場面を乾燥させるという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "再現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "話題が再現して、ニュースで大きく取り上げられた。", "explanation": "ここは〈再燃〉の意味。収まっていた話題が再び盛り上がることは再燃で、過去の場面を作り直す再現とは合わない。"}, {"text": "工事が再現して、また交通規制が始まった。", "explanation": "ここは〈再開〉の意味。中断していた工事を始め直すことは再開で、再現は過去のものを作り出すことなので合わない。"}, {"text": "昔の友人を再現して、久しぶりに食事をした。", "explanation": "ここは〈再会〉の意味。人と会うことは再会で、過去のことを作り出す36079の再現とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36079, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "博物館では、江戸時代の商店を再現で展示を見た。", "corrected_sentence": "博物館では、江戸時代の商店を再現した展示を見た。", "error_description": "活用の誤り。名詞「再現」に続けて連体修飾にするには「した」が必要。「で」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36079, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔の暮らしを再現に、古い道具を集めた。", "corrected_sentence": "昔の暮らしを再現するため、古い道具を集めた。", "error_description": "文法の誤り。目的を表す「再現するため」を、「再現に」と名詞に続けた形にしている。「再現するため」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aefd63-d97d-40d5-9d9c-e69489fba260') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36080, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を表す格助詞。「出力を高める」となる。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す格助詞。他動詞「高める」の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を表す格助詞。「出力に高める」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す格助詞。「出力と高める」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を表す格助詞。「出力を高める」となる。", "が": "主語を表す格助詞。他動詞「高める」の目的語にはならない。", "に": "方向や相手を表す格助詞。「出力に高める」は成り立たない。", "と": "共同や引用を表す格助詞。「出力と高める」は文が成り立たない。"}, "error_tags": {"が": "主語を表す格助詞。他動詞の目的語にならない", "に": "方向や相手を表す格助詞。目的語の位置に合わない", "と": "共同や引用を表す格助詞。目的語の位置に合わない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下げる", "is_correct": true, "explanation": "上の状態を低くするという意味で、「高める（声を高める）」の対義語。"}, {"text": "減らす", "is_correct": false, "explanation": "数量を少なくする意味で、「高める」の対義語ではない。"}, {"text": "広げる", "is_correct": false, "explanation": "範囲を大きくする意味で、「高める」の対義語ではない。"}, {"text": "続ける", "is_correct": false, "explanation": "継続を表し、「高める」の対義語にはならない。"}], "correct_answer": "下げる", "explanations": {"下げる": "上の状態を低くするという意味で、「高める（声を高める）」の対義語。", "減らす": "数量を少なくする意味で、「高める」の対義語ではない。", "広げる": "範囲を大きくする意味で、「高める」の対義語ではない。", "続ける": "継続を表し、「高める」の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36080, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を表す格助詞。「雰囲気を高める」となる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す格助詞。「雰囲気へ高める」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す格助詞。「雰囲気から高める」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「雰囲気の高めてくれる」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を表す格助詞。「雰囲気を高める」となる。", "へ": "方向を表す格助詞。「雰囲気へ高める」は不自然。", "から": "起点を表す格助詞。「雰囲気から高める」は不自然。", "の": "連体修飾の助詞。「雰囲気の高めてくれる」は文として成り立たない。"}, "error_tags": {"へ": "方向を表す格助詞。目的語の位置に合わない", "から": "起点を表す格助詞。目的語の位置に合わない", "の": "連体修飾の助詞。述語の位置に合わない"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下げる", "is_correct": true, "explanation": "強さの程度を低くするという意味で、「高める（強さを高める）」の対義語。"}, {"text": "止める", "is_correct": false, "explanation": "動きや活動を終わらせる意味で、「高める」の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる意味で、「高める」の対義語ではない。"}, {"text": "借りる", "is_correct": false, "explanation": "一時的に受け取る意味で、「高める」の対義語ではない。"}], "correct_answer": "下げる", "explanations": {"下げる": "強さの程度を低くするという意味で、「高める（強さを高める）」の対義語。", "止める": "動きや活動を終わらせる意味で、「高める」の対義語ではない。", "運ぶ": "物を移動させる意味で、「高める」の対義語ではない。", "借りる": "一時的に受け取る意味で、「高める」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36080, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを、もっと上の状態にすること。", "primary_collocate": null, "pronunciation": "たかめる", "ipa": "takameɾɯ", "syllable_count": 4, "sentences": [{"text": "安全性を高めるために、この橋は新しく作り直された。", "target_word": "高める", "complexity_tier": "T3", "furigana": "安全性[あんぜんせい]を高[たか]めるために、この橋[はし]は新[あたら]しく作[つく]り直[なお]された。", "sentence_source": "generated"}, {"text": "エンジンの出力を高めたら、車はさらに速く走れるようになった。", "target_word": "高め", "complexity_tier": "T3", "furigana": "エンジンの出力[しゅつりょく]を高[たか]めたら、車[くるま]はさらに速[はや]く走[はし]れるようになった。", "sentence_source": "generated"}, {"text": "ヒーターを使って、室内の温度を高めた。", "target_word": "高め", "complexity_tier": "T3", "furigana": "ヒーターを使[つか]って、室内[しつない]の温度[おんど]を高[たか]めた。", "sentence_source": "generated"}, {"text": "彼は声を高めて、会場の後ろの人にも話しかけた。", "target_word": "高め", "complexity_tier": "T3", "furigana": "彼[かれ]は声[こえ]を高[たか]めて、会場[かいじょう]の後[うし]ろの人[ひと]にも話[はな]しかけた。", "sentence_source": "generated"}, {"text": "試合の前に、選手たちは気持ちを高めていた。", "target_word": "高め", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、選手[せんしゅ]たちは気持[きも]ちを高[たか]めていた。", "sentence_source": "generated"}, {"text": "監督の言葉が、チームの士気を高めた。", "target_word": "高め", "complexity_tier": "T3", "furigana": "監督[かんとく]の言葉[ことば]が、チームの士気[しき]を高[たか]めた。", "sentence_source": "generated"}, {"text": "国際大会での優勝が、この国の地位を高めた。", "target_word": "高め", "complexity_tier": "T3", "furigana": "国際[こくさい]大会[たいかい]での優勝[ゆうしょう]が、この国[くに]の地位[ちい]を高[たか]めた。", "sentence_source": "generated"}, {"text": "音楽は、パーティーの雰囲気を高めてくれる。", "target_word": "高め", "complexity_tier": "T3", "furigana": "音楽[おんがく]は、パーティーの雰囲気[ふんいき]を高[たか]めてくれる。", "sentence_source": "generated"}, {"text": "ダムの水位を高めて、田んぼに水を送った。", "target_word": "高め", "complexity_tier": "T3", "furigana": "ダムの水位[すいい]を高[たか]めて、田[た]んぼに水[みず]を送[おく]った。", "sentence_source": "generated"}, {"text": "研究者たちは、鉄の強さを高める新しい方法を見つけた。", "target_word": "高める", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]たちは、鉄[てつ]の強[つよ]さを高[たか]める新[あたら]しい方法[ほうほう]を見[み]つけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高める", "label": "終止形"}, {"form": "高め", "label": "連用形"}, {"form": "高めて", "label": "て形"}, {"form": "高めた", "label": "過去形"}, {"form": "高めない", "label": "否定形"}, {"form": "高めれば", "label": "仮定形"}], "register": "plain", "sense_fingerprint": "温度・出力・士気・地位などをより上の段階に引き上げる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36080, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高める", "is_correct": true, "explanation": "終止形で、目的を表す「ために」の前に置かれている。「安全性を高めるために」となる。"}, {"text": "高め", "is_correct": false, "explanation": "連用形のため、「ために」に直接続かない。"}, {"text": "高めて", "is_correct": false, "explanation": "て形のため、「ために」に続かない。"}, {"text": "高めれば", "is_correct": false, "explanation": "仮定形のため、「ために」に続かない。"}], "explanations": {"高める": "終止形で、目的を表す「ために」の前に置かれている。「安全性を高めるために」となる。", "高め": "連用形のため、「ために」に直接続かない。", "高めて": "て形のため、「ために」に続かない。", "高めれば": "仮定形のため、「ために」に続かない。"}, "sentence_index": 0, "correct_answer": "高める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本のページ数を高めて、読みごたえを出した。", "explanation": "ここは〈増やす〉の意味。ページ数という量は「高める」では表せず、増やすと言う。"}, {"text": "部屋のゴミを高めて、窓を開けた。", "explanation": "ここは〈捨てる〉の意味。ゴミを処分する動作を「高める」では表さない。"}, {"text": "木の枝を高めて、形を整えた。", "explanation": "ここは〈削る〉の意味。枝を削って形を整える動作を「高める」では表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36080, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高め", "is_correct": true, "explanation": "連用形（語幹）で、「た」に続く形になる。「地位を高めた」となる。"}, {"text": "高める", "is_correct": false, "explanation": "終止形のため、「た」に続くと「高めるた」となり不自然。"}, {"text": "高く", "is_correct": false, "explanation": "形容詞の連用形で、他動詞の語幹にならない。"}, {"text": "高ければ", "is_correct": false, "explanation": "仮定形のため、「高めた」の前に入らない。"}], "explanations": {"高め": "連用形（語幹）で、「た」に続く形になる。「地位を高めた」となる。", "高める": "終止形のため、「た」に続くと「高めるた」となり不自然。", "高く": "形容詞の連用形で、他動詞の語幹にならない。", "高ければ": "仮定形のため、「高めた」の前に入らない。"}, "sentence_index": 6, "correct_answer": "高め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭に穴を高めて、植木を植えた。", "explanation": "ここは〈掘る〉の意味。地面を掘る動作を「高める」では表さない。"}, {"text": "洗濯物を高めるため、窓を開けた。", "explanation": "ここは〈乾かす〉の意味。洗濯物を乾かす行為を「高める」では表さない。"}, {"text": "卵を高めて、フライパンに入れた。", "explanation": "ここは〈割る〉の意味。卵を割る動作を「高める」では表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36080, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ポンプで用水の水位が高めて、畑に水を送った。", "corrected_sentence": "ポンプで用水の水位を高めて、畑に水を送った。", "error_description": "「水位を高める」の目的語は「を」で示す。「が」は主語を表すので、他動詞「高める」の目的語にはならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "高め", "is_correct": true, "explanation": "連用形（語幹）で、「た」に続く形になる。「出力を高めたら」の一部。"}, {"text": "高める", "is_correct": false, "explanation": "終止形のため、「たら」の前に「高めるた」とはならない。"}, {"text": "高めて", "is_correct": false, "explanation": "て形のため、「たら」に続く形として不自然。"}, {"text": "高めない", "is_correct": false, "explanation": "否定形のため、「高めないたら」とはならない。"}], "correct_form": "高め", "base_form": "高める", "form_label": "連用形", "sentence_index": 1, "explanations": {"高め": "連用形（語幹）で、「た」に続く形になる。「出力を高めたら」の一部。", "高める": "終止形のため、「たら」の前に「高めるた」とはならない。", "高めて": "て形のため、「たら」に続く形として不自然。", "高めない": "否定形のため、「高めないたら」とはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36080, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工場は機械の出力を高めったので、生産量が増えた。", "corrected_sentence": "この工場は機械の出力を高めたので、生産量が増えた。", "error_description": "「高めた」の過去形の活用が誤り。「高めったので」は存在しない形で、「高めたので」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "高め", "is_correct": true, "explanation": "連用形（語幹）で、「てくれる」の一部になっている。「雰囲気を高めてくれる」となる。"}, {"text": "高めた", "is_correct": false, "explanation": "過去形のため、「てくれる」の形につながらない。"}, {"text": "高めよう", "is_correct": false, "explanation": "意志形のため、「てくれる」の形につながらない。"}, {"text": "高めます", "is_correct": false, "explanation": "丁寧形のため、「てくれる」の形につながらない。"}], "correct_form": "高め", "base_form": "高める", "form_label": "連用形", "sentence_index": 7, "explanations": {"高め": "連用形（語幹）で、「てくれる」の一部になっている。「雰囲気を高めてくれる」となる。", "高めた": "過去形のため、「てくれる」の形につながらない。", "高めよう": "意志形のため、「てくれる」の形につながらない。", "高めます": "丁寧形のため、「てくれる」の形につながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36081, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を表す格助詞。「チームの力を高める」となる。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す格助詞。他動詞「高める」の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を表す格助詞。「力に高める」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す格助詞。「力と高める」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を表す格助詞。「チームの力を高める」となる。", "が": "主語を表す格助詞。他動詞「高める」の目的語にはならない。", "に": "方向や相手を表す格助詞。「力に高める」は成り立たない。", "と": "共同や引用を表す格助詞。「力と高める」は文が成り立たない。"}, "error_tags": {"が": "主語を表す格助詞。他動詞の目的語にならない", "に": "方向や相手を表す格助詞。目的語の位置に合わない", "と": "共同や引用を表す格助詞。目的語の位置に合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36081, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を表す格助詞。「信頼を高める」となる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す格助詞。「信頼へ高める」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す格助詞。「信頼から高める」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「信頼の高める」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を表す格助詞。「信頼を高める」となる。", "へ": "方向を表す格助詞。「信頼へ高める」は不自然。", "から": "起点を表す格助詞。「信頼から高める」は不自然。", "の": "連体修飾の助詞。「信頼の高める」は文として成り立たない。"}, "error_tags": {"へ": "方向を表す格助詞。目的語の位置に合わない", "から": "起点を表す格助詞。目的語の位置に合わない", "の": "連体修飾の助詞。述語の位置に合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36081, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の程度や質を、今よりも上がるようにすること。", "primary_collocate": null, "pronunciation": "たかめる", "ipa": "takameɾɯ", "syllable_count": 4, "sentences": [{"text": "変化に適応し、自らの価値を高め続ける姿勢が、これからの職場では強く求められる。", "target_word": "高め", "complexity_tier": "T4", "furigana": "変化[へんか]に適応[てきおう]し、自[みずか]らの価値[かち]を高[たか]め続[つづ]ける姿勢[しせい]が、これからの職場[しょくば]では強[つよ]く求[もと]められる。", "sentence_source": "mined"}, {"text": "毎日の練習は、チームの力を高めるために欠かせない。", "target_word": "高める", "complexity_tier": "T3", "furigana": "毎日[まいにち]の練習[れんしゅう]は、チームの力[ちから]を高[たか]めるために欠[か]かせない。", "sentence_source": "generated"}, {"text": "この本を読むと、環境への意識を高めることができる。", "target_word": "高める", "complexity_tier": "T3", "furigana": "この本[ほん]を読[よ]むと、環境[かんきょう]への意識[いしき]を高[たか]めることができる。", "sentence_source": "generated"}, {"text": "社員の意欲を高めるため、会社は新しい制度を作った。", "target_word": "高める", "complexity_tier": "T3", "furigana": "社員[しゃいん]の意欲[いよく]を高[たか]めるため、会社[かいしゃ]は新[あたら]しい制度[せいど]を作[つく]った。", "sentence_source": "generated"}, {"text": "先生の丁寧な指導が、生徒の学力を高めた。", "target_word": "高め", "complexity_tier": "T3", "furigana": "先生[せんせい]の丁寧[ていねい]な指導[しどう]が、生徒[せいと]の学力[がくりょく]を高[たか]めた。", "sentence_source": "generated"}, {"text": "商品の品質を高めれば、お客さんはもっと増えるだろう。", "target_word": "高め", "complexity_tier": "T3", "furigana": "商品[しょうひん]の品質[ひんしつ]を高[たか]めれば、お客[きゃく]さんはもっと増[ふ]えるだろう。", "sentence_source": "generated"}, {"text": "彼は専門の勉強を続けて、自分の能力を高めている。", "target_word": "高め", "complexity_tier": "T3", "furigana": "彼[かれ]は専門[せんもん]の勉強[べんきょう]を続[つづ]けて、自分[じぶん]の能力[のうりょく]を高[たか]めている。", "sentence_source": "generated"}, {"text": "笑顔であいさつすることは、店の信頼を高める第一歩だ。", "target_word": "高める", "complexity_tier": "T3", "furigana": "笑顔[えがお]であいさつすることは、店[みせ]の信頼[しんらい]を高[たか]める第一歩[だいいっぽ]だ。", "sentence_source": "generated"}, {"text": "もっとサービスの質を高めたいと、店長は話した。", "target_word": "高め", "complexity_tier": "T3", "furigana": "もっとサービスの質[しつ]を高[たか]めたいと、店長[てんちょう]は話[はな]した。", "sentence_source": "generated"}, {"text": "この研修は、仕事への集中力を高めるのに役立つ。", "target_word": "高める", "complexity_tier": "T3", "furigana": "この研修[けんしゅう]は、仕事[しごと]への集中力[しゅうちゅうりょく]を高[たか]めるのに役立[やくだ]つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高める", "label": "終止形"}, {"form": "高め", "label": "連用形"}, {"form": "高めて", "label": "て形"}, {"form": "高めた", "label": "過去形"}, {"form": "高めない", "label": "否定形"}, {"form": "高めれば", "label": "仮定形"}], "register": "plain", "sense_fingerprint": "能力・意識・質などの程度を向上させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36081, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高め", "is_correct": true, "explanation": "連用形で、「続ける」に続く形（高め続ける）になる。"}, {"text": "高める", "is_correct": false, "explanation": "終止形のため、「続ける」の前に置くと「高める続ける」となり不自然。"}, {"text": "高い", "is_correct": false, "explanation": "形容詞のため、他動詞「続ける」の前に入らない。"}, {"text": "高めた", "is_correct": false, "explanation": "過去形のため、「高めた続ける」とはならない。"}], "explanations": {"高め": "連用形で、「続ける」に続く形（高め続ける）になる。", "高める": "終止形のため、「続ける」の前に置くと「高める続ける」となり不自然。", "高い": "形容詞のため、他動詞「続ける」の前に入らない。", "高めた": "過去形のため、「高めた続ける」とはならない。"}, "sentence_index": 0, "correct_answer": "高め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の草を高めて、きれいに刈った。", "explanation": "ここは〈刈る〉の意味。草を切り揃える動作を「高める」では表さない。"}, {"text": "店は新しいメニューで客を高めることにした。", "explanation": "ここは〈増やす〉の意味。「高める」は人数には使わず、質や程度を上げることを表す。"}, {"text": "この大会は参加者を高めるため、賞金を増やした。", "explanation": "ここは〈集める〉の意味。人を集める場面では「高める」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36081, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高め", "is_correct": true, "explanation": "連用形（語幹）で、「ている」に続く形になる。"}, {"text": "高く", "is_correct": false, "explanation": "副詞形のため、「ている」に続かない。"}, {"text": "高ければ", "is_correct": false, "explanation": "仮定形のため、「ている」に続かない。"}, {"text": "高めない", "is_correct": false, "explanation": "否定形のため、「高めないている」とはならない。"}], "explanations": {"高め": "連用形（語幹）で、「ている」に続く形になる。", "高く": "副詞形のため、「ている」に続かない。", "高ければ": "仮定形のため、「ている」に続かない。", "高めない": "否定形のため、「高めないている」とはならない。"}, "sentence_index": 6, "correct_answer": "高め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末に新しい服を高めることにした。", "explanation": "ここは〈買う〉の意味。物を手に入れる行為に「高める」は使えない。"}, {"text": "服のほこりを高めた。", "explanation": "ここは〈払う〉の意味。ほこりを取り除く動作を「高める」では表さない。"}, {"text": "窓ガラスを高めて、部屋に風を入れた。", "explanation": "ここは〈窓を開ける〉の意味。窓を開けて風を通す動作を「高める」では表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36081, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機械を導入して、工場の生産性を高りた。", "corrected_sentence": "新しい機械を導入して、工場の生産性を高めた。", "error_description": "「高める」の連用形は「高め」。「高りた」は存在しない誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "高める", "is_correct": true, "explanation": "終止形で、目的を表す「ために」の前に置かれている。"}, {"text": "高め", "is_correct": false, "explanation": "連用形のため、「ために」に直接続かない。"}, {"text": "高めて", "is_correct": false, "explanation": "て形のため、「ために」に続かない。"}, {"text": "高めれば", "is_correct": false, "explanation": "仮定形のため、「ために」に続かない。"}], "correct_form": "高める", "base_form": "高める", "form_label": "終止形", "sentence_index": 1, "explanations": {"高める": "終止形で、目的を表す「ために」の前に置かれている。", "高め": "連用形のため、「ために」に直接続かない。", "高めて": "て形のため、「ために」に続かない。", "高めれば": "仮定形のため、「ために」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36081, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社員どうしの信頼に高めるために、定期的な話し合いを行った。", "corrected_sentence": "社員どうしの信頼を高めるために、定期的な話し合いを行った。", "error_description": "「信頼を高める」の目的語は「を」で示す。「に」は誤りで、「信頼を高める」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "高める", "is_correct": true, "explanation": "連体形で、名詞「第一歩」を修飾している。"}, {"text": "高めよう", "is_correct": false, "explanation": "意志形のため、名詞「第一歩」を修飾できない。"}, {"text": "高めます", "is_correct": false, "explanation": "丁寧形のため、名詞を修飾できない。"}, {"text": "高めろ", "is_correct": false, "explanation": "命令形のため、名詞を修飾できない。"}], "correct_form": "高める", "base_form": "高める", "form_label": "連体形", "sentence_index": 7, "explanations": {"高める": "連体形で、名詞「第一歩」を修飾している。", "高めよう": "意志形のため、名詞「第一歩」を修飾できない。", "高めます": "丁寧形のため、名詞を修飾できない。", "高めろ": "命令形のため、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
