INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36084, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わからない」の主語を示し、「相手の意図がわからない」という自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "「わからない」は目的語を取らないので、「意図を」では文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「相手の意図に」は「わからない」と結びつかず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「意図で」は手段の意味になり、「わからない」と合わない。"}], "correct_answer": "が", "explanations": {"が": "「わからない」の主語を示し、「相手の意図がわからない」という自然な文になる。", "を": "「わからない」は目的語を取らないので、「意図を」では文が成立しない。", "に": "「相手の意図に」は「わからない」と結びつかず、意味が通らない。", "で": "「意図で」は手段の意味になり、「わからない」と合わない。"}, "error_tags": {"を": "目的語", "に": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36084, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをしようと思っていること。", "primary_collocate": null, "pronunciation": "いと", "ipa": "ito", "syllable_count": 2, "sentences": [{"text": "彼がそう言った意図が、私にはよく分からない。", "target_word": "意図", "complexity_tier": "T3", "furigana": "彼[かれ]がそう言[い]った意図[いと]が、私[わたし]にはよく分[わ]からない。", "sentence_source": "generated"}, {"text": "悪い意図はなかったが、結果として相手を傷つけてしまった。", "target_word": "意図", "complexity_tier": "T3", "furigana": "悪[わる]い意図[いと]はなかったが、結果[けっか]として相手[あいて]を傷[きず]つけてしまった。", "sentence_source": "generated"}, {"text": "先生の意図を考えながら、問題を解いた。", "target_word": "意図", "complexity_tier": "T3", "furigana": "先生[せんせい]の意図[いと]を考[かんが]えながら、問題[もんだい]を解[と]いた。", "sentence_source": "generated"}, {"text": "この広告の意図は、新しい商品を知ってもらうことだ。", "target_word": "意図", "complexity_tier": "T3", "furigana": "この広告[こうこく]の意図[いと]は、新[あたら]しい商品[しょうひん]を知[し]ってもらうことだ。", "sentence_source": "generated"}, {"text": "彼女は何か意図があって、わざと遅れて来たようだ。", "target_word": "意図", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何[なに]か意図[いと]があって、わざと遅[おく]れて来[き]たようだ。", "sentence_source": "generated"}, {"text": "私の意図が正しく伝わらず、誤解を生んでしまった。", "target_word": "意図", "complexity_tier": "T3", "furigana": "私[わたし]の意図[いと]が正[ただ]しく伝[つた]わらず、誤解[ごかい]を生[う]んでしまった。", "sentence_source": "generated"}, {"text": "作者の意図を読み取るのが、この授業の目的だ。", "target_word": "意図", "complexity_tier": "T3", "furigana": "作者[さくしゃ]の意図[いと]を読[よ]み取[と]るのが、この授業[じゅぎょう]の目的[もくてき]だ。", "sentence_source": "generated"}, {"text": "相手の意図がわからないときは、直接聞くのがいちばんだ。", "target_word": "意図", "complexity_tier": "T3", "furigana": "相手[あいて]の意図[いと]がわからないときは、直接[ちょくせつ]聞[き]くのがいちばんだ。", "sentence_source": "generated"}, {"text": "そんな意図で言ったのではないと、彼は何度も説明した。", "target_word": "意図", "complexity_tier": "T3", "furigana": "そんな意図[いと]で言[い]ったのではないと、彼[かれ]は何度[なんど]も説明[せつめい]した。", "sentence_source": "generated"}, {"text": "計画の意図を説明してから、みんなの意見を聞いた。", "target_word": "意図", "complexity_tier": "T3", "furigana": "計画[けいかく]の意図[いと]を説明[せつめい]してから、みんなの意見[いけん]を聞[き]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意図", "label": "基本形"}], "register": "標準", "sense_fingerprint": "行動や発言の背後にある、しようと思っている考えやねらいを表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78c6ea7-fce0-4b94-ac7e-cd644dd6d111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36084, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意図", "is_correct": true, "explanation": "「彼がそう言った」の後に続き、言った人のねらいや考えを表す名詞として文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「言った天気」は意味が通らず、発言の内容は天気と結びつかないので合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「言った値段」は不自然で、発言が値段を指すという内容にならないので合わない。"}, {"text": "身長", "is_correct": false, "explanation": "「言った身長」は意味をなさず、発言と身長は関係がないので合わない。"}], "explanations": {"意図": "「彼がそう言った」の後に続き、言った人のねらいや考えを表す名詞として文に合う。", "天気": "「言った天気」は意味が通らず、発言の内容は天気と結びつかないので合わない。", "値段": "「言った値段」は不自然で、発言が値段を指すという内容にならないので合わない。", "身長": "「言った身長」は意味をなさず、発言と身長は関係がないので合わない。"}, "sentence_index": 0, "correct_answer": "意図"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新しい仕事に意図を燃やして、毎朝一番に出勤している。", "explanation": "ここは〈意欲〉の意味。仕事に対する熱い気持ちは意欲を燃やすと言うが、意図は燃やすものではないので合わない。"}, {"text": "彼の意図が冷たかった。", "explanation": "ここは〈態度〉の意味。人の振る舞いは態度が冷たいと言うが、意図は心に決めた考えを指すので合わない。"}, {"text": "彼女の意図が青ざめた。", "explanation": "ここは〈顔色〉の意味。顔色は青ざめると言うが、意図は人の考えを指し、顔色のように変わるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36084, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意図", "is_correct": true, "explanation": "「作者の」の後に続き、作者が作品に込めたねらいを表す名詞として自然に入る。"}, {"text": "手順", "is_correct": false, "explanation": "「作者の手順を読み取る」は意味が通らず、作品から読み取るものは手順ではないので合わない。"}, {"text": "期限", "is_correct": false, "explanation": "「作者の期限」は作品と関係がなく、読み取る対象にならないので合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「作者の季節」は意味をなさず、読み取る対象として合わない。"}], "explanations": {"意図": "「作者の」の後に続き、作者が作品に込めたねらいを表す名詞として自然に入る。", "手順": "「作者の手順を読み取る」は意味が通らず、作品から読み取るものは手順ではないので合わない。", "期限": "「作者の期限」は作品と関係がなく、読み取る対象にならないので合わない。", "季節": "「作者の季節」は意味をなさず、読み取る対象として合わない。"}, "sentence_index": 6, "correct_answer": "意図"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は勝つためなら、意図を選ばない人だ。", "explanation": "ここは〈手段〉の意味。「手段を選ばない」の形で使うが、意図は選ぶものではないので合わない。"}, {"text": "新しい工場の意図を焼いた。", "explanation": "ここは〈食器〉の意味。意図は焼いて作るものではないので合わない。"}, {"text": "会社は来年度の意図を運んだ。", "explanation": "ここは〈荷物〉の意味。意図は運ぶものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36084, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の意図をよく分かった。", "corrected_sentence": "彼女の意図がよく分かった。", "error_description": "「分かる」は「が」を取るので「意図が」が正しい。「意図を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36084, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の意図に正確に読み取るのは難しい。", "corrected_sentence": "彼の意図を正確に読み取るのは難しい。", "error_description": "「読み取る」は「を」を取るので「意図を」が正しい。「意図に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8c29ec8-8fc2-4ddd-a8d5-f4dfa75a1261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36093, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「以降」に続けて時の範囲を主題として示す「は」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「明日以降を天気が回復する」は目的語にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「明日以降で」は場所や手段の「で」としても意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「明日以降と天気」は並列にならず、文が成立しない。"}], "correct_answer": "は", "explanations": {"は": "「以降」に続けて時の範囲を主題として示す「は」が正しい。", "を": "「明日以降を天気が回復する」は目的語にならず不自然。", "で": "「明日以降で」は場所や手段の「で」としても意味が通らない。", "と": "「明日以降と天気」は並列にならず、文が成立しない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "並列・共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "基準となる時点より前を表し、「以降」の対義語として辞書で対になる語。"}, {"text": "以内", "is_correct": false, "explanation": "範囲の上限を示す語で、基準より後の時点とは対立しない。"}, {"text": "当日", "is_correct": false, "explanation": "〈当日〉はその日を指す語で、時間の前後を対立させる対義語にはならない。"}, {"text": "途中", "is_correct": false, "explanation": "期間の中の一点を指す語で、「以降」と対になる語ではない。"}], "correct_answer": "以前", "explanations": {"以前": "基準となる時点より前を表し、「以降」の対義語として辞書で対になる語。", "以内": "範囲の上限を示す語で、基準より後の時点とは対立しない。", "当日": "〈当日〉はその日を指す語で、時間の前後を対立させる対義語にはならない。", "途中": "期間の中の一点を指す語で、「以降」と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36093, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「以降」に続けて時の範囲を主題として示す「は」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「以降へ」は方向を表すが、ここは時点の範囲を述べるので不自然。"}, {"text": "で", "is_correct": false, "explanation": "「以降で」は場所や手段の「で」になり、時点の範囲を述べる文に合わず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「十八歳になって以降が契約できる」では主語が成立せず不自然。"}], "correct_answer": "は", "explanations": {"は": "「以降」に続けて時の範囲を主題として示す「は」が正しい。", "へ": "「以降へ」は方向を表すが、ここは時点の範囲を述べるので不自然。", "で": "「以降で」は場所や手段の「で」になり、時点の範囲を述べる文に合わず不自然。", "が": "「十八歳になって以降が契約できる」では主語が成立せず不自然。"}, "error_tags": {"へ": "方向", "で": "場所・手段", "が": "主語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "基準となる時点より前を表し、「以降」の対義語として辞書で対になる語。"}, {"text": "以外", "is_correct": false, "explanation": "「〜を除いて」の意味で、時間の前後を表す対義語にはならない。"}, {"text": "最中", "is_correct": false, "explanation": "ある時間の真っ只中を表す語で、対義語ではない。"}, {"text": "期間", "is_correct": false, "explanation": "期間の長さを表す語で、「以降」の対義語とは言えない。"}], "correct_answer": "以前", "explanations": {"以前": "基準となる時点より前を表し、「以降」の対義語として辞書で対になる語。", "以外": "「〜を除いて」の意味で、時間の前後を表す対義語にはならない。", "最中": "ある時間の真っ只中を表す語で、対義語ではない。", "期間": "期間の長さを表す語で、「以降」の対義語とは言えない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36093, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある時点を基準にして、それより後の時間を表す語。", "primary_collocate": null, "pronunciation": "いこう", "ipa": "ikoː", "syllable_count": 3, "sentences": [{"text": "しかし、産業革命以降の急激な人間活動、とりわけ化石燃料の大量消費と森林破壊は、この循環に深刻な破綻をもたらした。", "target_word": "以降", "complexity_tier": "T4", "furigana": "しかし、産業革命[さんぎょうかくめい]以降[いこう]の急激[きゅうげき]な人間活動[にんげんかつどう]、とりわけ化石燃料[かせきねんりょう]の大量消費[たいりょうしょうひ]と森林破壊[しんりんはかい]は、この循環[じゅんかん]に深刻[しんこく]な破綻[はたん]をもたらした。", "sentence_source": "mined"}, {"text": "明日以降は天気が回復する見込みです。", "target_word": "以降", "complexity_tier": "T2", "furigana": "明日[あす]以降[いこう]は天気[てんき]が回復[かいふく]する見込[みこ]みです。", "sentence_source": "generated"}, {"text": "来月以降、電車の料金が上がることになった。", "target_word": "以降", "complexity_tier": "T3", "furigana": "来月[らいげつ]以降[いこう]、電車[でんしゃ]の料金[りょうきん]が上[あ]がることになった。", "sentence_source": "generated"}, {"text": "午後九時以降は、大きな音を出さないでください。", "target_word": "以降", "complexity_tier": "T2", "furigana": "午後九時[ごごくじ]以降[いこう]は、大[おお]きな音[おと]を出[だ]さないでください。", "sentence_source": "generated"}, {"text": "私は大学を卒業して以降、一度も故郷に帰っていない。", "target_word": "以降", "complexity_tier": "T3", "furigana": "私[わたし]は大学[だいがく]を卒業[そつぎょう]して以降[いこう]、一度[いちど]も故郷[こきょう]に帰[かえ]っていない。", "sentence_source": "generated"}, {"text": "四月以降に入社した社員は、この研修を受ける必要があります。", "target_word": "以降", "complexity_tier": "T3", "furigana": "四月[しがつ]以降[いこう]に入社[にゅうしゃ]した社員[しゃいん]は、この研修[けんしゅう]を受[う]ける必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "二〇二〇年以降、在宅で働く人が大きく増えた。", "target_word": "以降", "complexity_tier": "T3", "furigana": "二〇二〇年[にせんにじゅうねん]以降[いこう]、在宅[ざいたく]で働[はたら]く人[ひと]が大[おお]きく増[ふ]えた。", "sentence_source": "generated"}, {"text": "十八歳になって以降は、親の同意がなくても契約できる。", "target_word": "以降", "complexity_tier": "T3", "furigana": "十八歳[じゅうはっさい]になって以降[いこう]は、親[おや]の同意[どうい]がなくても契約[けいやく]できる。", "sentence_source": "generated"}, {"text": "このクーポンは、五日以降は使えなくなります。", "target_word": "以降", "complexity_tier": "T2", "furigana": "このクーポンは、五日[いつか]以降[いこう]は使[つか]えなくなります。", "sentence_source": "generated"}, {"text": "引っ越し以降、毎朝歩いて駅まで通っている。", "target_word": "以降", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]し以降[いこう]、毎朝[まいあさ]歩[ある]いて駅[えき]まで通[かよ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "以降", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ある時点を起点として、それ以後の時間を指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36093, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以降", "is_correct": true, "explanation": "「産業革命以降」で、ある時点より後を表すので正しい。"}, {"text": "以内", "is_correct": false, "explanation": "「産業革命以内」は範囲を表す語で、時点の後を示す文脈に合わない。"}, {"text": "限界", "is_correct": false, "explanation": "「産業革命限界」は意味が通らず、ここに入らない。"}, {"text": "作業", "is_correct": false, "explanation": "「産業革命作業」は成り立たず、文の構造に入らない。"}], "explanations": {"以降": "「産業革命以降」で、ある時点より後を表すので正しい。", "以内": "「産業革命以内」は範囲を表す語で、時点の後を示す文脈に合わない。", "限界": "「産業革命限界」は意味が通らず、ここに入らない。", "作業": "「産業革命作業」は成り立たず、文の構造に入らない。"}, "sentence_index": 0, "correct_answer": "以降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年収三百万円以降の人は、税金が少し安くなる。", "explanation": "ここは〈以上〉の意味。金額の下限には「以上」を使い、「以降」は時点の後を表す語なので合わない。"}, {"text": "定員は十名以降ですので、先着順でご案内します。", "explanation": "ここは〈以内〉（上限）の意味。定員は上限を示すので「十名以内」と言い、「以降」は基準より後を表すため上限には合わない。"}, {"text": "三年以降、彼には会っていない。", "explanation": "ここは〈以来〉の意味。過去から今までの継続を表すので「三年以来」と言い、「以降」では意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36093, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以降", "is_correct": true, "explanation": "「二〇二〇年以降」で、その年より後の期間を表すので正しい。"}, {"text": "以下", "is_correct": false, "explanation": "「二〇二〇年以下」は時点の後を表す文脈と合わない。"}, {"text": "手段", "is_correct": false, "explanation": "「二〇二〇年手段」は意味が通らず、ここに入らない。"}, {"text": "寸法", "is_correct": false, "explanation": "「二〇二〇年寸法」は成り立たず、文の構造に入らない。"}], "explanations": {"以降": "「二〇二〇年以降」で、その年より後の期間を表すので正しい。", "以下": "「二〇二〇年以下」は時点の後を表す文脈と合わない。", "手段": "「二〇二〇年手段」は意味が通らず、ここに入らない。", "寸法": "「二〇二〇年寸法」は成り立たず、文の構造に入らない。"}, "sentence_index": 6, "correct_answer": "以降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ゴールを決めたすぐ以降、彼は喜んで走り回った。", "explanation": "ここは〈直後〉の意味。瞬間のすぐ後は「直後」と言い、「すぐ」と重なる「以降」は時間の幅を指すので合わない。"}, {"text": "試合の真っ最中以降、観客は大きな声で応援していた。", "explanation": "ここは〈最中〉の意味。試合の途中の場面は「真っ最中」と言い、途中から後を指す「以降」とは合わない。"}, {"text": "出発する直前以降に、彼は忘れ物に気づいた。", "explanation": "ここは〈直前〉の意味。出発の少し前は「直前」と言い、「以降」は出発後を指すので時間の向きが逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36093, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週以降を、電車の本数が増える予定です。", "corrected_sentence": "来週以降は、電車の本数が増える予定です。", "error_description": "「以降」に続けて主題を示すには「は」が自然。「を」は目的語を示すので、ここでは不適。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36093, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "四月以降の、この店は夜も営業している。", "corrected_sentence": "四月以降、この店は夜も営業している。", "error_description": "「以降」の後に「の」を付けると連体修飾になるが、続く名詞がなく文が中断する。ここでは「の」は不要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
