INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36095, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「さらに」は、物事の程度がもっと進むことや、何かに加えて別のことにも及ぶことを表します。", "primary_collocate": null, "pronunciation": "さらに", "ipa": "saɾani", "syllable_count": 3, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "さらに", "complexity_tier": "T6", "furigana": "我々[われわれ]が直面[ちょくめん]する環境的[かんきょうてき]限界[げんかい]を超越[ちょうえつ]するため、CCUSの社会[しゃかい]実装[じっそう]は、産業[さんぎょう]構造[こうぞう]の転換[てんかん]を支[ささ]える要石[かなめいし]として、その存在感[そんざいかん]をさらに増[ま]していくであろう。", "sentence_source": "mined"}, {"text": "風がさらに強くなった。", "target_word": "さらに", "complexity_tier": "T2", "furigana": "風[かぜ]がさらに強[つよ]くなった。", "sentence_source": "generated"}, {"text": "明日はさらに寒くなります。", "target_word": "さらに", "complexity_tier": "T2", "furigana": "明日[あした]はさらに寒[さむ]くなります。", "sentence_source": "generated"}, {"text": "さらに質問があります。", "target_word": "さらに", "complexity_tier": "T2", "furigana": "さらに質問[しつもん]があります。", "sentence_source": "generated"}, {"text": "説明を聞いて、さらに分かりにくくなった。", "target_word": "さらに", "complexity_tier": "T3", "furigana": "説明[せつめい]を聞[き]いて、さらに分[わ]かりにくくなった。", "sentence_source": "generated"}, {"text": "練習を続けて、さらに上手になりたいです。", "target_word": "さらに", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を続[つづ]けて、さらに上手[じょうず]になりたいです。", "sentence_source": "generated"}, {"text": "値段が上がったうえに、さらに税金も増えるそうだ。", "target_word": "さらに", "complexity_tier": "T4", "furigana": "値段[ねだん]が上[あ]がったうえに、さらに税金[ぜいきん]も増[ふ]えるそうだ。", "sentence_source": "generated"}, {"text": "さらに五分待ってください。", "target_word": "さらに", "complexity_tier": "T2", "furigana": "さらに五分[ごふん]待[ま]ってください。", "sentence_source": "generated"}, {"text": "計画を見直した結果、さらに費用を減らせることが分かった。", "target_word": "さらに", "complexity_tier": "T5", "furigana": "計画[けいかく]を見直[みなお]した結果[けっか]、さらに費用[ひよう]を減[へ]らせることが分[わ]かった。", "sentence_source": "generated"}, {"text": "この本は前の本よりさらに面白いです。", "target_word": "さらに", "complexity_tier": "T3", "furigana": "この本[ほん]は前[まえ]の本[ほん]よりさらに面白[おもしろ]いです。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | 程度がもっと進む、さらに加わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36095, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "更に", "is_correct": true, "explanation": "見出し語「さらに」で、これが正解です。"}, {"text": "攫う", "is_correct": false, "explanation": "「さらう」は最後の一拍が「に」でなく「う」で、別の語です。"}, {"text": "晒す", "is_correct": false, "explanation": "「さらす」は最後の一拍が「す」で、別の語です。"}, {"text": "さらり", "is_correct": false, "explanation": "「さらり」は最後の一拍が「り」で、別の語です。"}, {"text": "さらば", "is_correct": false, "explanation": "「さらば」は最後の一拍が「ば」で、別の語です。"}], "explanations": {"更に": "見出し語「さらに」で、これが正解です。", "攫う": "「さらう」は最後の一拍が「に」でなく「う」で、別の語です。", "晒す": "「さらす」は最後の一拍が「す」で、別の語です。", "さらり": "「さらり」は最後の一拍が「り」で、別の語です。", "さらば": "「さらば」は最後の一拍が「ば」で、別の語です。"}, "sentence_index": null, "correct_answer": "更に"}, "level_3": {"options": [{"text": "さらに", "is_correct": true, "explanation": "存在感がもっと増すという程度の進みを表し、文意に合います。"}, {"text": "突然", "is_correct": false, "explanation": "形は合うが、「増していくであろう」という流れと突発の意味が合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、社会実装の見通しに偶然という意味は合わない。"}, {"text": "前もって", "is_correct": false, "explanation": "形は合うが、存在感の増加に「事前に」という意味は合わない。"}], "explanations": {"さらに": "存在感がもっと増すという程度の進みを表し、文意に合います。", "突然": "形は合うが、「増していくであろう」という流れと突発の意味が合わない。", "偶然": "形は合うが、社会実装の見通しに偶然という意味は合わない。", "前もって": "形は合うが、存在感の増加に「事前に」という意味は合わない。"}, "sentence_index": 0, "correct_answer": "さらに"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の名前はさらに田中です。", "explanation": "名前の説明に「さらに」は使えず、程度の進行や追加の意味がないので不自然です。"}, {"text": "今日は天気がいいので、さらに傘を持って出かけた。", "explanation": "前の内容に追加も程度の進みもなく、「さらに」の意味に合いません。"}, {"text": "彼はさらに先生ではなく学生だ。", "explanation": "否定による言い換えに「さらに」は使えず、追加・程度の意味が成り立ちません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36095, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "さらに", "is_correct": true, "explanation": "値上がりに加えて税金も増えるという追加を表し、文意に合います。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は後ろに否定が必要で、「増えるそうだ」とは結びつかない。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "形は合うが、税金が増えることに速度の意味は合わない。"}, {"text": "きちんと", "is_correct": false, "explanation": "形は合うが、税金が増えるという話に几帳面さの意味は合わない。"}], "explanations": {"さらに": "値上がりに加えて税金も増えるという追加を表し、文意に合います。", "決して": "「決して」は後ろに否定が必要で、「増えるそうだ」とは結びつかない。", "ゆっくり": "形は合うが、税金が増えることに速度の意味は合わない。", "きちんと": "形は合うが、税金が増えるという話に几帳面さの意味は合わない。"}, "sentence_index": 6, "correct_answer": "さらに"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女はさらにわたしの姉です。", "explanation": "人物関係の説明に「さらに」は使えず、程度や追加の意味が成り立たない。"}, {"text": "山田さんは先月さらに生まれました。", "explanation": "出来事の時期に「さらに」は使えず、追加の意味が成り立たない。"}, {"text": "この魚はさらに死んでいます。", "explanation": "「すでに」の意味で誤用している。「さらに」は程度や追加を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36095, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "田中さんはさらに会社員です。", "corrected_sentence": "田中さんは会社員です。", "error_description": "追加も程度の進みもない文に「さらに」を使っているのが誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36095, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私の誕生日はさらに五月です。", "corrected_sentence": "私の誕生日は五月です。", "error_description": "追加も程度の進みもない文に「さらに」を使っているのが誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
