INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36096, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "何かが重なって、いくつもの層になっていること。", "primary_collocate": null, "pronunciation": "たそう", "ipa": "tasoː", "syllable_count": 3, "sentences": [{"text": "この壁は多層になっていて、音を通しにくい。", "target_word": "多層", "complexity_tier": "T3", "furigana": "この壁[かべ]は多層[たそう]になっていて、音[おと]を通[とお]しにくい。", "sentence_source": "generated"}, {"text": "この崖は多層になっていて、昔の火山の活動がよくわかる。", "target_word": "多層", "complexity_tier": "T3", "furigana": "この崖[がけ]は多層[たそう]になっていて、昔[むかし]の火山[かざん]の活動[かつどう]がよくわかる。", "sentence_source": "generated"}, {"text": "多層のケーキを作るために、生地を何枚も焼いた。", "target_word": "多層", "complexity_tier": "T3", "furigana": "多層[たそう]のケーキを作[つく]るために、生地[きじ]を何枚[なんまい]も焼[や]いた。", "sentence_source": "generated"}, {"text": "この岩は多層になっていて、割ると断面にしまが見える。", "target_word": "多層", "complexity_tier": "T3", "furigana": "この岩[いわ]は多層[たそう]になっていて、割[わ]ると断面[だんめん]にしまが見える。", "sentence_source": "generated"}, {"text": "この布は多層で、冬でも暖かい。", "target_word": "多層", "complexity_tier": "T3", "furigana": "この布[ぬの]は多層[たそう]で、冬[ふゆ]でも暖[あたた]かい。", "sentence_source": "generated"}, {"text": "多層のパイは、何枚もの生地が重なってさくさくする。", "target_word": "多層", "complexity_tier": "T3", "furigana": "多層[たそう]のパイは、何枚[なんまい]もの生地[きじ]が重[かさ]なってさくさくする。", "sentence_source": "generated"}, {"text": "紙を多層に貼り合わせると、丈夫な箱ができる。", "target_word": "多層", "complexity_tier": "T3", "furigana": "紙[かみ]を多層[たそう]に貼[は]り合[あ]わせると、丈夫[じょうぶ]な箱[はこ]ができる。", "sentence_source": "generated"}, {"text": "多層のフィルターが、細かいごみまでとってくれる。", "target_word": "多層", "complexity_tier": "T3", "furigana": "多層[たそう]のフィルターが、細[こま]かいごみまでとってくれる。", "sentence_source": "generated"}, {"text": "木の板を多層に重ねて、強いテーブルを作った。", "target_word": "多層", "complexity_tier": "T3", "furigana": "木[き]の板[いた]を多層[たそう]に重[かさ]ねて、強[つよ]いテーブルを作[つく]った。", "sentence_source": "generated"}, {"text": "火山の灰が多層に積もり、山の斜面にしまができた。", "target_word": "多層", "complexity_tier": "T3", "furigana": "火山[かざん]の灰[はい]が多層[たそう]に積[つ]もり、山[やま]の斜面[しゃめん]にしまができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多層", "label": "基本形"}, {"form": "多層の", "label": "連体形(の)"}, {"form": "多層に", "label": "連用形(に)"}], "register": "neutral", "sense_fingerprint": "多層: 物が重なって何枚もの層になっている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36096, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多層", "is_correct": true, "explanation": "何枚もの層が重なった壁の構造を指す名詞。「壁は多層になっていて」で文に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は粒の食品で、「壁は砂糖になっていて」は構造を表さず不自然。"}, {"text": "花びら", "is_correct": false, "explanation": "花びらは植物の一部で、壁の構造としては成り立たない。"}, {"text": "煙突", "is_correct": false, "explanation": "煙突は別の建造物で、「壁は煙突になっていて」は文として成立しない。"}], "explanations": {"多層": "何枚もの層が重なった壁の構造を指す名詞。「壁は多層になっていて」で文に合う。", "砂糖": "砂糖は粒の食品で、「壁は砂糖になっていて」は構造を表さず不自然。", "花びら": "花びらは植物の一部で、壁の構造としては成り立たない。", "煙突": "煙突は別の建造物で、「壁は煙突になっていて」は文として成立しない。"}, "sentence_index": 0, "correct_answer": "多層"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このボードは多層で、一枚の板からできている。", "explanation": "ここは〈一枚の板から切り出した〉の意味の単板。多層は層が何重にもあることなので、一枚の板からできた様子には合わない。"}, {"text": "この膜は多層で、細胞が一列に並んでいる。", "explanation": "ここは〈層が一枚だけ〉の意味の単層。多層は層が何重にもあることなので、一列の細胞には合わない。"}, {"text": "この布は多層で、一本の糸だけでできている。", "explanation": "ここは〈一本の糸で織った〉の意味の単糸。多層は層が重なることなので、一本の糸だけでできた布には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36096, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多層", "is_correct": true, "explanation": "紙を何枚も重ねて貼る状態を表す。「多層に貼り合わせる」の形で文に合う。"}, {"text": "霧", "is_correct": false, "explanation": "霧は空中の水滴で、「紙を霧に貼り合わせる」は成り立たない。"}, {"text": "粉末", "is_correct": false, "explanation": "粉末は細かい粒の状態で、紙を粉末に貼り合わせることはできない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は洗う物質で、「紙を石鹸に貼り合わせる」は不自然。"}], "explanations": {"多層": "紙を何枚も重ねて貼る状態を表す。「多層に貼り合わせる」の形で文に合う。", "霧": "霧は空中の水滴で、「紙を霧に貼り合わせる」は成り立たない。", "粉末": "粉末は細かい粒の状態で、紙を粉末に貼り合わせることはできない。", "石鹸": "石鹸は洗う物質で、「紙を石鹸に貼り合わせる」は不自然。"}, "sentence_index": 6, "correct_answer": "多層"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この文字は多層で、一画だけで書かれている。", "explanation": "ここは〈一本の線で描いた〉の意味の単線。多層は層が重なることなので、一画だけで書いた文字には合わない。"}, {"text": "この湖には小さな島が多層になっていて、景色がよい。", "explanation": "ここは〈あちこちに散らばる〉の意味の点在。多層は層が重なる状態なので、島の配置には合わない。"}, {"text": "このクリームは多層で、ゆっくり流れる。", "explanation": "ここは〈液体の状態〉の意味の液状。多層は層が重なることなので、流れる液体の状態には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36096, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この断面は多層でなっていて、昔の火山の灰の層が数えられる。", "corrected_sentence": "この断面は多層になっていて、昔の火山の灰の層が数えられる。", "error_description": "「なる」は結果を表す「に」を取る。「多層で」は誤りで、正しくは「多層に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36096, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このガラスは多層に重なったて、光をやわらげる。", "corrected_sentence": "このガラスは多層に重なっていて、光をやわらげる。", "error_description": "「重なる」は「ていて」の形で続ける。「重なったて」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
