INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36097, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事が複数の段階やレベルに重なっていること。また、その様子。", "primary_collocate": null, "pronunciation": "たそう", "ipa": "tasoː", "syllable_count": 3, "sentences": [{"text": "この問題は原因が多層になっていて、簡単には解決できない。", "target_word": "多層", "complexity_tier": "T3", "furigana": "この問題[もんだい]は原因[げんいん]が多層[たそう]になっていて、簡単[かんたん]には解決[かいけつ]できない。", "sentence_source": "generated"}, {"text": "この詩は多層の意味を持つので、読むたびに発見がある。", "target_word": "多層", "complexity_tier": "T3", "furigana": "この詩[し]は多層[たそう]の意味[いみ]を持[も]つので、読[よ]むたびに発見[はっけん]がある。", "sentence_source": "generated"}, {"text": "会社の組織が多層で、決定までに時間がかかる。", "target_word": "多層", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の組織[そしき]が多層[たそう]で、決定[けってい]までに時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "この小説は物語が多層になっていて、何度読んでも新しい意味が見つかる。", "target_word": "多層", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は物語[ものがたり]が多層[たそう]になっていて、何度[なんど]読[よ]んでも新[あたら]しい意味[いみ]が見[み]つかる。", "sentence_source": "generated"}, {"text": "彼の悩みは多層で、一つ解決しても別の問題が残る。", "target_word": "多層", "complexity_tier": "T3", "furigana": "彼[かれ]の悩[なや]みは多層[たそう]で、一[ひと]つ解決[かいけつ]しても別[べつ]の問題[もんだい]が残[のこ]る。", "sentence_source": "generated"}, {"text": "多層の支援があり、困ったときの相談窓口が複数ある。", "target_word": "多層", "complexity_tier": "T3", "furigana": "多層[たそう]の支援[しえん]があり、困[こま]ったときの相談窓口[そうだんまどぐち]が複数[ふくすう]ある。", "sentence_source": "generated"}, {"text": "説明が多層になりすぎて、初心者には難しい。", "target_word": "多層", "complexity_tier": "T3", "furigana": "説明[せつめい]が多層[たそう]になりすぎて、初心者[しょしんしゃ]には難[むずか]しい。", "sentence_source": "generated"}, {"text": "文化は多層に積み重なって、今の社会を作っている。", "target_word": "多層", "complexity_tier": "T3", "furigana": "文化[ぶんか]は多層[たそう]に積[つ]み重[かさ]なって、今[いま]の社会[しゃかい]を作[つく]っている。", "sentence_source": "generated"}, {"text": "この制度は多層の仕組みで、国と県と市がそれぞれ役割を持つ。", "target_word": "多層", "complexity_tier": "T3", "furigana": "この制度[せいど]は多層[たそう]の仕組[しく]みで、国[くに]と県[けん]と市[し]がそれぞれ役割[やくわり]を持[も]つ。", "sentence_source": "generated"}, {"text": "情報を守るため、多層の対策をとっている。", "target_word": "多層", "complexity_tier": "T3", "furigana": "情報[じょうほう]を守[まも]るため、多層[たそう]の対策[たいさく]をとっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多層", "label": "基本形"}, {"form": "多層の", "label": "連体形(の)"}, {"form": "多層に", "label": "連用形(に)"}], "register": "neutral", "sense_fingerprint": "多層: 物事や意味が複数の段階・レベルに重なっている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36097, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多層", "is_correct": true, "explanation": "原因が段階的に重なっている状態を表す。「原因が多層になっていて」で文に合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期を指す語で、「原因が季節になっていて」は成り立たない。"}, {"text": "方針", "is_correct": false, "explanation": "方針は進め方の決まりで、「原因が方針になっていて」は不自然。"}, {"text": "色合い", "is_correct": false, "explanation": "色合いは色の具合を指し、原因の状態を表す文脈には合わない。"}], "explanations": {"多層": "原因が段階的に重なっている状態を表す。「原因が多層になっていて」で文に合う。", "季節": "季節は時期を指す語で、「原因が季節になっていて」は成り立たない。", "方針": "方針は進め方の決まりで、「原因が方針になっていて」は不自然。", "色合い": "色合いは色の具合を指し、原因の状態を表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "多層"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この計画は多層で、目的は一つしかない。", "explanation": "ここは〈一つだけの〉の意味の単一。多層は段階が重なることなので、目的が一つだけの計画には合わない。"}, {"text": "この問題は原因が多層で、すぐに解決できる。", "explanation": "ここは〈要素が少なく単純〉の意味の単純。多層は段階が重なる意味なので、単純な原因には合わない。"}, {"text": "この説明は多層で、ほかの立場が入っていない。", "explanation": "ここは〈一つの面しか見ていない〉の意味の一面的。多層は段階が重なることなので、一面的な説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36097, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多層", "is_correct": true, "explanation": "説明の仕組みが段階的に重なっている状態を表す。「説明が多層になりすぎて」で文に合う。"}, {"text": "日程", "is_correct": false, "explanation": "日程は予定の期間を指し、「説明が日程になりすぎて」は成り立たない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分の割合を指し、「説明が湿度になりすぎて」は成り立たない。"}, {"text": "順番", "is_correct": false, "explanation": "順番は並ぶ順序を指し、説明の状態を表す文脈では成立しない。"}], "explanations": {"多層": "説明の仕組みが段階的に重なっている状態を表す。「説明が多層になりすぎて」で文に合う。", "日程": "日程は予定の期間を指し、「説明が日程になりすぎて」は成り立たない。", "湿度": "湿度は空気中の水分の割合を指し、「説明が湿度になりすぎて」は成り立たない。", "順番": "順番は並ぶ順序を指し、説明の状態を表す文脈では成立しない。"}, "sentence_index": 6, "correct_answer": "多層"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作業は決められた多層を守って行う。", "explanation": "ここは〈決まった並び〉の意味の順序。多層は段階が重なる様子なので、守るべき決まりにはならない。"}, {"text": "この店は多層の品ぞろえで、雑貨から食品まで選べる。", "explanation": "ここは〈種類がさまざまな〉の意味の多彩。多層は段階が重なることなので、品ぞろえの幅には使わない。"}, {"text": "家族は古い多層を守って暮らしている。", "explanation": "ここは〈受け継がれてきた習わし〉の意味の伝統。多層は段階が重なることなので、守る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36097, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この考えは多層で積み重なって、今の制度になった。", "corrected_sentence": "この考えは多層に積み重なって、今の制度になった。", "error_description": "「積み重なる」は結果を表す「に」を取る。「多層で」は誤りで、正しくは「多層に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36097, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この取り決めは多層になったで、分かりにくい。", "corrected_sentence": "この取り決めは多層になっていて、分かりにくい。", "error_description": "「多層になる」は「なっていて」の形で続ける。「なったで」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36102, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「テンポを（ゆっくりにする）」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「ゆっくりにして」の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「テンポに」と続けても、「ゆっくりにして」の対象として文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、「テンポで」を「ゆっくりにする」の対象にはできない。"}], "correct_answer": "を", "explanations": {"を": "「テンポを（ゆっくりにする）」の目的語を示す「を」。", "が": "主語を示す助詞で、「ゆっくりにして」の目的語にはならない。", "に": "「テンポに」と続けても、「ゆっくりにして」の対象として文が成り立たない。", "で": "手段や場所を示す助詞で、「テンポで」を「ゆっくりにする」の対象にはできない。"}, "error_tags": {"が": "主語", "に": "結果・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36102, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「テンポに合わせて」の相手を示す「に」。「合わせる」の基本の助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「合わせる」の相手には使わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「テンポから合わせて」とは言わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞で、「テンポより合わせて」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「テンポに合わせて」の相手を示す「に」。「合わせる」の基本の助詞。", "へ": "方向を示す助詞で、「合わせる」の相手には使わない。", "から": "起点を示す助詞で、「テンポから合わせて」とは言わない。", "より": "比較を示す助詞で、「テンポより合わせて」は文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36102, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音楽の速さのことです。", "primary_collocate": null, "pronunciation": "てんぽ", "ipa": "tempo", "syllable_count": 3, "sentences": [{"text": "この曲はテンポが速くて、歌うのが大変です。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "この曲[きょく]はテンポが速[はや]くて、歌[うた]うのが大変[たいへん]です。", "sentence_source": "generated"}, {"text": "先生は、テンポをゆっくりにして、ピアノを弾きました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、テンポをゆっくりにして、ピアノを弾[ひ]きました。", "sentence_source": "generated"}, {"text": "テンポが遅い曲は、聞くと心が落ち着きます。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "テンポが遅[おそ]い曲[きょく]は、聞[き]くと心[こころ]が落[お]ち着[つ]きます。", "sentence_source": "generated"}, {"text": "ダンスの前に、曲のテンポを確かめました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "ダンスの前[まえ]に、曲[きょく]のテンポを確[たし]かめました。", "sentence_source": "generated"}, {"text": "ドラムの人がテンポを間違えて、演奏が止まりました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "ドラムの人[ひと]がテンポを間違[まちが]えて、演奏[えんそう]が止[と]まりました。", "sentence_source": "generated"}, {"text": "この曲は途中でテンポが変わるので、おもしろいです。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "この曲[きょく]は途中[とちゅう]でテンポが変[か]わるので、おもしろいです。", "sentence_source": "generated"}, {"text": "練習では、まずゆっくりしたテンポで弾きます。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "練習[れんしゅう]では、まずゆっくりしたテンポで弾[ひ]きます。", "sentence_source": "generated"}, {"text": "テンポに合わせて、みんなで手をたたきました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "テンポに合[あ]わせて、みんなで手[て]をたたきました。", "sentence_source": "generated"}, {"text": "メトロノームでテンポを決めてから、ギターを弾きました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "メトロノームでテンポを決[き]めてから、ギターを弾[ひ]きました。", "sentence_source": "generated"}, {"text": "テンポの速い曲に合わせて、子どもたちが踊りました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "テンポの速[はや]い曲[きょく]に合[あ]わせて、子[こ]どもたちが踊[おど]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テンポ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "音楽の速さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36102, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テンポ", "is_correct": true, "explanation": "「この曲は___が速くて」には、音楽の速さを表す「テンポ」だけが入る。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを表す語なので、「速い」とは組み合わない。"}, {"text": "音程", "is_correct": false, "explanation": "音の高さの間隔を表す語で、「速い」とは言わない。"}, {"text": "楽譜", "is_correct": false, "explanation": "書かれた譜面を指す語で、速さを表す形容詞とは組み合わない。"}], "explanations": {"テンポ": "「この曲は___が速くて」には、音楽の速さを表す「テンポ」だけが入る。", "音量": "音の大きさを表す語なので、「速い」とは組み合わない。", "音程": "音の高さの間隔を表す語で、「速い」とは言わない。", "楽譜": "書かれた譜面を指す語で、速さを表す形容詞とは組み合わない。"}, "sentence_index": 0, "correct_answer": "テンポ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この車はテンポが時速百キロまで出せます。", "explanation": "ここは〈速度〉の意味。テンポは音楽の速さを指し、車の速さには使わない。"}, {"text": "ラジオの音が小さいので、テンポを大きくしました。", "explanation": "ここは〈音量〉の意味。テンポは速さを表すので、音の大きさの調節には使わない。"}, {"text": "この曲はテンポが高いので、歌いにくいです。", "explanation": "ここは〈音程〉の意味。テンポは速さなので、音の高さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36102, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テンポ", "is_correct": true, "explanation": "「まずゆっくりしたテンポで弾きます」の空欄には、速さを表す「テンポ」が入る。"}, {"text": "音域", "is_correct": false, "explanation": "音の範囲を表す語で、「ゆっくりした音域で弾く」とは言わない。"}, {"text": "強弱", "is_correct": false, "explanation": "音の強さの度合いを表す語で、「ゆっくりした強弱」とは組み合わない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌う言葉を指す語で、弾き方を表す「ゆっくりした」とは合わない。"}], "explanations": {"テンポ": "「まずゆっくりしたテンポで弾きます」の空欄には、速さを表す「テンポ」が入る。", "音域": "音の範囲を表す語で、「ゆっくりした音域で弾く」とは言わない。", "強弱": "音の強さの度合いを表す語で、「ゆっくりした強弱」とは組み合わない。", "歌詞": "歌う言葉を指す語で、弾き方を表す「ゆっくりした」とは合わない。"}, "sentence_index": 6, "correct_answer": "テンポ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドレミのテンポを順番に弾きました。", "explanation": "ここは〈音階〉の意味。テンポは速さなので、音を並べた順番を指すのには合わない。"}, {"text": "この歌はテンポが広くて、高い声まで出ます。", "explanation": "ここは〈音域〉の意味。テンポは速さなので、声の届く範囲には使わない。"}, {"text": "この曲はテンポが重なって、厚みがあります。", "explanation": "ここは〈和音〉の意味。テンポは速さなので、音が同時に重なることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36102, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この曲はテンポを速くて、踊るのが大変です。", "corrected_sentence": "この曲はテンポが速くて、踊るのが大変です。", "error_description": "「テンポ」に続く助詞は「が」。形容詞「速い」の主語を示す助詞で、「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36102, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演奏は、速いテンポを始まりました。", "corrected_sentence": "演奏は、速いテンポで始まりました。", "error_description": "「始まる」は自動詞なので目的語の「を」は使えない。「速いテンポで始まる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
