INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36103, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の進行の速さ。", "primary_collocate": null, "pronunciation": "てんぽ", "ipa": "tempo", "syllable_count": 3, "sentences": [{"text": "この映画は、話のテンポが速くて飽きません。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "この映画[えいが]は、話[はなし]のテンポが速[はや]くて飽[あ]きません。", "sentence_source": "generated"}, {"text": "彼女は仕事のテンポが速いので、すぐに終わります。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は仕事[しごと]のテンポが速[はや]いので、すぐに終[お]わります。", "sentence_source": "generated"}, {"text": "会議のテンポが遅く、予定の時間を過ぎました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "会議[かいぎ]のテンポが遅[おそ]く、予定[よてい]の時間[じかん]を過[す]ぎました。", "sentence_source": "generated"}, {"text": "テンポのいい会話が続いて、みんな笑っていました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "テンポのいい会話[かいわ]が続[つづ]いて、みんな笑[わら]っていました。", "sentence_source": "generated"}, {"text": "この小説はテンポが悪く、読むのに時間がかかりました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]はテンポが悪[わる]く、読[よ]むのに時間[じかん]がかかりました。", "sentence_source": "generated"}, {"text": "新人は、先輩の仕事のテンポに慣れるのが大変です。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "新人[しんじん]は、先輩[せんぱい]の仕事[しごと]のテンポに慣[な]れるのが大変[たいへん]です。", "sentence_source": "generated"}, {"text": "テンポよく話を進めて、授業は時間どおりに終わりました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "テンポよく話[はなし]を進[すす]めて、授業[じゅぎょう]は時間[じかん]どおりに終[お]わりました。", "sentence_source": "generated"}, {"text": "工事のテンポが上がり、予定より早く終わりそうです。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "工事[こうじ]のテンポが上[あ]がり、予定[よてい]より早[はや]く終[お]わりそうです。", "sentence_source": "generated"}, {"text": "新しい手順にしたら、仕事のテンポがよくなりました。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "新[あたら]しい手順[てじゅん]にしたら、仕事[しごと]のテンポがよくなりました。", "sentence_source": "generated"}, {"text": "同じテンポで走ったので、最後まで疲れませんでした。", "target_word": "テンポ", "complexity_tier": "T3", "furigana": "同[おな]じテンポで走[はし]ったので、最後[さいご]まで疲[つか]れませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テンポ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事の進む速さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36103, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テンポ", "is_correct": true, "explanation": "「話の___が速くて飽きません」には、話の進む速さを表す「テンポ」が入る。"}, {"text": "声量", "is_correct": false, "explanation": "声の大きさを表す語で、話の速さとは組み合わない。"}, {"text": "字数", "is_correct": false, "explanation": "文字の数を表す語で、「速い」とは言わない。"}, {"text": "語彙", "is_correct": false, "explanation": "使う言葉の範囲を表す語で、話の進み方の速さとは組み合わない。"}], "explanations": {"テンポ": "「話の___が速くて飽きません」には、話の進む速さを表す「テンポ」が入る。", "声量": "声の大きさを表す語で、話の速さとは組み合わない。", "字数": "文字の数を表す語で、「速い」とは言わない。", "語彙": "使う言葉の範囲を表す語で、話の進み方の速さとは組み合わない。"}, "sentence_index": 0, "correct_answer": "テンポ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この記事はテンポが多すぎて、書き直しました。", "explanation": "ここは〈字数〉の意味。テンポは進む速さなので、文章の長さには使わない。"}, {"text": "この店はテンポが安くて、学生に人気です。", "explanation": "ここは〈値段〉の意味。テンポは進む速さなので、料金の高さには使わない。"}, {"text": "この箱はテンポが軽くて、運びやすいです。", "explanation": "ここは〈重さ〉の意味。テンポは進む速さなので、物の重さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36103, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テンポ", "is_correct": true, "explanation": "「___よく話を進めて」には、進む速さを表す「テンポ」が入る。"}, {"text": "色彩", "is_correct": false, "explanation": "色の組み合わせを表す語で、「よく話を進める」とは組み合わない。"}, {"text": "照明", "is_correct": false, "explanation": "明かりを指す語で、話の進め方とは結びつかない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、話を進める様子には合わない。"}], "explanations": {"テンポ": "「___よく話を進めて」には、進む速さを表す「テンポ」が入る。", "色彩": "色の組み合わせを表す語で、「よく話を進める」とは組み合わない。", "照明": "明かりを指す語で、話の進め方とは結びつかない。", "体温": "体の温度を表す語で、話を進める様子には合わない。"}, "sentence_index": 6, "correct_answer": "テンポ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このお湯はテンポが熱くて、手を入れられません。", "explanation": "ここは〈温度〉の意味。テンポは進む速さなので、お湯の熱さを表すのには合わない。"}, {"text": "この絵はテンポが明るくて、見ていて楽しいです。", "explanation": "ここは〈色〉の意味。テンポは進む速さなので、絵の色の明るさには使わない。"}, {"text": "彼はテンポが若くて、みんなに慕われています。", "explanation": "ここは〈年齢〉の意味。テンポは進む速さなので、人の若さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
