INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36105, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「指示に従う」で、従う対象を表す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「指示を従う」は目的語として不自然で、「従う」の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「指示が従う」では指示が主体になり、意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「指示と従う」は並列の形になり、従う先の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「指示に従う」で、従う対象を表す正しい助詞。", "を": "「指示を従う」は目的語として不自然で、「従う」の対象を示せない。", "が": "「指示が従う」では指示が主体になり、意味が合わない。", "と": "「指示と従う」は並列の形になり、従う先の意味にならない。"}, "error_tags": {"に": "従う対象", "を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
