INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36105, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある事柄について、人に知らせたり、命令や注意を与えたりすること。また、その内容。", "primary_collocate": null, "pronunciation": "しじ", "ipa": "ɕidʑi", "syllable_count": 2, "sentences": [{"text": "教師の指示のもと、静寂を保ちつつも頭脳をフル回転させる学習の時間。", "target_word": "指示", "complexity_tier": "T4", "furigana": "教師[きょうし]の指示[しじ]のもと、静寂[せいじゃく]を保[たも]ちつつも頭脳[ずのう]をフル回転[かいてん]させる学習[がくしゅう]の時間[じかん]。", "sentence_source": "mined"}, {"text": "先生の指示に従って、みんなが静かに並んだ。", "target_word": "指示", "complexity_tier": "T3", "furigana": "先生[せんせい]の指示[しじ]に従[したが]って、みんなが静[しず]かに並[なら]んだ。", "sentence_source": "generated"}, {"text": "上司から細かい指示があり、急いで資料を直した。", "target_word": "指示", "complexity_tier": "T3", "furigana": "上司[じょうし]から細[こま]かい指示[しじ]があり、急[いそ]いで資料[しりょう]を直[なお]した。", "sentence_source": "generated"}, {"text": "地震のとき、係の人の指示を聞いて外へ出た。", "target_word": "指示", "complexity_tier": "T3", "furigana": "地震[じしん]のとき、係[かかり]の人[ひと]の指示[しじ]を聞[き]いて外[そと]へ出[で]た。", "sentence_source": "generated"}, {"text": "彼は部下に的確な指示を出すのが上手だ。", "target_word": "指示", "complexity_tier": "T3", "furigana": "彼[かれ]は部下[ぶか]に的確[てきかく]な指示[しじ]を出[だ]すのが上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "指示があるまで、ここで待っていてください。", "target_word": "指示", "complexity_tier": "T2", "furigana": "指示[しじ]があるまで、ここで待[ま]っていてください。", "sentence_source": "generated"}, {"text": "説明書の指示どおりに組み立てたが、うまくできなかった。", "target_word": "指示", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]の指示[しじ]どおりに組[く]み立[た]てたが、うまくできなかった。", "sentence_source": "generated"}, {"text": "監督は選手たちに、試合の前に短く指示した。", "target_word": "指示", "complexity_tier": "T3", "furigana": "監督[かんとく]は選手[せんしゅ]たちに、試合[しあい]の前[まえ]に短[みじか]く指示[しじ]した。", "sentence_source": "generated"}, {"text": "店長の指示で、新しい商品を入り口に並べた。", "target_word": "指示", "complexity_tier": "T3", "furigana": "店長[てんちょう]の指示[しじ]で、新[あたら]しい商品[しょうひん]を入[い]り口[ぐち]に並[なら]べた。", "sentence_source": "generated"}, {"text": "彼女は誰の指示も受けず、自分で考えて動いた。", "target_word": "指示", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は誰[だれ]の指示[しじ]も受[う]けず、自分[じぶん]で考[かんが]えて動[うご]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "指示", "label": "基本形"}, {"form": "指示する", "label": "サ変動詞"}, {"form": "指示した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "人に命令や注意を与えること、またその内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36105, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指示", "is_correct": true, "explanation": "「教師の指示のもと」と続き、教える側からの命令や注意を表す正しい語。"}, {"text": "窓", "is_correct": false, "explanation": "窓は物の名前で、「教師の窓のもと」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は状態で、「教師の天気のもと」は意味をなさない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は道具で、「教師の電話のもと」は文が成立しない。"}], "explanations": {"指示": "「教師の指示のもと」と続き、教える側からの命令や注意を表す正しい語。", "窓": "窓は物の名前で、「教師の窓のもと」は成り立たない。", "天気": "天気は状態で、「教師の天気のもと」は意味をなさない。", "電話": "電話は道具で、「教師の電話のもと」は文が成立しない。"}, "sentence_index": 0, "correct_answer": "指示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店に入って、友達と料理を指示した。", "explanation": "ここは注文の意味。店で料理を頼むことには指示ではなく注文を使う。"}, {"text": "悩んだ末、先輩に指示して結論を出した。", "explanation": "ここは相談の意味。指示は上の立場から命じる行為なので、相談の代わりにはならない。"}, {"text": "朝、玄関で先生に明るく指示した。", "explanation": "ここは挨拶（相手に声をかけること）の意味。指示は命じたり知らせたりする行為で、朝の挨拶には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36105, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指示", "is_correct": true, "explanation": "「説明書の指示どおりに組み立てた」と続き、具体的な指示内容を表す正しい語。"}, {"text": "数学", "is_correct": false, "explanation": "教科の名前で、「説明書の数学どおり」は意味をなさない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は自然の現象で、「説明書の雲どおり」は成り立たない。"}, {"text": "指輪", "is_correct": false, "explanation": "指輪は装飾品で、「説明書の指輪どおり」は文が成立しない。"}], "explanations": {"指示": "「説明書の指示どおりに組み立てた」と続き、具体的な指示内容を表す正しい語。", "数学": "教科の名前で、「説明書の数学どおり」は意味をなさない。", "雲": "雲は自然の現象で、「説明書の雲どおり」は成り立たない。", "指輪": "指輪は装飾品で、「説明書の指輪どおり」は文が成立しない。"}, "sentence_index": 6, "correct_answer": "指示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "帰宅後、今日の出来事を母に指示した。", "explanation": "ここは報告の意味。出来事を知らせるのは報告で、指示は相手に行動を求める行為。"}, {"text": "試験の前に、先生に教室へ入る許可を指示した。", "explanation": "ここは許可の意味。許可を求めたり出したりするのは許可で、指示とは別の行為。"}, {"text": "映画を見たあと、友達に感想を指示した。", "explanation": "ここは感想（見た後の気持ちを述べること）の意味。指示は行動を命じる行為で、感想を伝えるときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36105, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩の指示を従わず、彼は勝手な行動をとった。", "corrected_sentence": "先輩の指示に従わず、彼は勝手な行動をとった。", "error_description": "「従う」は対象を「に」で示す。「を」は目的語になり、「従う」とは結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36105, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員の指示に待たずに、客は勝手に商品を持っていった。", "corrected_sentence": "店員の指示を待たずに、客は勝手に商品を持っていった。", "error_description": "「待つ」は対象を「を」で示す。「に」は「待つ」とは結びつかず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36108, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ロマンを求めています」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「求めている」の目的語にはならず、「ロマンが求めている」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、「ロマンで求める」とは言わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「ロマンへ求める」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ロマンを求めています」の目的語を示す「を」。", "が": "主語を示す助詞で、「求めている」の目的語にはならず、「ロマンが求めている」は意味が通らない。", "で": "手段や場所を示す助詞で、「ロマンで求める」とは言わない。", "へ": "方向を示す助詞で、「ロマンへ求める」は文が成り立たない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36108, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ロマンを追いかける」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "到達点や相手を示す助詞で、「ロマンに追いかける」とは言わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示す助詞で、「ロマンと追いかける」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す助詞で、「ロマンの追いかける」は動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「ロマンを追いかける」の目的語を示す「を」。", "に": "到達点や相手を示す助詞で、「ロマンに追いかける」とは言わない。", "と": "並列や共同を示す助詞で、「ロマンと追いかける」は文が成り立たない。", "の": "所属や修飾を示す助詞で、「ロマンの追いかける」は動詞の目的語にならない。"}, "error_tags": {"に": "到達点・相手", "と": "並列・共同", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36108, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が感じる、美しい夢のような気持ちのこと。", "primary_collocate": null, "pronunciation": "ろまん", "ipa": "ɾoman", "syllable_count": 3, "sentences": [{"text": "宇宙の話を聞くと、ロマンを感じます。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]の話[はなし]を聞[き]くと、ロマンを感[かん]じます。", "sentence_source": "generated"}, {"text": "彼は、古い船の旅にロマンを求めています。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "彼[かれ]は、古[ふる]い船[ふね]の旅[たび]にロマンを求[もと]めています。", "sentence_source": "generated"}, {"text": "星空の下で、ロマンのある夜を過ごしました。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "星空[ほしぞら]の下[した]で、ロマンのある夜[よる]を過[す]ごしました。", "sentence_source": "generated"}, {"text": "ロマンがあるから、宝探しの話は人気です。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "ロマンがあるから、宝探[たからさが]しの話[はなし]は人気[にんき]です。", "sentence_source": "generated"}, {"text": "男の子たちは、大きな恐竜にロマンを感じるようです。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "男[おとこ]の子[こ]たちは、大[おお]きな恐竜[きょうりゅう]にロマンを感[かん]じるようです。", "sentence_source": "generated"}, {"text": "祖父はロマンを大切にして、夢の話をよくします。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "祖父[そふ]はロマンを大切[たいせつ]にして、夢[ゆめ]の話[はなし]をよくします。", "sentence_source": "generated"}, {"text": "この町には、昔の物語のようなロマンがあります。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "この町[まち]には、昔[むかし]の物語[ものがたり]のようなロマンがあります。", "sentence_source": "generated"}, {"text": "現実的な兄と違って、姉はロマンを追いかける人です。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "現実的[げんじつてき]な兄[あに]と違[ちが]って、姉[あね]はロマンを追[お]いかける人[ひと]です。", "sentence_source": "generated"}, {"text": "海の向こうの国へ行くことは、私のロマンです。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "海[うみ]の向[む]こうの国[くに]へ行[い]くことは、私[わたし]のロマンです。", "sentence_source": "generated"}, {"text": "ロマンのない仕事だと言われても、私は誇りを持っています。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "ロマンのない仕事[しごと]だと言[い]われても、私[わたし]は誇[ほこ]りを持[も]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ロマン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "夢や冒険にひかれる美しい気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36108, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ロマン", "is_correct": true, "explanation": "「宇宙の話を聞くと、___を感じます」には、夢にひかれる気持ちを表す「ロマン」が入る。"}, {"text": "規則", "is_correct": false, "explanation": "決まりを表す語で、「規則を感じる」とは言わない。"}, {"text": "期限", "is_correct": false, "explanation": "締め切りを表す語で、「期限を感じる」は文の意味が通らない。"}, {"text": "評価", "is_correct": false, "explanation": "価値を判断する結果を表す語で、「評価を感じる」とは言わない。"}], "explanations": {"ロマン": "「宇宙の話を聞くと、___を感じます」には、夢にひかれる気持ちを表す「ロマン」が入る。", "規則": "決まりを表す語で、「規則を感じる」とは言わない。", "期限": "締め切りを表す語で、「期限を感じる」は文の意味が通らない。", "評価": "価値を判断する結果を表す語で、「評価を感じる」とは言わない。"}, "sentence_index": 0, "correct_answer": "ロマン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はロマンが悪くて、今日は休みました。", "explanation": "ここは〈体調〉の意味。ロマンは夢のような気持ちなので、体の具合には使わない。"}, {"text": "彼はロマンが増えて、服が入らなくなりました。", "explanation": "ここは〈体重〉の意味。ロマンは気持ちを表すので、体の重さには使わない。"}, {"text": "今日はロマンが良くて、散歩に行きました。", "explanation": "ここは〈天気〉の意味。ロマンは気持ちを表すので、空模様の良し悪しには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36108, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ロマン", "is_correct": true, "explanation": "「昔の物語のような___があります」には、夢のような美しい気持ちを表す「ロマン」が入る。"}, {"text": "締め切り", "is_correct": false, "explanation": "期限を表す語で、「物語のような締め切り」は意味が通らない。"}, {"text": "年齢", "is_correct": false, "explanation": "人や物の経過年数を表す語で、「物語のような年齢」とは言わない。"}, {"text": "税金", "is_correct": false, "explanation": "国や自治体に納める金銭を表す語で、物語の雰囲気とは組み合わない。"}], "explanations": {"ロマン": "「昔の物語のような___があります」には、夢のような美しい気持ちを表す「ロマン」が入る。", "締め切り": "期限を表す語で、「物語のような締め切り」は意味が通らない。", "年齢": "人や物の経過年数を表す語で、「物語のような年齢」とは言わない。", "税金": "国や自治体に納める金銭を表す語で、物語の雰囲気とは組み合わない。"}, "sentence_index": 6, "correct_answer": "ロマン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この電池はロマンが長くて、何年も使えます。", "explanation": "ここは〈寿命〉の意味。ロマンは気持ちを表すので、電池の持ちには使わない。"}, {"text": "この機械はロマンが省けて、とても便利です。", "explanation": "ここは〈手間〉の意味。ロマンは気持ちを表すので、手間の少なさには使わない。"}, {"text": "この通販はロマンが無料で、助かりました。", "explanation": "ここは〈送料〉の意味。ロマンは気持ちを表すので、配送料の有無には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36108, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "星空を見上げると、ロマンに感じます。", "corrected_sentence": "星空を見上げると、ロマンを感じます。", "error_description": "「感じる」の目的語は「を」。「ロマンに感じる」は助詞が合わないので、「ロマンを感じる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36108, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は若いころ、大きなロマンに抱いて海を渡りました。", "corrected_sentence": "彼は若いころ、大きなロマンを抱いて海を渡りました。", "error_description": "「抱く」の目的語は「を」。「ロマンに抱く」は助詞が合わないので、「ロマンを抱く」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36109, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「強い感情とロマンにあふれています」の「にあふれる」の「に」。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「ロマンをあふれています」とは言わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、「ロマンであふれています」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「ロマンへあふれています」とは言わない。"}], "correct_answer": "に", "explanations": {"に": "「強い感情とロマンにあふれています」の「にあふれる」の「に」。", "を": "目的語を示す助詞で、「ロマンをあふれています」とは言わない。", "で": "手段や場所を示す助詞で、「ロマンであふれています」は文が成り立たない。", "へ": "方向を示す助詞で、「ロマンへあふれています」とは言わない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
