INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36109, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音楽や芸術で、強い感情や想像力を大切にする、19世紀ごろのヨーロッパの芸術の流れや、そのような雰囲気のこと。", "primary_collocate": null, "pronunciation": "ろまん", "ipa": "ɾoman", "syllable_count": 3, "sentences": [{"text": "この曲には、十九世紀のヨーロッパのロマンが感じられます。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "この曲[きょく]には、十九世紀[じゅうきゅうせいき]のヨーロッパのロマンが感[かん]じられます。", "sentence_source": "generated"}, {"text": "ショパンの音楽は、強い感情とロマンにあふれています。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "ショパンの音楽[おんがく]は、強[つよ]い感情[かんじょう]とロマンにあふれています。", "sentence_source": "generated"}, {"text": "美術館で、ロマンを大切にした絵の展示を見ました。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で、ロマンを大切[たいせつ]にした絵[え]の展示[てんじ]を見[み]ました。", "sentence_source": "generated"}, {"text": "ロマンを重んじた作曲家は、自分の気持ちを音楽で強く表しました。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "ロマンを重[おも]んじた作曲家[さっきょくか]は、自分[じぶん]の気持[きも]ちを音楽[おんがく]で強[つよ]く表[あらわ]しました。", "sentence_source": "generated"}, {"text": "古い城の写真には、物語のようなロマンの雰囲気があります。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "古[ふる]い城[しろ]の写真[しゃしん]には、物語[ものがたり]のようなロマンの雰囲気[ふんいき]があります。", "sentence_source": "generated"}, {"text": "この詩は、ロマンの流れをくむ強い言葉で書かれています。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "この詩[し]は、ロマンの流[なが]れをくむ強[つよ]い言葉[ことば]で書[か]かれています。", "sentence_source": "generated"}, {"text": "先生は、ロマンを大切にした画家たちについて短い話をしました。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ロマンを大切[たいせつ]にした画家[がか]たちについて短[みじか]い話[はなし]をしました。", "sentence_source": "generated"}, {"text": "彼のピアノは、技術よりもロマンの香りが魅力です。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "彼[かれ]のピアノは、技術[ぎじゅつ]よりもロマンの香[かお]りが魅力[みりょく]です。", "sentence_source": "generated"}, {"text": "ロマンを好む画家は、嵐の海や暗い森をよく描きました。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "ロマンを好[この]む画家[がか]は、嵐[あらし]の海[うみ]や暗[くら]い森[もり]をよく描[えが]きました。", "sentence_source": "generated"}, {"text": "そのコンサートは、ロマンあふれる曲ばかりでした。", "target_word": "ロマン", "complexity_tier": "T3", "furigana": "そのコンサートは、ロマンあふれる曲[きょく]ばかりでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ロマン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "感情と想像力を重んじる十九世紀ヨーロッパの芸術の流れ、またその雰囲気", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36109, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ロマン", "is_correct": true, "explanation": "「ヨーロッパの___が感じられます」には、十九世紀の芸術の流れを指す「ロマン」が入る。"}, {"text": "価格", "is_correct": false, "explanation": "値段を表す語で、芸術の雰囲気を表す「が感じられる」とは合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "経過年数を表す語で、芸術の流れとは関係がなく「感じられる」とも合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "物の使える期間を表す語で、「が感じられる」とは言わない。"}], "explanations": {"ロマン": "「ヨーロッパの___が感じられます」には、十九世紀の芸術の流れを指す「ロマン」が入る。", "価格": "値段を表す語で、芸術の雰囲気を表す「が感じられる」とは合わない。", "年齢": "経過年数を表す語で、芸術の流れとは関係がなく「感じられる」とも合わない。", "寿命": "物の使える期間を表す語で、「が感じられる」とは言わない。"}, "sentence_index": 0, "correct_answer": "ロマン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家は強いロマンで建てられています。", "explanation": "ここは〈建材〉の意味。ロマンは芸術の流れを指すので、家の材料を表すのには使わない。"}, {"text": "彼はロマンという楽器を習いました。", "explanation": "ここは〈楽器〉の意味。ロマンは芸術の流れを指す語で、楽器の名前には使わない。"}, {"text": "彼はロマンが高く、難しい曲も完璧に弾けます。", "explanation": "ここは〈技術〉の意味。ロマンは芸術の流れを指すので、弾く腕前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36109, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ロマン", "is_correct": true, "explanation": "「先生は、___を大切にした画家たち」には、芸術の流れを指す「ロマン」が入る。"}, {"text": "手数料", "is_correct": false, "explanation": "取引に払う費用を表す語で、「大切にした画家」とは組み合わない。"}, {"text": "残高", "is_correct": false, "explanation": "口座などに残っているお金を表す語で、「大切にする」の目的語にはならない。"}, {"text": "在庫", "is_correct": false, "explanation": "店にある商品を表す語で、「在庫を大切にした画家」は意味が通らない。"}], "explanations": {"ロマン": "「先生は、___を大切にした画家たち」には、芸術の流れを指す「ロマン」が入る。", "手数料": "取引に払う費用を表す語で、「大切にした画家」とは組み合わない。", "残高": "口座などに残っているお金を表す語で、「大切にする」の目的語にはならない。", "在庫": "店にある商品を表す語で、「在庫を大切にした画家」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "ロマン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この曲はロマンが整っていて、ソナタの決まりに従っています。", "explanation": "ここは〈形式〉の意味。ロマンは芸術の流れや雰囲気を指すので、曲の形の整い方には使わない。"}, {"text": "この店はロマンが広くて、車で行きやすいです。", "explanation": "ここは〈駐車場〉の意味。ロマンは芸術の流れを指すので、場所の広さには使わない。"}, {"text": "この通販はロマンが早くて、助かりました。", "explanation": "ここは〈配送〉の意味。ロマンは芸術の流れを指すので、届く速さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
