INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36114, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "感じや気持ちの細かい違いのこと。", "primary_collocate": null, "pronunciation": "にゅあんす", "ipa": "ɲɯaɴsɯ", "syllable_count": 4, "sentences": [{"text": "ニュアンスが分かりません。", "target_word": "ニュアンス", "complexity_tier": "T2", "furigana": "ニュアンスが分[わ]かりません。", "sentence_source": "generated"}, {"text": "「好き」と「大好き」はニュアンスが違う。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "「好[す]き」と「大好[だいす]き」はニュアンスが違[ちが]う。", "sentence_source": "generated"}, {"text": "手紙の言葉は、やさしいニュアンスにしたい。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "手紙[てがみ]の言葉[ことば]は、やさしいニュアンスにしたい。", "sentence_source": "generated"}, {"text": "先生は、ニュアンスの違いを教えてくれた。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ニュアンスの違[ちが]いを教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "その返事は、断るニュアンスだった。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "その返事[へんじ]は、断[ことわ]るニュアンスだった。", "sentence_source": "generated"}, {"text": "声の高さによって、ニュアンスも変わります。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "声[こえ]の高[たか]さによって、ニュアンスも変[か]わります。", "sentence_source": "generated"}, {"text": "ニュアンスを知りたければ、例文を読むといい。", "target_word": "ニュアンス", "complexity_tier": "T4", "furigana": "ニュアンスを知[し]りたければ、例文[れいぶん]を読[よ]むといい。", "sentence_source": "generated"}, {"text": "友だちの言葉に、少し怒ったニュアンスを感じた。", "target_word": "ニュアンス", "complexity_tier": "T4", "furigana": "友[とも]だちの言葉[ことば]に、少[すこ]し怒[おこ]ったニュアンスを感[かん]じた。", "sentence_source": "generated"}, {"text": "翻訳では、原文のニュアンスが失われやすい。", "target_word": "ニュアンス", "complexity_tier": "T4", "furigana": "翻訳[ほんやく]では、原文[げんぶん]のニュアンスが失[うしな]われやすい。", "sentence_source": "generated"}, {"text": "私は、ニュアンスの似た言葉を並べて覚えています。", "target_word": "ニュアンス", "complexity_tier": "T4", "furigana": "私[わたし]は、ニュアンスの似[に]た言葉[ことば]を並[なら]べて覚[おぼ]えています。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 感じや気持ちの細かい違い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36114, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ニュアンス", "is_correct": true, "explanation": "「にゅあんす」は聞いた音と同じ見出し語です。"}, {"text": "フランス", "is_correct": false, "explanation": "「ふらんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, {"text": "ロマンス", "is_correct": false, "explanation": "「ろまんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, {"text": "バランス", "is_correct": false, "explanation": "「ばらんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}], "explanations": {"ニュアンス": "「にゅあんす」は聞いた音と同じ見出し語です。", "フランス": "「ふらんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。", "ロマンス": "「ろまんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。", "バランス": "「ばらんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, "sentence_index": null, "correct_answer": "ニュアンス"}, "level_3": {"options": [{"text": "ニュアンス", "is_correct": true, "explanation": "言葉の感じの違いが分からないという意味で、文に合います。"}, {"text": "靴下", "is_correct": false, "explanation": "形は合うが、「靴下が分かりません」は文脈に合わず意味が合わない。"}, {"text": "階段", "is_correct": false, "explanation": "形は合うが、「階段が分かりません」は文脈に合わず意味が合わない。"}, {"text": "切手", "is_correct": false, "explanation": "形は合うが、「切手が分かりません」は文脈に合わず意味が合わない。"}], "explanations": {"ニュアンス": "言葉の感じの違いが分からないという意味で、文に合います。", "靴下": "形は合うが、「靴下が分かりません」は文脈に合わず意味が合わない。", "階段": "形は合うが、「階段が分かりません」は文脈に合わず意味が合わない。", "切手": "形は合うが、「切手が分かりません」は文脈に合わず意味が合わない。"}, "sentence_index": 0, "correct_answer": "ニュアンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は、ニュアンスの数を足してくれた。", "explanation": "「ニュアンス」は数えて足せるものではなく、感じの違いです。"}, {"text": "先生は、ニュアンスの駅を教えてくれた。", "explanation": "「ニュアンス」に駅という場所の意味はありません。"}, {"text": "先生は、ニュアンスの重さを量ってくれた。", "explanation": "「ニュアンス」は重さを量れる物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
