INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36115, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の微妙な違いや、言葉や音などが持つ細かな感じの違い。", "primary_collocate": null, "pronunciation": "にゅあんす", "ipa": "ɲɯaɴsɯ", "syllable_count": 4, "sentences": [{"text": "あえて色数を抑えたプリント技法を採用したのは、褪せた記憶のニュアンスを表現するためです。", "target_word": "ニュアンス", "complexity_tier": "T6", "furigana": "あえて色数[いろすう]を抑[おさ]えたプリント技法[ぎほう]を採用[さいよう]したのは、褪[あ]せた記憶[きおく]のニュアンスを表現[ひょうげん]するためです。", "sentence_source": "mined"}, {"text": "この二つの言葉は、ニュアンスが少し違います。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "この二[ふた]つの言葉[ことば]は、ニュアンスが少[すこ]し違[ちが]います。", "sentence_source": "generated"}, {"text": "日本語のニュアンスは、むずかしい。", "target_word": "ニュアンス", "complexity_tier": "T2", "furigana": "日本語[にほんご]のニュアンスは、むずかしい。", "sentence_source": "generated"}, {"text": "ニュアンスを伝えるのは簡単ではありません。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "ニュアンスを伝[つた]えるのは簡単[かんたん]ではありません。", "sentence_source": "generated"}, {"text": "その言い方には、冷たいニュアンスがある。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "その言[い]い方[かた]には、冷[つめ]たいニュアンスがある。", "sentence_source": "generated"}, {"text": "言葉のニュアンスの違いを辞書で調べた。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "言葉[ことば]のニュアンスの違[ちが]いを辞書[じしょ]で調[しら]べた。", "sentence_source": "generated"}, {"text": "彼女は、細かなニュアンスまで英語に訳してくれた。", "target_word": "ニュアンス", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は、細[こま]かなニュアンスまで英語[えいご]に訳[やく]してくれた。", "sentence_source": "generated"}, {"text": "ニュアンスが伝わらなくて、誤解されてしまった。", "target_word": "ニュアンス", "complexity_tier": "T4", "furigana": "ニュアンスが伝[つた]わらなくて、誤解[ごかい]されてしまった。", "sentence_source": "generated"}, {"text": "同じ意味でも、ニュアンスによって印象が変わる。", "target_word": "ニュアンス", "complexity_tier": "T3", "furigana": "同[おな]じ意味[いみ]でも、ニュアンスによって印象[いんしょう]が変[か]わる。", "sentence_source": "generated"}, {"text": "ニュアンスを間違えると、失礼に聞こえることもある。", "target_word": "ニュアンス", "complexity_tier": "T4", "furigana": "ニュアンスを間違[まちが]えると、失礼[しつれい]に聞[き]こえることもある。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 言葉や物事の微妙な違い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36115, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ニュアンス", "is_correct": true, "explanation": "「にゅあんす」は聞いた音と同じ見出し語です。"}, {"text": "フランス", "is_correct": false, "explanation": "「ふらんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, {"text": "ロマンス", "is_correct": false, "explanation": "「ろまんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, {"text": "バランス", "is_correct": false, "explanation": "「ばらんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}], "explanations": {"ニュアンス": "「にゅあんす」は聞いた音と同じ見出し語です。", "フランス": "「ふらんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。", "ロマンス": "「ろまんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。", "バランス": "「ばらんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, "sentence_index": null, "correct_answer": "ニュアンス"}, "level_3": {"options": [{"text": "ニュアンス", "is_correct": true, "explanation": "記憶の微妙な感じを表現するので、意味が合います。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、記憶の重さを表現するのは意味が合わない。"}, {"text": "速度", "is_correct": false, "explanation": "形は合うが、記憶の速度を表現するのは意味が合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、記憶の湿度を表現するのは意味が合わない。"}], "explanations": {"ニュアンス": "記憶の微妙な感じを表現するので、意味が合います。", "重さ": "形は合うが、記憶の重さを表現するのは意味が合わない。", "速度": "形は合うが、記憶の速度を表現するのは意味が合わない。", "湿度": "形は合うが、記憶の湿度を表現するのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "ニュアンス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ニュアンスを食べるのは簡単ではありません。", "explanation": "「ニュアンス」は食べ物ではないので、「食べる」は誤りです。"}, {"text": "ニュアンスを洗うのは簡単ではありません。", "explanation": "「ニュアンス」は洗える物ではなく、言葉の微妙な違いです。"}, {"text": "ニュアンスを買うのは、お店が遠くて簡単ではありません。", "explanation": "「ニュアンス」は店で売っている物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36115, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ニュアンス", "is_correct": true, "explanation": "「にゅあんす」は聞いた音と同じ見出し語です。"}, {"text": "ニュース", "is_correct": false, "explanation": "「にゅーす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, {"text": "チャンス", "is_correct": false, "explanation": "「ちゃんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, {"text": "ダンス", "is_correct": false, "explanation": "「だんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}], "explanations": {"ニュアンス": "「にゅあんす」は聞いた音と同じ見出し語です。", "ニュース": "「にゅーす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。", "チャンス": "「ちゃんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。", "ダンス": "「だんす」は別の語です。1音違いの実在語がほとんどなく、近い音の語で代用しています。"}, "sentence_index": null, "correct_answer": "ニュアンス"}, "level_3": {"options": [{"text": "ニュアンス", "is_correct": true, "explanation": "細かな言葉の違いまで訳したので、意味が合います。"}, {"text": "価格", "is_correct": false, "explanation": "形は合うが、細かな価格まで英語に訳すのは意味が合わない。"}, {"text": "体温", "is_correct": false, "explanation": "形は合うが、細かな体温まで英語に訳すのは意味が合わない。"}, {"text": "距離", "is_correct": false, "explanation": "形は合うが、細かな距離まで英語に訳すのは意味が合わない。"}], "explanations": {"ニュアンス": "細かな言葉の違いまで訳したので、意味が合います。", "価格": "形は合うが、細かな価格まで英語に訳すのは意味が合わない。", "体温": "形は合うが、細かな体温まで英語に訳すのは意味が合わない。", "距離": "形は合うが、細かな距離まで英語に訳すのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "ニュアンス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ニュアンスを間違えると、おなかが痛くなることもある。", "explanation": "「ニュアンス」を間違えても体調は悪くならず、結果が意味に合いません。"}, {"text": "ニュアンスを間違えると、電車が遅れることもある。", "explanation": "「ニュアンス」は言葉の感じのことで、電車の遅れとは関係ありません。"}, {"text": "ニュアンスを間違えると、雨が降ることもある。", "explanation": "「ニュアンス」は天気に影響するものではなく、言葉の微妙な違いです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_us