INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36117, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「表記を統一する」の形で、表記が目的語になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すので、統一の対象を示す文脈には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、統一の対象を表す文脈では不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、命令文で統一の対象を示す文脈には合わない。"}], "correct_answer": "を", "explanations": {"を": "「表記を統一する」の形で、表記が目的語になる。", "に": "「に」は方向や相手を示すので、統一の対象を示す文脈には合わない。", "で": "「で」は手段や場所を示すので、統一の対象を表す文脈では不自然。", "が": "「が」は主語を示すので、命令文で統一の対象を示す文脈には合わない。"}, "error_tags": {"に": "方向・相手", "で": "手段・場所", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36117, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「表記がある単語」の形で、表記が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「ある」の主語には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、存在を表す「ある」の文脈には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「表記がある」の形には合わない。"}], "correct_answer": "が", "explanations": {"が": "「表記がある単語」の形で、表記が主語になる。", "を": "「を」は目的語を示すので、「ある」の主語には合わない。", "へ": "「へ」は方向を示すので、存在を表す「ある」の文脈には合わない。", "から": "「から」は起点を示すので、「表記がある」の形には合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36117, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "言葉や音符などを、文字や記号を使って書き表す方法やその結果。", "primary_collocate": null, "pronunciation": "ひょうき", "ipa": "çʲoːki", "syllable_count": 3, "sentences": [{"text": "資料の中で、同じ言葉の表記が違っている。", "target_word": "表記", "complexity_tier": "T3", "furigana": "資料[しりょう]の中[なか]で、同[おな]じ言葉[ことば]の表記[ひょうき]が違[ちが]っている。", "sentence_source": "generated"}, {"text": "会社の名前の表記を、すべて統一してください。", "target_word": "表記", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の名前[なまえ]の表記[ひょうき]を、すべて統一[とういつ]してください。", "sentence_source": "generated"}, {"text": "「こんにちは」の表記は、昔は「こんにちわ」と書かれることもあった。", "target_word": "表記", "complexity_tier": "T3", "furigana": "「こんにちは」の表記[ひょうき]は、昔[むかし]は「こんにちわ」と書[か]かれることもあった。", "sentence_source": "generated"}, {"text": "外国の地名は、カタカナで表記する。", "target_word": "表記", "complexity_tier": "T3", "furigana": "外国[がいこく]の地名[ちめい]は、カタカナで表記[ひょうき]する。", "sentence_source": "generated"}, {"text": "この辞書では、単語の発音の表記が分かりやすい。", "target_word": "表記", "complexity_tier": "T3", "furigana": "この辞書[じしょ]では、単語[たんご]の発音[はつおん]の表記[ひょうき]が分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "楽譜の表記が読めなくて、先生に聞いた。", "target_word": "表記", "complexity_tier": "T3", "furigana": "楽譜[がくふ]の表記[ひょうき]が読[よ]めなくて、先生[せんせい]に聞[き]いた。", "sentence_source": "generated"}, {"text": "看板の表記が間違っていたので、店の人に伝えた。", "target_word": "表記", "complexity_tier": "T3", "furigana": "看板[かんばん]の表記[ひょうき]が間違[まちが]っていたので、店[みせ]の人[ひと]に伝[つた]えた。", "sentence_source": "generated"}, {"text": "日本語には、漢字とひらがなの二通りの表記がある単語が多い。", "target_word": "表記", "complexity_tier": "T3", "furigana": "日本語[にほんご]には、漢字[かんじ]とひらがなの二通[ふたとお]りの表記[ひょうき]がある単語[たんご]が多[おお]い。", "sentence_source": "generated"}, {"text": "正しい表記を知るために、国語辞典で調べた。", "target_word": "表記", "complexity_tier": "T3", "furigana": "正[ただ]しい表記[ひょうき]を知[し]るために、国語辞典[こくごじてん]で調[しら]べた。", "sentence_source": "generated"}, {"text": "値段の表記は、税込みで統一されている。", "target_word": "表記", "complexity_tier": "T3", "furigana": "値段[ねだん]の表記[ひょうき]は、税込[ぜいこ]みで統一[とういつ]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表記", "label": "基本形"}, {"form": "表記する", "label": "動詞形"}, {"form": "表記した", "label": "過去形"}, {"form": "表記して", "label": "て形"}, {"form": "表記される", "label": "受身形"}, {"form": "表記しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "文字や記号を使った書き表し方、またその書かれたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36117, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表記", "is_correct": true, "explanation": "文字や記号で書き表すことを指し、「同じ言葉の表記が違っている」に合う。"}, {"text": "表彰", "is_correct": false, "explanation": "功績をほめたたえることで、言葉の書き方の違いには合わない。"}, {"text": "表札", "is_correct": false, "explanation": "家や門に掲げる名札を指し、資料の言葉の書き方には合わない。"}, {"text": "表情", "is_correct": false, "explanation": "顔に出る感情を指し、言葉の書き方が違う文脈には合わない。"}], "explanations": {"表記": "文字や記号で書き表すことを指し、「同じ言葉の表記が違っている」に合う。", "表彰": "功績をほめたたえることで、言葉の書き方の違いには合わない。", "表札": "家や門に掲げる名札を指し、資料の言葉の書き方には合わない。", "表情": "顔に出る感情を指し、言葉の書き方が違う文脈には合わない。"}, "sentence_index": 0, "correct_answer": "表記"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は喜びの気持ちを、体全体で表記した。", "explanation": "ここは〈表現〉の意味。表記は文字や記号で書き表すことで、気持ちを体で示す意味はない。"}, {"text": "提出前に、誤字を表記して直した。", "explanation": "ここは〈修正〉の意味。表記は書き表すことで、誤りを直す意味はない。"}, {"text": "カメラのピントを表記して、写真を撮った。", "explanation": "ここは〈調整〉の意味。表記は文字や記号で書き表すことで、ピントを合わせる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36117, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表記", "is_correct": true, "explanation": "看板に書かれた文字の書き方を指し、「看板の表記が間違っていた」に合う。"}, {"text": "表明", "is_correct": false, "explanation": "考えや態度を公に示すことで、看板の書き方の文脈には合わない。"}, {"text": "表題", "is_correct": false, "explanation": "作品や文書の題名を指し、看板の書き方が間違っていた文脈には合わない。"}, {"text": "表皮", "is_correct": false, "explanation": "生物の体の表面の組織を指し、看板には当てはまらないので合わない。"}], "explanations": {"表記": "看板に書かれた文字の書き方を指し、「看板の表記が間違っていた」に合う。", "表明": "考えや態度を公に示すことで、看板の書き方の文脈には合わない。", "表題": "作品や文書の題名を指し、看板の書き方が間違っていた文脈には合わない。", "表皮": "生物の体の表面の組織を指し、看板には当てはまらないので合わない。"}, "sentence_index": 6, "correct_answer": "表記"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生に会ったので、丁寧に表記した。", "explanation": "ここは〈挨拶〉の意味。表記は文字や記号で書き表すことで、人にあいさつする意味はない。"}, {"text": "荷物を倉庫へ表記して、午後に届けた。", "explanation": "ここは〈運搬〉の意味。表記は書き表すことで、荷物を運ぶ意味はない。"}, {"text": "その会社はお金を表記して、社会を助けた。", "explanation": "ここは〈寄付〉の意味。表記は書き表すことで、お金を出して助ける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36117, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その地名は、カタカナを表記されている。", "corrected_sentence": "その地名は、カタカナで表記されている。", "error_description": "「表記」は手段を「で」で示す。「を」は誤りで、正しくは「カタカナで表記されている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36117, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店のメニューは、値段の表記を税込みで統一されている。", "corrected_sentence": "この店のメニューは、値段の表記が税込みで統一されている。", "error_description": "「統一されている」は受け身なので、「表記」は主語として「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36118, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "収縮", "is_correct": true, "explanation": "熱で大きくなる膨張の対義語で、縮んで小さくなることを表す。"}, {"text": "溶解", "is_correct": false, "explanation": "物質が液体に溶けることで、膨張の対義語ではない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつけることで、膨張の対義語ではない。"}, {"text": "凝固", "is_correct": false, "explanation": "液体が固まることで、大きさの変化を表す膨張の対義語ではない。"}], "correct_answer": "収縮", "explanations": {"収縮": "熱で大きくなる膨張の対義語で、縮んで小さくなることを表す。", "溶解": "物質が液体に溶けることで、膨張の対義語ではない。", "点火": "火をつけることで、膨張の対義語ではない。", "凝固": "液体が固まることで、大きさの変化を表す膨張の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36118, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "収縮", "is_correct": true, "explanation": "熱で大きくなる膨張の対義語で、縮んで小さくなることを表す。"}, {"text": "点滅", "is_correct": false, "explanation": "明かりがついたり消えたりすることで、膨張の対義語ではない。"}, {"text": "採掘", "is_correct": false, "explanation": "地中から資源を掘り出すことで、膨張の対義語ではない。"}, {"text": "結晶", "is_correct": false, "explanation": "物質が規則正しく固まることで、大きさの変化を表す膨張の対義語ではない。"}], "correct_answer": "収縮", "explanations": {"収縮": "熱で大きくなる膨張の対義語で、縮んで小さくなることを表す。", "点滅": "明かりがついたり消えたりすることで、膨張の対義語ではない。", "採掘": "地中から資源を掘り出すことで、膨張の対義語ではない。", "結晶": "物質が規則正しく固まることで、大きさの変化を表す膨張の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36118, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物の大きさや広がりが大きくなること。", "primary_collocate": null, "pronunciation": "ぼうちょう", "ipa": "boːtɕoː", "syllable_count": 4, "sentences": [{"text": "熱を加えると、空気は膨張して風船が大きくなります。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "熱[ねつ]を加[くわ]えると、空気[くうき]は膨張[ぼうちょう]して風船[ふうせん]が大[おお]きくなります。", "sentence_source": "generated"}, {"text": "金属は温度が上がると膨張する。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "金属[きんぞく]は温度[おんど]が上[あ]がると膨張[ぼうちょう]する。", "sentence_source": "generated"}, {"text": "宇宙は今も膨張し続けていると言われている。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]は今[いま]も膨張[ぼうちょう]し続[つづ]けていると言[い]われている。", "sentence_source": "generated"}, {"text": "水は凍ると膨張するので、瓶が割れてしまった。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "水[みず]は凍[こお]ると膨張[ぼうちょう]するので、瓶[びん]が割[わ]れてしまった。", "sentence_source": "generated"}, {"text": "夏に線路が膨張しても曲がらないように、すき間が作ってある。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "夏[なつ]に線路[せんろ]が膨張[ぼうちょう]しても曲[ま]がらないように、すき間[ま]が作[つく]ってある。", "sentence_source": "generated"}, {"text": "パンの生地が膨張して、オーブンの中で二倍の大きさになった。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "パンの生地[きじ]が膨張[ぼうちょう]して、オーブンの中[なか]で二倍[にばい]の大[おお]きさになった。", "sentence_source": "generated"}, {"text": "暑い日にペットボトルを車に置いたら、中の空気が膨張してふたが開いた。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]にペットボトルを車[くるま]に置[お]いたら、中[なか]の空気[くうき]が膨張[ぼうちょう]してふたが開[あ]いた。", "sentence_source": "generated"}, {"text": "温めると膨張し、冷やすと収縮する物は多い。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "温[あたた]めると膨張[ぼうちょう]し、冷[ひ]やすと収縮[しゅうしゅく]する物[もの]は多[おお]い。", "sentence_source": "generated"}, {"text": "都市の膨張が進み、郊外にも住宅が増えた。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "都市[とし]の膨張[ぼうちょう]が進[すす]み、郊外[こうがい]にも住宅[じゅうたく]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "風船は膨張しすぎると、割れて大きな音が出る。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "風船[ふうせん]は膨張[ぼうちょう]しすぎると、割[わ]れて大[おお]きな音[おと]が出[で]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "膨張する", "label": "dictionary form"}, {"form": "膨張した", "label": "past"}, {"form": "膨張して", "label": "te-form"}, {"form": "膨張しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "物が熱や圧力などで体積や範囲を増すこと。膨張する/膨張した。対は収縮。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36118, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "膨張", "is_correct": true, "explanation": "熱で体積が大きくなることを表し、「風船が大きくなる」と合う。"}, {"text": "収縮", "is_correct": false, "explanation": "縮んで小さくなることを表し、風船が大きくなる結果と矛盾する。"}, {"text": "消滅", "is_correct": false, "explanation": "なくなることを表し、空気が風船を大きくする文脈には合わない。"}, {"text": "沈殿", "is_correct": false, "explanation": "物質が底に沈むことを表し、空気が風船を大きくする文脈には合わない。"}], "explanations": {"膨張": "熱で体積が大きくなることを表し、「風船が大きくなる」と合う。", "収縮": "縮んで小さくなることを表し、風船が大きくなる結果と矛盾する。", "消滅": "なくなることを表し、空気が風船を大きくする文脈には合わない。", "沈殿": "物質が底に沈むことを表し、空気が風船を大きくする文脈には合わない。"}, "sentence_index": 0, "correct_answer": "膨張"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋の水は、夜の間に膨張してなくなった。", "explanation": "ここは〈蒸発〉の意味。膨張は大きくなることで、水が消えることは表さない。"}, {"text": "洗濯物は晴れた日に膨張して、夕方には乾いた。", "explanation": "ここは〈乾燥〉の意味。膨張は大きくなることで、水分がなくなる意味は含まない。"}, {"text": "夏の食品では、細菌が膨張して食中毒を起こすことがある。", "explanation": "ここは〈増殖〉の意味。膨張は大きさや広がりが大きくなることで、細菌が数を増やす意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36118, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "膨張", "is_correct": true, "explanation": "中の空気が熱で大きくなることを表し、ふたが開いた理由に合う。"}, {"text": "集計", "is_correct": false, "explanation": "数を合計することで、空気がふたを開ける文脈には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案に点数をつけることで、空気の変化を表さないので合わない。"}, {"text": "送信", "is_correct": false, "explanation": "情報を送ることで、空気がふたを開ける文脈には合わない。"}], "explanations": {"膨張": "中の空気が熱で大きくなることを表し、ふたが開いた理由に合う。", "集計": "数を合計することで、空気がふたを開ける文脈には合わない。", "採点": "答案に点数をつけることで、空気の変化を表さないので合わない。", "送信": "情報を送ることで、空気がふたを開ける文脈には合わない。"}, "sentence_index": 6, "correct_answer": "膨張"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車が膨張して、ホームを出発した。", "explanation": "ここは〈発車〉の意味。膨張は大きくなることで、電車が出ていく意味はない。"}, {"text": "夜になると、街灯が膨張した。", "explanation": "ここは〈点灯〉の意味。膨張は大きくなることで、明かりをつける意味はない。"}, {"text": "熱いコーヒーが膨張して、すぐに冷めた。", "explanation": "ここは〈冷却〉の意味。膨張は大きくなることで、温度が下がる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36118, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉄の棒は、夏になると膨張を長くなる。", "corrected_sentence": "鉄の棒は、夏になると膨張して長くなる。", "error_description": "「膨張」は自動詞なので、「を」ではなく「して」で続ける。「膨張を長くなる」は誤りで、正しくは「膨張して長くなる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36118, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "缶は、中の気体を膨張すると、破裂することがある。", "corrected_sentence": "缶は、中の気体が膨張すると、破裂することがある。", "error_description": "「膨張」は自動詞的に使い、変化する主語を「が」で示す。「を」は誤りで、正しくは「気体が膨張すると」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36120, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「関心がある」で、関心が主語になる形。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「関心をあり」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を示す。「関心のあり」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「関心へあり」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「関心がある」で、関心が主語になる形。", "を": "「を」は目的語を示す。「関心をあり」は文が成り立たない。", "の": "「の」は連体修飾を示す。「関心のあり」は文として成り立たない。", "へ": "「へ」は方向を示す。「関心へあり」は成り立たない。"}, "error_tags": {"を": "目的語の格", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関心", "is_correct": true, "explanation": "「関心」の対義語で、関心がないことを表す。"}, {"text": "興味", "is_correct": false, "explanation": "関心の類義語であり、対義語ではない。"}, {"text": "熱意", "is_correct": false, "explanation": "関心と同じ方向の気持ちで、対義語ではない。"}, {"text": "努力", "is_correct": false, "explanation": "物事に力を注ぐ行為で、関心の対義語ではない。"}], "correct_answer": "無関心", "explanations": {"無関心": "「関心」の対義語で、関心がないことを表す。", "興味": "関心の類義語であり、対義語ではない。", "熱意": "関心と同じ方向の気持ちで、対義語ではない。", "努力": "物事に力を注ぐ行為で、関心の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36120, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「関心がなかった」で、関心が主語となる否定の形。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示す。「関心となかった」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示す。「関心からなかった」は主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示す。ここでは主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「関心がなかった」で、関心が主語となる否定の形。", "と": "「と」は並列や引用を示す。「関心となかった」は成り立たない。", "から": "「から」は起点や理由を示す。「関心からなかった」は主語を示せない。", "より": "「より」は比較の基準を示す。ここでは主語を示せない。"}, "error_tags": {"と": "並列・引用", "から": "起点・理由", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関心", "is_correct": true, "explanation": "「関心」の対義語で、関心がないことを表す。"}, {"text": "好奇心", "is_correct": false, "explanation": "関心に近い気持ちで、対義語ではない。"}, {"text": "集中", "is_correct": false, "explanation": "一つのことに心を向ける状態で、対義語ではない。"}, {"text": "熱中", "is_correct": false, "explanation": "夢中になることで、対義語ではない。"}], "correct_answer": "無関心", "explanations": {"無関心": "「関心」の対義語で、関心がないことを表す。", "好奇心": "関心に近い気持ちで、対義語ではない。", "集中": "一つのことに心を向ける状態で、対義語ではない。", "熱中": "夢中になることで、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36120, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かに心をひかれる気持ち。", "primary_collocate": null, "pronunciation": "かんしん", "ipa": "kaɲɕiɴ", "syllable_count": 4, "sentences": [{"text": "弟は最近、宇宙にとても強い関心を持っている。", "target_word": "関心", "complexity_tier": "T3", "furigana": "弟[おとうと]は最近[さいきん]、宇宙[うちゅう]にとても強[つよ]い関心[かんしん]を持[も]っている。", "sentence_source": "generated"}, {"text": "私は昔から古い建物に関心があり、旅行先でよく見に行く。", "target_word": "関心", "complexity_tier": "T3", "furigana": "私[わたし]は昔[むかし]から古[ふる]い建物[たてもの]に関心[かんしん]があり、旅行先[りょこうさき]でよく見[み]に行[い]く。", "sentence_source": "generated"}, {"text": "子どもたちは新しい遊びに関心を示して、すぐに集まってきた。", "target_word": "関心", "complexity_tier": "T3", "furigana": "子[こ]どもたちは新[あたら]しい遊[あそ]びに関心[かんしん]を示[しめ]して、すぐに集[あつ]まってきた。", "sentence_source": "generated"}, {"text": "彼女は音楽への関心が深まり、毎日ピアノを練習するようになった。", "target_word": "関心", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は音楽[おんがく]への関心[かんしん]が深[ふか]まり、毎日[まいにち]ピアノを練習[れんしゅう]するようになった。", "sentence_source": "generated"}, {"text": "彼は絵には関心がないので、美術館に誘っても断られる。", "target_word": "関心", "complexity_tier": "T3", "furigana": "彼[かれ]は絵[え]には関心[かんしん]がないので、美術館[びじゅつかん]に誘[さそ]っても断[ことわ]られる。", "sentence_source": "generated"}, {"text": "祖母は料理に関心が強く、新しいレシピを見つけるとすぐ試す。", "target_word": "関心", "complexity_tier": "T3", "furigana": "祖母[そぼ]は料理[りょうり]に関心[かんしん]が強[つよ]く、新[あたら]しいレシピを見[み]つけるとすぐ試[ため]す。", "sentence_source": "generated"}, {"text": "猫は動くものに関心をひかれて、じっと目で追っている。", "target_word": "関心", "complexity_tier": "T3", "furigana": "猫[ねこ]は動[うご]くものに関心[かんしん]をひかれて、じっと目[め]で追[お]っている。", "sentence_source": "generated"}, {"text": "最初は関心がなかったのに、友達の話を聞いて読んでみたくなった。", "target_word": "関心", "complexity_tier": "T3", "furigana": "最初[さいしょ]は関心[かんしん]がなかったのに、友達[ともだち]の話[はなし]を聞[き]いて読[よ]んでみたくなった。", "sentence_source": "generated"}, {"text": "先生は生徒の関心を集めるために、おもしろい実験を見せた。", "target_word": "関心", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の関心[かんしん]を集[あつ]めるために、おもしろい実験[じっけん]を見[み]せた。", "sentence_source": "generated"}, {"text": "本人の関心が向かない勉強は、なかなか身につかない。", "target_word": "関心", "complexity_tier": "T3", "furigana": "本人[ほんにん]の関心[かんしん]が向[む]かない勉強[べんきょう]は、なかなか身[み]につかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関心", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かに心をひかれて、向かっていく気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36120, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関心", "is_correct": true, "explanation": "「強い関心を持つ」で、宇宙に心を向ける気持ちを表す。"}, {"text": "期限", "is_correct": false, "explanation": "「強い期限を持つ」とは言わない。期限は強さを持つ対象ではない。"}, {"text": "順番", "is_correct": false, "explanation": "「強い順番を持つ」は不自然。順番は心の強さを表せない。"}, {"text": "手順", "is_correct": false, "explanation": "「強い手順を持つ」は成り立たない。手順は持つ強さの対象にならない。"}], "explanations": {"関心": "「強い関心を持つ」で、宇宙に心を向ける気持ちを表す。", "期限": "「強い期限を持つ」とは言わない。期限は強さを持つ対象ではない。", "順番": "「強い順番を持つ」は不自然。順番は心の強さを表せない。", "手順": "「強い手順を持つ」は成り立たない。手順は持つ強さの対象にならない。"}, "sentence_index": 0, "correct_answer": "関心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の見事な演奏に、客席の全員が関心した。", "explanation": "ここは〈感心〉の意味。感心は「すばらしい」と心を動かされる意味で「感心する」と言うが、関心は心をひかれる気持ちなので「関心する」とは言わない。"}, {"text": "二人の関心は年々悪化して、ついに別れた。", "explanation": "ここは〈関係〉の意味。関係は悪化するが、関心は悪化するものではなく、高まる・低下するものなので合わない。"}, {"text": "彼は最後まで関心を果たした。", "explanation": "ここは〈責任〉の意味。責任は果たすものだが、関心は果たす対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36120, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関心", "is_correct": true, "explanation": "「関心をひかれる」で、心が引き寄せられる意味。"}, {"text": "時刻", "is_correct": false, "explanation": "「時刻をひかれる」は成り立たない。時刻は心を引く対象にならない。"}, {"text": "財布", "is_correct": false, "explanation": "財布は心を引く対象ではなく、「ひかれる」とは言わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は心をひかれるものではないので、この文脈に入らない。"}], "explanations": {"関心": "「関心をひかれる」で、心が引き寄せられる意味。", "時刻": "「時刻をひかれる」は成り立たない。時刻は心を引く対象にならない。", "財布": "財布は心を引く対象ではなく、「ひかれる」とは言わない。", "天気": "天気は心をひかれるものではないので、この文脈に入らない。"}, "sentence_index": 6, "correct_answer": "関心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は歴史の関心が豊富で、どんな質問にも答えられる。", "explanation": "ここは〈知識〉の意味。知識は「豊富」と言えるが、関心は「強い・深い」で表すもので「豊富」とは言わない。"}, {"text": "今朝の関心は五度で、とても寒かった。", "explanation": "ここは〈気温〉の意味。気温は数値で表すが、関心は数値で表す対象ではない。"}, {"text": "彼は初対面の人への関心を解き、笑顔で話し始めた。", "explanation": "ここは〈警戒〉の意味。警戒は解くものだが、関心は解く対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36120, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼はこの分野に関心に持ち、本を何冊も読んでいる。", "corrected_sentence": "彼はこの分野に関心を持ち、本を何冊も読んでいる。", "error_description": "助詞の誤り。「持つ」の目的語は「を」なので、「関心に持つ」ではなく「関心を持つ」と言う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36120, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多くの人がその事件に関心を寄るので、ニュースは毎日続いた。", "corrected_sentence": "多くの人がその事件に関心を寄せるので、ニュースは毎日続いた。", "error_description": "動詞の誤り。「寄る」は自動詞で「関心を寄る」とは言えない。他動詞「寄せる」を使い「関心を寄せる」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36121, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「関心がなく」で、関心が否定の文の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「関心をなく」は存在の否定の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示す。「関心となく」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示す。「関心からなく」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「関心がなく」で、関心が否定の文の主語になる。", "を": "「を」は目的語を示す。「関心をなく」は存在の否定の主語にならない。", "と": "「と」は並列や引用を示す。「関心となく」は成り立たない。", "から": "「から」は起点や理由を示す。「関心からなく」は不自然。"}, "error_tags": {"を": "目的語の格", "と": "並列・引用", "から": "起点・理由"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関心", "is_correct": true, "explanation": "「関心」の対義語で、関心がないことを表す。"}, {"text": "注意", "is_correct": false, "explanation": "心を向ける行為で、関心の対義語ではない。"}, {"text": "警戒", "is_correct": false, "explanation": "用心する気持ちで、対義語ではない。"}, {"text": "熱意", "is_correct": false, "explanation": "関心と同じ方向の気持ちで、対義語ではない。"}], "correct_answer": "無関心", "explanations": {"無関心": "「関心」の対義語で、関心がないことを表す。", "注意": "心を向ける行為で、関心の対義語ではない。", "警戒": "用心する気持ちで、対義語ではない。", "熱意": "関心と同じ方向の気持ちで、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36121, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「関心が薄れて」で、関心が主語になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着点を示す。「関心に薄れて」は主語が立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「関心へ薄れて」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示す。「関心より薄れて」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「関心が薄れて」で、関心が主語になる。", "に": "「に」は相手や帰着点を示す。「関心に薄れて」は主語が立たない。", "へ": "「へ」は方向を示す。「関心へ薄れて」は不自然。", "より": "「より」は比較の基準を示す。「関心より薄れて」は成り立たない。"}, "error_tags": {"に": "相手・帰着点", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関心", "is_correct": true, "explanation": "「関心」の対義語で、関心がないことを表す。"}, {"text": "好奇心", "is_correct": false, "explanation": "関心に近い気持ちで、対義語ではない。"}, {"text": "集中", "is_correct": false, "explanation": "一つのことに心を向ける状態で、対義語ではない。"}, {"text": "熱中", "is_correct": false, "explanation": "夢中になることで、対義語ではない。"}], "correct_answer": "無関心", "explanations": {"無関心": "「関心」の対義語で、関心がないことを表す。", "好奇心": "関心に近い気持ちで、対義語ではない。", "集中": "一つのことに心を向ける状態で、対義語ではない。", "熱中": "夢中になることで、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36121, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事や人に対して、知りたい、かかわりたいと思う気持ち。", "primary_collocate": null, "pronunciation": "かんしん", "ipa": "kaɲɕiɴ", "syllable_count": 4, "sentences": [{"text": "市民の政治への関心が低く、選挙の投票率が下がっている。", "target_word": "関心", "complexity_tier": "T3", "furigana": "市民[しみん]の政治[せいじ]への関心[かんしん]が低[ひく]く、選挙[せんきょ]の投票率[とうひょうりつ]が下[さ]がっている。", "sentence_source": "generated"}, {"text": "彼は他人の生活に関心がなく、隣の人の名前も知らない。", "target_word": "関心", "complexity_tier": "T3", "furigana": "彼[かれ]は他人[たにん]の生活[せいかつ]に関心[かんしん]がなく、隣[となり]の人[ひと]の名前[なまえ]も知[し]らない。", "sentence_source": "generated"}, {"text": "環境問題に関心のある学生が集まって、勉強会を開いた。", "target_word": "関心", "complexity_tier": "T3", "furigana": "環境問題[かんきょうもんだい]に関心[かんしん]のある学生[がくせい]が集[あつ]まって、勉強会[べんきょうかい]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "この事件は社会の関心が高く、ニュースで毎日報じられている。", "target_word": "関心", "complexity_tier": "T3", "furigana": "この事件[じけん]は社会[しゃかい]の関心[かんしん]が高[たか]く、ニュースで毎日[まいにち]報[ほう]じられている。", "sentence_source": "generated"}, {"text": "母は私の進路に関心を持ち、いろいろと質問してくる。", "target_word": "関心", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の進路[しんろ]に関心[かんしん]を持[も]ち、いろいろと質問[しつもん]してくる。", "sentence_source": "generated"}, {"text": "外国の文化に関心があるので、留学の説明会に参加した。", "target_word": "関心", "complexity_tier": "T3", "furigana": "外国[がいこく]の文化[ぶんか]に関心[かんしん]があるので、留学[りゅうがく]の説明会[せつめいかい]に参加[さんか]した。", "sentence_source": "generated"}, {"text": "健康への関心が高まり、毎朝歩く人が増えている。", "target_word": "関心", "complexity_tier": "T3", "furigana": "健康[けんこう]への関心[かんしん]が高[たか]まり、毎朝[まいあさ]歩[ある]く人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "世間の関心が薄れて、その話題はもう報じられなくなった。", "target_word": "関心", "complexity_tier": "T3", "furigana": "世間[せけん]の関心[かんしん]が薄[うす]れて、その話題[わだい]はもう報[ほう]じられなくなった。", "sentence_source": "generated"}, {"text": "記者は読者の関心がどこにあるのかを考えて記事を書く。", "target_word": "関心", "complexity_tier": "T3", "furigana": "記者[きしゃ]は読者[どくしゃ]の関心[かんしん]がどこにあるのかを考[かんが]えて記事[きじ]を書[か]く。", "sentence_source": "generated"}, {"text": "私は地元の歴史に関心があるので、図書館で資料を調べている。", "target_word": "関心", "complexity_tier": "T3", "furigana": "私[わたし]は地元[じもと]の歴史[れきし]に関心[かんしん]があるので、図書館[としょかん]で資料[しりょう]を調[しら]べている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関心", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事や人について知りたい、かかわりたいという気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36121, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関心", "is_correct": true, "explanation": "「政治への関心が低い」で、政治に心を向ける気持ちが弱いことを表す。"}, {"text": "寿命", "is_correct": false, "explanation": "「政治への寿命が低い」は成り立たない。寿命は関心の対象にならない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は政治への関心の対象ではなく、「低い」とも言わない。"}, {"text": "出費", "is_correct": false, "explanation": "出費は政治に向ける気持ちを表さないので、この文脈に入らない。"}], "explanations": {"関心": "「政治への関心が低い」で、政治に心を向ける気持ちが弱いことを表す。", "寿命": "「政治への寿命が低い」は成り立たない。寿命は関心の対象にならない。", "湿度": "湿度は政治への関心の対象ではなく、「低い」とも言わない。", "出費": "出費は政治に向ける気持ちを表さないので、この文脈に入らない。"}, "sentence_index": 0, "correct_answer": "関心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週の旅行の関心が決まり、皆で宿を探し始めた。", "explanation": "ここは〈予定〉の意味。予定は決まるものだが、関心は決まって定まるものではないので合わない。"}, {"text": "家計の関心が重く、毎月の支払いがつらい。", "explanation": "ここは〈負担〉の意味。負担は重さを持つが、関心には重さという性質がなく合わない。"}, {"text": "仕事が続いて、体に関心が溜まっている。", "explanation": "ここは〈疲労〉の意味。疲労は溜まるが、関心は体に溜まるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36121, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関心", "is_correct": true, "explanation": "「健康への関心が高まり」で、健康に心を向ける気持ちが強まる意味。"}, {"text": "体重", "is_correct": false, "explanation": "体重は健康への関心の対象ではなく、「高まる」とは言わない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は健康への関心を表せず、「高まる」とも言わない。"}, {"text": "雨量", "is_correct": false, "explanation": "雨量は関心の対象にならず、この文脈に入らない。"}], "explanations": {"関心": "「健康への関心が高まり」で、健康に心を向ける気持ちが強まる意味。", "体重": "体重は健康への関心の対象ではなく、「高まる」とは言わない。", "天候": "天候は健康への関心を表せず、「高まる」とも言わない。", "雨量": "雨量は関心の対象にならず、この文脈に入らない。"}, "sentence_index": 6, "correct_answer": "関心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "観客は選手たちに大きな関心を送った。", "explanation": "ここは〈声援〉の意味。声援は送るものだが、関心は人に送るものではない。"}, {"text": "この電池は関心が延びて、長く使える。", "explanation": "ここは〈寿命〉の意味。寿命は延びるが、関心は時間的に延びる性質を持たない。"}, {"text": "彼は毎日練習して関心を磨いた。", "explanation": "ここは〈腕〉の意味。腕は磨いて上達させるが、関心は磨いて上達させるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36121, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この事件は社会の関心を集まる話題になり、ニュースで毎日報じられている。", "corrected_sentence": "この事件は社会の関心を集める話題になり、ニュースで毎日報じられている。", "error_description": "動詞の誤り。「集まる」は自動詞で「関心を集まる」とは言えない。他動詞「集める」を使い「関心を集める」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36121, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世間の関心を薄れて、この話題は近頃ほとんど報じられなくなった。", "corrected_sentence": "世間の関心が薄れて、この話題は近頃ほとんど報じられなくなった。", "error_description": "助詞の誤り。「薄れる」は主語に「が」を取るので、「関心を薄れる」は誤り。正しくは「関心が薄れる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
