INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36122, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "20という数字のこと。", "primary_collocate": null, "pronunciation": "にじゅう", "ipa": "nidʑɯː", "syllable_count": 3, "sentences": [{"text": "10に10を足すと、答えは「20」になります。", "target_word": "20", "complexity_tier": "T3", "furigana": "10に10を足[た]すと、答[こた]えは「20」になります。", "sentence_source": "generated"}, {"text": "この電話番号の最後の数字は「20」です。", "target_word": "20", "complexity_tier": "T3", "furigana": "この電話番号[でんわばんごう]の最後[さいご]の数字[すうじ]は「20」です。", "sentence_source": "generated"}, {"text": "40を2で割ると、「20」になります。", "target_word": "20", "complexity_tier": "T3", "furigana": "40を2で割[わ]ると、「20」になります。", "sentence_source": "generated"}, {"text": "黒板に大きく「20」と書いてください。", "target_word": "20", "complexity_tier": "T3", "furigana": "黒板[こくばん]に大[おお]きく「20」と書[か]いてください。", "sentence_source": "generated"}, {"text": "「20」は偶数なので、2で割ることができます。", "target_word": "20", "complexity_tier": "T3", "furigana": "「20」は偶数[ぐうすう]なので、2で割[わ]ることができます。", "sentence_source": "generated"}, {"text": "百点満点のテストで、私の点数は「20」だった。", "target_word": "20", "complexity_tier": "T3", "furigana": "百点満点[ひゃくてんまんてん]のテストで、私[わたし]の点数[てんすう]は「20」だった。", "sentence_source": "generated"}, {"text": "「20」から5を引くと、15が残ります。", "target_word": "20", "complexity_tier": "T3", "furigana": "「20」から5を引[ひ]くと、15が残[のこ]ります。", "sentence_source": "generated"}, {"text": "背番号が「20」の選手が、決勝点を決めた。", "target_word": "20", "complexity_tier": "T3", "furigana": "背番号[せばんごう]が「20」の選手[せんしゅ]が、決勝点[けっしょうてん]を決[き]めた。", "sentence_source": "generated"}, {"text": "教室の席には、1から「20」まで番号がついている。", "target_word": "20", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の席[せき]には、1から「20」まで番号[ばんごう]がついている。", "sentence_source": "generated"}, {"text": "数字の「20」は、漢字で二十と書きます。", "target_word": "20", "complexity_tier": "T3", "furigana": "数字[すうじ]の「20」は、漢字[かんじ]で二十[にじゅう]と書[か]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "20", "label": "base form"}, {"form": "20の", "label": "attributive"}], "register": "neutral", "sense_fingerprint": "数字としての20。計算の答えや番号、書かれた数字として扱う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36122, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "20", "is_correct": true, "explanation": "10と10を足した答えは20なので、「答えは「20」」に合う。"}, {"text": "15", "is_correct": false, "explanation": "10と10の和は20で、15ではないので合わない。"}, {"text": "30", "is_correct": false, "explanation": "10と10の和は20で、30ではないので合わない。"}, {"text": "100", "is_correct": false, "explanation": "10と10の和は20で、100ではないので合わない。"}], "explanations": {"20": "10と10を足した答えは20なので、「答えは「20」」に合う。", "15": "10と10の和は20で、15ではないので合わない。", "30": "10と10の和は20で、30ではないので合わない。", "100": "10と10の和は20で、100ではないので合わない。"}, "sentence_index": 0, "correct_answer": "20"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の好きな色は20です。", "explanation": "ここは〈色〉の意味。20は数字で、色の名前としては使わない。"}, {"text": "田中さんの名字は「20」で、クラスの全員が知っている。", "explanation": "ここは〈名字〉の意味。20は数字で、人の名字には使わない。"}, {"text": "来年の20月に引っ越す予定だ。", "explanation": "ここは〈月〉の意味。月は1月から12月までで、20月という月はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36122, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "20", "is_correct": true, "explanation": "20から5を引くと15になるので、「20から5を引くと、15が残ります」に合う。"}, {"text": "25", "is_correct": false, "explanation": "25から5を引くと20になり、15は残らないので合わない。"}, {"text": "10", "is_correct": false, "explanation": "10から5を引くと5になり、15は残らないので合わない。"}, {"text": "18", "is_correct": false, "explanation": "18から5を引くと13になり、15は残らないので合わない。"}], "explanations": {"20": "20から5を引くと15になるので、「20から5を引くと、15が残ります」に合う。", "25": "25から5を引くと20になり、15は残らないので合わない。", "10": "10から5を引くと5になり、15は残らないので合わない。", "18": "18から5を引くと13になり、15は残らないので合わない。"}, "sentence_index": 6, "correct_answer": "20"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は20年生で、小学校に通っている。", "explanation": "ここは〈学年〉の意味。20は数字で、学年を数える語としては使わない。"}, {"text": "数字の十の位が20になっている。", "explanation": "ここは〈一桁〉の意味。十の位には一桁の数字しか入らないので、20は合わない。"}, {"text": "今日は20曜日で、学校が休みだ。", "explanation": "ここは〈曜日〉の意味。曜日は月曜から日曜までで、20曜日はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36122, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ケーキは20つ入りで、一箱800円です。", "corrected_sentence": "ケーキは20個入りで、一箱800円です。", "error_description": "「つ」は十までの数え方なので、20の個数には「個」を使う。「20つ」は誤りで、正しくは「20個」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36122, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議は来月の20日が、本社で行われる。", "corrected_sentence": "会議は来月の20日に、本社で行われる。", "error_description": "日付を示す「20日」には「に」で時期を示す。「が」は誤りで、正しくは「20日に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
