INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36123, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "整数の20。十九の次、二十一の前の数。", "primary_collocate": null, "pronunciation": "にじゅう", "ipa": "nidʑɯː", "syllable_count": 3, "sentences": [{"text": "19の次の数は「20」で、その次は21です。", "target_word": "20", "complexity_tier": "T3", "furigana": "19の次[つぎ]の数[かず]は「20」で、その次[つぎ]は21です。", "sentence_source": "generated"}, {"text": "「20」は、19より大きく21より小さい整数です。", "target_word": "20", "complexity_tier": "T3", "furigana": "「20」は、19より大[おお]きく21より小[ちい]さい整数[せいすう]です。", "sentence_source": "generated"}, {"text": "数を一から順に数えて、やっと「20」まで来た。", "target_word": "20", "complexity_tier": "T3", "furigana": "数[かず]を一[いち]から順[じゅん]に数[かぞ]えて、やっと「20」まで来[き]た。", "sentence_source": "generated"}, {"text": "「20」は4と5をかけた数で、5の倍数でもある。", "target_word": "20", "complexity_tier": "T3", "furigana": "「20」は4と5をかけた数[かず]で、5の倍数[ばいすう]でもある。", "sentence_source": "generated"}, {"text": "先生は出席番号が「20」の生徒を呼んだ。", "target_word": "20", "complexity_tier": "T3", "furigana": "先生[せんせい]は出席番号[しゅっせきばんごう]が「20」の生徒[せいと]を呼[よ]んだ。", "sentence_source": "generated"}, {"text": "19ではなく「20」を選んでください。", "target_word": "20", "complexity_tier": "T3", "furigana": "19ではなく「20」を選[えら]んでください。", "sentence_source": "generated"}, {"text": "100を5で割った答えは「20」だ。", "target_word": "20", "complexity_tier": "T3", "furigana": "100を5で割[わ]った答[こた]えは「20」だ。", "sentence_source": "generated"}, {"text": "箱の中にはカードが全部で「20」枚ありました。", "target_word": "20", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]にはカードが全部[ぜんぶ]で「20」枚[まい]ありました。", "sentence_source": "generated"}, {"text": "「20」と30の真ん中の数は25です。", "target_word": "20", "complexity_tier": "T3", "furigana": "「20」と30の真[ま]ん中[なか]の数[かず]は25です。", "sentence_source": "generated"}, {"text": "エレベーターの表示が19から「20」に変わった。", "target_word": "20", "complexity_tier": "T3", "furigana": "エレベーターの表示[ひょうじ]が19から「20」に変[か]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "20", "label": "base form"}, {"form": "20の", "label": "attributive"}], "register": "neutral", "sense_fingerprint": "19の次で21の前にある整数としての20。数の順序や大きさの中の位置を表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36123, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "20", "is_correct": true, "explanation": "19の次の整数で、21の前にある数。ここに入る正解。"}, {"text": "19", "is_correct": false, "explanation": "19は19自身なので、19の次の数としては入らない。"}, {"text": "21", "is_correct": false, "explanation": "21は20の次の数で、19の次の数には当たらない。"}, {"text": "30", "is_correct": false, "explanation": "30は19の次の数ではなく、20や21より後の数。"}], "explanations": {"20": "19の次の整数で、21の前にある数。ここに入る正解。", "19": "19は19自身なので、19の次の数としては入らない。", "21": "21は20の次の数で、19の次の数には当たらない。", "30": "30は19の次の数ではなく、20や21より後の数。"}, "sentence_index": 0, "correct_answer": "20"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の性格は20だ。", "explanation": "ここは〈性質〉の意味。整数の20は人の性質を表せないので、性格を述べるこの文には合わない。"}, {"text": "今朝の機嫌は20だ。", "explanation": "ここは〈感情〉の意味。整数の20は感情を表せないので、機嫌を述べるこの文には合わない。"}, {"text": "この歌の感想は20だ。", "explanation": "ここは〈評価〉の意味。整数の20は感想や評価を表せないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36123, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "20", "is_correct": true, "explanation": "100を5で割った答えで、20が正解。"}, {"text": "25", "is_correct": false, "explanation": "25は100を4で割った答えで、5で割った答えではない。"}, {"text": "50", "is_correct": false, "explanation": "50は100を2で割った答えで、5で割った答えではない。"}, {"text": "5", "is_correct": false, "explanation": "5は100を20で割った答えで、5で割った答えではない。"}], "explanations": {"20": "100を5で割った答えで、20が正解。", "25": "25は100を4で割った答えで、5で割った答えではない。", "50": "50は100を2で割った答えで、5で割った答えではない。", "5": "5は100を20で割った答えで、5で割った答えではない。"}, "sentence_index": 6, "correct_answer": "20"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その道の雰囲気は20だ。", "explanation": "ここは〈空気〉の意味。整数の20は場の空気を表せないので、雰囲気を述べるこの文には合わない。"}, {"text": "この映画の匂いは20だ。", "explanation": "ここは〈香り〉の意味。整数の20は香りを表せないので、匂いを述べるこの文には合わない。"}, {"text": "父の声の色は20だ。", "explanation": "ここは〈音色〉の意味。整数の20は音の質を表せないので、声の色を述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36123, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "得点は最後に20を止まった。", "corrected_sentence": "得点は最後に20で止まった。", "error_description": "「20」に続く助詞の誤り。「止まる」で到達点を示すときは「で」を使うので、「を」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36123, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙は20本あった。", "corrected_sentence": "紙は20枚あった。", "error_description": "「20」に続く助数詞の誤り。紙のような薄いものは「枚」で数えるので、「本」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
