INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36126, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをするため、やってみること。", "primary_collocate": null, "pronunciation": "こころみる", "ipa": "kokoɾomiɾɯ", "syllable_count": 5, "sentences": [{"text": "彼は固く閉まった扉を開けようと試みたが、びくともしなかった。", "target_word": "試みた", "complexity_tier": "T3", "furigana": "彼(かれ)は固(かた)く閉(し)まった扉(とびら)を開(あ)けようと試(こころ)みたが、びくともしなかった。", "sentence_source": "generated"}, {"text": "子どもたちは、初めて自分たちだけで料理を作ることを試みた。", "target_word": "試みた", "complexity_tier": "T3", "furigana": "子(こ)どもたちは、初(はじ)めて自分(じぶん)たちだけで料理(りょうり)を作(つく)ることを試(こころ)みた。", "sentence_source": "generated"}, {"text": "医師は新しい治療法を試みることにした。", "target_word": "試みる", "complexity_tier": "T3", "furigana": "医師(いし)は新(あたら)しい治療法(ちりょうほう)を試(こころ)みることにした。", "sentence_source": "generated"}, {"text": "彼女は十年ぶりに旧友へ連絡を取ろうと試みた。", "target_word": "試みた", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は十年(じゅうねん)ぶりに旧友(きゅうゆう)へ連絡(れんらく)を取(と)ろうと試(こころ)みた。", "sentence_source": "generated"}, {"text": "学生たちは、校庭に小さな畑を作ることを試みている。", "target_word": "試みている", "complexity_tier": "T3", "furigana": "学生(がくせい)たちは、校庭(こうてい)に小(ちい)さな畑(はたけ)を作(つく)ることを試(こころ)みている。", "sentence_source": "generated"}, {"text": "犯人は車で逃げようと試みたが、道路が封鎖されていた。", "target_word": "試みた", "complexity_tier": "T3", "furigana": "犯人(はんにん)は車(くるま)で逃(に)げようと試(こころ)みたが、道路(どうろ)が封鎖(ふうさ)されていた。", "sentence_source": "generated"}, {"text": "私は毎朝、早起きして走ることを試みているが、まだ続かない。", "target_word": "試みている", "complexity_tier": "T3", "furigana": "私(わたし)は毎朝(まいあさ)、早起(はやお)きして走(はし)ることを試(こころ)みているが、まだ続(つづ)かない。", "sentence_source": "generated"}, {"text": "作家は、これまでにない形式で小説を書くことを試みた。", "target_word": "試みた", "complexity_tier": "T4", "furigana": "作家(さっか)は、これまでにない形式(けいしき)で小説(しょうせつ)を書(か)くことを試(こころ)みた。", "sentence_source": "generated"}, {"text": "彼は川を泳いで渡ろうと試みて、途中で流されそうになった。", "target_word": "試みて", "complexity_tier": "T3", "furigana": "彼(かれ)は川(かわ)を泳(およ)いで渡(わた)ろうと試(こころ)みて、途中(とちゅう)で流(なが)されそうになった。", "sentence_source": "generated"}, {"text": "店主は、通りに屋台を出して客を呼ぶことを試みた。", "target_word": "試みた", "complexity_tier": "T3", "furigana": "店主(てんしゅ)は、通(とお)りに屋台(やたい)を出(だ)して客(きゃく)を呼(よ)ぶことを試(こころ)みた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試みる", "label": "終止形"}, {"form": "試みた", "label": "過去形"}, {"form": "試みて", "label": "て形"}, {"form": "試みない", "label": "否定形"}, {"form": "試みよう", "label": "意志形"}, {"form": "試みれば", "label": "仮定形"}], "register": "やや硬い", "sense_fingerprint": "何かを成すために実際にやってみる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36126, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試みた", "is_correct": true, "explanation": "過去形。「試みたが、びくともしなかった」と逆接の「が」に続く形として合う。"}, {"text": "試みて", "is_correct": false, "explanation": "て形は「が」に直接つながらず、「試みてが」となって文の形が崩れる。"}, {"text": "試みれば", "is_correct": false, "explanation": "仮定形は「が」に続かず、「試みればが」となって文が成り立たない。"}, {"text": "試みたら", "is_correct": false, "explanation": "たら形は「が」に続かず、「試みたらが」と言えない。"}], "explanations": {"試みた": "過去形。「試みたが、びくともしなかった」と逆接の「が」に続く形として合う。", "試みて": "て形は「が」に直接つながらず、「試みてが」となって文の形が崩れる。", "試みれば": "仮定形は「が」に続かず、「試みればが」となって文が成り立たない。", "試みたら": "たら形は「が」に続かず、「試みたらが」と言えない。"}, "sentence_index": 0, "correct_answer": "試みた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は来月の幹事を試みることになった。", "explanation": "ここは〈引き受ける〉の意味。役目を受け持つ時は引き受けるを使う。試みるはその役目には使わない。"}, {"text": "大学は来年の予算を試みた。", "explanation": "ここは〈組む〉の意味。予算を立てる時は組むを使う。試みるは予算の作成には使わない。"}, {"text": "店員は笑顔で試みた。", "explanation": "ここは〈接客〉の意味。客への応対は接客するを使う。試みるは人への応対には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36126, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試みている", "is_correct": true, "explanation": "〜ている形で、「試みているが」と後に逆接が続く形として合う。"}, {"text": "試みながら", "is_correct": false, "explanation": "ながら形は「が」に続かず、「試みながらが」は成り立たない。"}, {"text": "試みず", "is_correct": false, "explanation": "文語の否定の形で、「試みずが」と続けられない。"}, {"text": "試みなくて", "is_correct": false, "explanation": "て形の否定で、「が」に直接つながらず文の形が崩れる。"}], "explanations": {"試みている": "〜ている形で、「試みているが」と後に逆接が続く形として合う。", "試みながら": "ながら形は「が」に続かず、「試みながらが」は成り立たない。", "試みず": "文語の否定の形で、「試みずが」と続けられない。", "試みなくて": "て形の否定で、「が」に直接つながらず文の形が崩れる。"}, "sentence_index": 6, "correct_answer": "試みている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は月曜の朝、眠気を試みた。", "explanation": "ここは〈追い払う〉の意味。眠気を追い払う時は追い払うを使う。試みるは成否を確かめる行為なので、眠気には使わない。"}, {"text": "彼は友人に花束を試みた。", "explanation": "ここは〈贈る〉の意味。相手に物を与える時は贈るを使う。試みるはこの場面では使わない。"}, {"text": "彼女は国歌を試みた。", "explanation": "ここは〈歌う〉の意味。声に出して歌う時は歌うを使う。試みるは歌う行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36126, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は長年の夢に向かって、新しい事業を立ち上げように試みた。", "corrected_sentence": "彼は長年の夢に向かって、新しい事業を立ち上げようと試みた。", "error_description": "助詞が誤り。「〜しようと試みる」の形で意志を示すので、「と」が必要。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "試みた", "is_correct": true, "explanation": "過去形。既に行った一回の行為を表し、文の内容に合う。"}, {"text": "試みる", "is_correct": false, "explanation": "辞書形は非過去。既に行った行為を述べる文の時制と合わない。"}, {"text": "試みて", "is_correct": false, "explanation": "て形は文を終えられず、「。」の前に置くと文が成り立たない。"}, {"text": "試みない", "is_correct": false, "explanation": "否定形で、実際に行ったという内容と反対になる。"}], "correct_form": "試みた", "base_form": "試みる", "form_label": "過去形", "sentence_index": 1, "explanations": {"試みた": "過去形。既に行った一回の行為を表し、文の内容に合う。", "試みる": "辞書形は非過去。既に行った行為を述べる文の時制と合わない。", "試みて": "て形は文を終えられず、「。」の前に置くと文が成り立たない。", "試みない": "否定形で、実際に行ったという内容と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36126, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は毎晩、料理を作ることを試みしている。", "corrected_sentence": "父は毎晩、料理を作ることを試みている。", "error_description": "活用形が誤り。「試みている」が正しい形で、「試みし」は活用として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "試みた", "is_correct": true, "explanation": "過去形。一回きりの行為を表し、文の内容に合う。"}, {"text": "試みよう", "is_correct": false, "explanation": "意志形はこれからの意思を表し、既に行った過去の行為とは合わない。"}, {"text": "試みれば", "is_correct": false, "explanation": "仮定形は「〜すれば」の条件を表し、過去の出来事の叙述にならない。"}, {"text": "試みている", "is_correct": false, "explanation": "〜ている形は継続や進行を表し、完了した一回の行為を表す形ではない。"}], "correct_form": "試みた", "base_form": "試みる", "form_label": "過去形", "sentence_index": 7, "explanations": {"試みた": "過去形。一回きりの行為を表し、文の内容に合う。", "試みよう": "意志形はこれからの意思を表し、既に行った過去の行為とは合わない。", "試みれば": "仮定形は「〜すれば」の条件を表し、過去の出来事の叙述にならない。", "試みている": "〜ている形は継続や進行を表し、完了した一回の行為を表す形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36127, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「試みた」に続けて逆接の「が」で後文とつながり、「すぐに見つかった」と結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「試みた」の後に目的語の「を」は続かない。「脱走を」の「を」は別の語に付いている。"}, {"text": "に", "is_correct": false, "explanation": "「試みた」の後に「に」を続けると文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「試みた」の後に「で」を続けると文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「試みた」に続けて逆接の「が」で後文とつながり、「すぐに見つかった」と結ぶ。", "を": "「試みた」の後に目的語の「を」は続かない。「脱走を」の「を」は別の語に付いている。", "に": "「試みた」の後に「に」を続けると文が成り立たない。", "で": "「試みた」の後に「で」を続けると文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "格の不一致", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36127, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「描こうと」の形で意志形に付き、「試みた」につながる。"}, {"text": "へ", "is_correct": false, "explanation": "「描こうへ」の形は成り立たず、「試みた」とつながらない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞に続けるもので、意志形「描こう」の後には付かない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す語で、「描こう」と「試みた」の間には入らない。"}], "correct_answer": "と", "explanations": {"と": "「描こうと」の形で意志形に付き、「試みた」につながる。", "へ": "「描こうへ」の形は成り立たず、「試みた」とつながらない。", "の": "「の」は名詞に続けるもので、意志形「描こう」の後には付かない。", "より": "「より」は比較を表す語で、「描こう」と「試みた」の間には入らない。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36127, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事がうまくいくかどうか、実際にやってみること。", "primary_collocate": null, "pronunciation": "こころみる", "ipa": "kokoɾomiɾɯ", "syllable_count": 5, "sentences": [{"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "試みる", "complexity_tier": "T5", "furigana": "指先(ゆびさき)を通(つう)じて伝(つた)わる生地(きじ)の微妙(びみょう)な弾力(だんりょく)や発酵(はっこう)の進行具合(しんこうぐあい)を唯一(ゆいいつ)の羅針盤(らしんばん)とし、彼(かれ)は温度(おんど)と湿度(しつど)という変数(へんすう)を緻密(ちみつ)に制御(せいぎょ)することで、微生物(びせいぶつ)という目(め)に見(み)えぬパートナーとの静(しず)かなる対話(たいわ)を試(こころ)みる。", "sentence_source": "mined"}, {"text": "囚人は夜のうちに壁を越えて脱走を試みたが、すぐに見つかった。", "target_word": "試みた", "complexity_tier": "T4", "furigana": "囚人(しゅうじん)は夜(よる)のうちに壁(かべ)を越(こ)えて脱走(だっそう)を試(こころ)みたが、すぐに見(み)つかった。", "sentence_source": "generated"}, {"text": "彼女は新しい方法で、傷んだ畑の土を元に戻そうと試みた。", "target_word": "試みた", "complexity_tier": "T4", "furigana": "彼女(かのじょ)は新(あたら)しい方法(ほうほう)で、傷(いた)んだ畑(はたけ)の土(つち)を元(もと)に戻(もど)そうと試(こころ)みた。", "sentence_source": "generated"}, {"text": "会社は値下げによって売り上げを伸ばそうと試みている。", "target_word": "試みている", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は値下(ねさ)げによって売(う)り上(あ)げを伸(の)ばそうと試(こころ)みている。", "sentence_source": "generated"}, {"text": "彼は何度も説得を試みたが、父の考えは変わらなかった。", "target_word": "試みた", "complexity_tier": "T3", "furigana": "彼(かれ)は何度(なんど)も説得(せっとく)を試(こころ)みたが、父(ちち)の考(かんが)えは変(か)わらなかった。", "sentence_source": "generated"}, {"text": "山の頂上まで登ることを試みたものの、天候が悪くて引き返した。", "target_word": "試みた", "complexity_tier": "T4", "furigana": "山(やま)の頂上(ちょうじょう)まで登(のぼ)ることを試(こころ)みたものの、天候(てんこう)が悪(わる)くて引(ひ)き返(かえ)した。", "sentence_source": "generated"}, {"text": "研究チームは、実験で新しい薬の効果を確かめようと試みる。", "target_word": "試みる", "complexity_tier": "T4", "furigana": "研究(けんきゅう)チームは、実験(じっけん)で新(あたら)しい薬(くすり)の効果(こうか)を確(たし)かめようと試(こころ)みる。", "sentence_source": "generated"}, {"text": "私は古い写真を使って、祖父の若いころの町を絵に描こうと試みた。", "target_word": "試みた", "complexity_tier": "T4", "furigana": "私(わたし)は古(ふる)い写真(しゃしん)を使(つか)って、祖父(そふ)の若(わか)いころの町(まち)を絵(え)に描(か)こうと試(こころ)みた。", "sentence_source": "generated"}, {"text": "彼らは交渉を試みて、ようやく停戦に同意させた。", "target_word": "試みて", "complexity_tier": "T4", "furigana": "彼(かれ)らは交渉(こうしょう)を試(こころ)みて、ようやく停戦(ていせん)に同意(どうい)させた。", "sentence_source": "generated"}, {"text": "弟は逆立ちで歩くことを試みたが、三歩で倒れてしまった。", "target_word": "試みた", "complexity_tier": "T3", "furigana": "弟(おとうと)は逆立(さかだ)ちで歩(ある)くことを試(こころ)みたが、三歩(さんぽ)で倒(たお)れてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試みる", "label": "終止形"}, {"form": "試みた", "label": "過去形"}, {"form": "試みて", "label": "て形"}, {"form": "試みない", "label": "否定形"}, {"form": "試みよう", "label": "意志形"}, {"form": "試みれば", "label": "仮定形"}], "register": "やや硬い", "sense_fingerprint": "うまくいくか確かめるために実際にやってみる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36127, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試みる", "is_correct": true, "explanation": "終止形。「対話を試みる。」と文末で言い切れるので、ここに入る。"}, {"text": "試みて", "is_correct": false, "explanation": "て形は文を終えられず、「。」の前に置くと文が成り立たない。"}, {"text": "試みれば", "is_correct": false, "explanation": "仮定形は「試みれば、〜」と続く条件節になり、文末には立たない。"}, {"text": "試みたら", "is_correct": false, "explanation": "たら形は後ろに主節が続く条件節なので、文末の「。」の前には置けない。"}], "explanations": {"試みる": "終止形。「対話を試みる。」と文末で言い切れるので、ここに入る。", "試みて": "て形は文を終えられず、「。」の前に置くと文が成り立たない。", "試みれば": "仮定形は「試みれば、〜」と続く条件節になり、文末には立たない。", "試みたら": "たら形は後ろに主節が続く条件節なので、文末の「。」の前には置けない。"}, "sentence_index": 0, "correct_answer": "試みる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は来年、世界王者を試みるつもりだ。", "explanation": "ここは〈目指す〉の意味。タイトルを目標にする時は目指すを使う。試みるは成否を確かめる行為で、タイトルを対象にはしない。"}, {"text": "会社は毎週月曜に定例会議を試みている。", "explanation": "ここは〈行う〉の意味。決まって行う定例の行事は行うを使う。試みるは成否がまだ分からないことに取り組む時に使う。"}, {"text": "お客さんは新しい靴を試みてから、買うかどうか決めた。", "explanation": "ここは〈試す〉の意味。身につけて使い心地を確かめるなら試すを使う。試みるはこの場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36127, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試みる", "is_correct": true, "explanation": "終止形。「〜ようと試みる。」と文末で言い切れるので、ここに入る。"}, {"text": "試みながら", "is_correct": false, "explanation": "ながら形は同時の動作を表し、文末に置くと文が成り立たない。"}, {"text": "試みず", "is_correct": false, "explanation": "文語の否定の形で、文末に置くと文が終わらない。"}, {"text": "試みなくて", "is_correct": false, "explanation": "て形の否定で、後ろに文が続く形なので文末には立たない。"}], "explanations": {"試みる": "終止形。「〜ようと試みる。」と文末で言い切れるので、ここに入る。", "試みながら": "ながら形は同時の動作を表し、文末に置くと文が成り立たない。", "試みず": "文語の否定の形で、文末に置くと文が終わらない。", "試みなくて": "て形の否定で、後ろに文が続く形なので文末には立たない。"}, "sentence_index": 6, "correct_answer": "試みる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お客さんは新作のスイーツを試みて、満足そうに笑った。", "explanation": "ここは〈味わう〉の意味。食べ物の味を楽しむ時は味わうを使う。試みるはこの場面では使わない。"}, {"text": "彼は初めて主役を試みた。", "explanation": "ここは〈演じる〉の意味。役を演じる時は演じるを使う。試みるは役を務めることには使わない。"}, {"text": "彼は会社の重責を試みている。", "explanation": "ここは〈担う〉の意味。責任や役割を引き受けて持つ時は担うを使う。試みるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36127, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は新しいやり方に試みたが、結果は同じだった。", "corrected_sentence": "彼は新しいやり方を試みたが、結果は同じだった。", "error_description": "目的語の助詞が誤り。「試みる」は目的語を「を」で示すので「に」は誤り。正しくは「やり方を試みた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "試みた", "is_correct": true, "explanation": "過去形。実際に行われた一回の行為を表し、文の内容に合う。"}, {"text": "試みられた", "is_correct": false, "explanation": "受身形。「囚人は脱走を試みられた」は「を」の目的語を受身の主語にできず、文が成り立たない。"}, {"text": "試みて", "is_correct": false, "explanation": "て形は順接でつながるため、「〜たが」の逆接の文脈に合わない。"}, {"text": "試みれば", "is_correct": false, "explanation": "仮定形は「〜すれば」の条件を表し、実際にあった出来事の叙述にはならない。"}], "correct_form": "試みた", "base_form": "試みる", "form_label": "過去形", "sentence_index": 1, "explanations": {"試みた": "過去形。実際に行われた一回の行為を表し、文の内容に合う。", "試みられた": "受身形。「囚人は脱走を試みられた」は「を」の目的語を受身の主語にできず、文が成り立たない。", "試みて": "て形は順接でつながるため、「〜たが」の逆接の文脈に合わない。", "試みれば": "仮定形は「〜すれば」の条件を表し、実際にあった出来事の叙述にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36127, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は新しい方法を試みしたが、失敗した。", "corrected_sentence": "彼は新しい方法を試みたが、失敗した。", "error_description": "活用形が誤り。「試みる」の過去形は「試みた」で、「試みし」は活用として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "試みた", "is_correct": true, "explanation": "過去形。一回きりの行為を表し、文の内容に合う。"}, {"text": "試みない", "is_correct": false, "explanation": "否定形。描こうとした事実を否定することになり、文の内容と反対になる。"}, {"text": "試みよう", "is_correct": false, "explanation": "意志形はこれからの意思を表し、既に行った過去の行為を表せない。"}, {"text": "試みている", "is_correct": false, "explanation": "〜ている形は継続や進行を表し、完了した一回の行為を表す形ではない。"}], "correct_form": "試みた", "base_form": "試みる", "form_label": "過去形", "sentence_index": 7, "explanations": {"試みた": "過去形。一回きりの行為を表し、文の内容に合う。", "試みない": "否定形。描こうとした事実を否定することになり、文の内容と反対になる。", "試みよう": "意志形はこれからの意思を表し、既に行った過去の行為を表せない。", "試みている": "〜ている形は継続や進行を表し、完了した一回の行為を表す形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36129, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抽象", "is_correct": true, "explanation": "「具体」の対で、はっきりした形のない、頭の中だけの性質を表す。"}, {"text": "安全", "is_correct": false, "explanation": "危険がないことで、「具体」とは対の関係にない。"}, {"text": "正確", "is_correct": false, "explanation": "間違いがないことで、「具体」の反対ではない。"}, {"text": "有名", "is_correct": false, "explanation": "広く知られていることで、「具体」とは関係がない。"}], "correct_answer": "抽象", "explanations": {"抽象": "「具体」の対で、はっきりした形のない、頭の中だけの性質を表す。", "安全": "危険がないことで、「具体」とは対の関係にない。", "正確": "間違いがないことで、「具体」の反対ではない。", "有名": "広く知られていることで、「具体」とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36129, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抽象", "is_correct": true, "explanation": "「具体」の対で、数字のようなはっきりした内容がないこと。"}, {"text": "重要", "is_correct": false, "explanation": "大切なことで、「具体」とは対の関係にない。"}, {"text": "自然", "is_correct": false, "explanation": "人の手が加わらないことで、「具体」の反対ではない。"}, {"text": "簡単", "is_correct": false, "explanation": "やさしいことで、「具体」とは関係がない。"}], "correct_answer": "抽象", "explanations": {"抽象": "「具体」の対で、数字のようなはっきりした内容がないこと。", "重要": "大切なことで、「具体」とは対の関係にない。", "自然": "人の手が加わらないことで、「具体」の反対ではない。", "簡単": "やさしいことで、「具体」とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36129, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事が、はっきりした形や内容をそなえていること。「抽象」の対。", "primary_collocate": null, "pronunciation": "ぐたい", "ipa": "ɡɯtai", "syllable_count": 3, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "具体", "complexity_tier": "T6", "furigana": "具体的[ぐたいてき]には、無垢材[むくざい]の家具[かぐ]と白壁[しろかべ]の組[く]み合[あ]わせ、あるいは間接照明[かんせつしょうめい]による陰影[いんえい]の演出[えんしゅつ]などが効果的[こうかてき]です。", "sentence_source": "mined"}, {"text": "具体的に説明します。", "target_word": "具体的に", "complexity_tier": "T2", "furigana": "具体的[ぐたいてき]に説明[せつめい]します。", "sentence_source": "generated"}, {"text": "具体的な例を見せて。", "target_word": "具体的な", "complexity_tier": "T2", "furigana": "具体的[ぐたいてき]な例[れい]を見[み]せて。", "sentence_source": "generated"}, {"text": "話が具体的で、とてもわかりやすい。", "target_word": "具体的で", "complexity_tier": "T3", "furigana": "話[はなし]が具体的[ぐたいてき]で、とてもわかりやすい。", "sentence_source": "generated"}, {"text": "抽象と具体を分けて考える。", "target_word": "具体", "complexity_tier": "T3", "furigana": "抽象[ちゅうしょう]と具体[ぐたい]を分[わ]けて考[かんが]える。", "sentence_source": "generated"}, {"text": "考えを具体的にして、図に書いた。", "target_word": "具体的に", "complexity_tier": "T3", "furigana": "考[かんが]えを具体的[ぐたいてき]にして、図[ず]に書[か]いた。", "sentence_source": "generated"}, {"text": "もっと具体的に書けば、読む人も迷わない。", "target_word": "具体的に", "complexity_tier": "T4", "furigana": "もっと具体的[ぐたいてき]に書[か]けば、読[よ]む人[ひと]も迷[まよ]わない。", "sentence_source": "generated"}, {"text": "具体的でない答えでは、困ります。", "target_word": "具体的で", "complexity_tier": "T3", "furigana": "具体的[ぐたいてき]でない答[こた]えでは、困[こま]ります。", "sentence_source": "generated"}, {"text": "抽象より具体のほうが覚えやすい。", "target_word": "具体", "complexity_tier": "T3", "furigana": "抽象[ちゅうしょう]より具体[ぐたい]のほうが覚[おぼ]えやすい。", "sentence_source": "generated"}, {"text": "具体的な数字を出されて、納得した。", "target_word": "具体的な", "complexity_tier": "T4", "furigana": "具体的[ぐたいてき]な数字[すうじ]を出[だ]されて、納得[なっとく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "具体的", "label": "派生"}, {"form": "具体化", "label": "派生"}, {"form": "具体例", "label": "派生"}, {"form": "具体性", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | はっきりした形や内容があること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36129, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "具体", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "舞台", "is_correct": false, "explanation": "ぶたい。ぐ→ぶの一音だけが違う別語。"}, {"text": "擬態", "is_correct": false, "explanation": "ぎたい。ぐ→ぎの一音だけが違う別語。"}, {"text": "固体", "is_correct": false, "explanation": "こたい。ぐ→この一音だけが違う別語。"}, {"text": "具合", "is_correct": false, "explanation": "ぐあい。た→あの一音だけが違う別語。"}], "explanations": {"具体": "見出し語そのもの。", "舞台": "ぶたい。ぐ→ぶの一音だけが違う別語。", "擬態": "ぎたい。ぐ→ぎの一音だけが違う別語。", "固体": "こたい。ぐ→この一音だけが違う別語。", "具合": "ぐあい。た→あの一音だけが違う別語。"}, "sentence_index": null, "correct_answer": "具体"}, "level_3": {"options": [{"text": "具体", "is_correct": true, "explanation": "「具体的には」で「詳しく言うと」の意味になり、後の例の挙げ方に合う。"}, {"text": "消極", "is_correct": false, "explanation": "形は合うが、「消極的には」では例を挙げる文脈に意味が合わない。"}, {"text": "偶発", "is_correct": false, "explanation": "形は合うが、「偶発的には」では例を示す意味にならない。"}, {"text": "悲観", "is_correct": false, "explanation": "形は合うが、「悲観的には」では効果的な例を挙げる流れに合わない。"}], "explanations": {"具体": "「具体的には」で「詳しく言うと」の意味になり、後の例の挙げ方に合う。", "消極": "形は合うが、「消極的には」では例を挙げる文脈に意味が合わない。", "偶発": "形は合うが、「偶発的には」では例を示す意味にならない。", "悲観": "形は合うが、「悲観的には」では効果的な例を挙げる流れに合わない。"}, "sentence_index": 0, "correct_answer": "具体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夕食は具体的で、とてもおいしかった。", "explanation": "「具体的」は内容がはっきりしている意味で、味の良さを表すのには使えない。"}, {"text": "彼は具体的な人で、いつも大声で笑う。", "explanation": "「具体的」は人の明るい性格を表さない。話や内容の明確さを表す語。"}, {"text": "具体的に雨が降って、道がぬれた。", "explanation": "「具体的に」は「本当に」「たくさん」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
