INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36130, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵や文字をかいて作った作品。", "primary_collocate": null, "pronunciation": "ぐらふぃっく", "ipa": "ɡɯɾaɸiQkɯ", "syllable_count": 5, "sentences": [{"text": "これはグラフィックです。", "target_word": "グラフィック", "complexity_tier": "T2", "furigana": "これはグラフィックです。", "sentence_source": "generated"}, {"text": "グラフィックは、絵や文字の作品です。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "グラフィックは、絵[え]や文字[もじ]の作品[さくひん]です。", "sentence_source": "generated"}, {"text": "姉はグラフィックを学んでいます。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "姉[あね]はグラフィックを学[まな]んでいます。", "sentence_source": "generated"}, {"text": "壁に大きなグラフィックを描いた。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "壁[かべ]に大[おお]きなグラフィックを描[えが]いた。", "sentence_source": "generated"}, {"text": "文字の形がおもしろいグラフィックを見つけた。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "文字[もじ]の形[かたち]がおもしろいグラフィックを見[み]つけた。", "sentence_source": "generated"}, {"text": "グラフィックのポスターが、店の前にはってある。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "グラフィックのポスターが、店[みせ]の前[まえ]にはってある。", "sentence_source": "generated"}, {"text": "このグラフィックには、動物が三びきいる。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "このグラフィックには、動物[どうぶつ]が三[さん]びきいる。", "sentence_source": "generated"}, {"text": "色づかいがきれいなグラフィックですね。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "色[いろ]づかいがきれいなグラフィックですね。", "sentence_source": "generated"}, {"text": "グラフィックを作るために、新しいソフトを買った。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "グラフィックを作[つく]るために、新[あたら]しいソフトを買[か]った。", "sentence_source": "generated"}, {"text": "グラフィックが好きで、毎日ノートに絵を描いている。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "グラフィックが好[す]きで、毎日[まいにち]ノートに絵[え]を描[か]いている。", "sentence_source": "generated"}], "morpho