INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36130, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "グラフィック", "is_correct": true, "explanation": "見出し語そのもので、音が一致する。"}, {"text": "トラフィック", "is_correct": false, "explanation": "最初の「ぐ」が「と」に変わった別の語で、1拍だけが違う。"}, {"text": "グラフィティ", "is_correct": false, "explanation": "「ぐらふぃてぃ」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}, {"text": "ドラスティック", "is_correct": false, "explanation": "「どらすてぃっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}, {"text": "ロマンチック", "is_correct": false, "explanation": "「ろまんちっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}], "explanations": {"グラフィック": "見出し語そのもので、音が一致する。", "トラフィック": "最初の「ぐ」が「と」に変わった別の語で、1拍だけが違う。", "グラフィティ": "「ぐらふぃてぃ」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。", "ドラスティック": "「どらすてぃっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。", "ロマンチック": "「ろまんちっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}, "sentence_index": null, "correct_answer": "グラフィック"}, "level_3": {"options": [{"text": "グラフィック", "is_correct": true, "explanation": "「これは○○です」と絵や文字の作品を示すのに合う。"}, {"text": "来週", "is_correct": false, "explanation": "形は合うが、これが来週だという意味が合わない。"}, {"text": "午後", "is_correct": false, "explanation": "形は合うが、これが午後だという意味が合わない。"}, {"text": "今朝", "is_correct": false, "explanation": "形は合うが、これが今朝だという意味が合わない。"}], "explanations": {"グラフィック": "「これは○○です」と絵や文字の作品を示すのに合う。", "来週": "形は合うが、これが来週だという意味が合わない。", "午後": "形は合うが、これが午後だという意味が合わない。", "今朝": "形は合うが、これが今朝だという意味が合わない。"}, "sentence_index": 0, "correct_answer": "グラフィック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昼ごはんに、熱いグラフィックを食べた。", "explanation": "グラフィックは絵や文字を描いたものなので、食べ物ではなく「食べる」と合わない。"}, {"text": "グラフィックは、毎日駅から学校まで走っている。", "explanation": "グラフィックは作品であって、自分で走るものではない。"}, {"text": "雨のとき、グラフィックを頭にさして歩いた。", "explanation": "グラフィックは絵や文字を描いたものなので、傘のようにさして使うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONF