INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36131, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "視覚的に表現された図形や画像、またはコンピュータで扱われる画像全般を指す語。", "primary_collocate": null, "pronunciation": "ぐらふぃっく", "ipa": "ɡɯɾaɸiQkɯ", "syllable_count": 5, "sentences": [{"text": "彼が描いたのは、見慣れた商店街のグラフィックでした。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "彼[かれ]が描[えが]いたのは、見慣[みな]れた商店街[しょうてんがい]のグラフィックでした。", "sentence_source": "mined"}, {"text": "このグラフィックは、とてもきれいです。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "このグラフィックは、とてもきれいです。", "sentence_source": "generated"}, {"text": "彼はグラフィックの仕事をしている。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "彼[かれ]はグラフィックの仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "ポスターのグラフィックを新しくした。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "ポスターのグラフィックを新[あたら]しくした。", "sentence_source": "generated"}, {"text": "グラフィックが多いと、本が読みやすい。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "グラフィックが多[おお]いと、本[ほん]が読[よ]みやすい。", "sentence_source": "generated"}, {"text": "コンピュータのグラフィックは、年々よくなっている。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "コンピュータのグラフィックは、年々[ねんねん]よくなっている。", "sentence_source": "generated"}, {"text": "ゲームのグラフィックに、子どもたちは驚いた。", "target_word": "グラフィック", "complexity_tier": "T3", "furigana": "ゲームのグラフィックに、子[こ]どもたちは驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "この雑誌は、文章よりグラフィックを大切にしている。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "この雑誌[ざっし]は、文章[ぶんしょう]よりグラフィックを大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "グラフィックで説明すれば、誰でも分かりやすい。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "グラフィックで説明[せつめい]すれば、誰[だれ]でも分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "駅の壁にある大きなグラフィックを写真に撮った。", "target_word": "グラフィック", "complexity_tier": "T4", "furigana": "駅[えき]の壁[かべ]にある大[おお]きなグラフィックを写真[しゃしん]に撮[と]った。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 視覚的な図形や画像全般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36131, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "グラフィック", "is_correct": true, "explanation": "見出し語そのもので、音が一致する。"}, {"text": "トラフィック", "is_correct": false, "explanation": "最初の「ぐ」が「と」に変わった別の語で、1拍だけが違う。"}, {"text": "グラフィティ", "is_correct": false, "explanation": "「ぐらふぃてぃ」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}, {"text": "ドラスティック", "is_correct": false, "explanation": "「どらすてぃっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}, {"text": "ロマンチック", "is_correct": false, "explanation": "「ろまんちっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}], "explanations": {"グラフィック": "見出し語そのもので、音が一致する。", "トラフィック": "最初の「ぐ」が「と」に変わった別の語で、1拍だけが違う。", "グラフィティ": "「ぐらふぃてぃ」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。", "ドラスティック": "「どらすてぃっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。", "ロマンチック": "「ろまんちっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}, "sentence_index": null, "correct_answer": "グラフィック"}, "level_3": {"options": [{"text": "グラフィック", "is_correct": true, "explanation": "彼が描いたものとして、図や画像の意味が文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気を描いたという意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、約束を描いたという意味が合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、商店街の値段を描いたという意味が合わない。"}], "explanations": {"グラフィック": "彼が描いたものとして、図や画像の意味が文に合う。", "天気": "形は合うが、天気を描いたという意味が合わない。", "約束": "形は合うが、約束を描いたという意味が合わない。", "値段": "形は合うが、商店街の値段を描いたという意味が合わない。"}, "sentence_index": 0, "correct_answer": "グラフィック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重いグラフィックを食べたので、お腹がいっぱいだ。", "explanation": "グラフィックは図や画像のことで食べ物ではないので、「食べる」と合わない。"}, {"text": "グラフィックを歩いて、駅まで行った。", "explanation": "グラフィックは図や画像なので、道のように「歩く」場所にはならない。"}, {"text": "友達のグラフィックは、毎朝ジョギングしている。", "explanation": "グラフィックは人ではなく画像なので、「ジョギングする」の主語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36131, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "グラフィック", "is_correct": true, "explanation": "見出し語そのもので、音が一致する。"}, {"text": "トラフィック", "is_correct": false, "explanation": "最初の「ぐ」が「と」に変わった別の語で、1拍だけが違う。"}, {"text": "グラフィカル", "is_correct": false, "explanation": "「ぐらふぃかる」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}, {"text": "ドラマチック", "is_correct": false, "explanation": "「どらまちっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。"}, {"text": "グラフ", "is_correct": false, "explanation": "「ぐらふ」は別の語で、見出し語の前半と同じ音を持つ。"}], "explanations": {"グラフィック": "見出し語そのもので、音が一致する。", "トラフィック": "最初の「ぐ」が「と」に変わった別の語で、1拍だけが違う。", "グラフィカル": "「ぐらふぃかる」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。", "ドラマチック": "「どらまちっく」は別の語。1拍違いの実在語が少ないため、近い音の語で代用している。", "グラフ": "「ぐらふ」は別の語で、見出し語の前半と同じ音を持つ。"}, "sentence_index": null, "correct_answer": "グラフィック"}, "level_3": {"options": [{"text": "グラフィック", "is_correct": true, "explanation": "子どもたちが驚いた対象として、ゲームの画像が文に合う。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、ゲームの季節に驚くという意味が合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、ゲームの洗濯に驚くという意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、ゲームの辞書に驚くという意味が合わない。"}], "explanations": {"グラフィック": "子どもたちが驚いた対象として、ゲームの画像が文に合う。", "季節": "形は合うが、ゲームの季節に驚くという意味が合わない。", "洗濯": "形は合うが、ゲームの洗濯に驚くという意味が合わない。", "辞書": "形は合うが、ゲームの辞書に驚くという意味が合わない。"}, "sentence_index": 6, "correct_answer": "グラフィック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪を引いたので、グラフィックを飲んで寝た。", "explanation": "グラフィックは図や画像なので、薬のように「飲む」ものではない。"}, {"text": "弟はグラフィックに乗って、学校へ行った。", "explanation": "グラフィックは乗り物ではないので、「乗る」と合わない。"}, {"text": "このグラフィックは、とても大きな声で笑っている。", "explanation": "グラフィックは画像であって、声を出して笑う主体ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36131, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅のポスターは、グラフィックに美しい。", "corrected_sentence": "駅のポスターは、グラフィックが美しい。", "error_description": "「美しい」の主語を表すのに「グラフィックに」と「に」を使っているのが誤りで、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36131, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい映画のグラフィックを驚いた。", "corrected_sentence": "新しい映画のグラフィックに驚いた。", "error_description": "「驚く」の対象には「グラフィックに」と「に」を使うべきなのに、「を」を使っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36132, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「スコアが私より」の「が」。「高かった」の主語を示し、「AがBより高い」の形で文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「スコアを私より高かった」は対象の形になり、「高かった」の主語にならず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「スコアに私より」は文が続かず、比較の文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「スコアと私より」は並列にも比較にもならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「スコアが私より」の「が」。「高かった」の主語を示し、「AがBより高い」の形で文が成り立つ。", "を": "「スコアを私より高かった」は対象の形になり、「高かった」の主語にならず不自然。", "に": "「スコアに私より」は文が続かず、比較の文として成り立たない。", "と": "「スコアと私より」は並列にも比較にもならず、文が成り立たない。"}, "error_tags": {"を": "対象", "に": "位置・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
