INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36132, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ゲームなどで、とくてんのこと。", "primary_collocate": null, "pronunciation": "すこあ", "ipa": "sɯkoa", "syllable_count": 3, "sentences": [{"text": "このゲームは、スコアが高いほど強いキャラクターが使えます。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "このゲームは、スコアが高[たか]いほど強[つよ]いキャラクターが使[つか]えます。", "sentence_source": "generated"}, {"text": "昨夜のゲームでは、弟のスコアが私より少し高かった。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "昨夜[さくや]のゲームでは、弟[おとうと]のスコアが私[わたし]より少[すこ]し高[たか]かった。", "sentence_source": "generated"}, {"text": "スコアが千点を超えたので、次のステージに進めた。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "スコアが千[せん]点[てん]を超[こ]えたので、次[つぎ]のステージに進[すす]めた。", "sentence_source": "generated"}, {"text": "友だちと同じゲームで、スコアを比べて遊んだ。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "友[とも]だちと同[おな]じゲームで、スコアを比[くら]べて遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "最後に失敗して、せっかくのスコアが半分になってしまった。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "最後[さいご]に失敗[しっぱい]して、せっかくのスコアが半分[はんぶん]になってしまった。", "sentence_source": "generated"}, {"text": "ゲームが終わると、画面にスコアが出ます。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "ゲームが終[お]わると、画面[がめん]にスコアが出[で]ます。", "sentence_source": "generated"}, {"text": "彼女はいつもスコアを気にしながらゲームをする。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はいつもスコアを気[き]にしながらゲームをする。", "sentence_source": "generated"}, {"text": "練習したので、前よりスコアがずっとよくなった。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "練習[れんしゅう]したので、前[まえ]よりスコアがずっとよくなった。", "sentence_source": "generated"}, {"text": "スコアが低かったから、もう一度挑戦することにした。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "スコアが低[ひく]かったから、もう一度[いちど]挑戦[ちょうせん]することにした。", "sentence_source": "generated"}, {"text": "このゲームでは、敵を倒すとスコアが増えます。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "このゲームでは、敵[てき]を倒[たお]すとスコアが増[ふ]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スコア", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ゲームで得る得点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36132, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スコア", "is_correct": true, "explanation": "「スコアが高いほど」は、ゲームの得点が高いほど強いキャラクターが使えるという文脈に合う。"}, {"text": "ゲーム", "is_correct": false, "explanation": "「ゲームが高いほど」は意味をなさず、文脈の得点の話とも合わない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温が高いほど強いキャラクターが使えます」はゲームの話として成り立たず、文脈に合わない。"}, {"text": "キャラクター", "is_correct": false, "explanation": "「キャラクターが高いほど強いキャラクター」となり、文の主語として不自然で文脈にも合わない。"}], "explanations": {"スコア": "「スコアが高いほど」は、ゲームの得点が高いほど強いキャラクターが使えるという文脈に合う。", "ゲーム": "「ゲームが高いほど」は意味をなさず、文脈の得点の話とも合わない。", "体温": "「体温が高いほど強いキャラクターが使えます」はゲームの話として成り立たず、文脈に合わない。", "キャラクター": "「キャラクターが高いほど強いキャラクター」となり、文の主語として不自然で文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "スコア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は毎朝、スコアを体温計で確かめている。", "explanation": "ここは〈体温〉の意味。体温は体温計で確かめるが、ゲームの得点は体温計では確かめられないので合わない。"}, {"text": "週末にスコアを分別して、ごみに出した。", "explanation": "ここは〈ごみ〉の意味。ごみは分別して出すが、得点は分別するものではないので合わない。"}, {"text": "彼は毎朝、スコアを血圧計で測っている。", "explanation": "ここは〈血圧〉の意味。血圧は血圧計で測るが、ゲームの得点は血圧計では測らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36132, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スコア", "is_correct": true, "explanation": "「スコアを気にしながら」は、ゲームの得点を気にする文脈に合う。"}, {"text": "お湯", "is_correct": false, "explanation": "「お湯を気にしながら」はゲームの話の流れと無関係で、文脈に合わない。"}, {"text": "カレー", "is_correct": false, "explanation": "「カレーを気にしながらゲームをする」は文脈と無関係で、意味が通らない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "「ハンカチを気にしながらゲームをする」はゲームとの関係が薄く、文脈に合わない。"}], "explanations": {"スコア": "「スコアを気にしながら」は、ゲームの得点を気にする文脈に合う。", "お湯": "「お湯を気にしながら」はゲームの話の流れと無関係で、文脈に合わない。", "カレー": "「カレーを気にしながらゲームをする」は文脈と無関係で、意味が通らない。", "ハンカチ": "「ハンカチを気にしながらゲームをする」はゲームとの関係が薄く、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "スコア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このゲームでは、敵に当たるとスコアを受ける。", "explanation": "ここは〈ダメージ〉の意味。敵に当たって受けるのは体力への損害で、得点は「受ける」ものではない。"}, {"text": "ゲーム機を買って、スコアを払った。", "explanation": "ここは〈料金〉の意味。代金は払うが、得点は払うものではないので合わない。"}, {"text": "毎朝、スコアを炊飯器で炊いた。", "explanation": "ここは〈米〉の意味。米は炊飯器で炊くが、得点は炊けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36132, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ステージをクリアして、スコアを千点を超えた。", "corrected_sentence": "ステージをクリアして、スコアが千点を超えた。", "error_description": "「スコアを」は誤り。「超える」の主語は「スコア」なので「が」を使い、「スコアが千点を超えた」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36132, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゲームが終わると、画面にスコアが表示ます。", "corrected_sentence": "ゲームが終わると、画面にスコアが表示されます。", "error_description": "「表示ます」は誤り。「表示する」は「表示し」に「ます」が続く形なので、受け身の「表示されます」とすれば文として成り立つ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36133, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「スコアを取る」の「を」。「取る」の目的語を示し、文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「スコアが取る」は主語になり、「取る」の目的語として成り立たず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「スコアに取る」は文が続かず、目的語を示す形として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「スコアへ取る」は方向を表し、「取る」の目的語にはならず意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「スコアを取る」の「を」。「取る」の目的語を示し、文が成り立つ。", "が": "「スコアが取る」は主語になり、「取る」の目的語として成り立たず不自然。", "に": "「スコアに取る」は文が続かず、目的語を示す形として成り立たない。", "へ": "「スコアへ取る」は方向を表し、「取る」の目的語にはならず意味が通らない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36133, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「スコアを表にまとめた」の「を」。「まとめる」の目的語を示し、文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「スコアが表にまとめた」は主語になり、「まとめた」の目的語として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「表へまとめた」は方向を表し、「まとめる」の対象を示さないので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、「スコアより表にまとめた」は比較の文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「スコアを表にまとめた」の「を」。「まとめる」の目的語を示し、文が成り立つ。", "が": "「スコアが表にまとめた」は主語になり、「まとめた」の目的語として不自然。", "へ": "「表へまとめた」は方向を表し、「まとめる」の対象を示さないので不自然。", "より": "「より」は比較を表すが、「スコアより表にまとめた」は比較の文として成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36133, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "競技や試験などで得た点数や評点。", "primary_collocate": null, "pronunciation": "すこあ", "ipa": "sɯkoa", "syllable_count": 3, "sentences": [{"text": "試験のスコアが基準に届かず、もう一度受けることになった。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "試験[しけん]のスコアが基準[きじゅん]に届[とど]かず、もう一度[いちど]受[う]けることになった。", "sentence_source": "generated"}, {"text": "英語のテストで、いいスコアを取るために毎日勉強している。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "英語[えいご]のテストで、いいスコアを取[と]るために毎日[まいにち]勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "彼は大会で、自己ベストのスコアを出した。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "彼[かれ]は大会[たいかい]で、自己[じこ]ベストのスコアを出[だ]した。", "sentence_source": "generated"}, {"text": "二人のスコアは同じだったので、もう一度競うことになった。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "二人[ふたり]のスコアは同[おな]じだったので、もう一度[いちど]競[きそ]うことになった。", "sentence_source": "generated"}, {"text": "ゴルフではスコアが少ないほうが勝ちです。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "ゴルフではスコアが少[すく]ないほうが勝[か]ちです。", "sentence_source": "generated"}, {"text": "入学にはTOEICのスコアが必要です。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "入学[にゅうがく]にはTOEICのスコアが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "試合のスコアは三対二で、私たちのチームが勝った。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "試合[しあい]のスコアは三対[さんたい]二[に]で、私[わたし]たちのチームが勝[か]った。", "sentence_source": "generated"}, {"text": "先生は生徒のスコアを表にまとめた。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]のスコアを表[ひょう]にまとめた。", "sentence_source": "generated"}, {"text": "前回よりスコアが上がって、母もとても喜んだ。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "前回[ぜんかい]よりスコアが上[あ]がって、母[はは]もとても喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "スコアが悪くても、あきらめずに次の試合に出た。", "target_word": "スコア", "complexity_tier": "T3", "furigana": "スコアが悪[わる]くても、あきらめずに次[つぎ]の試合[しあい]に出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スコア", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "試験や競技で得る点数・評点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36133, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スコア", "is_correct": true, "explanation": "「試験のスコア」は試験の得点で、基準に届かず再受験になるという文脈に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書が基準に届かず」は成り立たず、試験の点数の文脈に合わない。"}, {"text": "制服", "is_correct": false, "explanation": "「制服が基準に届く」は意味をなさず、試験の話とも合わない。"}, {"text": "座席", "is_correct": false, "explanation": "「座席が基準に届かず」は不自然で、試験の得点の話にならない。"}], "explanations": {"スコア": "「試験のスコア」は試験の得点で、基準に届かず再受験になるという文脈に合う。", "教科書": "「教科書が基準に届かず」は成り立たず、試験の点数の文脈に合わない。", "制服": "「制服が基準に届く」は意味をなさず、試験の話とも合わない。", "座席": "「座席が基準に届かず」は不自然で、試験の得点の話にならない。"}, "sentence_index": 0, "correct_answer": "スコア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店で二人は、同じスコアの靴を選んだ。", "explanation": "ここは〈サイズ〉の意味。靴の大きさは「サイズ」で表し、試験の点数を表すスコアでは言わないので合わない。"}, {"text": "保健室で、先生が二人のスコアを体温計で測った。", "explanation": "ここは〈体温〉の意味。体温計で測るのは体温で、得た点数は測るものではないので合わない。"}, {"text": "受験料を払い、二人はスコアを払った。", "explanation": "ここは〈受験料〉の意味。料金は払うが、試験で得た点数は払うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36133, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スコア", "is_correct": true, "explanation": "「試合のスコアは三対二」は試合の得点を述べる文で、文脈に合う。"}, {"text": "観客", "is_correct": false, "explanation": "「観客は三対二で」は意味をなさず、試合の得点を表す文にならない。"}, {"text": "審判", "is_correct": false, "explanation": "「審判は三対二で」は試合の点数の説明にならず、文が成り立たない。"}, {"text": "会場", "is_correct": false, "explanation": "「会場は三対二で」は点数を述べる文として成り立たず、文脈にも合わない。"}], "explanations": {"スコア": "「試合のスコアは三対二」は試合の得点を述べる文で、文脈に合う。", "観客": "「観客は三対二で」は意味をなさず、試合の得点を表す文にならない。", "審判": "「審判は三対二で」は試合の点数の説明にならず、文が成り立たない。", "会場": "「会場は三対二で」は点数を述べる文として成り立たず、文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "スコア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スコアが降っても、試合は予定どおり行われた。", "explanation": "ここは〈雨〉の意味。雨は降るが、得点は降るものではないので合わない。"}, {"text": "スコアが治らなくて、試合を休んだ。", "explanation": "ここは〈ケガ〉の意味。ケガは治るものだが、得点は治るものではないので合わない。"}, {"text": "スコアを着て次の試合に出た。", "explanation": "ここは〈ユニフォーム〉の意味。ユニフォームは着るものだが、得点は着られないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36133, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英語のテストでスコアを上がり、母が喜んだ。", "corrected_sentence": "英語のテストでスコアが上がり、母が喜んだ。", "error_description": "「スコアを上がり」は誤り。「上がる」は自動詞なので、主語に「が」を使い「スコアが上がり」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36133, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海外の大学には英語のスコアが必要に。", "corrected_sentence": "海外の大学には英語のスコアが必要です。", "error_description": "「必要に」で文が終わっており、続く述語がないので不完全。「必要です」で結ぶのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36135, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ラテンで書く」と、言語を使って書くという手段を表すので入る。"}, {"text": "が", "is_correct": false, "explanation": "「書く」の主語としては不自然で、「ラテンが書く」とは読めない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着先を表し、書く先の場所や対象になりにくいので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、言語は方向を表す対象にならないので合わない。"}], "correct_answer": "で", "explanations": {"で": "「ラテンで書く」と、言語を使って書くという手段を表すので入る。", "が": "「書く」の主語としては不自然で、「ラテンが書く」とは読めない。", "に": "「に」は帰着先を表し、書く先の場所や対象になりにくいので合わない。", "へ": "「へ」は方向を表し、言語は方向を表す対象にならないので合わない。"}, "error_tags": {"が": "主語（「書く」の主語として不自然）", "に": "帰着先（書く先の場所や対象になりにくい）", "へ": "方向（言語は方向を表す対象にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36135, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36135, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ラテン語は、古代ローマで使われていた言語で、現在は学術用語などに用いられる。", "primary_collocate": null, "pronunciation": "らてん", "ipa": "ɾateɴ", "syllable_count": 3, "sentences": [{"text": "学術の世界では、今もラテンが使われている。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "学術[がくじゅつ]の世界[せかい]では、今[いま]もラテンが使[つか]われている。", "sentence_source": "generated"}, {"text": "植物の学名は、ラテンで書くことになっている。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]の学名[がくめい]は、ラテンで書[か]くことになっている。", "sentence_source": "generated"}, {"text": "ラテンは古代ローマの言語で、日常では使われない。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "ラテンは古代[こだい]ローマの言語[げんご]で、日常[にちじょう]では使[つか]われない。", "sentence_source": "generated"}, {"text": "薬の名前にラテンが多いのは、昔からの習慣だからだ。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "薬[くすり]の名前[なまえ]にラテンが多[おお]いのは、昔[むかし]からの習慣[しゅうかん]だからだ。", "sentence_source": "generated"}, {"text": "大学の授業で、ラテンの基本を学んだ。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "大学[だいがく]の授業[じゅぎょう]で、ラテンの基本[きほん]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "法律の用語にも、ラテンから来た言葉がある。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "法律[ほうりつ]の用語[ようご]にも、ラテンから来[き]た言葉[ことば]がある。", "sentence_source": "generated"}, {"text": "病気の名前は、ラテンで表すと世界中の医者に通じる。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "病気[びょうき]の名前[なまえ]は、ラテンで表[あらわ]すと世界[せかい]中[じゅう]の医者[いしゃ]に通[つう]じる。", "sentence_source": "generated"}, {"text": "古い論文を読むために、ラテンを習う学生もいる。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "古[ふる]い論文[ろんぶん]を読[よ]むために、ラテンを習[なら]う学生[がくせい]もいる。", "sentence_source": "generated"}, {"text": "ラテンは現在、話す人が少ないが、学問では大切だ。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "ラテンは現在[げんざい]、話[はな]す人[ひと]が少[すく]ないが、学問[がくもん]では大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "辞書でこの単語を調べると、ラテンから来たと書いてあった。", "target_word": "ラテン", "complexity_tier": "T3", "furigana": "辞書[じしょ]でこの単語[たんご]を調[しら]べると、ラテンから来[き]たと書[か]いてあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ラテン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "古代ローマの言語で、今は学術用語に使われる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36135, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ラテン", "is_correct": true, "explanation": "ここは学術の世界で今も使われる言語を指すので、「ラテン」が入る。"}, {"text": "流行歌", "is_correct": false, "explanation": "大衆向けの歌で、学術の世界で使われるものではないため合わない。"}, {"text": "週刊誌", "is_correct": false, "explanation": "雑誌の一種で、学術の世界の道具としては合わない。"}, {"text": "漫画", "is_correct": false, "explanation": "娯楽の媒体で、学術の世界では使われないため合わない。"}], "explanations": {"ラテン": "ここは学術の世界で今も使われる言語を指すので、「ラテン」が入る。", "流行歌": "大衆向けの歌で、学術の世界で使われるものではないため合わない。", "週刊誌": "雑誌の一種で、学術の世界の道具としては合わない。", "漫画": "娯楽の媒体で、学術の世界では使われないため合わない。"}, "sentence_index": 0, "correct_answer": "ラテン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお祭りは、毎年ラテンに行われる。", "explanation": "ここは〈春〉（季節）の意味。ラテンは言語の名前なので、時期を表す語の代わりにはならない。"}, {"text": "壁をラテンで塗って、部屋を明るくした。", "explanation": "ここは〈ペンキ〉（塗料）の意味。ラテンは言語の名前なので、壁を塗る材料の代わりにはならない。"}, {"text": "けがをして、ラテンで手当てを受けた。", "explanation": "ここは〈病院〉の意味。ラテンは言語の名前なので、治療を受ける場所の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36135, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ラテン", "is_correct": true, "explanation": "ここは医者に通じる表記の言語を指すので、「ラテン」が入る。"}, {"text": "方言", "is_correct": false, "explanation": "地域限定の言葉で、世界中の医者には通じないため合わない。"}, {"text": "暗号", "is_correct": false, "explanation": "秘密の符号で、医者に通じる表記ではないため合わない。"}, {"text": "手話", "is_correct": false, "explanation": "身ぶりによる言語で、医者への病名の表記としては合わない。"}], "explanations": {"ラテン": "ここは医者に通じる表記の言語を指すので、「ラテン」が入る。", "方言": "地域限定の言葉で、世界中の医者には通じないため合わない。", "暗号": "秘密の符号で、医者に通じる表記ではないため合わない。", "手話": "身ぶりによる言語で、医者への病名の表記としては合わない。"}, "sentence_index": 6, "correct_answer": "ラテン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この神殿では、昔からラテンを拝んでいる。", "explanation": "ここは〈神〉の意味。ラテンは言語の名前なので、拝む対象にはならない。"}, {"text": "ラテンは、古代の哲学を伝えた国だ。", "explanation": "ここは〈ギリシャ〉の意味。ラテンは言語の名前なので、古代の哲学を伝えた国としては使えない。"}, {"text": "庭の枝は、ラテンで切り落とした。", "explanation": "ここは〈はさみ〉（道具）の意味。ラテンは言語の名前なので、枝を切る道具の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36135, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医学の用語は、ラテンの書かれていることが多い。", "corrected_sentence": "医学の用語は、ラテンで書かれていることが多い。", "error_description": "正しくは「ラテンで書かれている」。「書かれる」に合う手段の「で」が必要で、「の」では文が続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36135, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い論文は、ラテンが習わないと読めない。", "corrected_sentence": "古い論文は、ラテンを習わないと読めない。", "error_description": "正しくは「ラテンを習う」。「習う」の対象は「を」で示すので、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
