INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36136, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こるかもしれないし、起こらないかもしれないという、その起こりやすさのこと。", "primary_collocate": null, "pronunciation": "かくりつ", "ipa": "kakɯɾitsɯ", "syllable_count": 4, "sentences": [{"text": "明日は雨が降る確率が高いので、傘を持っていこう。", "target_word": "確率", "complexity_tier": "T3", "furigana": "明日[あした]は雨[あめ]が降[ふ]る確率[かくりつ]が高[たか]いので、傘[かさ]を持[も]っていこう。", "sentence_source": "generated"}, {"text": "この方法なら、成功する確率は五割ぐらいだと思う。", "target_word": "確率", "complexity_tier": "T3", "furigana": "この方法[ほうほう]なら、成功[せいこう]する確率[かくりつ]は五割[ごわり]ぐらいだと思[おも]う。", "sentence_source": "generated"}, {"text": "雪の日は、電車が遅れる確率が上がる。", "target_word": "確率", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、電車[でんしゃ]が遅[おく]れる確率[かくりつ]が上[あ]がる。", "sentence_source": "generated"}, {"text": "試合に勝つ確率は低いが、あきらめたくない。", "target_word": "確率", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]つ確率[かくりつ]は低[ひく]いが、あきらめたくない。", "sentence_source": "generated"}, {"text": "早く病院に行けば、病気が治る確率は大きくなる。", "target_word": "確率", "complexity_tier": "T3", "furigana": "早[はや]く病院[びょういん]に行[い]けば、病気[びょうき]が治[なお]る確率[かくりつ]は大[おお]きくなる。", "sentence_source": "generated"}, {"text": "彼が約束を忘れる確率は、ほとんどないだろう。", "target_word": "確率", "complexity_tier": "T3", "furigana": "彼[かれ]が約束[やくそく]を忘[わす]れる確率[かくりつ]は、ほとんどないだろう。", "sentence_source": "generated"}, {"text": "成功する確率が低くても、挑戦する価値はあると思う。", "target_word": "確率", "complexity_tier": "T3", "furigana": "成功[せいこう]する確率[かくりつ]が低[ひく]くても、挑戦[ちょうせん]する価値[かち]はあると思[おも]う。", "sentence_source": "generated"}, {"text": "天気予報では、午後に雨が降る確率は七十パーセントだと言っていた。", "target_word": "確率", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]では、午後[ごご]に雨[あめ]が降[ふ]る確率[かくりつ]は七十[ななじゅう]パーセントだと言[い]っていた。", "sentence_source": "generated"}, {"text": "道が込んでいるので、間に合う確率は半分以下だ。", "target_word": "確率", "complexity_tier": "T3", "furigana": "道[みち]が込[こ]んでいるので、間[ま]に合[あ]う確率[かくりつ]は半分[はんぶん]以下[いか]だ。", "sentence_source": "generated"}, {"text": "毎日練習すれば、合格する確率は少しずつ高くなる。", "target_word": "確率", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]すれば、合格[ごうかく]する確率[かくりつ]は少[すこ]しずつ高[たか]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "確率", "label": "基本形"}], "register": "中立", "sense_fingerprint": "日常語。物事の起こりやすさ・見込み(数式ではなく感覚的な可能性)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36136, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気温", "is_correct": false, "explanation": "気温は空気の温度で、雨が降る見込みの高さを表す語としては文に合わない。"}, {"text": "風速", "is_correct": false, "explanation": "風速は風の速さで、「雨が降る風速が高い」は文として意味が通らない。"}, {"text": "確率", "is_correct": true, "explanation": "雨が降る可能性の度合いを表す確率で、「高いので傘を持っていこう」と合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は人の体の温度で、雨が降る見込みとは結びつかないので文に合わない。"}], "explanations": {"気温": "気温は空気の温度で、雨が降る見込みの高さを表す語としては文に合わない。", "風速": "風速は風の速さで、「雨が降る風速が高い」は文として意味が通らない。", "確率": "雨が降る可能性の度合いを表す確率で、「高いので傘を持っていこう」と合う。", "体温": "体温は人の体の温度で、雨が降る見込みとは結びつかないので文に合わない。"}, "sentence_index": 0, "correct_answer": "確率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このクラスの女子の確率は三十人だ。", "explanation": "ここは〈人数〉の意味。人の数は人数と言い、起こりやすさを表す確率とは結びつかない。"}, {"text": "試合に勝つ得点は低いが、あきらめたくない。", "explanation": "ここは〈得点〉の意味。得点は点数のことで、勝つ見込みや起こりやすさは表さないので合わない。"}, {"text": "彼女には無限の確率がある。", "explanation": "ここは〈可能性〉の意味（伸びしろ）。「無限の可能性」は将来の伸びしろを言う言い方で、確率は起こる度合いなので人の才能には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36136, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身長", "is_correct": false, "explanation": "身長は人の背の高さで、成功する見込みの話の主語としては文が成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さで、「成功する体重が低くても」という文の主語には合わない。"}, {"text": "室温", "is_correct": false, "explanation": "室温は部屋の温度で、挑戦する価値の話とは関係がないので文に合わない。"}, {"text": "確率", "is_correct": true, "explanation": "成功する可能性の度合いを表す確率で、低くても挑戦する価値があるという文に合う。"}], "explanations": {"身長": "身長は人の背の高さで、成功する見込みの話の主語としては文が成り立たない。", "体重": "体重は体の重さで、「成功する体重が低くても」という文の主語には合わない。", "室温": "室温は部屋の温度で、挑戦する価値の話とは関係がないので文に合わない。", "確率": "成功する可能性の度合いを表す確率で、低くても挑戦する価値があるという文に合う。"}, "sentence_index": 6, "correct_answer": "確率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日練習すれば、語彙の確率は少しずつ増える。", "explanation": "ここは〈語彙〉の意味。語彙は使える言葉の数で、物事の起こりやすさは表さないので合わない。"}, {"text": "毎日練習すれば、年収の確率は少しずつ高くなる。", "explanation": "ここは〈年収〉の意味。年収は一年間の収入の額で、起こりやすさの度合いとは別物なので合わない。"}, {"text": "毎日練習すれば、体重の確率は少しずつ減る。", "explanation": "ここは〈体重〉の意味。体の重さは体重と言い、確率は起こりやすさの度合いなので体の重さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36136, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降る確率を低いので、洗濯物を外に干した。", "corrected_sentence": "雨が降る確率が低いので、洗濯物を外に干した。", "error_description": "形容詞「低い」は主語に「が」を取るので、「確率を」は誤り。正しくは「確率が低いので」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36136, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の道は、事故が起きる確率を高い。", "corrected_sentence": "夜の道は、事故が起きる確率が高い。", "error_description": "形容詞「高い」は主語に「が」を取るので、「確率を」は誤り。正しくは「確率が高い」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
