INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36137, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄が起こる可能性の度合い。数学や統計で使われる、0から1までの数で表されることが多い。", "primary_collocate": null, "pronunciation": "かくりつ", "ipa": "kakɯɾitsɯ", "syllable_count": 4, "sentences": [{"text": "コインを投げて表が出る確率は二分の一だ。", "target_word": "確率", "complexity_tier": "T3", "furigana": "コインを投[な]げて表[おもて]が出[で]る確率[かくりつ]は二分[にぶん]の一[いち]だ。", "sentence_source": "generated"}, {"text": "サイコロで1の目が出る確率は、六分の一になる。", "target_word": "確率", "complexity_tier": "T3", "furigana": "サイコロで1[いち]の目[め]が出[で]る確率[かくりつ]は、六分[ろくぶん]の一[いち]になる。", "sentence_source": "generated"}, {"text": "確率は、0から1までの数で表される。", "target_word": "確率", "complexity_tier": "T3", "furigana": "確率[かくりつ]は、0[ぜろ]から1[いち]までの数[かず]で表[あらわ]される。", "sentence_source": "generated"}, {"text": "数学の授業で、くじに当たる確率の求め方を習った。", "target_word": "確率", "complexity_tier": "T3", "furigana": "数学[すうがく]の授業[じゅぎょう]で、くじに当[あ]たる確率[かくりつ]の求[もと]め方[かた]を習[なら]った。", "sentence_source": "generated"}, {"text": "確率を計算するには、全部の場合の数を数える必要がある。", "target_word": "確率", "complexity_tier": "T3", "furigana": "確率[かくりつ]を計算[けいさん]するには、全部[ぜんぶ]の場合[ばあい]の数[かず]を数[かぞ]える必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "赤い玉と白い玉が入った袋から、赤を引く確率を求めなさい。", "target_word": "確率", "complexity_tier": "T3", "furigana": "赤[あか]い玉[たま]と白[しろ]い玉[たま]が入[はい]った袋[ふくろ]から、赤[あか]を引[ひ]く確率[かくりつ]を求[もと]めなさい。", "sentence_source": "generated"}, {"text": "確率が1のとき、その事柄は必ず起こる。", "target_word": "確率", "complexity_tier": "T3", "furigana": "確率[かくりつ]が1[いち]のとき、その事柄[ことがら]は必[かなら]ず起[お]こる。", "sentence_source": "generated"}, {"text": "互いに影響しない二つの出来事が同時に起こる確率は、かけ算で求める。", "target_word": "確率", "complexity_tier": "T3", "furigana": "互[たが]いに影響[えいきょう]しない二[ふた]つの出来事[できごと]が同時[どうじ]に起[お]こる確率[かくりつ]は、かけ算[ざん]で求[もと]める。", "sentence_source": "generated"}, {"text": "統計では、データから確率を推定することがある。", "target_word": "確率", "complexity_tier": "T3", "furigana": "統計[とうけい]では、データから確率[かくりつ]を推定[すいてい]することがある。", "sentence_source": "generated"}, {"text": "確率が0なら、その出来事は決して起こらない。", "target_word": "確率", "complexity_tier": "T3", "furigana": "確率[かくりつ]が0[ぜろ]なら、その出来事[できごと]は決[けっ]して起[お]こらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "確率", "label": "基本形"}], "register": "中立", "sense_fingerprint": "数学・統計用語。事象が起こる可能性を0から1の数で表したもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: かけ算 (Zipf 2.42)']::text[], 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36137, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回数", "is_correct": false, "explanation": "回数は行った数のことで、表が出る割合を表す文の主語には合わない。"}, {"text": "硬貨", "is_correct": false, "explanation": "硬貨はお金の一種で、表が出る割合を表す文の主語としては意味が通らない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは物の重量で、表が出る割合を表すことはできないので文に合わない。"}, {"text": "確率", "is_correct": true, "explanation": "表が出る起こりやすさを表す確率で、二分の一という値に合う。"}], "explanations": {"回数": "回数は行った数のことで、表が出る割合を表す文の主語には合わない。", "硬貨": "硬貨はお金の一種で、表が出る割合を表す文の主語としては意味が通らない。", "重さ": "重さは物の重量で、表が出る割合を表すことはできないので文に合わない。", "確率": "表が出る起こりやすさを表す確率で、二分の一という値に合う。"}, "sentence_index": 0, "correct_answer": "確率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数学の授業で、三角形の角の確率の求め方を習った。", "explanation": "ここは〈角度〉の意味。角の大きさは角度と言い、確率は0から1の数で表す概念なので角には使えない。"}, {"text": "数学の授業で、円の確率の求め方を習った。", "explanation": "ここは〈面積〉の意味。図形の広さは面積で表し、確率は0から1の数なので図形には使えない。"}, {"text": "数学の授業で、箱の確率の求め方を習った。", "explanation": "ここは〈体積〉の意味。箱の容量は体積で表し、確率は物の大きさを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36137, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得点", "is_correct": false, "explanation": "得点は点数のことで、「得点が1のとき必ず起こる」という文の主語には合わない。"}, {"text": "金額", "is_correct": false, "explanation": "金額はお金の額で、事柄が必ず起こる条件を表す主語としては意味が通らない。"}, {"text": "確率", "is_correct": true, "explanation": "事柄が起こる可能性の度合いを表す確率で、1のとき必ず起こるという文に合う。"}, {"text": "身長", "is_correct": false, "explanation": "身長は人の背の高さで、事柄が起こる条件の数値として文に合わない。"}], "explanations": {"得点": "得点は点数のことで、「得点が1のとき必ず起こる」という文の主語には合わない。", "金額": "金額はお金の額で、事柄が必ず起こる条件を表す主語としては意味が通らない。", "確率": "事柄が起こる可能性の度合いを表す確率で、1のとき必ず起こるという文に合う。", "身長": "身長は人の背の高さで、事柄が起こる条件の数値として文に合わない。"}, "sentence_index": 6, "correct_answer": "確率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車の確率は時速百キロだ。", "explanation": "ここは〈速度〉の意味。速さは速度と言い、確率は0から1の数で表すので時速の値とは合わない。"}, {"text": "この荷物の確率は十キロだ。", "explanation": "ここは〈重量〉の意味。重さは重量で表し、確率は重さを量る語ではないので十キロとは合わない。"}, {"text": "この町の高齢者の確率は三十人だ。", "explanation": "ここは〈人数〉の意味。人の数は人数と言い、0から1の数で表す確率とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36137, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "サイコロを振って偶数が出る確率が求めよう。", "corrected_sentence": "サイコロを振って偶数が出る確率を求めよう。", "error_description": "「求める」は対象を「を」で示すので、「確率が」は誤り。正しくは「確率を求めよう」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36137, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱から玉を一つ取り出すとき、白が出る確率が求める。", "corrected_sentence": "箱から玉を一つ取り出すとき、白が出る確率を求める。", "error_description": "「求める」は対象を「を」で示すので、「確率が」は誤り。正しくは「確率を求める」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36140, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「試みがうまくいけば」で、試みが主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「試みをうまくいけば」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を示す。「試みのうまくいけば」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示す。「試みからうまくいけば」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「試みがうまくいけば」で、試みが主語になる。", "を": "「を」は目的語を示す。「試みをうまくいけば」は文が成り立たない。", "の": "「の」は連体修飾を示す。「試みのうまくいけば」は文として成り立たない。", "から": "「から」は起点や理由を示す。「試みからうまくいけば」は不自然。"}, "error_tags": {"を": "目的語の格", "の": "連体修飾", "から": "起点・理由"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36140, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「試みは、最初は誰にも理解されなかった」で、試みを主題として示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着点を示す。「試みに理解されなかった」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「試みへ理解されなかった」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示す。「試みより理解されなかった」は意味を成さない。"}], "correct_answer": "は", "explanations": {"は": "「試みは、最初は誰にも理解されなかった」で、試みを主題として示す。", "に": "「に」は相手や帰着点を示す。「試みに理解されなかった」は不自然。", "へ": "「へ」は方向を示す。「試みへ理解されなかった」は成り立たない。", "より": "「より」は比較の基準を示す。「試みより理解されなかった」は意味を成さない。"}, "error_tags": {"に": "相手・帰着点", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36140, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをしてみようとする行為です。", "primary_collocate": null, "pronunciation": "こころみ", "ipa": "kokoɾomi", "syllable_count": 4, "sentences": [{"text": "新しい料理を作る試みは、残念ながら失敗に終わった。", "target_word": "試み", "complexity_tier": "T3", "furigana": "新[あたら]しい料理[りょうり]を作[つく]る試[こころ]みは、残念[ざんねん]ながら失敗[しっぱい]に終[お]わった。", "sentence_source": "generated"}, {"text": "この試みがうまくいけば、町の人も喜ぶだろう。", "target_word": "試み", "complexity_tier": "T3", "furigana": "この試[こころ]みがうまくいけば、町[まち]の人[ひと]も喜[よろこ]ぶだろう。", "sentence_source": "generated"}, {"text": "彼女は毎朝走るという試みを、一か月続けている。", "target_word": "試み", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は毎朝[まいあさ]走[はし]るという試[こころ]みを、一[いっ]か月[げつ]続[つづ]けている。", "sentence_source": "generated"}, {"text": "初めての試みだったので、最初は緊張した。", "target_word": "試み", "complexity_tier": "T3", "furigana": "初[はじ]めての試[こころ]みだったので、最初[さいしょ]は緊張[きんちょう]した。", "sentence_source": "generated"}, {"text": "学校では、新しい授業の試みが始まった。", "target_word": "試み", "complexity_tier": "T3", "furigana": "学校[がっこう]では、新[あたら]しい授業[じゅぎょう]の試[こころ]みが始[はじ]まった。", "sentence_source": "generated"}, {"text": "試みは小さくても、続ければ大きな変化につながる。", "target_word": "試み", "complexity_tier": "T3", "furigana": "試[こころ]みは小[ちい]さくても、続[つづ]ければ大[おお]きな変化[へんか]につながる。", "sentence_source": "generated"}, {"text": "空を飛ぼうとした古い試みが、のちの飛行機を生んだ。", "target_word": "試み", "complexity_tier": "T3", "furigana": "空[そら]を飛[と]ぼうとした古[ふる]い試[こころ]みが、のちの飛行機[ひこうき]を生[う]んだ。", "sentence_source": "generated"}, {"text": "彼の試みは、最初は誰にも理解されなかった。", "target_word": "試み", "complexity_tier": "T3", "furigana": "彼[かれ]の試[こころ]みは、最初[さいしょ]は誰[だれ]にも理解[りかい]されなかった。", "sentence_source": "generated"}, {"text": "失敗した試みからも、学べることはたくさんある。", "target_word": "試み", "complexity_tier": "T3", "furigana": "失敗[しっぱい]した試[こころ]みからも、学[まな]べることはたくさんある。", "sentence_source": "generated"}, {"text": "野菜を育てる試みを、ベランダで始めてみた。", "target_word": "試み", "complexity_tier": "T3", "furigana": "野菜[やさい]を育[そだ]てる試[こころ]みを、ベランダで始[はじ]めてみた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試み", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "うまくいくか分からないが、とにかくやってみること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36140, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試み", "is_correct": true, "explanation": "「新しい料理を作る試みは失敗に終わった」で、やってみる行為を表す。"}, {"text": "運賃", "is_correct": false, "explanation": "運賃は料理を作る行為に当てはまらず、「作る運賃」は成り立たない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は作る対象ではなく、この文脈に入らない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は料理を作る行為とは結びつかず、文が成り立たない。"}], "explanations": {"試み": "「新しい料理を作る試みは失敗に終わった」で、やってみる行為を表す。", "運賃": "運賃は料理を作る行為に当てはまらず、「作る運賃」は成り立たない。", "眠気": "眠気は作る対象ではなく、この文脈に入らない。", "湿度": "湿度は料理を作る行為とは結びつかず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "試み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は難しい試みに合格した。", "explanation": "ここは〈試験〉の意味。試験は合格するものだが、試みは合否で合格する性質のものではない。"}, {"text": "彼は朝、楽しい試みから覚めた。", "explanation": "ここは〈夢〉の意味。夢からは覚めるが、試みから覚めることはないので合わない。"}, {"text": "彼は百メートルの試みを更新した。", "explanation": "ここは〈記録〉の意味。記録は更新するが、試みは更新の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36140, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試み", "is_correct": true, "explanation": "「古い試みが、飛行機を生んだ」で、飛ぼうとした行為を指す。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は試みの代わりにならず、飛行機を生む主語として成り立たない。"}, {"text": "出費", "is_correct": false, "explanation": "出費は飛ぼうとする行為を指さず、文が成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は飛行機を生む行為の主語にならず、文が成り立たない。"}], "explanations": {"試み": "「古い試みが、飛行機を生んだ」で、飛ぼうとした行為を指す。", "寿命": "寿命は試みの代わりにならず、飛行機を生む主語として成り立たない。", "出費": "出費は飛ぼうとする行為を指さず、文が成り立たない。", "体重": "体重は飛行機を生む行為の主語にならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "試み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "社員は上司の試みに従って、資料を作った。", "explanation": "ここは〈指示〉の意味。指示は従うものだが、試みは従う対象ではない。"}, {"text": "この地域は試みが上がって、若い人が住みにくくなった。", "explanation": "ここは〈家賃〉の意味。家賃は上がるが、試みは値段のように上がるものではない。"}, {"text": "風邪で試みを測ったら、三十八度あった。", "explanation": "ここは〈熱〉の意味。熱は測るが、試みは測る対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36140, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は毎朝公園を走るという試みに、一か月続けている。", "corrected_sentence": "彼女は毎朝公園を走るという試みを、一か月続けている。", "error_description": "助詞の誤り。「続ける」の目的語は「を」なので、「試みに続ける」ではなく「試みを続ける」と言う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36140, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その病院は患者を減らす試みを立てて、新しい対策を始めた。", "corrected_sentence": "その病院は患者を減らす試みを行って、新しい対策を始めた。", "error_description": "動詞の誤り。「試みを立てる」は不自然で、「試みを行う」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
