INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36141, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを成し遂げようとして行う取り組みや行為。", "primary_collocate": null, "pronunciation": "こころみ", "ipa": "kokoɾomi", "syllable_count": 4, "sentences": [{"text": "町をきれいにする試みとして、住民が毎週ごみを拾っている。", "target_word": "試み", "complexity_tier": "T3", "furigana": "町[まち]をきれいにする試[こころ]みとして、住民[じゅうみん]が毎週[まいしゅう]ごみを拾[ひろ]っている。", "sentence_source": "generated"}, {"text": "会社は売り上げを伸ばす試みを、いくつも行ってきた。", "target_word": "試み", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は売[う]り上[あ]げを伸[の]ばす試[こころ]みを、いくつも行[おこな]ってきた。", "sentence_source": "generated"}, {"text": "病気の子どもを助けようとする試みが、多くの人の協力で実った。", "target_word": "試み", "complexity_tier": "T3", "furigana": "病気[びょうき]の子[こ]どもを助[たす]けようとする試[こころ]みが、多[おお]くの人[ひと]の協力[きょうりょく]で実[みの]った。", "sentence_source": "generated"}, {"text": "彼らは砂漠に緑を増やす試みに、十年かけて取り組んだ。", "target_word": "試み", "complexity_tier": "T3", "furigana": "彼[かれ]らは砂漠[さばく]に緑[みどり]を増[ふ]やす試[こころ]みに、十年[じゅうねん]かけて取[と]り組[く]んだ。", "sentence_source": "generated"}, {"text": "世界の言葉を一つにしようとする試みは、これまで何度もあった。", "target_word": "試み", "complexity_tier": "T3", "furigana": "世界[せかい]の言葉[ことば]を一[ひと]つにしようとする試[こころ]みは、これまで何度[なんど]もあった。", "sentence_source": "generated"}, {"text": "市は交通事故を減らす試みとして、道路に新しい標識を置いた。", "target_word": "試み", "complexity_tier": "T3", "furigana": "市[し]は交通事故[こうつうじこ]を減[へ]らす試[こころ]みとして、道路[どうろ]に新[あたら]しい標識[ひょうしき]を置[お]いた。", "sentence_source": "generated"}, {"text": "この試みは、地域の古い祭りを守るために始まった。", "target_word": "試み", "complexity_tier": "T3", "furigana": "この試[こころ]みは、地域[ちいき]の古[ふる]い祭[まつ]りを守[まも]るために始[はじ]まった。", "sentence_source": "generated"}, {"text": "研究者たちは、新しいエネルギーを作る試みを続けている。", "target_word": "試み", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]たちは、新[あたら]しいエネルギーを作[つく]る試[こころ]みを続[つづ]けている。", "sentence_source": "generated"}, {"text": "山の頂上まで車いすで登る試みは、大きな話題になった。", "target_word": "試み", "complexity_tier": "T3", "furigana": "山[やま]の頂上[ちょうじょう]まで車[くるま]いすで登[のぼ]る試[こころ]みは、大[おお]きな話題[わだい]になった。", "sentence_source": "generated"}, {"text": "図書館が本を増やす試みを進めたので、利用者も増えた。", "target_word": "試み", "complexity_tier": "T3", "furigana": "図書館[としょかん]が本[ほん]を増[ふ]やす試[こころ]みを進[すす]めたので、利用者[りようしゃ]も増[ふ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試み", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある目標を成し遂げるために行う取り組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee9fcd9-3997-4915-b930-109ef40f4284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36141, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試み", "is_correct": true, "explanation": "「町をきれいにする試みとして」で、町を美しくする取り組みを表す。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は町をきれいにする取り組みとは言えず、文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は町をきれいにする取り組みに当てはまらない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は取り組みにならず、この文脈に入らない。"}], "explanations": {"試み": "「町をきれいにする試みとして」で、町を美しくする取り組みを表す。", "手紙": "手紙は町をきれいにする取り組みとは言えず、文が成り立たない。", "天気": "天気は町をきれいにする取り組みに当てはまらない。", "眠気": "眠気は取り組みにならず、この文脈に入らない。"}, "sentence_index": 0, "correct_answer": "試み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日、花の試みを描いて過ごしている。", "explanation": "ここは〈絵〉の意味。絵は描くものだが、試みは描けるものではない。"}, {"text": "この出版社は、毎月新しい試みを発行している。", "explanation": "ここは〈雑誌〉の意味。雑誌は発行するが、試みは発行されるものではない。"}, {"text": "この家では、試みを飼うことに決めた。", "explanation": "ここは〈犬〉の意味。犬は飼うものだが、試みは飼う対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36141, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試み", "is_correct": true, "explanation": "「この試みは、地域の古い祭りを守るために始まった」で、取り組みを指す。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は祭りを守るために始まる主語にならず、文が成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は祭りを守るために始まるものではなく、この文脈に入らない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は取り組みの主語にならず、文が成り立たない。"}], "explanations": {"試み": "「この試みは、地域の古い祭りを守るために始まった」で、取り組みを指す。", "寿命": "寿命は祭りを守るために始まる主語にならず、文が成り立たない。", "体重": "体重は祭りを守るために始まるものではなく、この文脈に入らない。", "湿度": "湿度は取り組みの主語にならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "試み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "観光客が、有名な塔の試みを撮った。", "explanation": "ここは〈写真〉の意味。写真は撮るものだが、試みは撮影の対象にならない。"}, {"text": "選手は、ゴールまでの試みを測った。", "explanation": "ここは〈距離〉の意味。距離は測るものだが、試みは測れない。"}, {"text": "夜中に火事の試みが鳴って、皆が起きた。", "explanation": "ここは〈警報〉の意味。警報は鳴るものだが、試みは鳴るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36141, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "住民は町をきれいにする試みを参加して、毎週ごみを拾っている。", "corrected_sentence": "住民は町をきれいにする試みに参加して、毎週ごみを拾っている。", "error_description": "助詞の誤り。「参加する」は「に」を取るので、「試みを参加する」ではなく「試みに参加する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36141, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は歩道を広げる試みを始まって、事故も減った。", "corrected_sentence": "市は歩道を広げる試みを始めて、事故も減った。", "error_description": "動詞の誤り。「始まる」は自動詞で「試みを始まる」とは言えない。他動詞「始める」を使い「試みを始める」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0218227-55e6-4967-8f82-bc38f62f0a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
