INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36142, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "たくさんあること。", "primary_collocate": null, "pronunciation": "かずおおく", "ipa": "kazɯoːkɯ", "syllable_count": 5, "sentences": [{"text": "この図書館には、古い本が数多くそろっている。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "この図書館[としょかん]には、古[ふる]い本[ほん]が数多[かずおお]くそろっている。", "sentence_source": "generated"}, {"text": "公園には、数多くの桜の木が植えられている。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "公園[こうえん]には、数多[かずおお]くの桜[さくら]の木[き]が植[う]えられている。", "sentence_source": "generated"}, {"text": "この町には、古い看板が数多く残っている。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "この町[まち]には、古[ふる]い看板[かんばん]が数多[かずおお]く残[のこ]っている。", "sentence_source": "generated"}, {"text": "駅の近くには、安くておいしい店が数多くある。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くには、安[やす]くておいしい店[みせ]が数多[かずおお]くある。", "sentence_source": "generated"}, {"text": "京都には、数多くの古いお寺が残っている。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "京都[きょうと]には、数多[かずおお]くの古[ふる]いお寺[てら]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "祖父の部屋には、数多くの写真が飾られている。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "祖父[そふ]の部屋[へや]には、数多[かずおお]くの写真[しゃしん]が飾[かざ]られている。", "sentence_source": "generated"}, {"text": "この島では、めずらしい鳥が数多く見られる。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "この島[しま]では、めずらしい鳥[とり]が数多[かずおお]く見[み]られる。", "sentence_source": "generated"}, {"text": "市場には、新鮮な野菜が数多く並んでいた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "市場[いちば]には、新鮮[しんせん]な野菜[やさい]が数多[かずおお]く並[なら]んでいた。", "sentence_source": "generated"}, {"text": "展覧会には、有名な画家の絵が数多く集められた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]には、有名[ゆうめい]な画家[がか]の絵[え]が数多[かずおお]く集[あつ]められた。", "sentence_source": "generated"}, {"text": "山の中には、まだ知られていない花が数多くある。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]には、まだ知[し]られていない花[はな]が数多[かずおお]くある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "数多く", "label": "基本形"}], "register": "やや改まった中立", "sense_fingerprint": "物や人がたくさん存在するさま(存在・所在の多さ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36142, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数多く", "is_correct": true, "explanation": "正解。古い本が多く存在することを表すので入る。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "「古い本がゆっくりそろっている」は速さの話になり、本の数の多さを表さない。"}, {"text": "大きく", "is_correct": false, "explanation": "「大きくそろっている」は本の大きさの意味になり、数の多さを表さない。"}, {"text": "固く", "is_correct": false, "explanation": "「固くそろっている」は意味が通らず、数の多さとも関係がない。"}], "explanations": {"数多く": "正解。古い本が多く存在することを表すので入る。", "ゆっくり": "「古い本がゆっくりそろっている」は速さの話になり、本の数の多さを表さない。", "大きく": "「大きくそろっている」は本の大きさの意味になり、数の多さを表さない。", "固く": "「固くそろっている」は意味が通らず、数の多さとも関係がない。"}, "sentence_index": 0, "correct_answer": "数多く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では、毎日数多くの水を使う。", "explanation": "ここは〈大量〉の意味。数多くは数えられるものの多さを表すので、水のような数えられない量には使わない。"}, {"text": "この部屋には、テレビが数多く一台だけある。", "explanation": "ここは〈一つだけ〉の意味。数多くは数の多さを表すので、「一台だけ」と並べると矛盾して使えない。"}, {"text": "その靴は、数多く大きすぎて、歩くのに向かない。", "explanation": "ここは〈とても〉の意味。数多くは数や回数の多さを表すので、大きさの程度を強める副詞としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36142, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数多く", "is_correct": true, "explanation": "正解。めずらしい鳥が多く見られることを表すので入る。"}, {"text": "深く", "is_correct": false, "explanation": "「めずらしい鳥が深く見られる」は意味が通らず、数を表さない。"}, {"text": "厚く", "is_correct": false, "explanation": "「厚く見られる」は厚みの話になり、鳥の数の多さを表さない。"}, {"text": "冷たく", "is_correct": false, "explanation": "「冷たく見られる」は冷淡に扱われる意味になり、鳥の数の多さを表さない。"}], "explanations": {"数多く": "正解。めずらしい鳥が多く見られることを表すので入る。", "深く": "「めずらしい鳥が深く見られる」は意味が通らず、数を表さない。", "厚く": "「厚く見られる」は厚みの話になり、鳥の数の多さを表さない。", "冷たく": "「冷たく見られる」は冷淡に扱われる意味になり、鳥の数の多さを表さない。"}, "sentence_index": 6, "correct_answer": "数多く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋には、新鮮な空気が数多くある。", "explanation": "ここは〈たっぷり〉の意味。数多くは数えられるものの多さを表すので、空気のような数えられない量には使わない。"}, {"text": "この世界には、太陽が数多く一つしかない。", "explanation": "ここは〈一つだけ〉の意味。数多くは数の多さを表すので、「一つしかない」と並べると矛盾して使えない。"}, {"text": "彼女は、ジュースを数多く一気に飲み干した。", "explanation": "ここは〈一気に〉の意味。数多くは数量や回数の多さを表すので、一度に飲み干す様子を言う「一気に」の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36142, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前には、新しい店が数多くが並んでいた。", "corrected_sentence": "駅前には、新しい店が数多く並んでいた。", "error_description": "副詞「数多く」の後に「が」は付けられない。「並ぶ」の主語は「店」なので、「が」は店の後にだけ付く。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36142, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その駅からは、近くの山が数多くが見える。", "corrected_sentence": "その駅からは、近くの山が数多く見える。", "error_description": "副詞「数多く」の後に「が」は付けられない。「見える」の主語は「山」なので、「が」は山の後にだけ付く。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
