INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36143, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "数量や回数が非常に多いこと。", "primary_collocate": null, "pronunciation": "かずおおく", "ipa": "kazɯoːkɯ", "syllable_count": 5, "sentences": [{"text": "彼はこれまで大会で数多く優勝してきた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "彼[かれ]はこれまで大会[たいかい]で数多[かずおお]く優勝[ゆうしょう]してきた。", "sentence_source": "generated"}, {"text": "その作家は、生涯に数多くの賞を受けた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "その作家[さっか]は、生涯[しょうがい]に数多[かずおお]くの賞[しょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "医者は、これまでに数多くの患者を治してきた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、これまでに数多[かずおお]くの患者[かんじゃ]を治[なお]してきた。", "sentence_source": "generated"}, {"text": "小さな失敗を数多く重ねて、やっと上手になった。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "小[ちい]さな失敗[しっぱい]を数多[かずおお]く重[かさ]ねて、やっと上手[じょうず]になった。", "sentence_source": "generated"}, {"text": "この町は、台風の被害を数多く受けてきた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "この町[まち]は、台風[たいふう]の被害[ひがい]を数多[かずおお]く受[う]けてきた。", "sentence_source": "generated"}, {"text": "彼女は海外のコンサートに数多く出演している。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は海外[かいがい]のコンサートに数多[かずおお]く出演[しゅつえん]している。", "sentence_source": "generated"}, {"text": "数多く練習したおかげで、本番でも落ち着いて弾けた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "数多[かずおお]く練習[れんしゅう]したおかげで、本番[ほんばん]でも落[お]ち着[つ]いて弾[ひ]けた。", "sentence_source": "generated"}, {"text": "この会社は、ヒット商品を数多く生み出してきた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、ヒット商品[しょうひん]を数多[かずおお]く生[う]み出[だ]してきた。", "sentence_source": "generated"}, {"text": "先生は教師として、数多くの生徒を送り出した。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "先生[せんせい]は教師[きょうし]として、数多[かずおお]くの生徒[せいと]を送[おく]り出[だ]した。", "sentence_source": "generated"}, {"text": "事故が数多く起こる交差点には、信号がつけられた。", "target_word": "数多く", "complexity_tier": "T3", "furigana": "事故[じこ]が数多[かずおお]く起[お]こる交差点[こうさてん]には、信号[しんごう]がつけられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "数多く", "label": "基本形"}], "register": "やや改まった中立", "sense_fingerprint": "動作や経験の回数・件数が非常に多いさま(繰り返し・積み重ね)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffaa13fb-9bf0-4c05-bfe6-151c390be6f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36143, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数多く", "is_correct": true, "explanation": "正解。大会での優勝が繰り返し多く起きたことを表すので入る。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "「ゆっくり優勝してきた」は速さの話になり、優勝の回数を表さない。"}, {"text": "固く", "is_correct": false, "explanation": "「固く優勝してきた」は意味が通らず、回数とも関係がない。"}, {"text": "厚く", "is_correct": false, "explanation": "「厚く優勝してきた」は意味が通らず、回数を表さない。"}], "explanations": {"数多く": "正解。大会での優勝が繰り返し多く起きたことを表すので入る。", "ゆっくり": "「ゆっくり優勝してきた」は速さの話になり、優勝の回数を表さない。", "固く": "「固く優勝してきた」は意味が通らず、回数とも関係がない。", "厚く": "「厚く優勝してきた」は意味が通らず、回数を表さない。"}, "sentence_index": 0, "correct_answer": "数多く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は数多く優しくて、誰とでもすぐ仲良くなれる。", "explanation": "ここは〈とても〉の意味。数多くは数量や回数の多さを表すので、性質の程度を強める副詞としては使えない。"}, {"text": "彼は大会で一度だけ数多く優勝した。", "explanation": "ここは〈一回だけ〉の意味。数多くは回数が多いことを表すので、一度きりの出来事を言う場面には使えない。"}, {"text": "毎朝、数多く牛乳を飲んでいる。", "explanation": "ここは〈大量〉の意味。数多くは数えられるものの多さに使うので、牛乳のように量で測るものには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36143, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数多く", "is_correct": true, "explanation": "正解。練習を繰り返し多くしたことを表すので入る。"}, {"text": "薄く", "is_correct": false, "explanation": "「薄く練習した」は練習の密度が低い意味になり、回数の多さを表さない。"}, {"text": "重く", "is_correct": false, "explanation": "「重く練習した」は意味が通らず、回数を表さない。"}, {"text": "冷たく", "is_correct": false, "explanation": "「冷たく練習した」は意味が通らず、練習の仕方とも合わない。"}], "explanations": {"数多く": "正解。練習を繰り返し多くしたことを表すので入る。", "薄く": "「薄く練習した」は練習の密度が低い意味になり、回数の多さを表さない。", "重く": "「重く練習した」は意味が通らず、回数を表さない。", "冷たく": "「冷たく練習した」は意味が通らず、練習の仕方とも合わない。"}, "sentence_index": 6, "correct_answer": "数多く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、数多く三十年も続いている。", "explanation": "ここは〈長い期間〉の意味。数多くは数や回数の多さを表すので、年月の長さを言う場面には使えない。"}, {"text": "この部屋は、窓が数多く一つしかない。", "explanation": "ここは〈たった一つ〉の意味。数多くは数や回数の多さを表すので、「一つしかない」と並べると矛盾する。"}, {"text": "この鍋には、塩が数多く入っている。", "explanation": "ここは〈たくさん存在する〉の意味。数多くは回数や件数の多さを表すので、中身の量を言う場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36143, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は外国の映画を数多くを見てきた。", "corrected_sentence": "私は外国の映画を数多く見てきた。", "error_description": "目的語「映画を」はすでに示されているので、副詞「数多く」の後に「を」は付けられない。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36143, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は毎年、旅行を数多くに楽しんでいる。", "corrected_sentence": "私は毎年、旅行を数多く楽しんでいる。", "error_description": "副詞「数多く」の後に「に」は付けられない。「楽しむ」の目的語は「旅行を」で、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f09fa199-f411-40f5-b302-d91b28a14a58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36144, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "「自転車が改良して」は目的語のない形になり、他動詞の改良として不自然。"}, {"text": "を", "is_correct": true, "explanation": "正解。自転車は「改良して」の対象（目的語）なので「を」。"}, {"text": "の", "is_correct": false, "explanation": "「自転車の改良して」と続くと動詞がつながらず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「自転車と改良して」は並列や共同の形で、自転車を対象とする文にならない。"}], "correct_answer": "を", "explanations": {"が": "「自転車が改良して」は目的語のない形になり、他動詞の改良として不自然。", "を": "正解。自転車は「改良して」の対象（目的語）なので「を」。", "の": "「自転車の改良して」と続くと動詞がつながらず、文が成り立たない。", "と": "「自転車と改良して」は並列や共同の形で、自転車を対象とする文にならない。"}, "error_tags": {"が": "主語の誤り", "の": "連体の誤り", "と": "並列の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36144, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "に", "is_correct": false, "explanation": "「作品に改良して」は対象を示せず、改良の目的語にならない。"}, {"text": "を", "is_correct": true, "explanation": "正解。作品は「改良して」の対象（目的語）なので「を」。"}, {"text": "へ", "is_correct": false, "explanation": "「作品へ改良して」は方向を示す形で、作品を対象とする文にならない。"}, {"text": "で", "is_correct": false, "explanation": "「作品で改良して」は手段の意味になり、作品を直す対象の文脈に合わない。"}], "correct_answer": "を", "explanations": {"に": "「作品に改良して」は対象を示せず、改良の目的語にならない。", "を": "正解。作品は「改良して」の対象（目的語）なので「を」。", "へ": "「作品へ改良して」は方向を示す形で、作品を対象とする文にならない。", "で": "「作品で改良して」は手段の意味になり、作品を直す対象の文脈に合わない。"}, "error_tags": {"に": "位置・相手の誤り", "へ": "方向の誤り", "で": "手段の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36144, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "直したり、もっとよくすること。", "primary_collocate": null, "pronunciation": "かいりょう", "ipa": "kaiɾʲoː", "syllable_count": 4, "sentences": [{"text": "このナイフは持ちにくかったので、持ち手を改良してもらいました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "このナイフは持[も]ちにくかったので、持[も]ち手[て]を改良[かいりょう]してもらいました。", "sentence_source": "generated"}, {"text": "兄は自分の自転車を改良して、もっと速く走れるようにしました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "兄[あに]は自分[じぶん]の自転車[じてんしゃ]を改良[かいりょう]して、もっと速[はや]く走[はし]れるようにしました。", "sentence_source": "generated"}, {"text": "会社は古い製品の改良に力を入れています。", "target_word": "改良", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は古[ふる]い製品[せいひん]の改良[かいりょう]に力[ちから]を入[い]れています。", "sentence_source": "generated"}, {"text": "改良したレシピで作ると、ケーキがふんわりと焼き上がります。", "target_word": "改良", "complexity_tier": "T3", "furigana": "改良[かいりょう]したレシピで作[つく]ると、ケーキがふんわりと焼[や]き上[あ]がります。", "sentence_source": "generated"}, {"text": "使いにくいところは、みんなで話し合って改良しましょう。", "target_word": "改良", "complexity_tier": "T3", "furigana": "使[つか]いにくいところは、みんなで話[はな]し合[あ]って改良[かいりょう]しましょう。", "sentence_source": "generated"}, {"text": "この町では、古い水道を改良する工事が続いています。", "target_word": "改良", "complexity_tier": "T3", "furigana": "この町[まち]では、古[ふる]い水道[すいどう]を改良[かいりょう]する工事[こうじ]が続[つづ]いています。", "sentence_source": "generated"}, {"text": "改良された靴は、前のものより足が痛くなりません。", "target_word": "改良", "complexity_tier": "T3", "furigana": "改良[かいりょう]された靴[くつ]は、前[まえ]のものより足[あし]が痛[いた]くなりません。", "sentence_source": "generated"}, {"text": "失敗した作品を改良して、もう一度展覧会に出しました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "失敗[しっぱい]した作品[さくひん]を改良[かいりょう]して、もう一度[いちど]展覧会[てんらんかい]に出[だ]しました。", "sentence_source": "generated"}, {"text": "小さな改良でも、毎日の仕事はずっと楽になります。", "target_word": "改良", "complexity_tier": "T3", "furigana": "小[ちい]さな改良[かいりょう]でも、毎日[まいにち]の仕事[しごと]はずっと楽[らく]になります。", "sentence_source": "generated"}, {"text": "先月、この携帯電話のカメラが大きく改良されました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "先月[せんげつ]、この携帯電話[けいたいでんわ]のカメラが大[おお]きく改良[かいりょう]されました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "改良", "label": "基本形"}, {"form": "改良する", "label": "辞書形"}, {"form": "改良した", "label": "過去形"}, {"form": "改良される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "使いにくい点や悪い点を直して、もっと良くすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36144, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出荷", "is_correct": false, "explanation": "「持ち手を出荷してもらいました」は意味が通らない。持ち手を手直ししてもらう文脈に合わない。"}, {"text": "改良", "is_correct": true, "explanation": "正解。持ち手を手直ししてもらったという意味で、「改良してもらいました」が自然。"}, {"text": "延期", "is_correct": false, "explanation": "「持ち手を延期してもらいました」は意味をなさない。物の状態を良くする文脈に合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「持ち手を採点してもらいました」は意味が通らない。"}], "explanations": {"出荷": "「持ち手を出荷してもらいました」は意味が通らない。持ち手を手直ししてもらう文脈に合わない。", "改良": "正解。持ち手を手直ししてもらったという意味で、「改良してもらいました」が自然。", "延期": "「持ち手を延期してもらいました」は意味をなさない。物の状態を良くする文脈に合わない。", "採点": "「持ち手を採点してもらいました」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "改良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は作文の点数を改良しました。", "explanation": "ここは〈採点〉の意味。点数をつけることは採点で、改良は物や方法をより良くしたり直したりすることに使う。"}, {"text": "国会は選挙法を改良しました。", "explanation": "ここは〈改正〉の意味。法律を部分的に変えることは改正で、改良は道具や方法に使う。"}, {"text": "店は接客の態度を改良しました。", "explanation": "ここは〈改善〉の意味。態度や状況を良くする場合は改善を使い、改良は物や方法の手直しに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36144, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誤解", "is_correct": false, "explanation": "「誤解された靴」は意味が通らない。足の痛みに関する文脈に合わない。"}, {"text": "改良", "is_correct": true, "explanation": "正解。手直しされた靴は足が痛くならないという意味で自然。"}, {"text": "解体", "is_correct": false, "explanation": "「解体された靴は足が痛くなりません」は靴の性能の話として成り立たない。"}, {"text": "中断", "is_correct": false, "explanation": "「中断された靴」は文脈に合わず、意味が通らない。"}], "explanations": {"誤解": "「誤解された靴」は意味が通らない。足の痛みに関する文脈に合わない。", "改良": "正解。手直しされた靴は足が痛くならないという意味で自然。", "解体": "「解体された靴は足が痛くなりません」は靴の性能の話として成り立たない。", "中断": "「中断された靴」は文脈に合わず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "改良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月、この携帯電話の料金が大きく改良されました。", "explanation": "ここは〈改定〉の意味。料金を新しく決め直すことは改定で、改良は物や方法の性能を高めることに使う。"}, {"text": "先月、会社は携帯電話の番号を改良しました。", "explanation": "ここは〈変更〉の意味。番号を新しく変えることは変更で、改良は物や方法をより良くしたり直したりすることに使う。"}, {"text": "先月、この店は新人の社員を改良しました。", "explanation": "ここは〈採用〉の意味。新しく人を雇うことは採用で、改良は物や方法をより良くしたり直したりすることに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36144, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校は古い校舎の設備に改良して、冷房を入れました。", "corrected_sentence": "学校は古い校舎の設備を改良して、冷房を入れました。", "error_description": "「改良」は他動詞で、対象の設備は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36144, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い椅子を改良されて、座りやすくしました。", "corrected_sentence": "古い椅子を改良して、座りやすくしました。", "error_description": "「を」で目的語を示す文に「改良されて」（受身）を使うのは誤り。能動の「改良して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36145, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "の", "is_correct": false, "explanation": "「欠点の改良して」と続くと名詞の後に動詞がつながらず、文が成り立たない。"}, {"text": "を", "is_correct": true, "explanation": "正解。欠点は「改良して」の対象（目的語）なので「を」。"}, {"text": "と", "is_correct": false, "explanation": "「欠点と改良して」は並列や共同を表す形で、欠点を対象とする文にならない。"}, {"text": "で", "is_correct": false, "explanation": "「欠点で改良して」は手段や場所の意味になり、欠点を対象とする文脈に合わない。"}], "correct_answer": "を", "explanations": {"の": "「欠点の改良して」と続くと名詞の後に動詞がつながらず、文が成り立たない。", "を": "正解。欠点は「改良して」の対象（目的語）なので「を」。", "と": "「欠点と改良して」は並列や共同を表す形で、欠点を対象とする文にならない。", "で": "「欠点で改良して」は手段や場所の意味になり、欠点を対象とする文脈に合わない。"}, "error_tags": {"の": "連体の誤り", "と": "並列の誤り", "で": "手段の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
