INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36145, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事をより良い状態に変えること。", "primary_collocate": null, "pronunciation": "かいりょう", "ipa": "kaiɾʲoː", "syllable_count": 4, "sentences": [{"text": "ブロイラーは、食肉を得るために改良された鶏の品種です。", "target_word": "改良", "complexity_tier": "T3", "furigana": "ブロイラーは、食肉[しょくにく]を得[え]るために改良[かいりょう]された鶏[にわとり]の品種[ひんしゅ]です。", "sentence_source": "mined"}, {"text": "新しい機械は、古い型の欠点を改良して作られました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は、古[ふる]い型[かた]の欠点[けってん]を改良[かいりょう]して作[つく]られました。", "sentence_source": "generated"}, {"text": "技術者たちは、電池が長持ちするように改良を重ねました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "技術者[ぎじゅつしゃ]たちは、電池[でんち]が長持[ながもち]ちするように改良[かいりょう]を重[かさ]ねました。", "sentence_source": "generated"}, {"text": "土の質が悪かったので、肥料を入れて土壌の改良を行いました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "土[つち]の質[しつ]が悪[わる]かったので、肥料[ひりょう]を入[い]れて土壌[どじょう]の改良[かいりょう]を行[おこな]いました。", "sentence_source": "generated"}, {"text": "この傘は風で壊れにくいように改良されています。", "target_word": "改良", "complexity_tier": "T3", "furigana": "この傘[かさ]は風[かぜ]で壊[こわ]れにくいように改良[かいりょう]されています。", "sentence_source": "generated"}, {"text": "古い道具でも、少し改良すれば今も十分使えます。", "target_word": "改良", "complexity_tier": "T3", "furigana": "古[ふる]い道具[どうぐ]でも、少[すこ]し改良[かいりょう]すれば今[いま]も十分[じゅうぶん]使[つか]えます。", "sentence_source": "generated"}, {"text": "改良の結果、この自転車は前より三割軽くなりました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "改良[かいりょう]の結果[けっか]、この自転車[じてんしゃ]は前[まえ]より三割[さんわり]軽[かる]くなりました。", "sentence_source": "generated"}, {"text": "先生は、生徒の意見をもとに授業のやり方を改良しました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の意見[いけん]をもとに授業[じゅぎょう]のやり方[かた]を改良[かいりょう]しました。", "sentence_source": "generated"}, {"text": "開発チームは使いにくい画面を改良し、操作が簡単になりました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "開発[かいはつ]チームは使[つか]いにくい画面[がめん]を改良[かいりょう]し、操作[そうさ]が簡単[かんたん]になりました。", "sentence_source": "generated"}, {"text": "味が薄いという声があり、店はスープのレシピを改良しました。", "target_word": "改良", "complexity_tier": "T3", "furigana": "味[あじ]が薄[うす]いという声[こえ]があり、店[みせ]はスープのレシピを改良[かいりょう]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "改良", "label": "基本形"}, {"form": "改良する", "label": "辞書形"}, {"form": "改良した", "label": "過去形"}, {"form": "改良される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "欠点のある物や方法を手直しして、前より良い状態にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70618750-c0d0-4505-a26a-1400cc363087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36145, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停止", "is_correct": false, "explanation": "「停止された鶏の品種」は意味が通らない。品種を手直しして良くしたという文脈に合わない。"}, {"text": "改良", "is_correct": true, "explanation": "正解。食肉のために品種を手直ししたという意味で、「改良された」が自然。"}, {"text": "解剖", "is_correct": false, "explanation": "「解剖された品種」は品種を手直しする文脈と合わず、意味が通らない。"}, {"text": "中断", "is_correct": false, "explanation": "「中断された品種」は文脈に合わない。ここには品種をより良くする語が入る。"}], "explanations": {"停止": "「停止された鶏の品種」は意味が通らない。品種を手直しして良くしたという文脈に合わない。", "改良": "正解。食肉のために品種を手直ししたという意味で、「改良された」が自然。", "解剖": "「解剖された品種」は品種を手直しする文脈と合わず、意味が通らない。", "中断": "「中断された品種」は文脈に合わない。ここには品種をより良くする語が入る。"}, "sentence_index": 0, "correct_answer": "改良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は社員の待遇を改良しました。", "explanation": "ここは〈改善〉の意味。待遇のように状況を良くする場合は改善を使い、改良は道具や方法を手直しすることに使う。"}, {"text": "彼女は英語の会話力を改良しました。", "explanation": "ここは〈向上〉の意味。能力や力を高める場合は向上を使い、改良は物や方法の手直しに使う。"}, {"text": "組織委員会は大会の開催日を改良しました。", "explanation": "ここは〈変更〉の意味。開催日を別の日に変えることは変更で、改良は物事をより良い状態にすることに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36145, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誤解", "is_correct": false, "explanation": "「誤解の結果、自転車が軽くなった」は因果として意味をなさない。"}, {"text": "改良", "is_correct": true, "explanation": "正解。手直しの結果として自転車が軽くなったという意味で自然。"}, {"text": "出荷", "is_correct": false, "explanation": "「出荷の結果、自転車が軽くなった」は因果関係が成り立たず、文脈に合わない。"}, {"text": "混雑", "is_correct": false, "explanation": "「混雑の結果、自転車が軽くなった」は意味が通らない。"}], "explanations": {"誤解": "「誤解の結果、自転車が軽くなった」は因果として意味をなさない。", "改良": "正解。手直しの結果として自転車が軽くなったという意味で自然。", "出荷": "「出荷の結果、自転車が軽くなった」は因果関係が成り立たず、文脈に合わない。", "混雑": "「混雑の結果、自転車が軽くなった」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "改良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月から電気料金を改良します。", "explanation": "ここは〈改定〉の意味。料金や規則を決め直すことは改定で、改良は物や方法の性能を高めることに使う。"}, {"text": "書類の誤りを改良しました。", "explanation": "ここは〈修正〉の意味。誤りを直すことは修正で、改良は物や方法をより良くすることに使う。"}, {"text": "国会は選挙の法律を改良しました。", "explanation": "ここは〈改正〉の意味。法律を部分的に変えることは改正で、改良は道具や方法に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36145, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この製品は古い型の欠点に改良して、部品を作り直しました。", "corrected_sentence": "この製品は古い型の欠点を改良して、部品を作り直しました。", "error_description": "「改良」は他動詞で、対象の欠点は「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36145, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この炊飯器は内釜が改良して、火加減が安定しました。", "corrected_sentence": "この炊飯器は内釜が改良されて、火加減が安定しました。", "error_description": "「改良」は他動詞なので、主語の「内釜」が変えられる側になる場合は受身の「改良されて」が必要。能動の「改良して」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ace7ae9e-6da2-4379-b646-788a398b520b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
