INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36146, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "〈見えてくる〉は自動詞なので目的語の「を」を取れず、「川を見えてきました」は成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す。『川より見えてきました』は比べる相手がなく、成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体を表す。『川の見えてきました』では動詞の主語にならず、文が完成しない。"}, {"text": "が", "is_correct": true, "explanation": "〈見えてきた〉の主語は〈大きな川〉なので『が』。見えてくるものを示す助詞。"}], "correct_answer": "が", "explanations": {"を": "〈見えてくる〉は自動詞なので目的語の「を」を取れず、「川を見えてきました」は成立しない。", "より": "比較を表す。『川より見えてきました』は比べる相手がなく、成り立たない。", "の": "連体を表す。『川の見えてきました』では動詞の主語にならず、文が完成しない。", "が": "〈見えてきた〉の主語は〈大きな川〉なので『が』。見えてくるものを示す助詞。"}, "error_tags": {"を": "目的語", "より": "比較", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36146, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが目にうつる。", "primary_collocate": null, "pronunciation": "みえる", "ipa": "mieɾɯ", "syllable_count": 3, "sentences": [{"text": "晴れた日には、この窓から富士山が見えます。", "target_word": "見えます", "complexity_tier": "T3", "furigana": "晴[は]れた日[ひ]には、この窓[まど]から富士山[ふじさん]が見[み]えます。", "sentence_source": "generated"}, {"text": "霧が濃くて、前の車がほとんど見えなかった。", "target_word": "見えなかった", "complexity_tier": "T3", "furigana": "霧[きり]が濃[こ]くて、前[まえ]の車[くるま]がほとんど見[み]えなかった。", "sentence_source": "generated"}, {"text": "山の上に登ると、遠くに海が見える。", "target_word": "見える", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に登[のぼ]ると、遠[とお]くに海[うみ]が見[み]える。", "sentence_source": "generated"}, {"text": "眼鏡をかけないと、黒板の字が見えません。", "target_word": "見えません", "complexity_tier": "T3", "furigana": "眼鏡[めがね]をかけないと、黒板[こくばん]の字[じ]が見[み]えません。", "sentence_source": "generated"}, {"text": "星は昼間は太陽の光が強いので見えない。", "target_word": "見えない", "complexity_tier": "T3", "furigana": "星[ほし]は昼間[ひるま]は太陽[たいよう]の光[ひかり]が強[つよ]いので見[み]えない。", "sentence_source": "generated"}, {"text": "背の高い人が前に立ったので、舞台が見えなくなった。", "target_word": "見えなく", "complexity_tier": "T3", "furigana": "背[せ]の高[たか]い人[ひと]が前[まえ]に立[た]ったので、舞台[ぶたい]が見[み]えなくなった。", "sentence_source": "generated"}, {"text": "夜になると、町の明かりがきれいに見えた。", "target_word": "見えた", "complexity_tier": "T3", "furigana": "夜[よる]になると、町[まち]の明[あ]かりがきれいに見[み]えた。", "sentence_source": "generated"}, {"text": "電車の窓から大きな川が見えてきました。", "target_word": "見えて", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の窓[まど]から大[おお]きな川[かわ]が見[み]えてきました。", "sentence_source": "generated"}, {"text": "部屋が暗くて、机の上のものがよく見えない。", "target_word": "見えない", "complexity_tier": "T3", "furigana": "部屋[へや]が暗[くら]くて、机[つくえ]の上[うえ]のものがよく見[み]えない。", "sentence_source": "generated"}, {"text": "あの建物の屋上からなら、花火が見えるはずだ。", "target_word": "見える", "complexity_tier": "T3", "furigana": "あの建物[たてもの]の屋上[おくじょう]からなら、花火[はなび]が見[み]えるはずだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見える", "label": "終止形"}, {"form": "見えます", "label": "丁寧形"}, {"form": "見えない", "label": "否定形"}, {"form": "見えた", "label": "過去形"}, {"form": "見えて", "label": "て形"}, {"form": "見えれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ものが視界に入って目でとらえられる、可視の意味の見える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36146, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眺めます", "is_correct": false, "explanation": "〈眺める〉は『富士山を眺める』と目的語に『を』を取る他動詞。『富士山が眺めます』は成立しない。"}, {"text": "見えます", "is_correct": true, "explanation": "〈見える〉の丁寧形。『富士山が』を主語に、窓から視界に入る様子を表すので合う。"}, {"text": "聞こえます", "is_correct": false, "explanation": "耳で感じる音について使う語。富士山は音を出さないので合わない。"}, {"text": "運びます", "is_correct": false, "explanation": "物を移す他動詞。『富士山が運びます』は主語と動詞が合わず成立しない。"}], "explanations": {"眺めます": "〈眺める〉は『富士山を眺める』と目的語に『を』を取る他動詞。『富士山が眺めます』は成立しない。", "見えます": "〈見える〉の丁寧形。『富士山が』を主語に、窓から視界に入る様子を表すので合う。", "聞こえます": "耳で感じる音について使う語。富士山は音を出さないので合わない。", "運びます": "物を移す他動詞。『富士山が運びます』は主語と動詞が合わず成立しない。"}, "sentence_index": 0, "correct_answer": "見えます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の隙間から、この冬の寒さが見える。", "explanation": "ここは〈感じる〉の意味。寒さは肌で感じるもので、目にうつるという〈見える〉とは合わない。"}, {"text": "ざらついた壁の手触りが見えた。", "explanation": "ここは〈触る〉（手で確かめる）の意味。手触りは手で確かめるもので、目にうつるという〈見える〉とは合わない。"}, {"text": "遠くから踏切の音が見える。", "explanation": "ここは〈聞こえる〉の意味。音は耳で感じるもので、目にうつるという〈見える〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36146, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鳴った", "is_correct": false, "explanation": "音を出す動詞。明かりは音を出さないので、『明かりがきれいに鳴った』は成立しない。"}, {"text": "煮えた", "is_correct": false, "explanation": "加熱して煮える意味。明かりには合わない。"}, {"text": "見えた", "is_correct": true, "explanation": "〈見える〉の過去形。夜に町の明かりが視界に入ったことを表すので合う。"}, {"text": "濡れた", "is_correct": false, "explanation": "水などに触れて湿る意味。明かりには合わない。"}], "explanations": {"鳴った": "音を出す動詞。明かりは音を出さないので、『明かりがきれいに鳴った』は成立しない。", "煮えた": "加熱して煮える意味。明かりには合わない。", "見えた": "〈見える〉の過去形。夜に町の明かりが視界に入ったことを表すので合う。", "濡れた": "水などに触れて湿る意味。明かりには合わない。"}, "sentence_index": 6, "correct_answer": "見えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台所から、夕食のおいしそうな匂いが見える。", "explanation": "ここは〈匂う〉の意味。においは鼻で感じるもので、目にうつるという〈見える〉は合わない。"}, {"text": "その一言が、彼の胸に見えた。", "explanation": "ここは〈響く〉（心に強く伝わる）の意味。言葉の影響は目で見えるものではないので、〈見える〉は合わない。"}, {"text": "この荷物の重さが見えた。", "explanation": "ここは〈感じる〉（重さが感覚でわかる）の意味。重さは目にうつるものではないので、〈見える〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36146, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この展望台からは、晴れた日に海を見える。", "corrected_sentence": "この展望台からは、晴れた日に海が見える。", "error_description": "〈見える〉は見えるものを『が』で示す。『海を見える』は『を』を使った誤りで、正しくは『海が見える』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見えられた", "is_correct": false, "explanation": "〈見える〉は自動詞で、受身形（見えられる）は作れないので成立しない。"}, {"text": "見えた", "is_correct": false, "explanation": "肯定の過去形。『ほとんど見えた』だと、霧が濃いという理由と逆の意味になる。"}, {"text": "見えなかった", "is_correct": true, "explanation": "過去の否定形。霧のせいで前が見えなかったという過去の事実を述べるので合う。"}, {"text": "見えれば", "is_correct": false, "explanation": "仮定形。文末に置くと文が完成せず、後ろに続く句がない。"}], "correct_form": "見えなかった", "base_form": "見える", "form_label": "過去否定形", "sentence_index": 1, "explanations": {"見えられた": "〈見える〉は自動詞で、受身形（見えられる）は作れないので成立しない。", "見えた": "肯定の過去形。『ほとんど見えた』だと、霧が濃いという理由と逆の意味になる。", "見えなかった": "過去の否定形。霧のせいで前が見えなかったという過去の事実を述べるので合う。", "見えれば": "仮定形。文末に置くと文が完成せず、後ろに続く句がない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36146, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "手術のあと、ようやく字が見えるになった。", "corrected_sentence": "手術のあと、ようやく字が見えるようになった。", "error_description": "〈見える〉が状態の変化を表すときは『見えるようになる』と『ように』を付ける。『見えるになった』は『ように』が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見えます", "is_correct": false, "explanation": "丁寧形。『きました』と続かず、文が成立しない。"}, {"text": "見える", "is_correct": false, "explanation": "終止形。『きました』が続かないので、文が完成しない。"}, {"text": "見えて", "is_correct": true, "explanation": "て形。『〜てきました』につなげ、川が見え始めたという変化を表すので合う。"}, {"text": "見えなくなった", "is_correct": false, "explanation": "〜なくなった形。『きました』と続かず、意味も『見えなくなる』と逆になる。"}], "correct_form": "見えて", "base_form": "見える", "form_label": "て形", "sentence_index": 7, "explanations": {"見えます": "丁寧形。『きました』と続かず、文が成立しない。", "見える": "終止形。『きました』が続かないので、文が完成しない。", "見えて": "て形。『〜てきました』につなげ、川が見え始めたという変化を表すので合う。", "見えなくなった": "〜なくなった形。『きました』と続かず、意味も『見えなくなる』と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36148, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "で", "is_correct": false, "explanation": "場所や手段を表す。『他者で思いやる』は、思いやる相手を示せず不自然。"}, {"text": "を", "is_correct": true, "explanation": "〈思いやる〉は相手を目的語に取る他動詞なので『を』で示す。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す。『他者から思いやる』では、思いやる相手の関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "〈思いやる〉は相手を「を」で示す。「他者に思いやる気持ち」は成り立たない。"}], "correct_answer": "を", "explanations": {"で": "場所や手段を表す。『他者で思いやる』は、思いやる相手を示せず不自然。", "を": "〈思いやる〉は相手を目的語に取る他動詞なので『を』で示す。", "から": "起点を表す。『他者から思いやる』では、思いやる相手の関係が成り立たない。", "に": "〈思いやる〉は相手を「を」で示す。「他者に思いやる気持ち」は成り立たない。"}, "error_tags": {"で": "場所・手段", "から": "起点", "に": "相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "社会", "is_correct": false, "explanation": "個人と対になる語だが、〈他者〉の対義語ではない。"}, {"text": "自己", "is_correct": true, "explanation": "〈他者〉（自分以外の人）の対義語は〈自己〉（自分自身）。対になる関係が辞書に載る。"}, {"text": "周囲", "is_correct": false, "explanation": "まわりの環境を指す語で、〈他者〉の対義語ではない。"}, {"text": "理想", "is_correct": false, "explanation": "現実と対になる語で、〈他者〉とは対義の関係にない。"}], "correct_answer": "自己", "explanations": {"社会": "個人と対になる語だが、〈他者〉の対義語ではない。", "自己": "〈他者〉（自分以外の人）の対義語は〈自己〉（自分自身）。対になる関係が辞書に載る。", "周囲": "まわりの環境を指す語で、〈他者〉の対義語ではない。", "理想": "現実と対になる語で、〈他者〉とは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36148, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "を", "is_correct": false, "explanation": "『迷惑をかける』はすでに相手を『に』で示す形なので、『を』を重ねると不自然。"}, {"text": "に", "is_correct": true, "explanation": "〈迷惑をかける〉の相手は『に』で示す。『他者に迷惑をかける』で正しい。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す。「他者で迷惑をかける」は迷惑の相手を示せず成立しない。"}, {"text": "の", "is_correct": false, "explanation": "連体を表す。『他者の迷惑をかける』は、迷惑をかける相手を示せず文が崩れる。"}], "correct_answer": "に", "explanations": {"を": "『迷惑をかける』はすでに相手を『に』で示す形なので、『を』を重ねると不自然。", "に": "〈迷惑をかける〉の相手は『に』で示す。『他者に迷惑をかける』で正しい。", "で": "場所や手段を表す。「他者で迷惑をかける」は迷惑の相手を示せず成立しない。", "の": "連体を表す。『他者の迷惑をかける』は、迷惑をかける相手を示せず文が崩れる。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "の": "連体"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "世間", "is_correct": false, "explanation": "社会全体を指す語で、〈他者〉の対義語ではない。"}, {"text": "集団", "is_correct": false, "explanation": "まとまった人の群れを指す語で、〈他者〉の対義語ではない。"}, {"text": "空間", "is_correct": false, "explanation": "場所の広がりを指す語で、〈他者〉とは関係がない。"}, {"text": "自己", "is_correct": true, "explanation": "〈他者〉（ほかの人）の対義語は〈自己〉（自分自身）。対になる関係が辞書に載る。"}], "correct_answer": "自己", "explanations": {"世間": "社会全体を指す語で、〈他者〉の対義語ではない。", "集団": "まとまった人の群れを指す語で、〈他者〉の対義語ではない。", "空間": "場所の広がりを指す語で、〈他者〉とは関係がない。", "自己": "〈他者〉（ほかの人）の対義語は〈自己〉（自分自身）。対になる関係が辞書に載る。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36148, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分のほかの人。", "primary_collocate": null, "pronunciation": "たしゃ", "ipa": "taɕa", "syllable_count": 2, "sentences": [{"text": "他者の意見にもきちんと耳を傾けることが大切だ。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]の意見[いけん]にもきちんと耳[みみ]を傾[かたむ]けることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "他者を思いやる気持ちが、よいチームをつくる。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]を思[おも]いやる気持[きも]ちが、よいチームをつくる。", "sentence_source": "generated"}, {"text": "彼は他者に厳しく、自分にはもっと厳しい人だ。", "target_word": "他者", "complexity_tier": "T3", "furigana": "彼[かれ]は他者[たしゃ]に厳[きび]しく、自分[じぶん]にはもっと厳[きび]しい人[ひと]だ。", "sentence_source": "generated"}, {"text": "自分の考えを他者に伝えるのは簡単ではない。", "target_word": "他者", "complexity_tier": "T3", "furigana": "自分[じぶん]の考[かんが]えを他者[たしゃ]に伝[つた]えるのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "他者との違いを認めれば、争いは減るだろう。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]との違[ちが]いを認[みと]めれば、争[あらそ]いは減[へ]るだろう。", "sentence_source": "generated"}, {"text": "他者の成功をねたむより、自分の努力を続けたい。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]の成功[せいこう]をねたむより、自分[じぶん]の努力[どりょく]を続[つづ]けたい。", "sentence_source": "generated"}, {"text": "子どもは遊びの中で、他者と協力することを学ぶ。", "target_word": "他者", "complexity_tier": "T3", "furigana": "子[こ]どもは遊[あそ]びの中[なか]で、他者[たしゃ]と協力[きょうりょく]することを学[まな]ぶ。", "sentence_source": "generated"}, {"text": "他者に迷惑をかけないように、静かに歩いた。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]に迷惑[めいわく]をかけないように、静[しず]かに歩[ある]いた。", "sentence_source": "generated"}, {"text": "人は他者の目を気にしすぎると、疲れてしまう。", "target_word": "他者", "complexity_tier": "T3", "furigana": "人[ひと]は他者[たしゃ]の目[め]を気[き]にしすぎると、疲[つか]れてしまう。", "sentence_source": "generated"}, {"text": "他者の立場に立って考えると、分かることがある。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]の立場[たちば]に立[た]って考[かんが]えると、分[わ]かることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "他者", "label": "基本形"}, {"form": "他者の", "label": "の格"}, {"form": "他者を", "label": "を格"}, {"form": "他者に", "label": "に格"}, {"form": "他者と", "label": "と格"}], "register": "formal", "sense_fingerprint": "自分とは別の人という、考え方や人間関係を語るときの他者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: ねたむ (Zipf 1.36)']::text[], '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36148, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天気", "is_correct": false, "explanation": "空模様を表す名詞。『天気の意見』では意味が通らない。"}, {"text": "他者", "is_correct": true, "explanation": "〈他者〉は自分以外の人。『他者の意見に耳を傾ける』で、ほかの人の意見を指すので合う。"}, {"text": "機械", "is_correct": false, "explanation": "装置を指す名詞。機械には意見がないので、『機械の意見』は成立しない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す名詞。『季節の意見』は意味が通らない。"}], "explanations": {"天気": "空模様を表す名詞。『天気の意見』では意味が通らない。", "他者": "〈他者〉は自分以外の人。『他者の意見に耳を傾ける』で、ほかの人の意見を指すので合う。", "機械": "装置を指す名詞。機械には意見がないので、『機械の意見』は成立しない。", "季節": "時期を表す名詞。『季節の意見』は意味が通らない。"}, "sentence_index": 0, "correct_answer": "他者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新製品を他者より先に発売した。", "explanation": "ここは〈他社〉（別の会社）の意味。〈他者〉は会社ではなく、自分以外の人を指すので合わない。"}, {"text": "彼女は姉に似ているが、他者の空似だった。", "explanation": "ここは〈他人の空似〉（血のつながりがないのに似ていること）の意味。慣用句は『他人』を使い、〈他者〉とは言わない。"}, {"text": "彼は赤の他者を家に泊めた。", "explanation": "ここは〈赤の他人〉（まったく知らない人）の意味。『赤の他者』という言い方はなく、〈他者〉に置き換えると不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36148, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石", "is_correct": false, "explanation": "鉱物を指す語。石と協力することは成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "材料を指す語。紙と協力する文は意味が通らない。"}, {"text": "他者", "is_correct": true, "explanation": "〈他者〉はほかの人。『他者と協力する』で、協力する相手を指すので合う。"}, {"text": "鉄", "is_correct": false, "explanation": "金属を指す語。鉄と協力する文は成立しない。"}], "explanations": {"石": "鉱物を指す語。石と協力することは成り立たない。", "紙": "材料を指す語。紙と協力する文は意味が通らない。", "他者": "〈他者〉はほかの人。『他者と協力する』で、協力する相手を指すので合う。", "鉄": "金属を指す語。鉄と協力する文は成立しない。"}, "sentence_index": 6, "correct_answer": "他者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三か国の他者会談が開かれた。", "explanation": "ここは〈多者〉（三者以上）の意味。『他者』は自分以外の人を指すので、『多者会談』の代わりには使えない。"}, {"text": "彼は語学を磨くため、他者へ留学した。", "explanation": "ここは〈他国〉（自国以外の国）の意味。〈他者〉は人を指すので、国を指す文には合わない。"}, {"text": "新しい服は、他者で買った。", "explanation": "ここは〈他店〉（ほかの店）の意味。〈他者〉は人を指すので、店を指す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36148, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもは他者を遊ぶなかで、ルールを学ぶ。", "corrected_sentence": "子どもは他者と遊ぶなかで、ルールを学ぶ。", "error_description": "〈遊ぶ〉は相手と一緒に行う動作なので、相手は『と』で示す。『他者を遊ぶ』は『を』の誤りで、正しくは『他者と遊ぶ』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36148, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他者を意見を聞くことで、自分の考えが深まることがある。", "corrected_sentence": "他者の意見を聞くことで、自分の考えが深まることがある。", "error_description": "〈他者〉に続く『の』は『他者の意見』の所有を示す。『を』にすると『を』が二つ重なり誤り。正しくは『他者の意見を聞く』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36149, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "で", "is_correct": false, "explanation": "場所や手段を表す。『他者でものを使う』は成立しない。"}, {"text": "の", "is_correct": true, "explanation": "連体の『の』。〈他者〉が〈もの〉を修飾し、ほかの人の持ち物を指すので合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」を重ねると「他者をものを使う」は目的語が二つ並び、成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す。『他者へものを使う』は持ち物の所有者を示せず不自然。"}], "correct_answer": "の", "explanations": {"で": "場所や手段を表す。『他者でものを使う』は成立しない。", "の": "連体の『の』。〈他者〉が〈もの〉を修飾し、ほかの人の持ち物を指すので合う。", "を": "「を」を重ねると「他者をものを使う」は目的語が二つ並び、成立しない。", "へ": "方向を表す。『他者へものを使う』は持ち物の所有者を示せず不自然。"}, "error_tags": {"で": "場所・手段", "を": "目的語（重複）", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "周囲", "is_correct": false, "explanation": "まわりの環境を指す語で、〈他者〉の対義語ではない。"}, {"text": "自分", "is_correct": true, "explanation": "〈他者〉（自分以外の人）の対義語は〈自分〉。対になる関係が辞書に載る。"}, {"text": "組織", "is_correct": false, "explanation": "まとまった団体を指す語で、〈他者〉の対義語ではない。"}, {"text": "理論", "is_correct": false, "explanation": "考えの体系を指す語で、〈他者〉とは関係がない。"}], "correct_answer": "自分", "explanations": {"周囲": "まわりの環境を指す語で、〈他者〉の対義語ではない。", "自分": "〈他者〉（自分以外の人）の対義語は〈自分〉。対になる関係が辞書に載る。", "組織": "まとまった団体を指す語で、〈他者〉の対義語ではない。", "理論": "考えの体系を指す語で、〈他者〉とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36149, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "から", "is_correct": false, "explanation": "起点を表す。『他者から早く着く』では比べる関係が成立しない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す。『他者を早く着く』は文が成り立たない。"}, {"text": "より", "is_correct": true, "explanation": "比較の『より』。〈他者〉と比べて早く着く意味で、文脈に合う。"}, {"text": "に", "is_correct": false, "explanation": "到着点を表す。『他者に早く着く』は着く場所を示せず不自然。"}], "correct_answer": "より", "explanations": {"から": "起点を表す。『他者から早く着く』では比べる関係が成立しない。", "を": "目的語を表す。『他者を早く着く』は文が成り立たない。", "より": "比較の『より』。〈他者〉と比べて早く着く意味で、文脈に合う。", "に": "到着点を表す。『他者に早く着く』は着く場所を示せず不自然。"}, "error_tags": {"から": "起点", "を": "目的語", "に": "到着点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "世間", "is_correct": false, "explanation": "社会全体を指す語で、〈他者〉の対義語ではない。"}, {"text": "集団", "is_correct": false, "explanation": "まとまった人の群れを指す語で、〈他者〉の対義語ではない。"}, {"text": "空間", "is_correct": false, "explanation": "場所の広がりを指す語で、〈他者〉とは関係がない。"}, {"text": "自己", "is_correct": true, "explanation": "〈他者〉の対義語は〈自己〉（自分自身）。対になる関係が辞書に載る。"}], "correct_answer": "自己", "explanations": {"世間": "社会全体を指す語で、〈他者〉の対義語ではない。", "集団": "まとまった人の群れを指す語で、〈他者〉の対義語ではない。", "空間": "場所の広がりを指す語で、〈他者〉とは関係がない。", "自己": "〈他者〉の対義語は〈自己〉（自分自身）。対になる関係が辞書に載る。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36149, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分以外の人。他人。", "primary_collocate": null, "pronunciation": "たしゃ", "ipa": "taɕa", "syllable_count": 2, "sentences": [{"text": "この部屋は他者の立ち入りを禁止しています。", "target_word": "他者", "complexity_tier": "T3", "furigana": "この部屋[へや]は他者[たしゃ]の立[た]ち入[い]りを禁止[きんし]しています。", "sentence_source": "generated"}, {"text": "他者のものを勝手に使ってはいけません。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]のものを勝手[かって]に使[つか]ってはいけません。", "sentence_source": "generated"}, {"text": "パスワードを他者に教えないでください。", "target_word": "他者", "complexity_tier": "T3", "furigana": "パスワードを他者[たしゃ]に教[おし]えないでください。", "sentence_source": "generated"}, {"text": "他者からの批判に、彼は冷静に答えた。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]からの批判[ひはん]に、彼[かれ]は冷静[れいせい]に答[こた]えた。", "sentence_source": "generated"}, {"text": "作品の写真を他者が無断で使うことは認められない。", "target_word": "他者", "complexity_tier": "T3", "furigana": "作品[さくひん]の写真[しゃしん]を他者[たしゃ]が無断[むだん]で使[つか]うことは認[みと]められない。", "sentence_source": "generated"}, {"text": "彼女は他者の前ではあまり話さない。", "target_word": "他者", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は他者[たしゃ]の前[まえ]ではあまり話[はな]さない。", "sentence_source": "generated"}, {"text": "他者の評価ばかり気にして、自分の気持ちを忘れていた。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]の評価[ひょうか]ばかり気[き]にして、自分[じぶん]の気持[きも]ちを忘[わす]れていた。", "sentence_source": "generated"}, {"text": "他者より早く着くために、朝五時に家を出た。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]より早[はや]く着[つ]くために、朝[あさ]五時[ごじ]に家[いえ]を出[で]た。", "sentence_source": "generated"}, {"text": "自分の失敗を他者のせいにするのはよくない。", "target_word": "他者", "complexity_tier": "T3", "furigana": "自分[じぶん]の失敗[しっぱい]を他者[たしゃ]のせいにするのはよくない。", "sentence_source": "generated"}, {"text": "他者の助けがあって、ようやく仕事が終わった。", "target_word": "他者", "complexity_tier": "T3", "furigana": "他者[たしゃ]の助[たす]けがあって、ようやく仕事[しごと]が終[お]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "他者", "label": "基本形"}, {"form": "他者の", "label": "の格"}, {"form": "他者が", "label": "が格"}, {"form": "他者に", "label": "に格"}, {"form": "他者より", "label": "より格"}], "register": "formal", "sense_fingerprint": "自分以外の人、他人という意味で、禁止や所有、責任を語るときの他者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36149, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "季節", "is_correct": false, "explanation": "時期を表す語で、『季節の立ち入り』は成立しない。"}, {"text": "天気", "is_correct": false, "explanation": "天候を表す語で、立ち入りの対象にならない。"}, {"text": "他者", "is_correct": true, "explanation": "〈他者〉（自分以外の人）が立ち入るのを禁止する文なので合う。"}, {"text": "機械", "is_correct": false, "explanation": "装置を表す語。『機械の立ち入り』は禁止の対象として不自然。"}], "explanations": {"季節": "時期を表す語で、『季節の立ち入り』は成立しない。", "天気": "天候を表す語で、立ち入りの対象にならない。", "他者": "〈他者〉（自分以外の人）が立ち入るのを禁止する文なので合う。", "機械": "装置を表す語。『機械の立ち入り』は禁止の対象として不自然。"}, "sentence_index": 0, "correct_answer": "他者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新商品は、他者より早く発売された。", "explanation": "ここは〈他社〉（別の会社）の意味。〈他者〉は人を指すので、会社を指す文には合わない。"}, {"text": "人見知りの彼は、他者行儀な態度を取る。", "explanation": "ここは〈他人行儀〉（よそよそしい態度）の意味。慣用句では『他人』を使い、『他者行儀』とは言わない。"}, {"text": "三か国による他者間の交渉が始まった。", "explanation": "ここは〈多者間〉（三者以上の間）の意味。〈他者〉は『ほかの人』なので、『他者間』とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36149, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雲", "is_correct": false, "explanation": "空に浮かぶものを指す語。『雲の評価』は意味が通らない。"}, {"text": "石", "is_correct": false, "explanation": "鉱物を表す語。『石の評価』は評価の対象として成立しない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様を表す語。『天候の評価』は意味が通らない。"}, {"text": "他者", "is_correct": true, "explanation": "〈他者〉（ほかの人）の評価を気にする文なので合う。"}], "explanations": {"雲": "空に浮かぶものを指す語。『雲の評価』は意味が通らない。", "石": "鉱物を表す語。『石の評価』は評価の対象として成立しない。", "天候": "空模様を表す語。『天候の評価』は意味が通らない。", "他者": "〈他者〉（ほかの人）の評価を気にする文なので合う。"}, "sentence_index": 6, "correct_answer": "他者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "これは、他者事ではない。", "explanation": "ここは〈他人事〉（自分とは無関係な出来事）の慣用句。『他者事』という言い方はなく、〈他者〉に置き換えると不自然。"}, {"text": "赤の他者を信用して、財布を預けた。", "explanation": "ここは〈赤の他人〉（まったく知らない人）の意味。『赤の他者』とは言わないので、〈他者〉を使うと合わない。"}, {"text": "その条約は、他者との国境問題を解決した。", "explanation": "ここは〈他国〉（自国以外の国）の意味。〈他者〉は人を指すので、国と国の問題には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36149, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他者を責任を押しつけるのは、よくない。", "corrected_sentence": "他者に責任を押しつけるのは、よくない。", "error_description": "〈押しつける〉は押しつけられる相手を『に』で示す。『他者を』は『に』の誤りで、正しくは『他者に責任を押しつける』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36149, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他者を助けを求めることは、恥ではない。", "corrected_sentence": "他者に助けを求めることは、恥ではない。", "error_description": "〈求める〉は助けを求める相手を『に』で示す。『他者を』は『に』の誤りで、正しくは『他者に助けを求める』。『を』が二つ重なるのも誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36152, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "目的語を表す。『危険を内在している』では、ひそむものの主語を示せず不自然。"}, {"text": "が", "is_correct": true, "explanation": "〈内在する〉の主語は〈危険〉なので『が』。ひそむものを示す主語の助詞。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す。『危険で内在している』は主語にならず成立しない。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を表す。『危険と内在している』はひそむものの主語を示せない。"}], "correct_answer": "が", "explanations": {"を": "目的語を表す。『危険を内在している』では、ひそむものの主語を示せず不自然。", "が": "〈内在する〉の主語は〈危険〉なので『が』。ひそむものを示す主語の助詞。", "で": "場所や手段を表す。『危険で内在している』は主語にならず成立しない。", "と": "共同の相手を表す。『危険と内在している』はひそむものの主語を示せない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表面", "is_correct": false, "explanation": "物の外側の面を指す語で、〈内在〉の対義語ではない。"}, {"text": "提示", "is_correct": false, "explanation": "示して見せること。〈内在〉の対義語ではない。"}, {"text": "外在", "is_correct": true, "explanation": "〈内在〉（内にひそむ）の対義語は〈外在〉（外に表れている）。対になる関係が辞書に載る。"}, {"text": "地表", "is_correct": false, "explanation": "地面の表面を指す語で、〈内在〉とは関係がない。"}], "correct_answer": "外在", "explanations": {"表面": "物の外側の面を指す語で、〈内在〉の対義語ではない。", "提示": "示して見せること。〈内在〉の対義語ではない。", "外在": "〈内在〉（内にひそむ）の対義語は〈外在〉（外に表れている）。対になる関係が辞書に載る。", "地表": "地面の表面を指す語で、〈内在〉とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36152, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外側", "is_correct": false, "explanation": "外の方を指す語で、〈内在〉の対義語としての関係は辞書に載らない。"}, {"text": "外気", "is_correct": false, "explanation": "外の空気を指す語で、〈内在〉の対義語ではない。"}, {"text": "外在", "is_correct": true, "explanation": "〈内在〉（内にひそむ）の対義語は〈外在〉（外に表れている）。対になる関係が辞書に載る。"}, {"text": "外観", "is_correct": false, "explanation": "見た目を指す語で、〈内在〉の対義語ではない。"}], "correct_answer": "外在", "explanations": {"外側": "外の方を指す語で、〈内在〉の対義語としての関係は辞書に載らない。", "外気": "外の空気を指す語で、〈内在〉の対義語ではない。", "外在": "〈内在〉（内にひそむ）の対義語は〈外在〉（外に表れている）。対になる関係が辞書に載る。", "外観": "見た目を指す語で、〈内在〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36152, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "外には見えないけど、物や心の中にあること。", "primary_collocate": null, "pronunciation": "ないざい", "ipa": "naizai", "syllable_count": 4, "sentences": [{"text": "人はだれでも、心の中に大きな可能性が内在している。", "target_word": "内在", "complexity_tier": "T3", "furigana": "人[ひと]はだれでも、心[こころ]の中[なか]に大[おお]きな可能性[かのうせい]が内在[ないざい]している。", "sentence_source": "generated"}, {"text": "この問題には、まだ見えていない危険が内在している。", "target_word": "内在", "complexity_tier": "T3", "furigana": "この問題[もんだい]には、まだ見[み]えていない危険[きけん]が内在[ないざい]している。", "sentence_source": "generated"}, {"text": "彼の冷たい態度には、不安が内在しているように思う。", "target_word": "内在", "complexity_tier": "T3", "furigana": "彼[かれ]の冷[つめ]たい態度[たいど]には、不安[ふあん]が内在[ないざい]しているように思[おも]う。", "sentence_source": "generated"}, {"text": "子どもの才能は、遊びの中に内在していることが多い。", "target_word": "内在", "complexity_tier": "T3", "furigana": "子[こ]どもの才能[さいのう]は、遊[あそ]びの中[なか]に内在[ないざい]していることが多[おお]い。", "sentence_source": "generated"}, {"text": "言葉の中に内在する意味を読み取るのが、この授業の目的だ。", "target_word": "内在", "complexity_tier": "T3", "furigana": "言葉[ことば]の中[なか]に内在[ないざい]する意味[いみ]を読[よ]み取[と]るのが、この授業[じゅぎょう]の目的[もくてき]だ。", "sentence_source": "generated"}, {"text": "この制度には、不公平を生む原因が内在している。", "target_word": "内在", "complexity_tier": "T3", "furigana": "この制度[せいど]には、不公平[ふこうへい]を生[う]む原因[げんいん]が内在[ないざい]している。", "sentence_source": "generated"}, {"text": "物語には、作者の悩みが内在していると言われる。", "target_word": "内在", "complexity_tier": "T3", "furigana": "物語[ものがたり]には、作者[さくしゃ]の悩[なや]みが内在[ないざい]していると言[い]われる。", "sentence_source": "generated"}, {"text": "内在する力を引き出すために、毎日練習を続けた。", "target_word": "内在", "complexity_tier": "T3", "furigana": "内在[ないざい]する力[ちから]を引[ひ]き出[だ]すために、毎日[まいにち]練習[れんしゅう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "古い機械の中に内在していた欠陥が、ようやく見つかった。", "target_word": "内在", "complexity_tier": "T3", "furigana": "古[ふる]い機械[きかい]の中[なか]に内在[ないざい]していた欠陥[けっかん]が、ようやく見[み]つかった。", "sentence_source": "generated"}, {"text": "怒りが内在していても、顔には出さない人もいる。", "target_word": "内在", "complexity_tier": "T3", "furigana": "怒[いか]りが内在[ないざい]していても、顔[かお]には出[だ]さない人[ひと]もいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "内在", "label": "基本形"}, {"form": "内在する", "label": "動詞形"}, {"form": "内在している", "label": "継続形"}, {"form": "内在した", "label": "過去形"}, {"form": "内在的", "label": "形容動詞形"}], "register": "formal", "sense_fingerprint": "外からは見えないが、心や物の中にひそんでいること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36152, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放出", "is_correct": false, "explanation": "外へ出すという意味。『可能性が放出している』では、内にひそむという意味に合わない。"}, {"text": "流出", "is_correct": false, "explanation": "外へ流れ出す意味。『可能性が流出している』は内にある状態と逆になる。"}, {"text": "内在", "is_correct": true, "explanation": "〈内在〉は外からは見えず中にひそむ意味。『大きな可能性が内在している』で合う。"}, {"text": "消費", "is_correct": false, "explanation": "使い尽くす意味。『可能性が消費している』は成り立たない。"}], "explanations": {"放出": "外へ出すという意味。『可能性が放出している』では、内にひそむという意味に合わない。", "流出": "外へ流れ出す意味。『可能性が流出している』は内にある状態と逆になる。", "内在": "〈内在〉は外からは見えず中にひそむ意味。『大きな可能性が内在している』で合う。", "消費": "使い尽くす意味。『可能性が消費している』は成り立たない。"}, "sentence_index": 0, "correct_answer": "内在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このカメラには、高性能なフラッシュが内在している。", "explanation": "ここは〈内蔵〉（機器に組み込まれている）の意味。〈内在〉は目に見えない要素が中にひそむことを表し、機器の部品には使わない。"}, {"text": "テーブルの表面に、大きな傷が内在している。", "explanation": "ここは〈表れる〉（外に出て見える）の意味。〈内在〉は中にひそむことなので、表面の傷には合わない。"}, {"text": "彼の不満は、誰の目にもはっきり内在している。", "explanation": "ここは〈表れる〉（外に出て見える）の意味。〈内在〉は中にひそむことなので、誰の目にも明らかな不満には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36152, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒸発", "is_correct": false, "explanation": "液体が気体になる意味。『悩みが蒸発している』は成り立たない。"}, {"text": "落下", "is_correct": false, "explanation": "下へ落ちる意味。『悩みが落下している』は不自然。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解く意味。『悩みが解散している』は成り立たない。"}, {"text": "内在", "is_correct": true, "explanation": "〈内在〉は中にひそむ意味。作品の中に悩みがあることを表すので、ここに入る。"}], "explanations": {"蒸発": "液体が気体になる意味。『悩みが蒸発している』は成り立たない。", "落下": "下へ落ちる意味。『悩みが落下している』は不自然。", "解散": "集まりを解く意味。『悩みが解散している』は成り立たない。", "内在": "〈内在〉は中にひそむ意味。作品の中に悩みがあることを表すので、ここに入る。"}, "sentence_index": 6, "correct_answer": "内在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喜びが表情に内在していた。", "explanation": "ここは〈表れる〉（外に出て見える）の意味。〈内在〉は外からは見えず中にひそむことなので、表情に現れた喜びには合わない。"}, {"text": "ポケットに財布が内在している。", "explanation": "〈内在〉は抽象的なものや気持ちがひそむ意味。ポケットに入っている財布は『入っている』と言い、〈内在〉は使わない。"}, {"text": "この部屋の窓には、大きな穴が内在している。", "explanation": "ここは〈ある〉（そこにあること）の意味。窓の穴は目に見えるものなので、見えない形で中にひそむ〈内在〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36152, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この思想には、矛盾を内在している。", "corrected_sentence": "この思想には、矛盾が内在している。", "error_description": "〈内在する〉はひそむものを『が』で示す。『矛盾を』は『が』の誤りで、正しくは『矛盾が内在している』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36152, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "心の奥に、まだ消えない不安が内在したている。", "corrected_sentence": "心の奥に、まだ消えない不安が内在している。", "error_description": "〈内在する〉の『〜ている』形は『内在している』。『内在したている』は『した』と『ている』が重なった誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36153, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外在", "is_correct": true, "explanation": "内在の対義語。内側に対して外側にあり、外から見える性質を表すので対になる。"}, {"text": "外観", "is_correct": false, "explanation": "外観は見た目の姿のことで、内在の反対語ではない。"}, {"text": "実在", "is_correct": false, "explanation": "実在は実際に存在することで、内と外の関係を表さない。"}, {"text": "進行", "is_correct": false, "explanation": "進行は物事が進むことで、内在と反対の関係にはない。"}], "correct_answer": "外在", "explanations": {"外在": "内在の対義語。内側に対して外側にあり、外から見える性質を表すので対になる。", "外観": "外観は見た目の姿のことで、内在の反対語ではない。", "実在": "実在は実際に存在することで、内と外の関係を表さない。", "進行": "進行は物事が進むことで、内在と反対の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36153, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外在", "is_correct": true, "explanation": "内在の対義語。内側に対して外側にあり、外から見える性質を表すので対になる。"}, {"text": "外装", "is_correct": false, "explanation": "外装は製品の外側のカバーのことで、内在の反対語ではない。"}, {"text": "既存", "is_correct": false, "explanation": "既存は以前から存在することで、内と外の関係を表さない。"}, {"text": "停止", "is_correct": false, "explanation": "停止は動きを止めることで、内在とは反対の関係にない。"}], "correct_answer": "外在", "explanations": {"外在": "内在の対義語。内側に対して外側にあり、外から見える性質を表すので対になる。", "外装": "外装は製品の外側のカバーのことで、内在の反対語ではない。", "既存": "既存は以前から存在することで、内と外の関係を表さない。", "停止": "停止は動きを止めることで、内在とは反対の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36153, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の内側に存在し、外から直接見えない状態にあること。", "primary_collocate": null, "pronunciation": "ないざい", "ipa": "naizai", "syllable_count": 4, "sentences": [{"text": "この計画には、失敗につながる要因が内在している。", "target_word": "内在", "complexity_tier": "T3", "furigana": "この計画[けいかく]には、失敗[しっぱい]につながる要因[よういん]が内在[ないざい]している。", "sentence_source": "generated"}, {"text": "内在する矛盾が、ついに表に出てきた。", "target_word": "内在", "complexity_tier": "T3", "furigana": "内在[ないざい]する矛盾[むじゅん]が、ついに表[おもて]に出[で]てきた。", "sentence_source": "generated"}, {"text": "この古い法典には、当時の社会の価値観が内在している。", "target_word": "内在", "complexity_tier": "T3", "furigana": "この古(ふる)い法典(ほうてん)には、当時(とうじ)の社会(しゃかい)の価値観(かちかん)が内在(ないざい)している。", "sentence_source": "generated"}, {"text": "システムに内在するバグは、使ってみないと分からない。", "target_word": "内在", "complexity_tier": "T3", "furigana": "システムに内在[ないざい]するバグは、使[つか]ってみないと分[わ]からない。", "sentence_source": "generated"}, {"text": "組織に内在する問題を、外から見つけるのは難しい。", "target_word": "内在", "complexity_tier": "T3", "furigana": "組織[そしき]に内在[ないざい]する問題[もんだい]を、外[そと]から見[み]つけるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼は作品に内在するリズムを大切にして演奏した。", "target_word": "内在", "complexity_tier": "T3", "furigana": "彼[かれ]は作品[さくひん]に内在[ないざい]するリズムを大切[たいせつ]にして演奏[えんそう]した。", "sentence_source": "generated"}, {"text": "木の中に内在していた傷が、切ってから分かった。", "target_word": "内在", "complexity_tier": "T3", "furigana": "木[き]の中[なか]に内在[ないざい]していた傷[きず]が、切[き]ってから分[わ]かった。", "sentence_source": "generated"}, {"text": "社会に内在する差別を、なくす努力が必要だ。", "target_word": "内在", "complexity_tier": "T3", "furigana": "社会[しゃかい]に内在[ないざい]する差別[さべつ]を、なくす努力[どりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "薬には、体に害を与える危険が内在することもある。", "target_word": "内在", "complexity_tier": "T3", "furigana": "薬[くすり]には、体[からだ]に害[がい]を与[あた]える危険[きけん]が内在[ないざい]することもある。", "sentence_source": "generated"}, {"text": "内在する課題を整理してから、会議を始めた。", "target_word": "内在", "complexity_tier": "T3", "furigana": "内在[ないざい]する課題[かだい]を整理[せいり]してから、会議[かいぎ]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "内在", "label": "基本形"}, {"form": "内在する", "label": "動詞形"}, {"form": "内在している", "label": "継続形"}, {"form": "内在した", "label": "過去形"}, {"form": "内在的", "label": "形容動詞形"}], "register": "formal", "sense_fingerprint": "制度や物事の内部にあって外から直接は見えない要因や性質があること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '867e6da7-b7bb-4db0-b05a-8fbe2c1dbaea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36153, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内在", "is_correct": true, "explanation": "要因が中に備わっている状態を表し、「失敗につながる要因が内在している」と文意が通る。"}, {"text": "達成", "is_correct": false, "explanation": "達成は目標を成し遂げることなので、要因を主語にする文には合わない。"}, {"text": "妥協", "is_correct": false, "explanation": "妥協は互いに譲り合うことなので、要因が主語の文には当てはまらない。"}, {"text": "放棄", "is_correct": false, "explanation": "放棄は権利や物を手放すことで、要因が内側にある状態には合わない。"}], "explanations": {"内在": "要因が中に備わっている状態を表し、「失敗につながる要因が内在している」と文意が通る。", "達成": "達成は目標を成し遂げることなので、要因を主語にする文には合わない。", "妥協": "妥協は互いに譲り合うことなので、要因が主語の文には当てはまらない。", "放棄": "放棄は権利や物を手放すことで、要因が内側にある状態には合わない。"}, "sentence_index": 0, "correct_answer": "内在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その病気の症状は、ついに内在した。", "explanation": "ここは〈顕在〉（表に現れる）の意味。内在は内側に隠れて外から見えない状態を表すので、表に出た症状には合わない。"}, {"text": "彼は会議室に内在している。", "explanation": "ここは〈存在〉の意味。内在は物事の内側にある性質や要因に使い、人がいる場所を言う文には使わない。"}, {"text": "木の表面に、傷が内在している。", "explanation": "ここは〈表面化〉（表に現れている）の意味。内在は内側にあって外から見えない状態なので、表面に見えている傷とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36153, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内在", "is_correct": true, "explanation": "木の中に傷が備わっていて外から見えなかった状態を表し、文意に合う。"}, {"text": "解決", "is_correct": false, "explanation": "解決は問題が片づくことで、傷を主語にして「木の中で解決していた」とは言えない。"}, {"text": "失踪", "is_correct": false, "explanation": "失踪は人が行方不明になることで、傷には当てはまらない。"}, {"text": "会釈", "is_correct": false, "explanation": "会釈は軽く頭を下げる動作で、傷を主語にする文には合わない。"}], "explanations": {"内在": "木の中に傷が備わっていて外から見えなかった状態を表し、文意に合う。", "解決": "解決は問題が片づくことで、傷を主語にして「木の中で解決していた」とは言えない。", "失踪": "失踪は人が行方不明になることで、傷には当てはまらない。", "会釈": "会釈は軽く頭を下げる動作で、傷を主語にする文には合わない。"}, "sentence_index": 6, "correct_answer": "内在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の考えは、会議で内在した。", "explanation": "ここは〈表明〉（考えを示す）の意味。内在は外に出さず内側にあることなので、考えを会議で示す場面には合わない。"}, {"text": "新しい計画は、来月に内在することになった。", "explanation": "ここは〈公表〉の意味。内在は外から見えない内側にあることなので、計画を広く知らせる場面には合わない。"}, {"text": "窓の向こうに、遠くの山が内在している。", "explanation": "ここは〈見える〉（外から目に入る）の意味。内在は外から見えない内側にあることなので、窓越しに見える山には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36153, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この計画には、失敗の原因が内在をしている。", "corrected_sentence": "この計画には、失敗の原因が内在している。", "error_description": "「内在」は「内在している」の形で使い、後ろに「を」を付けない。「内在をしている」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36153, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の資料には、確認すべき点が内在くなっている。", "corrected_sentence": "会議の資料には、確認すべき点が内在している。", "error_description": "「内在」はサ変の名詞として「している」と続ける。「内在くなっている」は形容詞の活用になるので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5f2262-c6a2-494a-bf81-41eac77c9c52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36154, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「論理の飛躍」と名詞を「の」で続けて修飾する。ここが正解。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列を示す。「論理と飛躍がある」では二つを並べるだけで、飛躍の内容を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「論理を飛躍がある」は目的語になりうる形ではなく、存在の文に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「論理で飛躍がある」は手段になるが、この「ある」の文には合わない。"}], "correct_answer": "の", "explanations": {"の": "「論理の飛躍」と名詞を「の」で続けて修飾する。ここが正解。", "と": "〈と〉は並列を示す。「論理と飛躍がある」では二つを並べるだけで、飛躍の内容を表せない。", "を": "「論理を飛躍がある」は目的語になりうる形ではなく、存在の文に合わない。", "で": "「論理で飛躍がある」は手段になるが、この「ある」の文には合わない。"}, "error_tags": {"と": "並列", "を": "目的語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36154, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「論理が混乱していて」と主語を「が」で示す。ここが正解。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示す。〈混乱している〉は目的語を取らないので、「論理を混乱していて」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「論理と混乱していて」は並列にならず、混乱の主体が示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「論理へ混乱していて」は方向を表す形で、混乱の文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「論理が混乱していて」と主語を「が」で示す。ここが正解。", "を": "〈を〉は目的語を示す。〈混乱している〉は目的語を取らないので、「論理を混乱していて」は成り立たない。", "と": "「論理と混乱していて」は並列にならず、混乱の主体が示せない。", "へ": "「論理へ混乱していて」は方向を表す形で、混乱の文には合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36154, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "考えや話のつながり方のこと。正しい道すじ。", "primary_collocate": null, "pronunciation": "ろんり", "ipa": "ɾoɴɾi", "syllable_count": 3, "sentences": [{"text": "彼の話は論理が通っていて、とても分かりやすい。", "target_word": "論理", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は論理[ろんり]が通[とお]っていて、とても分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "その意見には論理の飛躍がある。", "target_word": "論理", "complexity_tier": "T3", "furigana": "その意見[いけん]には論理[ろんり]の飛躍[ひやく]がある。", "sentence_source": "generated"}, {"text": "論理に合わない説明では、誰も納得しない。", "target_word": "論理", "complexity_tier": "T3", "furigana": "論理[ろんり]に合[あ]わない説明[せつめい]では、誰[だれ]も納得[なっとく]しない。", "sentence_source": "generated"}, {"text": "数学では、正しい論理にしたがって答えを出す。", "target_word": "論理", "complexity_tier": "T3", "furigana": "数学[すうがく]では、正[ただ]しい論理[ろんり]にしたがって答[こた]えを出[だ]す。", "sentence_source": "generated"}, {"text": "彼女は感情ではなく、論理で相手を説得した。", "target_word": "論理", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は感情[かんじょう]ではなく、論理[ろんり]で相手[あいて]を説得[せっとく]した。", "sentence_source": "generated"}, {"text": "話の論理が途中で崩れてしまった。", "target_word": "論理", "complexity_tier": "T3", "furigana": "話[はなし]の論理[ろんり]が途中[とちゅう]で崩[くず]れてしまった。", "sentence_source": "generated"}, {"text": "彼は論理を一つずつ確かめながら、考えを順に説明した。", "target_word": "論理", "complexity_tier": "T3", "furigana": "彼[かれ]は論理[ろんり]を一[ひと]つずつ確[たし]かめながら、考[かんが]えを順[じゅん]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この文章は論理が混乱していて、何が言いたいのか分からない。", "target_word": "論理", "complexity_tier": "T3", "furigana": "この文章[ぶんしょう]は論理[ろんり]が混乱[こんらん]していて、何[なに]が言[い]いたいのか分[わ]からない。", "sentence_source": "generated"}, {"text": "子どもの言い分にも、子どもなりの論理がある。", "target_word": "論理", "complexity_tier": "T3", "furigana": "子[こ]どもの言[い]い分[ぶん]にも、子[こ]どもなりの論理[ろんり]がある。", "sentence_source": "generated"}, {"text": "論理を重ねていけば、この結論にたどり着く。", "target_word": "論理", "complexity_tier": "T3", "furigana": "論理[ろんり]を重[かさ]ねていけば、この結論[けつろん]にたどり着[つ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "論理", "label": "基本形"}, {"form": "論理的", "label": "形容動詞形（〜的）"}], "register": "書き言葉（普通体）", "sense_fingerprint": "考えや議論が筋道立ってつながっていること、その道すじ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36154, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "論理", "is_correct": true, "explanation": "「論理が通る」は話の筋道が立つという意味で、ここに入る。"}, {"text": "感情", "is_correct": false, "explanation": "「感情が通る」とは言わない。感情は筋道を通すものではない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温が通る」は不自然。体温は温度で、話の筋とは関係しない。"}, {"text": "色彩", "is_correct": false, "explanation": "「色彩が通る」とは言わない。見た目の要素で、話の筋道には合わない。"}], "explanations": {"論理": "「論理が通る」は話の筋道が立つという意味で、ここに入る。", "感情": "「感情が通る」とは言わない。感情は筋道を通すものではない。", "体温": "「体温が通る」は不自然。体温は温度で、話の筋とは関係しない。", "色彩": "「色彩が通る」とは言わない。見た目の要素で、話の筋道には合わない。"}, "sentence_index": 0, "correct_answer": "論理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は論理を飲んで、すぐに眠った。", "explanation": "ここは〈薬〉の意味。論理は飲むものではないので、この文は誤り。"}, {"text": "会社には守るべき論理がある。", "explanation": "ここは〈倫理〉（守るべき行動の基準）の意味。論理は「守る」対象ではない。"}, {"text": "その会議は論理が白熱して、夜中まで終わらなかった。", "explanation": "ここは〈議論〉の意味。論理は話し合いで使う言葉で、白熱するものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36154, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "論理", "is_correct": true, "explanation": "「論理を確かめる」は、説明の筋道を一つずつ確認するという意味で自然。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸音で、一つずつ確かめる説明の対象にはならない。"}, {"text": "湯気", "is_correct": false, "explanation": "湯気は立ちのぼるものなので、説明を順に確かめる文脈には合わない。"}, {"text": "残響", "is_correct": false, "explanation": "残響は音が消えたあとに残る響きで、説明の順序を確かめる対象ではない。"}], "explanations": {"論理": "「論理を確かめる」は、説明の筋道を一つずつ確認するという意味で自然。", "寝息": "寝息は眠っている人の呼吸音で、一つずつ確かめる説明の対象にはならない。", "湯気": "湯気は立ちのぼるものなので、説明を順に確かめる文脈には合わない。", "残響": "残響は音が消えたあとに残る響きで、説明の順序を確かめる対象ではない。"}, "sentence_index": 6, "correct_answer": "論理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は論理を失って、つい怒鳴ってしまった。", "explanation": "ここは〈理性〉の意味。「理性を失う」とは言うが、「論理を失う」とは言わない。"}, {"text": "論理が冷めないうちに食べよう。", "explanation": "ここは〈料理〉の意味。冷めるのは食べ物で、論理は冷めない。"}, {"text": "裁判官は慎重に考えて、論理を下した。", "explanation": "ここは〈判決〉の意味。判決は下すものだが、論理を下すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36154, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の説明は論理を通っていて、とても分かりやすかった。", "corrected_sentence": "彼の説明は論理が通っていて、とても分かりやすかった。", "error_description": "助詞の誤り。「論理が通る」の「論理」は「が」で示す。「を」は他動詞の目的語用で、自動詞「通る」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36154, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は論理に一つずつ確かめながら、話を組み立てた。", "corrected_sentence": "彼女は論理を一つずつ確かめながら、話を組み立てた。", "error_description": "助詞の誤り。「確かめる」の対象は「を」で示す。「論理に」では対象が示せず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36156, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「外部の音」と名詞を修飾する「の」。ここが正解。"}, {"text": "が", "is_correct": false, "explanation": "「外部が音が聞こえない」と主語が二つ重なり、文として不自然。"}, {"text": "を", "is_correct": false, "explanation": "「外部を音が聞こえない」は目的語にならず、「聞こえる」とも合わない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列を示す。「外部と音が聞こえない」では二つを並べるだけで、音の主語にならない。"}], "correct_answer": "の", "explanations": {"の": "「外部の音」と名詞を修飾する「の」。ここが正解。", "が": "「外部が音が聞こえない」と主語が二つ重なり、文として不自然。", "を": "「外部を音が聞こえない」は目的語にならず、「聞こえる」とも合わない。", "と": "〈と〉は並列を示す。「外部と音が聞こえない」では二つを並べるだけで、音の主語にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36156, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「外部に雨水がたまらない」と場所を「に」で示す。ここが正解。"}, {"text": "と", "is_correct": false, "explanation": "「外部と雨水がたまらない」は場所を示せず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「外部より雨水がたまらない」は比較の形で、場所の文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示す。「外部を雨水がたまる」では場所を表せず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「外部に雨水がたまらない」と場所を「に」で示す。ここが正解。", "と": "「外部と雨水がたまらない」は場所を示せず、意味が通らない。", "より": "「外部より雨水がたまらない」は比較の形で、場所の文として成り立たない。", "を": "〈を〉は目的語を示す。「外部を雨水がたまる」では場所を表せず、文が成り立たない。"}, "error_tags": {"と": "並列", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36156, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "外のほう。", "primary_collocate": null, "pronunciation": "がいぶ", "ipa": "ɡaibɯ", "syllable_count": 3, "sentences": [{"text": "建物の外部は、白いかべでおおわれている。", "target_word": "外部", "complexity_tier": "T3", "furigana": "建物[たてもの]の外部[がいぶ]は、白[しろ]いかべでおおわれている。", "sentence_source": "generated"}, {"text": "外部の音が聞こえないように、窓を二重にした。", "target_word": "外部", "complexity_tier": "T3", "furigana": "外部[がいぶ]の音[おと]が聞[き]こえないように、窓[まど]を二重[にじゅう]にした。", "sentence_source": "generated"}, {"text": "この製品は外部からの衝撃に弱いので、箱に入れて運んだ。", "target_word": "外部", "complexity_tier": "T3", "furigana": "この製品[せいひん]は外部[がいぶ]からの衝撃[しょうげき]に弱[よわ]いので、箱[はこ]に入[い]れて運[はこ]んだ。", "sentence_source": "generated"}, {"text": "この機械は外部から水が入らない作りだ。", "target_word": "外部", "complexity_tier": "T3", "furigana": "この機械[きかい]は外部[がいぶ]から水[みず]が入[はい]らない作[つく]りだ。", "sentence_source": "generated"}, {"text": "窓を開けると、外部の空気が車内に入ってくる。", "target_word": "外部", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、外部[がいぶ]の空気[くうき]が車内[しゃない]に入[はい]ってくる。", "sentence_source": "generated"}, {"text": "家の外部をペンキでぬりかえた。", "target_word": "外部", "complexity_tier": "T3", "furigana": "家[いえ]の外部[がいぶ]をペンキでぬりかえた。", "sentence_source": "generated"}, {"text": "外部の寒さに比べて、部屋の中はあたたかい。", "target_word": "外部", "complexity_tier": "T3", "furigana": "外部[がいぶ]の寒[さむ]さに比[くら]べて、部屋[へや]の中[なか]はあたたかい。", "sentence_source": "generated"}, {"text": "屋根の外部に雨水がたまらないよう、排水溝を作った。", "target_word": "外部", "complexity_tier": "T3", "furigana": "屋根[やね]の外部[がいぶ]に雨水[あまみず]がたまらないよう、排水溝[はいすいこう]を作[つく]った。", "sentence_source": "generated"}, {"text": "洞窟の外部には、明るい森が広がっていた。", "target_word": "外部", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の外部[がいぶ]には、明[あか]るい森[もり]が広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "ドアが厚く、外部の光はほとんど入らない。", "target_word": "外部", "complexity_tier": "T3", "furigana": "ドアが厚[あつ]く、外部[がいぶ]の光[ひかり]はほとんど入[はい]らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外部", "label": "基本形"}, {"form": "外部の", "label": "連体形（〜の）"}], "register": "書き言葉（普通体）", "sense_fingerprint": "建物・容器・機械など、物の外側の部分や外の空間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36156, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外部", "is_correct": true, "explanation": "「建物の外部」は建物の外側を指し、白いかべでおおわれている説明に自然につながる。"}, {"text": "食料", "is_correct": false, "explanation": "「食料はかべでおおわれている」は意味をなさず、建物の部位ではない。"}, {"text": "歌声", "is_correct": false, "explanation": "歌声は建物の部位ではなく、「白いかべでおおわれている」とは結びつかない。"}, {"text": "残高", "is_correct": false, "explanation": "残高は金額の数字で、建物の外側を表さない。"}], "explanations": {"外部": "「建物の外部」は建物の外側を指し、白いかべでおおわれている説明に自然につながる。", "食料": "「食料はかべでおおわれている」は意味をなさず、建物の部位ではない。", "歌声": "歌声は建物の部位ではなく、「白いかべでおおわれている」とは結びつかない。", "残高": "残高は金額の数字で、建物の外側を表さない。"}, "sentence_index": 0, "correct_answer": "外部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は外部に留学して、三年間帰らなかった。", "explanation": "ここは〈海外〉の意味。外部は国外を表す言葉ではないので、留学先には「海外に留学」と言う。"}, {"text": "人は外部を見て判断するべきではない。", "explanation": "ここは〈外見〉の意味。人の見かけを指すときは「外部」とは言わない。"}, {"text": "彼は外部を数えて、代金を払った。", "explanation": "外部は数えられるものではないので、この文は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36156, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外部", "is_correct": true, "explanation": "「外部の寒さ」は建物の外の寒さを指し、室内と比べる文脈に合う。"}, {"text": "食器", "is_correct": false, "explanation": "「食器の寒さ」とは言わない。食器は寒さを比べる対象にならない。"}, {"text": "歌詞", "is_correct": false, "explanation": "「歌詞の寒さ」は意味をなさず、比べる対象として成り立たない。"}, {"text": "香り", "is_correct": false, "explanation": "「香りの寒さ」は不自然。香りは寒さの比較に使えない。"}], "explanations": {"外部": "「外部の寒さ」は建物の外の寒さを指し、室内と比べる文脈に合う。", "食器": "「食器の寒さ」とは言わない。食器は寒さを比べる対象にならない。", "歌詞": "「歌詞の寒さ」は意味をなさず、比べる対象として成り立たない。", "香り": "「香りの寒さ」は不自然。香りは寒さの比較に使えない。"}, "sentence_index": 6, "correct_answer": "外部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓を開けると、外部が入ってきて寒い。", "explanation": "ここは〈外気〉（屋外の空気）の意味。外部は空気そのものを指さず、「入ってくる」の主語にならない。"}, {"text": "彼は外部をよく読んで、感想を書いた。", "explanation": "外部は読むものではないので、この文は誤り。"}, {"text": "彼は外部を買って、友人に渡した。", "explanation": "外部は買える物ではないので、この文は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36156, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この建物の外部で、昔とあまり変わらない。", "corrected_sentence": "この建物の外部は、昔とあまり変わらない。", "error_description": "助詞の誤り。主題は「は」で示す。「で」は場所を表すため、「変わらない」の主語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36156, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱の外部を、シールが貼ってある。", "corrected_sentence": "箱の外部に、シールが貼ってある。", "error_description": "助詞の誤り。「貼ってある」の場所は「に」で示す。「を」は目的語用で、状態を表す文には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36157, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「外部にもれて」と到達点を「に」で示す。ここが正解。"}, {"text": "を", "is_correct": false, "explanation": "「外部をもれて」は自動詞「もれる」に目的語が付かず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「外部ともれて」は意味が通らず、到達点を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「外部のもれて」は名詞の後に「の」が続く形で、動詞「もれる」の到達点にならず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「外部にもれて」と到達点を「に」で示す。ここが正解。", "を": "「外部をもれて」は自動詞「もれる」に目的語が付かず、不自然。", "と": "「外部ともれて」は意味が通らず、到達点を示せない。", "の": "「外部のもれて」は名詞の後に「の」が続く形で、動詞「もれる」の到達点にならず文が成り立たない。"}, "error_tags": {"に": "帰着点", "を": "目的語", "と": "相手", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内部", "is_correct": true, "explanation": "「組織の外の人」の意味での対義語で、組織の中を指す。ここが正解。"}, {"text": "表面", "is_correct": false, "explanation": "表面は外側の面のことで、「外部」の対義語ではない。"}, {"text": "内容", "is_correct": false, "explanation": "内容は中身の意味で、「外部」の対義語として登録されていない。"}, {"text": "中心", "is_correct": false, "explanation": "中心は真ん中の意味で、「外部」の対義語ではない。"}], "correct_answer": "内部", "explanations": {"内部": "「組織の外の人」の意味での対義語で、組織の中を指す。ここが正解。", "表面": "表面は外側の面のことで、「外部」の対義語ではない。", "内容": "内容は中身の意味で、「外部」の対義語として登録されていない。", "中心": "中心は真ん中の意味で、「外部」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36157, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「外部の専門家」と名詞を修飾する「の」。ここが正解。"}, {"text": "が", "is_correct": false, "explanation": "「外部が専門家に」と主語が重なり、依頼の文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「外部へ専門家に」は方向の形で、修飾関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「外部に専門家に」は場所と相手が重なり、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「外部の専門家」と名詞を修飾する「の」。ここが正解。", "が": "「外部が専門家に」と主語が重なり、依頼の文として不自然。", "へ": "「外部へ専門家に」は方向の形で、修飾関係が成り立たない。", "に": "「外部に専門家に」は場所と相手が重なり、意味が通らない。"}, "error_tags": {"の": "連体修飾", "が": "主語", "へ": "方向", "に": "相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内部", "is_correct": true, "explanation": "「組織の外の人」の意味での対義語で、組織の中を指す。ここが正解。"}, {"text": "中身", "is_correct": false, "explanation": "中身は入っている物のことで、「外部」の対義語ではない。"}, {"text": "本音", "is_correct": false, "explanation": "本音は本当の気持ちの意味で、「外部」の対義語ではない。"}, {"text": "余白", "is_correct": false, "explanation": "余白は何もない部分の意味で、「外部」の対義語ではない。"}], "correct_answer": "内部", "explanations": {"内部": "「組織の外の人」の意味での対義語で、組織の中を指す。ここが正解。", "中身": "中身は入っている物のことで、「外部」の対義語ではない。", "本音": "本音は本当の気持ちの意味で、「外部」の対義語ではない。", "余白": "余白は何もない部分の意味で、「外部」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36157, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "内側ではない、そと。", "primary_collocate": null, "pronunciation": "がいぶ", "ipa": "ɡaibɯ", "syllable_count": 3, "sentences": [{"text": "会社の外部の人には、この資料を見せられない。", "target_word": "外部", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の外部[がいぶ]の人[ひと]には、この資料[しりょう]を見[み]せられない。", "sentence_source": "generated"}, {"text": "情報が外部にもれて、問題になった。", "target_word": "外部", "complexity_tier": "T3", "furigana": "情報[じょうほう]が外部[がいぶ]にもれて、問題[もんだい]になった。", "sentence_source": "generated"}, {"text": "外部の意見を聞いて、計画を見直した。", "target_word": "外部", "complexity_tier": "T3", "furigana": "外部[がいぶ]の意見[いけん]を聞[き]いて、計画[けいかく]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "工事は外部の業者にたのむことにした。", "target_word": "外部", "complexity_tier": "T3", "furigana": "工事[こうじ]は外部[がいぶ]の業者[ぎょうしゃ]にたのむことにした。", "sentence_source": "generated"}, {"text": "外部から来た先生が、特別授業を行った。", "target_word": "外部", "complexity_tier": "T3", "furigana": "外部[がいぶ]から来[き]た先生[せんせい]が、特別[とくべつ]授業[じゅぎょう]を行[おこな]った。", "sentence_source": "generated"}, {"text": "このシステムは外部とつながっていないので安全だ。", "target_word": "外部", "complexity_tier": "T3", "furigana": "このシステムは外部[がいぶ]とつながっていないので安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "外部の人が学校に入るときは、受付で名前を書く。", "target_word": "外部", "complexity_tier": "T3", "furigana": "外部[がいぶ]の人[ひと]が学校[がっこう]に入[はい]るときは、受付[うけつけ]で名前[なまえ]を書[か]く。", "sentence_source": "generated"}, {"text": "外部の専門家に調査を依頼した。", "target_word": "外部", "complexity_tier": "T3", "furigana": "外部[がいぶ]の専門家[せんもんか]に調査[ちょうさ]を依頼[いらい]した。", "sentence_source": "generated"}, {"text": "組織の内部だけでなく、外部からの批判も受け止めるべきだ。", "target_word": "外部", "complexity_tier": "T3", "furigana": "組織[そしき]の内部[ないぶ]だけでなく、外部[がいぶ]からの批判[ひはん]も受[う]け止[と]めるべきだ。", "sentence_source": "generated"}, {"text": "チームの外部の人にも意見を聞いてみよう。", "target_word": "外部", "complexity_tier": "T3", "furigana": "チームの外部[がいぶ]の人[ひと]にも意見[いけん]を聞[き]いてみよう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外部", "label": "基本形"}, {"form": "外部の", "label": "連体形（〜の）"}], "register": "書き言葉（普通体）", "sense_fingerprint": "会社・組織・システムなどの内側に属さない、外の人や場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36157, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外部", "is_correct": true, "explanation": "「会社の外部の人」は会社の外にいる人を指し、資料を見せられない文脈に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "「会社の年齢の人」は成り立たず、人を修飾する語にならない。"}, {"text": "色彩", "is_correct": false, "explanation": "「会社の色彩の人」は意味をなさない。"}, {"text": "体重", "is_correct": false, "explanation": "「会社の体重の人」は不自然で、人を指す語として成り立たない。"}], "explanations": {"外部": "「会社の外部の人」は会社の外にいる人を指し、資料を見せられない文脈に合う。", "年齢": "「会社の年齢の人」は成り立たず、人を修飾する語にならない。", "色彩": "「会社の色彩の人」は意味をなさない。", "体重": "「会社の体重の人」は不自然で、人を指す語として成り立たない。"}, "sentence_index": 0, "correct_answer": "外部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は外部を三台も持っている。", "explanation": "ここは〈外車〉（外国製の車）の意味。外部は車の種類を指さないので、「三台も持っている」とは言えない。"}, {"text": "その詩は外部の感情をよく表している。", "explanation": "ここは〈内面〉の意味。感情は内面に属し、「外部の感情」とは言わない。"}, {"text": "この本の外部は、難しくて読めなかった。", "explanation": "ここは〈内容〉の意味。内容は本の中身で、「外部」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36157, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外部", "is_correct": true, "explanation": "「外部の人」は組織の外の人で、学校で受付を通す文脈に合う。"}, {"text": "昨日", "is_correct": false, "explanation": "「昨日の人」は人の分類として成り立たず、学校に入る文脈に合わない。"}, {"text": "午前", "is_correct": false, "explanation": "「午前の人」は人を指す言い方として不自然。"}, {"text": "先週", "is_correct": false, "explanation": "「先週の人」は人の分類として成り立たない。"}], "explanations": {"外部": "「外部の人」は組織の外の人で、学校で受付を通す文脈に合う。", "昨日": "「昨日の人」は人の分類として成り立たず、学校に入る文脈に合わない。", "午前": "「午前の人」は人を指す言い方として不自然。", "先週": "「先週の人」は人の分類として成り立たない。"}, "sentence_index": 6, "correct_answer": "外部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は外部を話さなかった。", "explanation": "ここは〈本音〉の意味。外部は話す内容ではない。"}, {"text": "チームの外部を読んで、感想を書いた。", "explanation": "ここは〈本〉（読むもの）の意味。外部は読むものではない。"}, {"text": "旅行に行くので、外部を両替した。", "explanation": "ここは〈外貨〉の意味。両替するのは通貨で、外部は両替できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36157, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の内容が外部をもれないよう、資料は鍵をかけて保管した。", "corrected_sentence": "会議の内容が外部にもれないよう、資料は鍵をかけて保管した。", "error_description": "助詞の誤り。「もれる」の到達点は「に」で示す。「を」は目的語用で、自動詞「もれる」には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36157, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外部を情報を公開する前に、確認した。", "corrected_sentence": "外部へ情報を公開する前に、確認した。", "error_description": "助詞の誤り。「公開する」の相手・方向は「へ」で示す。「を」は目的語用なので、「外部」を公開される対象にしてしまう。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
