INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36158, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「瞬間をカメラにおさめた」と、おさめる対象を「を」で示す。ここが正解。"}, {"text": "が", "is_correct": false, "explanation": "「瞬間がカメラにおさめた」は主語と動作が合わず、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「瞬間でカメラにおさめた」は場所や手段になり、対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「瞬間とカメラにおさめた」は並列にならず、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「瞬間をカメラにおさめた」と、おさめる対象を「を」で示す。ここが正解。", "が": "「瞬間がカメラにおさめた」は主語と動作が合わず、文として成り立たない。", "で": "「瞬間でカメラにおさめた」は場所や手段になり、対象を示せない。", "と": "「瞬間とカメラにおさめた」は並列にならず、対象を示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36158, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とても短い時間のこと。", "primary_collocate": null, "pronunciation": "しゅんかん", "ipa": "ɕɯŋkaɴ", "syllable_count": 4, "sentences": [{"text": "ドアを開けた瞬間、おいしそうなにおいがした。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "ドアを開[あ]けた瞬間[しゅんかん]、おいしそうなにおいがした。", "sentence_source": "generated"}, {"text": "彼女と目が合った瞬間、時間が止まったように感じた。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "彼女[かのじょ]と目[め]が合[あ]った瞬間[しゅんかん]、時間[じかん]が止[と]まったように感[かん]じた。", "sentence_source": "generated"}, {"text": "シャッターを押す瞬間を、ずっと待っていた。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "シャッターを押[お]す瞬間[しゅんかん]を、ずっと待[ま]っていた。", "sentence_source": "generated"}, {"text": "ゴールが決まった瞬間、会場は大きな歓声に包まれた。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "ゴールが決[き]まった瞬間[しゅんかん]、会場[かいじょう]は大[おお]きな歓声[かんせい]に包[つつ]まれた。", "sentence_source": "generated"}, {"text": "幸せな瞬間は、あっという間に過ぎてしまう。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "幸[しあわ]せな瞬間[しゅんかん]は、あっという間[ま]に過[す]ぎてしまう。", "sentence_source": "generated"}, {"text": "電車が出る瞬間に、友だちが走ってきた。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が出[で]る瞬間[しゅんかん]に、友[とも]だちが走[はし]ってきた。", "sentence_source": "generated"}, {"text": "その瞬間、部屋の電気が消えた。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "その瞬間[しゅんかん]、部屋[へや]の電気[でんき]が消[き]えた。", "sentence_source": "generated"}, {"text": "一生に一度の瞬間を、カメラにおさめた。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "一生[いっしょう]に一度[いちど]の瞬間[しゅんかん]を、カメラにおさめた。", "sentence_source": "generated"}, {"text": "気がゆるんだ瞬間に、コップを落としてしまった。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "気[き]がゆるんだ瞬間[しゅんかん]に、コップを落[お]としてしまった。", "sentence_source": "generated"}, {"text": "水がこおる瞬間を、写真で見たことがある。", "target_word": "瞬間", "complexity_tier": "T3", "furigana": "水[みず]がこおる瞬間[しゅんかん]を、写真[しゃしん]で見[み]たことがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "瞬間", "label": "基本形"}, {"form": "瞬間的", "label": "形容動詞形（〜的）"}], "register": "書き言葉（普通体）", "sense_fingerprint": "ある出来事が起こる、ごく短い一点の時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: こおる (Zipf 1.91)']::text[], '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36158, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瞬間", "is_correct": true, "explanation": "「ドアを開けた瞬間」は一点の時間を表し、においがした出来事に続く。ここが正解。"}, {"text": "感情", "is_correct": false, "explanation": "「ドアを開けた感情」は成り立たず、時点を表さない。"}, {"text": "材質", "is_correct": false, "explanation": "「ドアを開けた材質」は意味をなさない。"}, {"text": "天気", "is_correct": false, "explanation": "「ドアを開けた天気」は時点を表さず、文が成り立たない。"}], "explanations": {"瞬間": "「ドアを開けた瞬間」は一点の時間を表し、においがした出来事に続く。ここが正解。", "感情": "「ドアを開けた感情」は成り立たず、時点を表さない。", "材質": "「ドアを開けた材質」は意味をなさない。", "天気": "「ドアを開けた天気」は時点を表さず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "瞬間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "受験の瞬間は、とても忙しかった。", "explanation": "ここは〈時期〉の意味。瞬間は一点の時間で、受験のような期間には使えない。"}, {"text": "江戸の瞬間は、三百年以上続いた。", "explanation": "ここは〈時代〉の意味。瞬間は短い一点で、三百年続くことはない。"}, {"text": "夏休みの瞬間は、思ったより長く感じた。", "explanation": "ここは〈期間〉の意味。瞬間は短いので、「長く感じた」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36158, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瞬間", "is_correct": true, "explanation": "「その瞬間、部屋の電気が消えた」と、出来事が起きた一点を示す。ここが正解。"}, {"text": "意見", "is_correct": false, "explanation": "「その意見、部屋の電気が消えた」は時点を示さず、文が成り立たない。"}, {"text": "味", "is_correct": false, "explanation": "「その味、部屋の電気が消えた」は時点を表せず、意味が通らない。"}, {"text": "色彩", "is_correct": false, "explanation": "「その色彩、部屋の電気が消えた」は時点を表さず、文として不自然。"}], "explanations": {"瞬間": "「その瞬間、部屋の電気が消えた」と、出来事が起きた一点を示す。ここが正解。", "意見": "「その意見、部屋の電気が消えた」は時点を示さず、文が成り立たない。", "味": "「その味、部屋の電気が消えた」は時点を表せず、意味が通らない。", "色彩": "「その色彩、部屋の電気が消えた」は時点を表さず、文として不自然。"}, "sentence_index": 6, "correct_answer": "瞬間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬の瞬間は、朝晩がとても寒い。", "explanation": "ここは〈季節〉の意味。瞬間は一点の時間で、朝晩の状態を持つ季節には使えない。"}, {"text": "旅行の瞬間は五日間だった。", "explanation": "ここは〈日数〉の意味。瞬間は五日も続かないので、日数の意味には合わない。"}, {"text": "私の瞬間は二十歳です。", "explanation": "ここは〈年齢〉の意味。人の年齢は瞬間では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36158, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試合が終わった瞬間を、選手たちは泣き出した。", "corrected_sentence": "試合が終わった瞬間、選手たちは泣き出した。", "error_description": "助詞の誤り。「泣き出す」は目的語を取らないため、「瞬間」に「を」は付かない。「、」で続ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36158, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕日が沈む瞬間で、友だちと一緒に見届けた。", "corrected_sentence": "夕日が沈む瞬間を、友だちと一緒に見届けた。", "error_description": "助詞の誤り。「見届ける」の対象は「を」で示す。「で」は場所や手段を表し、ここでは目的語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36160, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈を〉は目的語。「現象を、本で読んだ」と続く対象として自然。"}, {"text": "に", "is_correct": false, "explanation": "「現象に、本で読んだ」は目的語にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すが、「現象で、本で読んだ」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。「現象へ、本で読んだ」は不自然。"}], "correct_answer": "を", "explanations": {"を": "〈を〉は目的語。「現象を、本で読んだ」と続く対象として自然。", "に": "「現象に、本で読んだ」は目的語にならず、文が成り立たない。", "で": "〈で〉は手段や場所を示すが、「現象で、本で読んだ」は意味が通らない。", "へ": "〈へ〉は方向を示す。「現象へ、本で読んだ」は不自然。"}, "error_tags": {"に": "位置・相手", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36160, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "〈は〉は主題。「現象は、雪の日に毎年起こる」と続き自然。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は連体修飾。「現象の、雪の日に」では文が続かない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点や理由を示す。「現象から、雪の日に」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示す。比べる相手がなく不自然。"}], "correct_answer": "は", "explanations": {"は": "〈は〉は主題。「現象は、雪の日に毎年起こる」と続き自然。", "の": "〈の〉は連体修飾。「現象の、雪の日に」では文が続かない。", "から": "〈から〉は起点や理由を示す。「現象から、雪の日に」は意味が通らない。", "より": "〈より〉は比較を示す。比べる相手がなく不自然。"}, "error_tags": {"の": "連体修飾", "から": "起点・理由", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36160, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "起こることや、見たり感じたりできること。", "primary_collocate": null, "pronunciation": "げんしょう", "ipa": "ɡeɴɕoː", "syllable_count": 4, "sentences": [{"text": "最近、スマホを見ながら歩く人が増えるという現象が気になる。", "target_word": "現象", "complexity_tier": "T3", "furigana": "最近[さいきん]、スマホを見[み]ながら歩[ある]く人[ひと]が増[ふ]えるという現象[げんしょう]が気[き]になる。", "sentence_source": "generated"}, {"text": "地震の前に動物が騒ぐという現象を、本で読んだことがある。", "target_word": "現象", "complexity_tier": "T3", "furigana": "地震[じしん]の前[まえ]に動物[どうぶつ]が騒[さわ]ぐという現象[げんしょう]を、本[ほん]で読[よ]んだことがある。", "sentence_source": "generated"}, {"text": "冬の朝に窓が白くなる現象は、部屋と外の温度差で起こる。", "target_word": "現象", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]に窓[まど]が白[しろ]くなる現象[げんしょう]は、部屋[へや]と外[そと]の温度差[おんどさ]で起[お]こる。", "sentence_source": "generated"}, {"text": "今日は夕方に空が真っ赤になる現象が見られて、みんな外に出た。", "target_word": "現象", "complexity_tier": "T3", "furigana": "今日[きょう]は夕方[ゆうがた]に空[そら]が真[ま]っ赤[か]になる現象[げんしょう]が見[み]られて、みんな外[そと]に出[で]た。", "sentence_source": "generated"}, {"text": "珍しい現象を見つけたので、先生に写真を送った。", "target_word": "現象", "complexity_tier": "T3", "furigana": "珍[めずら]しい現象[げんしょう]を見[み]つけたので、先生[せんせい]に写真[しゃしん]を送[おく]った。", "sentence_source": "generated"}, {"text": "夏になると、この町では雷が多く鳴る現象がよくある。", "target_word": "現象", "complexity_tier": "T3", "furigana": "夏[なつ]になると、この町[まち]では雷[かみなり]が多[おお]く鳴[な]る現象[げんしょう]がよくある。", "sentence_source": "generated"}, {"text": "虹は、雨上がりに太陽の光が水滴に当たって起こる現象だ。", "target_word": "現象", "complexity_tier": "T3", "furigana": "虹[にじ]は、雨上[あめあ]がりに太陽[たいよう]の光[ひかり]が水滴[すいてき]に当[あ]たって起[お]こる現象[げんしょう]だ。", "sentence_source": "generated"}, {"text": "電車が止まって駅に人があふれる現象は、雪の日に毎年起こる。", "target_word": "現象", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まって駅[えき]に人[ひと]があふれる現象[げんしょう]は、雪[ゆき]の日[ひ]に毎年[まいとし]起[お]こる。", "sentence_source": "generated"}, {"text": "静電気でかみの毛が立つ現象を、弟は面白がって何度も友達に見せた。", "target_word": "現象", "complexity_tier": "T3", "furigana": "静電気[せいでんき]でかみの毛が立つ現象[げんしょう]を、弟[おとうと]は面白[おもしろ]がって何度[なんど]も友達[ともだち]に見[み]せた。", "sentence_source": "generated"}, {"text": "不思議な現象に出会ったとき、まず何が起こったかをノートに書く。", "target_word": "現象", "complexity_tier": "T3", "furigana": "不思議[ふしぎ]な現象[げんしょう]に出会[であ]ったとき、まず何[なに]が起[お]こったかをノートに書[か]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "現象", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "身の回りで起こる、見たり感じたりできる出来事（日常的・一般的な意味）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36160, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "現象", "is_correct": true, "explanation": "「という現象」の語。起きている出来事を指し、〈気になる〉の主語として合う。"}, {"text": "天井", "is_correct": false, "explanation": "「増えるという天井」は意味が通らない。"}, {"text": "卵", "is_correct": false, "explanation": "「増えるという卵」は文の内容に合わない。"}, {"text": "指輪", "is_correct": false, "explanation": "「増えるという指輪」は成り立たない。"}], "explanations": {"現象": "「という現象」の語。起きている出来事を指し、〈気になる〉の主語として合う。", "天井": "「増えるという天井」は意味が通らない。", "卵": "「増えるという卵」は文の内容に合わない。", "指輪": "「増えるという指輪」は成り立たない。"}, "sentence_index": 0, "correct_answer": "現象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の現象に勝った。", "explanation": "ここは〈試合〉の意味。現象は勝ち負けの相手にならない。"}, {"text": "財布の現象を数えた。", "explanation": "ここは〈お金〉の意味。現象は財布の中身として数える対象にはならない。"}, {"text": "本人の現象を確認する。", "explanation": "ここは〈年齢〉の意味。現象は人の属性ではなく、本人の確認対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36160, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "現象", "is_correct": true, "explanation": "「起こる現象」の語。虹が生じる出来事を指し、文に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "「起こる手紙」は成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "「起こる会議」は意味が通らない。"}, {"text": "財布", "is_correct": false, "explanation": "「起こる財布」は文の内容に合わない。"}], "explanations": {"現象": "「起こる現象」の語。虹が生じる出来事を指し、文に合う。", "手紙": "「起こる手紙」は成り立たない。", "会議": "「起こる会議」は意味が通らない。", "財布": "「起こる財布」は文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "現象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この現象は有名な作曲家が作った。", "explanation": "ここは〈曲〉の意味。現象は作られる作品ではないので、作曲家の作品にはならない。"}, {"text": "夏の終わりに、現象を畑に植えた。", "explanation": "ここは〈作物〉の意味。現象は植えて育てる対象にはならない。"}, {"text": "来月の現象に出場する。", "explanation": "ここは〈大会〉の意味。現象は競技に出場する対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36160, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この現象へ驚いた人が多かった。", "corrected_sentence": "この現象に驚いた人が多かった。", "error_description": "「驚く」は「に」で対象を示す。「へ」は方向を表すので誤り。正しくは「現象に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36160, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の日に毎年、その現象を起こる。", "corrected_sentence": "雪の日に毎年、その現象が起こる。", "error_description": "「起こる」は自動詞で、現象は「が」で主語として示す。「を」は他動詞に付く助詞なので誤り。正しくは「現象が起こる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
